def _register_release_failure(config, code, message):
    """Record a machine-readable condition that must make the run nonzero."""
    failures = getattr(config, '_release_failures', None)
    if failures is None:
        failures = []
        config._release_failures = failures
    rec = {'code': str(code), 'message': str(message)}
    if rec not in failures:
        failures.append(rec)
    print(f"[RELEASE-FAIL] {code}: {message}")


def _student_t_mean_ci(values, confidence=0.95):
    """Mean and two-sided Student-t CI for a small sample."""
    x = np.asarray(values, dtype=float).ravel()
    x = x[np.isfinite(x)]
    n = int(x.size)
    if n == 0:
        return np.nan, np.nan, np.nan
    mean = float(np.mean(x))
    if n < 2:
        return mean, np.nan, np.nan
    sem = float(scipy_stats.sem(x, nan_policy='omit'))
    if not np.isfinite(sem):
        return mean, np.nan, np.nan
    critical = float(scipy_stats.t.ppf((1.0 + confidence) / 2.0, n - 1))
    half_width = critical * sem
    return mean, mean - half_width, mean + half_width


def _paired_binary_effect(unprotected, final, n_boot=10000, seed=42):
    """Paired event-rate effects, bootstrap CI, and exact McNemar p-value."""
    u = np.asarray(unprotected, dtype=bool).ravel()
    f = np.asarray(final, dtype=bool).ravel()
    if u.size != f.size or u.size == 0:
        raise ValueError('paired binary arrays must have equal nonzero length')
    u_rate = float(np.mean(u))
    f_rate = float(np.mean(f))
    abs_reduction = u_rate - f_rate
    rel_reduction = (abs_reduction / u_rate) if u_rate > 0 else np.nan
    prevented = int(np.sum(u & ~f))
    introduced = int(np.sum(~u & f))
    discordant = prevented + introduced
    mcnemar_p = (float(scipy_stats.binomtest(
        prevented, discordant, p=0.5, alternative='two-sided').pvalue)
        if discordant else 1.0)

    rng = np.random.default_rng(int(seed))
    n = int(u.size)
    boot_abs = np.empty(int(n_boot), dtype=float)
    boot_rel = np.full(int(n_boot), np.nan, dtype=float)
    for b in range(int(n_boot)):
        ids = rng.integers(0, n, size=n)
        ur = float(np.mean(u[ids]))
        fr = float(np.mean(f[ids]))
        boot_abs[b] = ur - fr
        if ur > 0:
            boot_rel[b] = (ur - fr) / ur
    abs_lo, abs_hi = np.percentile(boot_abs, [2.5, 97.5])
    finite_rel = boot_rel[np.isfinite(boot_rel)]
    rel_lo, rel_hi = ((np.nan, np.nan) if finite_rel.size == 0
                      else np.percentile(finite_rel, [2.5, 97.5]))
    return dict(
        n_paired=n,
        unprotected_event_rate=u_rate,
        final_event_rate=f_rate,
        absolute_rate_reduction=abs_reduction,
        absolute_rate_reduction_ci_lo=float(abs_lo),
        absolute_rate_reduction_ci_hi=float(abs_hi),
        relative_rate_reduction=rel_reduction,
        relative_rate_reduction_ci_lo=float(rel_lo),
        relative_rate_reduction_ci_hi=float(rel_hi),
        prevented_discordant=prevented,
        introduced_discordant=introduced,
        mcnemar_exact_p=mcnemar_p,
    )

