# =============================================================================
_SUPPORTED_CADENCES = [
    # (pandas offset alias, timedelta, steps/day, seasonal period, label)
    ('15min', pd.Timedelta('15min'),  96, 96, '15 minutes'),
    ('30min', pd.Timedelta('30min'),  48, 48, '30 minutes'),
    ('h',     pd.Timedelta('1h'),     24, 24, 'hourly'),
    ('3h',    pd.Timedelta('3h'),      8,  8, '3-hourly'),
    ('6h',    pd.Timedelta('6h'),      4,  4, '6-hourly'),
    ('D',     pd.Timedelta('1D'),      1,  7, 'daily'),
]


def infer_series_frequency(df, config=None, dataset_name=None, verbose=True):
    """Infer the dataset sampling cadence and cadence-dependent settings."""
    idx = pd.DatetimeIndex(pd.to_datetime(df.index)).sort_values()
    deltas = idx.to_series().diff().dropna()
    deltas = deltas[deltas > pd.Timedelta(0)]
    override = None
    if config is not None and dataset_name is not None:
        override = getattr(config, 'DATASET_FREQ_OVERRIDE', {}).get(dataset_name)

    if override is not None:
        cand = [c for c in _SUPPORTED_CADENCES if c[0] == override]
        if not cand:
            raise ValueError(
                f"[R16-A] DATASET_FREQ_OVERRIDE['{dataset_name}']='{override}' is "
                f"not one of the supported cadences "
                f"{[c[0] for c in _SUPPORTED_CADENCES]}.")
        alias, td, spd, seas, label = cand[0]
        inferred_from = 'DATASET_FREQ_OVERRIDE'
        med = deltas.median() if len(deltas) else td
    elif len(deltas) == 0:
        alias, td, spd, seas, label = _SUPPORTED_CADENCES[2]      # hourly
        inferred_from = 'default (index carries no usable deltas)'
        med = td
    else:
        med = deltas.median()
        # Snap on a log scale: equidistant in ratio, so 45min lands on 30min
        # rather than on hourly purely because the absolute gap is smaller.
        alias, td, spd, seas, label = min(
            _SUPPORTED_CADENCES,
            key=lambda c: abs(np.log(med / c[1])))
        inferred_from = 'median timestamp delta'

    regular_frac = (float((deltas == td).mean()) if len(deltas) else float('nan'))

    # Lag and window sets, expressed in STEPS, spanning comparable physical
    # time on every cadence: the immediate past, one day, and one week.
    if spd >= 24:
        lags = [1, 2, 3, 6, 12, spd, 2 * spd, 3 * spd]
        roll_windows = [6, 12, spd]
        short_window, long_window = spd, 3 * spd
    elif spd > 1:
        lags = [1, 2, 3, spd, 2 * spd, 7 * spd]
        roll_windows = [2, spd, 2 * spd]
        short_window, long_window = spd, 7 * spd
    else:
        # Daily. One "day" is one step, so the useful scales are the week and
        # the month; a 72-STEP window would be 72 days of context for a
        # one-day-ahead forecast.
        lags = [1, 2, 3, 7, 14, 28]
        roll_windows = [3, 7, 14]
        short_window, long_window = 7, 28

    lags = sorted(set(int(x) for x in lags if x >= 1))
    roll_windows = sorted(set(int(x) for x in roll_windows if x >= 2))

    info = dict(freq=alias, timedelta=td, steps_per_day=int(spd),
                seasonality=int(seas), lags=lags, roll_windows=roll_windows,
                short_window=int(short_window), long_window=int(long_window),
                label=label, inferred_from=inferred_from,
                median_delta=str(med), n_rows=int(len(idx)),
                regular_frac=regular_frac)

    if verbose:
        print("\n" + "=" * 78)
        print(f"[R16-A] CADENCE -- {dataset_name or 'dataset'}")
        print(f"    rows in source        : {len(idx)}")
        print(f"    median delta          : {med}  ({inferred_from})")
        print(f"    resolved cadence      : {alias}  ({label})")
        print(f"    steps/day             : {spd}")
        print(f"    seasonal MASE period m: {seas}")
        print(f"    lag set               : {lags}")
        print(f"    rolling windows       : {roll_windows}")
        print(f"    encoder short/long    : {short_window}/{long_window} steps "
              f"({short_window / max(spd, 1):.3g}d / "
              f"{long_window / max(spd, 1):.3g}d)")
        if np.isfinite(regular_frac):
            print(f"    deltas equal to grid  : {100 * regular_frac:.1f}%")
            if regular_frac < 0.5:
                print("    [R16-A] WARNING: fewer than half the timestamp gaps "
                      "equal the resolved\n"
                      "            cadence. The series is irregular, so any "
                      "regular grid inserts\n"
                      "            rows. The interpolated-fraction guard below "
                      "is what decides\n"
                      "            whether the testbed is still usable.")
        print("=" * 78)
    return info


def apply_cadence_to_config(config, info, verbose=True):
    """Apply inferred cadence settings to the active configuration."""
    config._cadence = info
    config._freq = info['freq']
    config._seasonality = info['seasonality']
    config._steps_per_day = info['steps_per_day']
    config._lags = info['lags']
    config._roll_windows = info['roll_windows']
    prev = (getattr(config, 'SHORT_WINDOW_SIZE', None),
            getattr(config, 'LONG_WINDOW_SIZE', None))
    config.SHORT_WINDOW_SIZE = info['short_window']
    config.LONG_WINDOW_SIZE = info['long_window']
    # Keep the diagnostic window constant in physical/seasonal meaning rather
    # than in row count: two daily cycles for hourly data (48), two weekly
    # cycles for daily data (14).
    config.CONTIGUOUS_MIN_LEN = int(2 * info['seasonality'])
    if verbose and prev != (info['short_window'], info['long_window']):
        print(f"    [R16-A] SHORT/LONG_WINDOW_SIZE {prev[0]}/{prev[1]} -> "
              f"{info['short_window']}/{info['long_window']} for this cadence.")
    return config


def _freq_of(config):
    """Internal experiment utility."""
    return getattr(config, '_freq', 'h')


def _seasonality_of(config):
    """Internal experiment utility."""
    return int(getattr(config, '_seasonality', 24))


def _lags_of(config):
    return list(getattr(config, '_lags', [1, 2, 3, 6, 12, 24, 48, 72]))


def _roll_windows_of(config):
    return list(getattr(config, '_roll_windows', [6, 12, 24]))


def ensure_cadence(df, config, dataset_name, verbose=False):
    """Ensure that the active dataset uses the correct cadence settings."""
    info = infer_series_frequency(df, config=config, dataset_name=dataset_name,
                                  verbose=verbose)
    if getattr(config, '_cadence', {}).get('freq') != info['freq'] or verbose:
        print(f"    [R16-A] cadence for '{dataset_name}': {info['label']} "
              f"(freq={info['freq']}, m={info['seasonality']})")
    config._dataset_name = dataset_name
    return apply_cadence_to_config(config, info, verbose=verbose)


def assert_cadence_integrity(df, eval_truth, config, target_vars, dataset_name,
                             obs_mask=None):
    """Report interpolation and cadence integrity on the scored window."""
    n = len(eval_truth)
    tv_end = int(n * (getattr(config, 'TRAIN_SPLIT', 0.7)
                      + getattr(config, 'VAL_SPLIT', 0.15)))
    test_index = eval_truth.index[tv_end:]
    n_test = len(test_index)
    src = pd.DatetimeIndex(pd.to_datetime(df.index))
    present = test_index.isin(src)
    interp_frac = float(1.0 - present.mean()) if n_test else float('nan')

    # The observation mask, when available, is the stricter statement: a row can
    # be present in the source file and still have been imputed by the DQA.
    obs_frac = np.nan
    if obs_mask is not None:
        cols = [v for v in target_vars if v in obs_mask.columns]
        if cols:
            om = obs_mask[cols].reindex(test_index).fillna(False)
            obs_frac = float(om.values.astype(bool).mean())

    thresh = float(getattr(config, 'CADENCE_MAX_INTERP_FRAC', 0.5))
    valid = bool(np.isfinite(interp_frac) and interp_frac <= thresh)

    diag = dict(dataset=dataset_name, cadence=_freq_of(config),
                seasonality=_seasonality_of(config),
                n_source_rows=int(len(src)), n_grid_rows=int(n),
                n_test_rows=int(n_test),
                n_test_rows_observed=int(present.sum()),
                cadence_interp_frac=interp_frac,
                obs_mask_observed_frac=obs_frac,
                threshold=thresh, cadence_valid=valid)

    print("\n" + "=" * 78)
    print(f"[R16-A] EVALUATION-WINDOW CADENCE INTEGRITY -- {dataset_name}")
    print(f"    grid                       : {_freq_of(config)}")
    print(f"    source rows / grid rows    : {len(src)} / {n}")
    print(f"    scored rows                : {n_test}")
    print(f"    of which present in source : {int(present.sum())} "
          f"({100 * (1 - interp_frac):.1f}%)")
    print(f"    INTERPOLATED FRACTION      : {100 * interp_frac:.1f}%  "
          f"(threshold {100 * thresh:.0f}%)")
    if np.isfinite(obs_frac):
        print(f"    never-imputed (obs mask)   : {100 * obs_frac:.1f}%")
    if valid:
        print("    VERDICT: cadence_valid = True. The scored window is mostly "
              "real observations.")
    else:
        print("    VERDICT: cadence_valid = FALSE.")
        print("    The majority of scored rows do not exist in the source file; "
              "they were")
        print("    manufactured by regularising a coarser series onto this grid. "
              "A one-step")
        print("    forecast of such a row is a forecast of the interpolant, and "
              "the ranking")
        print("    it produces measures smoothness, not sensor forecasting. "
              "Every row of")
        print("    this testbed is stamped cadence_valid=False; it may be "
              "reported as a")
        print("    negative/diagnostic result and must NOT enter a headline "
              "aggregate.")
        print(f"    Remedy: set DATASET_FREQ_OVERRIDE['{dataset_name}'] to the "
              f"source cadence")
        print("    so the series is scored on its own grid.")
    print("=" * 78)
    return valid, diag


# --- Custom Loss & Feature Engineering ---
class AdaptiveLoss(tf.keras.losses.Loss):
    """Huber residual loss with correction sparsity and parity regularization."""

    def __init__(self, lambda_l1, huber_delta=1.0, lambda_parity=0.0, **kwargs):
        super().__init__(**kwargs)
        self.lambda_l1 = tf.constant(lambda_l1, dtype=tf.float32)
        self.lambda_parity = tf.constant(lambda_parity, dtype=tf.float32)
        self.huber_delta = float(huber_delta)
        self.huber_loss = tf.keras.losses.Huber(delta=self.huber_delta)

    def call(self, y_true, y_pred):
        y_true = tf.cast(y_true, tf.float32)
        y_pred = tf.cast(y_pred, tf.float32)
        accuracy_loss = self.huber_loss(y_true, y_pred)
        correction_cost = self.lambda_l1 * tf.math.reduce_mean(tf.math.abs(y_pred))
        parity_excess = tf.math.abs(y_true - y_pred) - tf.math.abs(y_true)
        parity_cost = self.lambda_parity * tf.math.reduce_mean(
            tf.nn.relu(parity_excess))
        return accuracy_loss + correction_cost + parity_cost

    def get_config(self):
        cfg = super().get_config()
        cfg.update(lambda_l1=float(self.lambda_l1.numpy())
                   if hasattr(self.lambda_l1, 'numpy') else None,
                   huber_delta=self.huber_delta)
        return cfg


class DriftRescueLoss(tf.keras.losses.Loss):
    """Degradation-supervised correction loss.

    Frozen legacy mode reproduces the previous residual-regression objective.

    Native mode changes the estimand at the root:
      * labelled degraded row: learn the clean/reference residual r
      * labelled nominal row : learn EXACT zero correction

    Drift and nominal strata are averaged separately before combination, so
    prevalence cannot make the nominal majority wash out the drift objective or
    vice versa. This removes the old contradiction where nominal rows were
    simultaneously asked to predict ordinary anchor residuals and to preserve
    anchor parity.
    """

    def __init__(self, lambda_l1, huber_delta=1.0, lambda_parity=0.0,
                 lambda_aux=0.0, episode_w=1.0,
                 native_zero_nominal=False,
                 native_drift_weight=1.0,
                 native_nominal_weight=1.0,
                 objective_mode='native_balanced',
                 lambda_harm=0.0, **kwargs):
        super().__init__(**kwargs)
        self.lambda_l1 = tf.constant(float(lambda_l1), dtype=tf.float32)
        self.lambda_parity = tf.constant(float(lambda_parity), dtype=tf.float32)
        self.lambda_aux = tf.constant(float(lambda_aux), dtype=tf.float32)
        self.episode_w = tf.constant(float(episode_w), dtype=tf.float32)
        self.native_zero_nominal = bool(native_zero_nominal)
        self.native_drift_weight = tf.constant(float(native_drift_weight), dtype=tf.float32)
        self.native_nominal_weight = tf.constant(float(native_nominal_weight), dtype=tf.float32)
        self.objective_mode = str(objective_mode).lower()
        self.lambda_harm = tf.constant(float(lambda_harm), dtype=tf.float32)
        self.huber_delta = float(huber_delta)

    def _huber(self, e):
        d = self.huber_delta
        a = tf.math.abs(e)
        return tf.where(a <= d, 0.5 * a * a, d * (a - 0.5 * d))

    def call(self, y_true, y_pred):
        y_true = tf.cast(y_true, tf.float32)
        y_pred = tf.cast(tf.reshape(y_pred, (-1,)), tf.float32)
        y_true = tf.reshape(y_true, (tf.shape(y_pred)[0], -1))

        r = y_true[:, 0]
        lab = tf.cond(tf.shape(y_true)[1] > 1,
                      lambda: y_true[:, 1],
                      lambda: tf.fill(tf.shape(r), -1.0))

        labelled = tf.cast(lab >= 0.0, tf.float32)
        drift = tf.cast(tf.math.equal(lab, 1.0), tf.float32) * labelled
        nominal = tf.cast(tf.math.equal(lab, 0.0), tf.float32) * labelled

        if self.native_zero_nominal:
            # Root-level intervention objectives used by the development tournament.
            # All modes share the same estimand: degraded -> clean-anchor residual;
            # nominal -> zero correction. They differ in how strongly harmful actions
            # and nominal movement are penalised.
            post_abs = tf.math.abs(r - y_pred)
            pre_abs = tf.math.abs(r)
            drift_huber = self._huber(r - y_pred)
            nominal_huber = self._huber(y_pred)
            harm = tf.nn.relu(post_abs - pre_abs)

            n_d = tf.math.reduce_sum(drift)
            n_n = tf.math.reduce_sum(nominal)
            d_mean = tf.math.reduce_sum(drift * drift_huber) / (n_d + 1e-8)
            n_mean = tf.math.reduce_sum(nominal * nominal_huber) / (n_n + 1e-8)
            harm_mean = tf.math.reduce_sum(drift * harm) / (n_d + 1e-8)
            d_on = tf.cast(n_d > 0.0, tf.float32)
            n_on = tf.cast(n_n > 0.0, tf.float32)

            mode = self.objective_mode
            if mode == 'degraded_only':
                # Drift residual regression is primary; nominal rows only impose an
                # explicit sparsity/parity penalty rather than a competing residual fit.
                acc = self.native_drift_weight * d_on * d_mean
                acc += self.native_nominal_weight * n_on * tf.math.reduce_sum(
                    nominal * tf.math.abs(y_pred)) / (n_n + 1e-8)
            elif mode == 'harm_aware':
                denom = (self.native_drift_weight*d_on +
                         self.native_nominal_weight*n_on + 1e-8)
                acc = ((self.native_drift_weight*d_on*d_mean +
                        self.native_nominal_weight*n_on*n_mean) / denom)
                acc += self.lambda_harm * harm_mean
            elif mode == 'gain_aware':
                # Directly optimise no-worse-than-anchor behaviour. Softplus keeps a
                # smooth gradient around zero gain while retaining a smaller residual
                # regression term to preserve correction magnitude/direction.
                beta = tf.constant(4.0, dtype=tf.float32)
                gain_pen = tf.nn.softplus(beta * (post_abs - pre_abs)) / beta
                gain_mean = tf.math.reduce_sum(drift * gain_pen) / (n_d + 1e-8)
                denom = (self.native_drift_weight*d_on +
                         self.native_nominal_weight*n_on + 1e-8)
                acc = ((0.35*self.native_drift_weight*d_on*d_mean +
                        self.native_nominal_weight*n_on*n_mean) / denom)
                acc += tf.maximum(self.lambda_harm, 1.0) * gain_mean
            else:  # native_balanced
                denom = (self.native_drift_weight*d_on +
                         self.native_nominal_weight*n_on + 1e-8)
                acc = ((self.native_drift_weight*d_on*d_mean +
                        self.native_nominal_weight*n_on*n_mean) / denom)

            cost = self.lambda_l1 * tf.math.reduce_sum(
                labelled * tf.math.abs(y_pred)) / (tf.math.reduce_sum(labelled) + 1e-8)
            parity = self.lambda_parity * harm_mean
            return acc + cost + parity

        # Frozen legacy objective.
        err = self._huber(r - y_pred)
        w = labelled * (1.0 + (self.episode_w - 1.0) * drift)
        acc = tf.math.reduce_sum(w * err) / (tf.math.reduce_sum(w) + 1e-8)
        cost = self.lambda_l1 * tf.math.reduce_sum(
            labelled * tf.math.abs(y_pred)) / (tf.math.reduce_sum(labelled) + 1e-8)
        par = tf.nn.relu(tf.math.abs(r - y_pred) - tf.math.abs(r))
        parity = self.lambda_parity * tf.math.reduce_sum(
            labelled * par) / (tf.math.reduce_sum(labelled) + 1e-8)
        n_d = tf.math.reduce_sum(drift)
        aux = tf.cond(
            n_d > 0.0,
            lambda: self.lambda_aux * tf.math.reduce_sum(drift * err) / n_d,
            lambda: tf.constant(0.0, dtype=tf.float32))
        return acc + cost + parity + aux

    def get_config(self):
        cfg = super().get_config()
        cfg.update(lambda_l1=float(self.lambda_l1.numpy())
                   if hasattr(self.lambda_l1, 'numpy') else None,
                   huber_delta=self.huber_delta,
                   lambda_aux=float(self.lambda_aux.numpy())
                   if hasattr(self.lambda_aux, 'numpy') else None,
                   episode_w=float(self.episode_w.numpy())
                   if hasattr(self.episode_w, 'numpy') else None,
                   native_zero_nominal=self.native_zero_nominal,
                   native_drift_weight=float(self.native_drift_weight.numpy())
                   if hasattr(self.native_drift_weight, 'numpy') else None,
                   native_nominal_weight=float(self.native_nominal_weight.numpy())
                   if hasattr(self.native_nominal_weight, 'numpy') else None)
        return cfg


class BareCorrectionLoss(tf.keras.losses.Loss):
    """Auxiliary loss for the ungated-correction ablation."""

    def __init__(self, lambda_aux=1.0, huber_delta=1.0, **kwargs):
        super().__init__(**kwargs)
        self.lambda_aux = tf.constant(float(lambda_aux), dtype=tf.float32)
        self.huber_delta = float(huber_delta)

    def call(self, y_true, y_pred):
        y_true = tf.cast(y_true, tf.float32)
        y_pred = tf.cast(tf.reshape(y_pred, (-1,)), tf.float32)
        y_true = tf.reshape(y_true, (tf.shape(y_pred)[0], -1))
        r = y_true[:, 0]
        lab = tf.cond(tf.shape(y_true)[1] > 1,
                      lambda: y_true[:, 1],
                      lambda: tf.fill(tf.shape(r), -1.0))
        drift = tf.cast(tf.math.equal(lab, 1.0), tf.float32)
        d = self.huber_delta
        a = tf.math.abs(r - y_pred)
        err = tf.where(a <= d, 0.5 * a * a, d * (a - 0.5 * d))
        n_d = tf.math.reduce_sum(drift)
        return tf.cond(
            n_d > 0.0,
            lambda: self.lambda_aux * tf.math.reduce_sum(drift * err) / n_d,
            lambda: tf.constant(0.0, dtype=tf.float32))


def _safe_name(s):
    """Internal experiment utility."""
    return re.sub(r'[^0-9A-Za-z._=-]+', '_', str(s)).strip('_')


class DeltaGradNorm(tf.keras.callbacks.Callback):
    """Internal experiment utility."""

    def __init__(self, probe_x, probe_y, target_vars, sample_weight=None):
        super().__init__()
        self.probe_x = probe_x
        self.probe_y = probe_y
        self.target_vars = list(target_vars)
        self.sample_weight = sample_weight
        self.history = []

    def on_epoch_end(self, epoch, logs=None):
        # A diagnostic must never be able to abort the run it is diagnosing.
        try:
            self._probe(epoch)
        except Exception as e:
            if epoch == 0:
                print(f"    [DEV] gradient probe unavailable ({e}); "
                      f"delta_raw telemetry is unaffected.")

    def _probe(self, epoch):
        m = self.model
        names = {v: v.replace(" ", "_") for v in self.target_vars}
        delta_w, trunk_w = {}, {}
        for v, s in names.items():
            try:
                delta_w[v] = m.get_layer(f'delta_{s}').trainable_weights[0]
            except Exception:
                delta_w[v] = None
            try:
                trunk_w[v] = m.get_layer(f'trunk_{s}').trainable_weights[0]
            except Exception:
                trunk_w[v] = None
        watch = [w for w in list(delta_w.values()) + list(trunk_w.values())
                 if w is not None]
        # Keras 3 exposes keras.Variable, which GradientTape.watch() rejects;
        # the backing tf.Variable is on `.value`. Fall back to the object
        # itself on backends where it is already a tf.Variable.
        watch = [getattr(w, 'value', w) for w in watch]
        _key = {}
        for _lbl, _d in (('delta', delta_w), ('trunk', trunk_w)):
            for _v, _w in _d.items():
                if _w is not None:
                    _key[(_lbl, _v)] = id(getattr(_w, 'value', _w))
        with tf.GradientTape() as tape:
            tape.watch(watch)
            y_hat = m(self.probe_x, training=True)
            y_hat = y_hat if isinstance(y_hat, list) else [y_hat]
            loss = 0.0
            for i, lo in enumerate(m.loss if isinstance(m.loss, list) else [m.loss]):
                if i >= len(y_hat) or i >= len(self.probe_y):
                    break
                lw = 1.0
                if isinstance(getattr(m, 'loss_weights', None), list) and i < len(m.loss_weights):
                    lw = float(m.loss_weights[i])
                loss = loss + lw * lo(self.probe_y[i], y_hat[i])
        grads = tape.gradient(loss, watch)
        gmap = {id(w): g for w, g in zip(watch, grads)}

        def _n(t):
            if t is None:
                return float('nan')
            return float(tf.norm(t).numpy())

        # p_fault heads occupy outputs [n_t:2n_t] when gating is on.
        n_t = int(getattr(m, '_m2p_n_targets', len(self.target_vars)))
        p_means = {}
        if getattr(m, '_m2p_gated', False) and len(y_hat) >= 2 * n_t:
            for j, v in enumerate(self.target_vars):
                p_means[v] = float(np.mean(np.asarray(y_hat[n_t + j])))
        for v in self.target_vars:
            self.history.append(dict(
                epoch=int(epoch), target=v,
                g_delta=_n(gmap.get(_key.get(('delta', v)))),
                g_trunk=_n(gmap.get(_key.get(('trunk', v)))),
                w_delta=_n(delta_w[v]) if delta_w[v] is not None else float('nan'),
                p_fault_mean=p_means.get(v, float('nan')),
                loss=float(loss.numpy())))


def dev_delta_telemetry(model, target_vars, splits, scaler_residuals, config,
                        out_dir, tag):
    """Internal experiment utility."""
    import tensorflow as tf
    safe = [v.replace(" ", "_") for v in target_vars]
    n_t = len(target_vars)
    try:
        raw_model = tf.keras.Model(
            inputs=model.inputs,
            outputs=[model.get_layer(f'delta_{s}').output for s in safe])
    except Exception as e:
        print(f"    [DEV] cannot tap delta_ layers ({e}); telemetry skipped.")
        return None
    act_frac = float(getattr(config, 'DEV_DELTA_ACT_FRAC', 0.01))

    # ------------------------------------------------------------------ DEV
    # REPRESENTATION TAP. A Dense head whose output is a literal constant
    # while its kernel is non-zero and receives gradient can only mean its
    # INPUT is constant. That distinguishes "the head refuses to learn"
    # (optimisation) from "the head has nothing to learn from" (a collapsed
    # encoder upstream), which are different bugs with different fixes. Tap
    # the GLU fusion output and each per-target trunk and report how many
    # units actually vary across samples.
    rep_rows = []
    try:
        _taps, _tap_names = [], []
        for _ln in (['glu_fusion'] + [f'trunk_{s}' for s in safe]
                    + [f'det_trunk_{s}' for s in safe]
                    + [f'pfault_{s}' for s in safe]):
            try:
                _taps.append(model.get_layer(_ln).output)
                _tap_names.append(_ln)
            except Exception:
                pass
        rep_model = (tf.keras.Model(inputs=model.inputs, outputs=_taps)
                     if _taps else None)
    except Exception:
        rep_model = None

    rows = []
    for split_name, (X, ctx, r_scaled) in splits.items():
        if X is None or len(X) == 0:
            continue
        o = raw_model.predict([X, ctx], verbose=0)
        o = o if isinstance(o, list) else [o]
        d_scaled = np.stack([np.asarray(a).reshape(-1) for a in o], axis=1)
        # delta_eff for the same rows, so the two are directly comparable.
        e = model.predict([X, ctx], verbose=0)
        e = e if isinstance(e, list) else [e]
        e_scaled = np.stack([np.asarray(a).reshape(-1) for a in e[:n_t]], axis=1)
        p_fault = (np.stack([np.asarray(a).reshape(-1) for a in e[n_t:2 * n_t]], axis=1)
                   if len(e) >= 2 * n_t else None)
        if rep_model is not None:
            _ro = rep_model.predict([X, ctx], verbose=0)
            _ro = _ro if isinstance(_ro, list) else [_ro]
            for _nm, _a in zip(_tap_names, _ro):
                _a = np.asarray(_a)
                _sd = _a.std(axis=0)
                rep_rows.append(dict(
                    tag=tag, split=split_name, layer=_nm,
                    n_units=int(_a.shape[-1]),
                    n_units_varying=int(np.sum(_sd > 1e-8)),
                    frac_units_varying=float(np.mean(_sd > 1e-8)),
                    mean_unit_sd=float(_sd.mean()),
                    max_unit_sd=float(_sd.max()),
                    mean_abs_activation=float(np.abs(_a).mean()),
                    frac_exact_zero=float(np.mean(_a == 0.0)),
                    # For the sigmoid gate only: the pre-activation logit,
                    # recovered from p. A logit far below the bias
                    # initialiser means upstream activations, not the
                    # initialiser, drove the gate into saturation.
                    implied_logit_mean=(
                        float(np.mean(np.log(np.clip(_a, 1e-300, 1 - 1e-16)
                                             / np.clip(1 - _a, 1e-300, 1))))
                        if _nm.startswith('pfault_') else float('nan'))))

        d_raw = scaler_residuals.inverse_transform(d_scaled)
        d_eff = scaler_residuals.inverse_transform(e_scaled)
        r_raw = scaler_residuals.inverse_transform(np.asarray(r_scaled))
        for j, v in enumerate(target_vars):
            dr, de, rr = d_raw[:, j], d_eff[:, j], r_raw[:, j]
            sig_r = float(np.std(rr))
            thr = act_frac * sig_r
            # Useful/harmful measured on delta_RAW against the true residual:
            # |r - delta| < |r| means the correction moved the prediction
            # toward truth. Ties (delta exactly 0) are neither.
            imp = np.abs(rr - dr) < np.abs(rr)
            hrm = np.abs(rr - dr) > np.abs(rr)
            with np.errstate(invalid='ignore'):
                corr = (float(np.corrcoef(dr, rr)[0, 1])
                        if np.std(dr) > 0 and np.std(rr) > 0 else float('nan'))
            rows.append(dict(
                tag=tag, split=split_name, target=v, n=len(dr),
                # --- delta_raw distribution (items 3-8 of the brief) ---
                mean_delta_raw=float(np.mean(dr)),
                std_delta_raw=float(np.std(dr)),
                mean_abs_delta_raw=float(np.mean(np.abs(dr))),
                median_abs_delta_raw=float(np.median(np.abs(dr))),
                min_delta_raw=float(np.min(dr)),
                max_delta_raw=float(np.max(dr)),
                # --- how many corrections actually acted (item 9) ---
                act_threshold=thr,
                n_acted=int(np.sum(np.abs(dr) > thr)),
                pct_acted=float(100.0 * np.mean(np.abs(dr) > thr)),
                # --- signal alignment (item 10) ---
                corr_delta_residual=corr,
                # --- usefulness (items 11-12) ---
                useful_rate=float(np.mean(imp)),
                harmful_rate=float(np.mean(hrm)),
                # --- the residual target the head was asked to predict ---
                std_residual_raw=sig_r,
                mean_abs_residual_raw=float(np.mean(np.abs(rr))),
                std_residual_scaled=float(np.std(np.asarray(r_scaled)[:, j])),
                # --- the collapse ratio, on RAW and on EFFECTIVE ---
                ratio_raw_to_residual=(float(np.std(dr) / sig_r)
                                       if sig_r > 0 else float('nan')),
                std_delta_eff=float(np.std(de)),
                ratio_eff_to_residual=(float(np.std(de) / sig_r)
                                       if sig_r > 0 else float('nan')),
                # --- the gate, which is what separates raw from effective ---
                p_fault_mean=(float(np.mean(p_fault[:, j]))
                              if p_fault is not None else float('nan')),
                p_fault_max=(float(np.max(p_fault[:, j]))
                             if p_fault is not None else float('nan')),
                frac_p_above_deadband=(
                    float(np.mean(p_fault[:, j] >= float(getattr(
                        config, 'FAULT_PROB_DEADBAND', 1e-4))))
                    if p_fault is not None else float('nan'))))
    if rep_rows:
        rp = pd.DataFrame(rep_rows)
        rp.to_csv(os.path.join(out_dir, f"dev_representation_{tag}.csv"),
                  index=False)
        for _, rw in rp.iterrows():
            print(f"      [rep] {rw['split']:5s} {rw['layer'][:26]:26s} "
                  f"{rw['n_units_varying']:3d}/{rw['n_units']:3d} units vary "
                  f"(max unit sd {rw['max_unit_sd']:.3g}, "
                  f"{100*rw['frac_exact_zero']:.0f}% exact zeros)")
    out = pd.DataFrame(rows)
    p = os.path.join(out_dir, f"dev_delta_telemetry_{tag}.csv")
    out.to_csv(p, index=False)
    print(f"    [DEV] delta_raw telemetry -> {p}")
    for _, rw in out.iterrows():
        print(f"      {rw['split']:5s} {rw['target'][:22]:22s} "
              f"std(delta_raw)={rw['std_delta_raw']:.4g} "
              f"(residual sigma {rw['std_residual_raw']:.4g}, "
              f"ratio {rw['ratio_raw_to_residual']:.3g})  "
              f"acted {rw['pct_acted']:.1f}%  corr={rw['corr_delta_residual']:+.3f}  "
              f"p_fault_mean={rw['p_fault_mean']:.3g}")
    return out


class FaultDetectionLoss(tf.keras.losses.Loss):
    """Class-weighted binary cross-entropy for target fault probabilities."""

    def __init__(self, pos_weight=1.0, **kwargs):
        super().__init__(**kwargs)
        self.pos_weight = tf.constant(float(pos_weight), dtype=tf.float32)

    def call(self, y_true, y_pred):
        y_true = tf.cast(tf.reshape(y_true, tf.shape(y_pred)), tf.float32)
        labelled = tf.cast(y_true >= 0.0, tf.float32)
        y = tf.clip_by_value(y_true, 0.0, 1.0)
        p = tf.clip_by_value(y_pred, 1e-7, 1.0 - 1e-7)
        bce = -(self.pos_weight * y * tf.math.log(p)
                + (1.0 - y) * tf.math.log(1.0 - p))
        return tf.math.reduce_sum(bce * labelled) / (
            tf.math.reduce_sum(labelled) + 1e-8)


