_FEATURE_NAME_RE = None      # compiled on first call


def create_tabular_features(df, target_vars, config=None,
                            exog_vars=None, return_delta=False,
                            return_health=False):
    """Build causal lagged, rolling, differenced, calendar, and health features."""
    import re as _re
    global _FEATURE_NAME_RE
    if _FEATURE_NAME_RE is None:
        _FEATURE_NAME_RE = _re.compile(
            r'(_lag_\d+|_roll_(mean|std|min|max)_\d+|_ewm_mean_\d+'
            r'|_diff_\d+|_diff\d+_lag1'
            # shifted series, so admitting them to the convention does not
            # weaken the leak assertion -- it records that they were audited.
            r'|_cusum_pos_lag1|_cusum_neg_lag1|_ewma_resid_lag1'
            r'|_tstat_resid_lag1|_signrun_lag1|_sdratio_lag1|_repeat_lag1'
            r'|_consensus_resid_lag1|_sat_resid_lag1)$'
        )
    _CALENDAR = {'hour', 'dayofweek', 'dayofyear', 'hour_sin', 'hour_cos',
                 'doy_sin', 'doy_cos'}

    df_feat = df.copy()
    df_feat['hour'] = df_feat.index.hour
    df_feat['dayofweek'] = df_feat.index.dayofweek
    df_feat['dayofyear'] = df_feat.index.dayofyear
    # Cyclical encodings: hour 23 and hour 0 are adjacent in time but maximally
    # far apart as integers, which costs a tree extra splits to recover.
    df_feat['hour_sin'] = np.sin(2 * np.pi * df_feat.index.hour / 24.0)
    df_feat['hour_cos'] = np.cos(2 * np.pi * df_feat.index.hour / 24.0)
    # zero-variance and the only usable periodicity is annual.
    df_feat['doy_sin'] = np.sin(2 * np.pi * df_feat.index.dayofyear / 365.25)
    df_feat['doy_cos'] = np.cos(2 * np.pi * df_feat.index.dayofyear / 365.25)

    if exog_vars is None:
        exog_vars = [c for c in df.columns
                     if c not in target_vars
                     and not _is_battery_voltage_column(c)]
    else:
        exog_vars = [c for c in exog_vars
                     if not _is_battery_voltage_column(c)]
    all_channels = list(target_vars) + [c for c in exog_vars if c in df.columns]

    _lags = _lags_of(config) if config is not None else [1, 2, 3, 6, 12, 24, 48, 72]
    _rolls = _roll_windows_of(config) if config is not None else [6, 12, 24]
    _spd = int(getattr(config, '_steps_per_day', 24)) if config is not None else 24
    _ewm_spans = sorted(set([max(2, _rolls[len(_rolls) // 2]), max(2, _spd)]))
    _seas_diff = max(2, _spd if _spd > 1 else 7)

    for var in all_channels:
        for lag in _lags:
            df_feat[f'{var}_lag_{lag}'] = df_feat[var].shift(lag)
        for window in _rolls:
            df_feat[f'{var}_roll_mean_{window}'] = df_feat[var].shift(1).rolling(window=window).mean()
            df_feat[f'{var}_roll_std_{window}'] = df_feat[var].shift(1).rolling(window=window).std()
            df_feat[f'{var}_roll_min_{window}'] = df_feat[var].shift(1).rolling(window=window).min()
            df_feat[f'{var}_roll_max_{window}'] = df_feat[var].shift(1).rolling(window=window).max()
        for span in _ewm_spans:
            df_feat[f'{var}_ewm_mean_{span}'] = df_feat[var].shift(1).ewm(span=span).mean()
        
        # local slope from lag differences at every split; giving it the
        # increment directly is what makes the differenced target learnable.
        df_feat[f'{var}_diff_1'] = df_feat[var].diff(1).shift(1)
        # week on daily data), not a fixed 24 rows.
        df_feat[f'{var}_diff_{_seas_diff}'] = df_feat[var].diff(_seas_diff).shift(1)

    # ------------------------------------------------------------------ R16-C
    _health_cols = []
    if config is not None and getattr(config, 'USE_HEALTH_FEATURES', False):
        _tr_end, _, _ = _raw_split_boundaries(config, len(df))
        _H = build_health_features(df, target_vars, config, train_end_idx=_tr_end)
        _health_cols = list(_H.columns)
        for c in _health_cols:
            df_feat[c] = _H[c].values

    df_feat = df_feat.dropna()

    y = df_feat[list(target_vars)]
    X = df_feat.drop(columns=[c for c in df.columns if c in df_feat.columns])

    bad = [c for c in X.columns
           if c not in _CALENDAR and not _FEATURE_NAME_RE.search(str(c))]
    if bad:
        raise AssertionError(
            f"[R15-C] create_tabular_features: {len(bad)} feature column(s) do "
            f"not match the lag/roll/ewm/diff/calendar convention and may carry "
            f"contemporaneous information: {bad[:12]}. Either build them with an "
            f"explicit .shift() and a conforming name, or drop them.")

    out = [X, y]
    if return_delta:
        lag1 = pd.DataFrame(
            {v: df_feat[f'{v}_lag_1'] for v in target_vars}, index=df_feat.index)
        out.append(lag1)
    if return_health:
        out.append(X[[c for c in _health_cols if c in X.columns]])
    return tuple(out) if len(out) > 2 else (X, y)


def create_m2p_features(df, all_vars, time_vars, config):
    X_short, X_long, indices = [], [], []
    for i in range(config.LONG_WINDOW_SIZE, len(df)):
        X_short.append(df[all_vars + time_vars].iloc[i-config.SHORT_WINDOW_SIZE:i].values)
        X_long.append(df[all_vars].iloc[i-config.LONG_WINDOW_SIZE:i].values)
        indices.append(df.index[i])
    return {'short_term_input': np.array(X_short), 'long_term_input': np.array(X_long)}, indices


def calculate_mase(y_true, y_pred, y_train, seasonality=None):
    """Internal experiment utility."""
    if seasonality is None:
        seasonality = 24
    seasonality = max(1, int(seasonality))
    mae = np.mean(np.abs(y_true - y_pred))
    if len(y_train) <= seasonality:
        mae_naive = np.mean(np.abs(np.diff(y_train)))
    else:
        mae_naive = np.mean(np.abs(y_train[seasonality:] - y_train[:-seasonality]))
    if mae_naive < 1e-10:
        return np.inf
    return mae / mae_naive


def calculate_mase_h1(y_true, y_pred, y_train):
    """Internal experiment utility."""
    y_train = np.asarray(y_train, dtype=float)
    y_train = y_train[np.isfinite(y_train)]
    if len(y_train) < 2:
        return np.nan
    mae = np.mean(np.abs(np.asarray(y_true, dtype=float)
                         - np.asarray(y_pred, dtype=float)))
    mae_naive = np.mean(np.abs(np.diff(y_train)))
    if mae_naive < 1e-10:
        return np.inf
    return mae / mae_naive


