def _one_sided_cusum(z, k):
    """Internal experiment utility."""
    z = np.asarray(z, dtype=float)
    n = len(z)
    sp = np.zeros(n)
    sn = np.zeros(n)
    p = 0.0
    m = 0.0
    for i in range(n):
        zi = z[i]
        if not np.isfinite(zi):
            zi = 0.0
        p = max(0.0, p + zi - k)
        m = max(0.0, m - zi - k)
        sp[i] = p
        sn[i] = m
    return sp, sn


def _signed_run_length(x):
    """Internal experiment utility."""
    s = np.sign(np.nan_to_num(np.asarray(x, dtype=float)))
    out = np.zeros(len(s))
    run = 0.0
    prev = 0.0
    for i, si in enumerate(s):
        if si == 0:
            run = 0.0
        elif si == prev:
            run += si
        else:
            run = si
        out[i] = run
        prev = si
    return out


def _repeat_run_length(x):
    """Internal experiment utility."""
    v = np.asarray(x, dtype=float)
    out = np.zeros(len(v))
    run = 0.0
    for i in range(1, len(v)):
        if np.isfinite(v[i]) and np.isfinite(v[i - 1]) and v[i] == v[i - 1]:
            run += 1.0
        else:
            run = 0.0
        out[i] = run
    return out


def do_saturation_mgl(temp_c, salinity_psu=0.0):
    """Internal experiment utility."""
    t = np.asarray(temp_c, dtype=float)
    tk = t + 273.15
    tk = np.where(np.isfinite(tk) & (tk > 0), tk, np.nan)
    ln_c = (-139.34411
            + 1.575701e5 / tk
            - 6.642308e7 / tk ** 2
            + 1.243800e10 / tk ** 3
            - 8.621949e11 / tk ** 4)
    s = np.asarray(salinity_psu, dtype=float)
    ln_c = ln_c - s * (1.7674e-2 - 1.0754e1 / tk + 2.1407e3 / tk ** 2)
    return np.exp(ln_c)


def build_drift_bank(df, channel, per_day, config, health_channel=None,
                     max_history_rows=None):
    """Build causal multi-scale drift-evidence features."""
    if channel not in df.columns:
        return pd.DataFrame(index=df.index)

    windows = tuple(getattr(config, 'R17_DRIFT_WINDOWS_DAYS', (1, 3, 7, 14)))
    v = pd.to_numeric(df[channel], errors='coerce').astype(float)
    s = v.shift(1)
    # Window admissibility is a property of the TRAINING history.  Using the
    # full series allowed a window that exists only because validation/test
    # rows were counted when deciding the feature layout.
    n = int(max_history_rows) if max_history_rows is not None else len(v)
    f = {}

    for W in windows:
        w = int(round(W * per_day))
        if w < 2 or w > max(n // 4, 2):
            continue
        mp = max(w // 2, 2)
        ewma = s.ewm(span=w, adjust=False).mean()
        dep = s - ewma
        f[f'r17_ewma_dep_{W}d'] = dep
        f[f'r17_cusum_{W}d'] = dep.rolling(w, min_periods=mp).sum()
        f[f'r17_med_dep_{W}d'] = s - s.rolling(w, min_periods=mp).median()
        short = max(int(round(per_day)), 2)
        f[f'r17_sd_ratio_{W}d'] = (
            s.rolling(short, min_periods=2).std()
            / (s.rolling(w, min_periods=mp).std() + 1e-9))

    if per_day >= 24:
        d = int(round(per_day))
        amp = (s.rolling(d, min_periods=max(d // 2, 2)).max()
               - s.rolling(d, min_periods=max(d // 2, 2)).min())
        f['r17_diel_amp'] = amp
        f['r17_diel_atten'] = amp / (
            amp.rolling(7 * d, min_periods=d).median() + 1e-9)

    others = [c for c in df.columns
              if c != channel and c != health_channel
              and pd.api.types.is_numeric_dtype(df[c])]
    if others:
        # CAUSAL z-scores: EXPANDING statistics, never whole-series.  The
        # first version of this bank used .mean()/.std() over the full
        # series and leaked the future into every row from index 1 onward.
        # verify_leak_free() caught it; the failure is invisible in ordinary
        # train/test metrics, which is precisely why the check is in CI.
        def _cz(col):
            m_ = col.expanding(min_periods=2).mean()
            sd_ = col.expanding(min_periods=2).std()
            return (col - m_) / (sd_ + 1e-9)
        z = df[others].shift(1).apply(_cz)
        f['r17_consensus_resid'] = _cz(s) - z.mean(axis=1)

    if health_channel and health_channel in df.columns:
        h = pd.to_numeric(df[health_channel], errors='coerce').astype(float).shift(1)
        f['r17_health_level'] = h
        f['r17_health_dep_7d'] = h - h.ewm(
            span=max(int(round(7 * per_day)), 2), adjust=False).mean()

    out = pd.DataFrame(f, index=df.index)
    return out.replace([np.inf, -np.inf], np.nan)


def verify_leak_free(df, channel, per_day, config, t_probe=None,
                     magnitude=1e6, verbose=True):
    """Verify that causal drift-bank features do not depend on future values."""
    t = int(t_probe if t_probe is not None else len(df) // 2)
    if channel not in df.columns or t <= 1 or t >= len(df) - 1:
        return True, 0.0, -1
    b0 = build_drift_bank(df, channel, per_day, config)
    if b0.shape[1] == 0:
        return True, 0.0, -1
    d2 = df.copy()
    d2.iloc[t, d2.columns.get_loc(channel)] = (
        float(d2.iloc[t][channel]) + magnitude)
    b1 = build_drift_bank(d2, channel, per_day, config)
    diff = (b1 - b0).abs().fillna(0.0).sum(axis=1).values
    max_before = float(np.nanmax(diff[:t + 1])) if t + 1 > 0 else 0.0
    nz = np.nonzero(diff > 1e-9)[0]
    first = int(nz[0]) if nz.size else -1
    ok = max_before <= 1e-9
    if verbose:
        status = "PASS" if ok else "FAIL"
        print(f"    [R17 leak] {channel}: {status} "
              f"max|d| at rows<=t {max_before:.3g}, first affected row {first} "
              f"(probe t={t})")
    if not ok:
        raise AssertionError(
            f"[R17] drift bank leaks future information on '{channel}': "
            f"perturbation at t={t} changed features at row {first}.")
    return ok, max_before, first


def accumulated_bias_target(y, W, valid_mask=None):
    """Internal experiment utility."""
    y = np.asarray(y, dtype=float)
    W = max(int(W), 1)
    b = np.full(y.shape[0], np.nan, dtype=float)
    if y.shape[0] > W:
        b[W:] = y[W:] - y[:-W]
    if valid_mask is not None:
        m = np.asarray(valid_mask).astype(bool)
        bad = ~m
        b[bad] = np.nan
        if b.shape[0] > W:
            b[W:][bad[:-W]] = np.nan
    return b


def channel_tau(y_train, kappa=3.0, floor=1e-6, kappa_level=None):
    """Compute a train-only target-specific correction bound."""
    y = np.asarray(y_train, dtype=float)
    y = y[np.isfinite(y)]
    if y.size < 3:
        return float(floor)
    d = np.diff(y)
    d = d[np.isfinite(d)]
    if d.size == 0:
        return float(floor)
    mad = 1.4826 * float(np.median(np.abs(d - np.median(d))))
    tau_innov = kappa * mad
    tau_level = 0.0
    if kappa_level:
        # The level term uses the STANDARD DEVIATION, not a robust MAD, because
        # `kappa_level` is a specification in SIGMA UNITS -- "the corrector may
        # remove a calibration offset of up to kappa_level sigma of the
        # historical level" -- and a calibration step is conventionally quoted
        # that way. Using MAD here silently rescales that specification on
        # heavy-tailed channels: on this station's EC, std/MAD = 3.51, so a
        # MAD-based bound of 26.0 uS/cm was still 14x short of a 2-sigma step
        # (365.6) while the three near-Gaussian channels (ratio 1.00, 0.96,
        # 1.02) were unaffected. The bound and the fault must be in the same
        # units or the constraint means something different per channel.
        lstd = float(np.std(y))
        tau_level = float(kappa_level) * lstd
    return float(max(tau_innov, tau_level, floor))


def rescue_ratio(y_true, y_anchor, y_corrected, drift_mask):
    """Compute correction rescue relative to the matched anchor on degraded rows."""
    m = np.asarray(drift_mask).astype(bool)
    yt = np.asarray(y_true, float)
    ya = np.asarray(y_anchor, float)
    yc = np.asarray(y_corrected, float)
    ok = m & np.isfinite(yt) & np.isfinite(ya) & np.isfinite(yc)
    if ok.sum() == 0:
        return float('nan')
    den = float(np.mean(np.abs(yt[ok] - ya[ok])))
    if not np.isfinite(den) or den <= 1e-12:
        return float('nan')
    num = float(np.mean(np.abs(yt[ok] - yc[ok])))
    return float(1.0 - num / den)


def evaluate_rescue_acceptance(curve_df, null_tol=0.02):
    """Evaluate the prespecified rescue-curve acceptance criteria."""
    _all = curve_df.dropna(subset=['rescue']).sort_values('intensity')
    if _all.empty:
        return dict(monotone=None, positive=None, null_ok=None,
                    accepted=None, note='no evaluable intensities')

    # ------------------------------------------------------------------ R18
    # (c) IS EVALUATED ON THE FULL CURVE, BEFORE THE ABSTENTION FILTER.
    #
    # The abstention filter below is correct for (a) and (b) -- a row where no
    # correction ran is not evidence that the corrector rescues -- but applying
    # it to (c) inverted the null control's logic. At I=0 a well-behaved
    # corrector SHOULD abstain; the filter then dropped the I=0 row, z.size
    # became 0, and null_ok came back None, so the very behaviour the criterion
    
    # null=None for this reason, and the gate REJECTed for want of evidence
    # rather than because of evidence. R(0) == 0 from abstention is a PASS:
    # nothing was injected and nothing was changed.
    _z = _all['rescue'].values[np.isclose(_all['intensity'].values, 0.0)]
    null_val = float(_z[0]) if _z.size else float('nan')
    null_ok = bool(abs(null_val) <= null_tol) if _z.size else None

    d = _all
    if 'max_abs_correction' in d.columns:
        # Abstained points carry R = 0 by construction and are not evidence
        # about the corrector in either direction; excluding them keeps the
        # monotonicity test from being satisfied by rows where nothing ran.
        d = d[d['max_abs_correction'] > 0]
    if d.empty:
        return dict(monotone=None, positive=None, null_ok=null_ok,
                    null_rescue=null_val, accepted=False,
                    note='corrector abstained at every tested intensity')
    r = d['rescue'].values
    ii = d['intensity'].values
    monotone = bool(np.all(np.diff(r) >= -1e-9))

    # ------------------------------------------------------------------ R18
    # (b) HAS NO FIXED INTENSITY THRESHOLD, BECAUSE `intensity` HAS NO FIXED
    # UNIT ACROSS ARMS.
    #
    # `hi = r[ii >= 1.0]` was written for sudden_shift, where intensity is in
    # sigma units and I>=1 means "at or above the noise floor". In the
    # gradual_bias arm intensity is a ramp slope as a FRACTION of the mean
    # level, tested over 0.05-0.20, so no point ever reached 1.0, hi was empty,
    # and positive came back None for that arm on every run -- the criterion
    # silently never applied to the arm the corrector actually works on.
    #
    # The unit-free equivalent of "drift at or above the noise floor" is: at
    # every intensity where the corrector CHOSE to act, acting must have helped,
    # and it must act at the largest intensity tested (a corrector that abstains
    # on the worst drift in the sweep has not demonstrated rescue).
    positive = bool(np.all(r > 0)) and bool(
        np.isclose(ii.max(), float(_all['intensity'].max())))
    # with fault intensity. A robust corrector may compensate a stronger fault
    # more effectively. Monotonicity is retained as descriptive telemetry; the
    # stress HARNESS is validated separately on the matched differenced-target
    # XGBoost + drift-bank anchor in R4.
    accepted = bool((positive is True) and (null_ok is True))
    return dict(monotone=monotone, positive=positive, null_ok=null_ok,
                null_rescue=null_val, accepted=accepted,
                note='' if accepted else
                     'FAILS null control' if null_ok is False else
                     'acted but did not help, or abstained at max intensity'
                     if positive is False else
                     'incomplete criteria')


def build_health_features(df, target_vars, config, train_end_idx=None,
                          verbose=False):
    """Build causal sensor-health features from training and past observations."""
    if not getattr(config, 'USE_HEALTH_FEATURES', True):
        return pd.DataFrame(index=df.index)

    # None means "derive from this dataset's cadence" -- the Config default, so a
    # daily file gets daily-scale accumulation windows rather than hourly ones.
    win_s = getattr(config, 'HEALTH_SHORT_WINDOW', None)
    win_s = int(win_s) if win_s else int(max(3, _roll_windows_of(config)[0]))
    win_l = getattr(config, 'HEALTH_LONG_WINDOW', None)
    win_l = int(win_l) if win_l else int(max(win_s + 2,
                                            _roll_windows_of(config)[-1]))
    k_slack = float(getattr(config, 'HEALTH_CUSUM_K', 0.5))
    ewma_alpha = float(getattr(config, 'HEALTH_EWMA_ALPHA', 0.1))

    if train_end_idx is None:
        train_end_idx = int(len(df) * getattr(config, 'TRAIN_SPLIT', 0.7))
    train_end_idx = int(max(win_l + 2, min(train_end_idx, len(df))))

    H = pd.DataFrame(index=df.index)
    channels = [v for v in target_vars if v in df.columns]

    for v in channels:
        s = pd.to_numeric(df[v], errors='coerce')
        # The residual of the naive one-step forecast, made causal: the value at
        # row t is the error the model would have made at t-1, so no part of
        # row t's observation enters row t's feature.
        resid = s.diff(1).shift(1)
        scale = resid.rolling(win_l, min_periods=win_s).std()
        # Training-window fallback scale so early rows are not divided by NaN.
        base_scale = float(np.nanstd(resid.iloc[:train_end_idx].values))
        if not np.isfinite(base_scale) or base_scale <= 0:
            base_scale = 1.0
        scale = scale.fillna(base_scale).replace(0.0, base_scale)
        z = (resid / scale).values

        sp, sn = _one_sided_cusum(z, k_slack)
        H[f'{v}_cusum_pos_lag1'] = sp
        H[f'{v}_cusum_neg_lag1'] = sn
        H[f'{v}_ewma_resid_lag1'] = pd.Series(
            z, index=df.index).ewm(alpha=ewma_alpha, adjust=False).mean().values
        rm = pd.Series(z, index=df.index).rolling(win_l, min_periods=win_s).mean()
        rs = pd.Series(z, index=df.index).rolling(win_l, min_periods=win_s).std()
        # R34D: zero rolling variance is a SENSOR-HEALTH STATE, not missing data.
        # A perfectly flat standardized residual has rm=0 and rs=0; encode its
        # t-statistic as 0 instead of NaN.  For the rare rs=0, rm!=0 case use a
        # positive scale estimated from TRAINING ONLY so no validation/test
        # information enters the denominator.
        _rs_train = pd.to_numeric(rs.iloc[:train_end_idx], errors='coerce')
        _rs_pos = _rs_train[np.isfinite(_rs_train.values) & (_rs_train.values > 0)]
        _rs_floor = float(np.nanmedian(_rs_pos.values)) if len(_rs_pos) else 1.0
        if not np.isfinite(_rs_floor) or _rs_floor <= 0:
            _rs_floor = 1.0
        _rs_safe = rs.copy()
        _flat = (rm.fillna(0.0).abs() <= 1e-12) & (rs.fillna(0.0).abs() <= 1e-12)
        _rs_safe = _rs_safe.mask(_rs_safe <= 1e-12, _rs_floor)
        _tstat = rm / _rs_safe
        _tstat = _tstat.mask(_flat, 0.0)
        H[f'{v}_tstat_resid_lag1'] = _tstat.values
        H[f'{v}_signrun_lag1'] = _signed_run_length(z)

        sd_s = s.shift(1).rolling(win_s, min_periods=2).std()
        sd_l = s.shift(1).rolling(win_l, min_periods=win_s).std()
        # Same principle for the short/long variability ratio.  0/0 during a
        # truly stuck episode is encoded as 0 (no short-term variability), while
        # a non-zero numerator over a zero denominator uses a TRAINING-ONLY floor.
        _sdl_train = pd.to_numeric(sd_l.iloc[:train_end_idx], errors='coerce')
        _sdl_pos = _sdl_train[np.isfinite(_sdl_train.values) & (_sdl_train.values > 0)]
        _sdl_floor = float(np.nanmedian(_sdl_pos.values)) if len(_sdl_pos) else 1.0
        if not np.isfinite(_sdl_floor) or _sdl_floor <= 0:
            _sdl_floor = 1.0
        _sdl_safe = sd_l.copy().mask(sd_l <= 1e-12, _sdl_floor)
        _sdr = sd_s / _sdl_safe
        _both_flat = (sd_s.fillna(0.0).abs() <= 1e-12) & (sd_l.fillna(0.0).abs() <= 1e-12)
        _sdr = _sdr.mask(_both_flat, 0.0)
        H[f'{v}_sdratio_lag1'] = _sdr.values
        H[f'{v}_repeat_lag1'] = _repeat_run_length(s.shift(1).values)

    # --------------------------------------------------------------- consensus
    # Analytical redundancy. Fit on the training window only.
    if len(channels) >= 2 and getattr(config, 'USE_CONSENSUS_FEATURE', True):
        from sklearn.linear_model import Ridge
        lag1 = pd.DataFrame({v: pd.to_numeric(df[v], errors='coerce').shift(1)
                             for v in channels}, index=df.index)
        for v in channels:
            others = [c for c in channels if c != v]
            Xc = lag1[others]
            yc = lag1[v]
            fit_rows = np.arange(len(df)) < train_end_idx
            ok = fit_rows & Xc.notna().all(axis=1).values & yc.notna().values
            if int(ok.sum()) < max(20, 3 * len(others)):
                H[f'{v}_consensus_resid_lag1'] = np.nan
                continue
            mu = Xc.values[ok].mean(axis=0)
            sd = Xc.values[ok].std(axis=0)
            sd = np.where(sd > 0, sd, 1.0)
            ymu = float(yc.values[ok].mean())
            ysd = float(yc.values[ok].std()) or 1.0
            rg = Ridge(alpha=float(getattr(config, 'CONSENSUS_RIDGE_ALPHA', 1.0)))
            rg.fit((Xc.values[ok] - mu) / sd, (yc.values[ok] - ymu) / ysd)
            Xz = (Xc.values - mu) / sd
            pred = np.full(len(df), np.nan)
            good = np.isfinite(Xz).all(axis=1)
            if good.any():
                pred[good] = rg.predict(Xz[good]) * ysd + ymu
            # Standardised by the TRAINING residual scale, so the feature is
            # comparable across channels and thresholds transfer.
            r = yc.values - pred
            rsd = float(np.nanstd(r[ok])) or 1.0
            H[f'{v}_consensus_resid_lag1'] = r / rsd

    # ------------------------------------------------------- DO saturation
    do_col = next((c for c in ('dissolved oxygen', 'disolved oxygen')
                   if c in df.columns), None)
    if (do_col is not None and 'temperature' in df.columns
            and getattr(config, 'USE_DO_SATURATION_FEATURE', True)):
        do_lag = pd.to_numeric(df[do_col], errors='coerce').shift(1)
        t_lag = pd.to_numeric(df['temperature'], errors='coerce').shift(1)
        sat = do_saturation_mgl(t_lag.values)
        with np.errstate(invalid='ignore', divide='ignore'):
            H[f'{do_col}_sat_resid_lag1'] = do_lag.values - sat

    H = H.replace([np.inf, -np.inf], np.nan)

    # R34D finite-health contract.  Health statistics can be mathematically
    # undefined at start-up, on an exactly flat sensor, or when a consensus
    # regressor has insufficient TRAINING support.  Those conditions must not
    # delete whole chronological validation/test blocks via the downstream
    # global dropna().  In the challenged-only confirmation, replace remaining
    # undefined DERIVED health values with a neutral value estimated from the
    # TRAINING slice only (median; 0 when the feature has no training support).
    # Raw target labels are never filled here.
    if bool(getattr(config, 'R34_CHALLENGED_ONLY', False)):
        _finite_diag = {}
        _tr_stop = int(max(1, min(train_end_idx, len(H))))
        for _c in list(H.columns):
            _hs = pd.to_numeric(H[_c], errors='coerce').replace([np.inf, -np.inf], np.nan)
            _n_before = int(_hs.isna().sum())
            if _n_before:
                _tr_vals = _hs.iloc[:_tr_stop].dropna().values.astype(float)
                _fallback = float(np.nanmedian(_tr_vals)) if len(_tr_vals) else 0.0
                if not np.isfinite(_fallback):
                    _fallback = 0.0
                _hs = _hs.fillna(_fallback)
                _finite_diag[str(_c)] = {
                    'filled': _n_before,
                    'train_fallback': _fallback,
                }
            H[_c] = _hs.astype(float).values
        _nonfinite = [c for c in H.columns if not np.isfinite(H[c].values).all()]
        if _nonfinite:
            raise RuntimeError(
                '[R34D] health-feature finite contract failed for: ' +
                ', '.join(map(str, _nonfinite[:20])))
        if _finite_diag:
            _top = sorted(_finite_diag.items(), key=lambda kv: kv[1]['filled'], reverse=True)[:12]
            print('    [R34D] finite-health repair (training-only neutral fills): ' +
                  ', '.join(f"{k}={v['filled']}" for k, v in _top))
    if verbose:
        print(f"    [R16-C] health features: {H.shape[1]} columns "
              f"({len(channels)} channels, consensus="
              f"{getattr(config, 'USE_CONSENSUS_FEATURE', True)}, "
              f"do_sat={'yes' if do_col else 'n/a'})")
    return H


def health_feature_columns(H):
    """Internal experiment utility."""
    return [c for c in H.columns if str(c).endswith(_HEALTH_NAME_SUFFIXES)]


