def build_persistence_reference(eval_truth, target_vars, config, verbose=True):
    """Internal experiment utility."""
    cols = [v for v in target_vars if v in eval_truth.columns]
    ref = eval_truth[cols].shift(1)
    # Row 0 has no predecessor. Backfill by one so the frame is finite; the
    # affected row is the first of the SERIES, which lies deep inside the
    # training window and is never scored.
    ref = ref.bfill(limit=1)
    if verbose:
        print(f"    [R16-B] persistence reference built on {len(ref)} rows "
              f"({len(cols)} targets), cadence {_freq_of(config)}.")
    return ref


def apply_physical_guard(pred, target_vars, limits, return_counts=False):
    """Internal experiment utility."""
    was_df = isinstance(pred, pd.DataFrame)
    cols = list(pred.columns) if was_df else list(target_vars)
    arr = pred.values.astype(float).copy() if was_df else \
        np.asarray(pred, dtype=float).copy()
    if arr.ndim == 1:
        arr = arr.reshape(-1, 1)
    n_clipped = 0
    for j, v in enumerate(cols):
        if j >= arr.shape[1]:
            break
        lo, hi = limits.get(v, (-np.inf, np.inf))
        col = arr[:, j]
        fin = np.isfinite(col)
        hit = fin & ((col < lo) | (col > hi))
        n_clipped += int(hit.sum())
        arr[fin, j] = np.clip(col[fin], lo, hi)
    out = pd.DataFrame(arr, index=pred.index, columns=pred.columns) if was_df \
        else arr
    return (out, n_clipped) if return_counts else out


# --- Model Architectures ---

def load_target_exclusions(config, station_hint=None):
    """Load DQA headline exclusions using an exact station identifier."""
    suffix = _validated_mask_suffix(config)
    p = _append_suffix_once(
        os.path.join(config.MASK_DIR, 'target_exclusions.csv'), suffix)
    required = bool(getattr(config, 'REQUIRE_DQA_HANDOFF', True))
    if not os.path.exists(p):
        if required:
            raise FileNotFoundError(
                f"Required DQA exclusion registry is missing: {p}")
        print(f"[DQA] exclusion registry absent (non-release mode): {p}")
        return {}
    if station_hint is None:
        raise ValueError(
            "station_hint is required: exclusions must never be pooled across stations")

    ex = pd.read_csv(p, dtype=str)
    required_cols = {'station_id', 'reason', 'target',
                     'headline_metric_allowed', 'keep_for_fault_analysis'}
    missing = sorted(required_cols - set(ex.columns))
    if missing:
        raise ValueError(f"{p} lacks required columns: {missing}")
    if ex.empty:
        raise ValueError(f"{p} is empty; the audited DQA registry is expected")
    for col in ('headline_metric_allowed', 'keep_for_fault_analysis'):
        ex[col] = _parse_strict_bool(ex[col], f"{p}:{col}")

    key = str(station_hint).strip().casefold()
    ex = ex[ex['station_id'].astype(str).str.strip().str.casefold() == key]
    # Rows explicitly allowed in headline metrics are metadata, not exclusions.
    ex = ex[~ex['headline_metric_allowed']]
    # Gate A writes MULTIPLE targets in one row as a bracketed list --
    # "[disolved oxygen, temperature]" -- because it reports whichever columns
    # went all-NaN together. Parsed naively that becomes a single dict key that
    # matches no column name, so BOTH targets silently escape exclusion and get
    # modelled as all-NaN. Split the list form back into individual targets.
    ren = {'disolved oxygen': 'dissolved oxygen'}
    out = {}
    for _, r in ex.iterrows():
        raw = str(r['target']).strip()
        if raw.startswith('[') and raw.endswith(']'):
            # The DQA writes a Python repr of the list, so the entries arrive
            # QUOTED: "['disolved oxygen', 'temperature']". Splitting on comma
            # alone leaves the quotes attached and the name still matches no
            # column. ast.literal_eval handles the repr exactly; the manual
            # split is the fallback for a bare comma-separated form.
            try:
                names = [str(t).strip() for t in ast.literal_eval(raw)]
            except (ValueError, SyntaxError):
                names = [t.strip().strip('\'"') for t in raw[1:-1].split(',')]
            names = [t for t in names if t]
        else:
            names = [raw]
        for t in names:
            canonical = ren.get(t.strip().casefold(), t.strip().casefold())
            reason = str(r['reason']).strip()
            if canonical in out and out[canonical] != reason:
                raise ValueError(
                    f"Conflicting exclusion reasons for {station_hint}/{canonical}")
            out[canonical] = reason
    return out


def _parse_strict_bool(series, label):
    """Parse only explicit True/False values; never use bool('False')."""
    if series.isna().any():
        raise ValueError(f"{label} contains null Boolean values")
    token = series.astype(str).str.strip().str.casefold()
    bad = sorted(token[~token.isin({'true', 'false'})].unique().tolist())
    if bad:
        raise ValueError(
            f"{label} contains non-Boolean tokens {bad[:8]}; expected True/False")
    return token.map({'true': True, 'false': False}).astype(bool)


def _read_boolean_mask(path, label, required=True):
    """Read and validate one timestamp-indexed Boolean DQA mask."""
    if not os.path.exists(path):
        if required:
            raise FileNotFoundError(f"Required {label} is missing: {path}")
        return None
    raw = _normalise_dqa_columns(pd.read_csv(path, dtype=str))
    if 'timestamp' not in raw.columns:
        raise ValueError(f"{label} {path} lacks the required timestamp column")
    original_ts = raw['timestamp'].copy()
    raw['timestamp'] = pd.to_datetime(raw['timestamp'], errors='coerce')
    if raw['timestamp'].isna().any():
        bad = original_ts[raw['timestamp'].isna()].head(5).tolist()
        raise ValueError(f"{label} {path} has invalid timestamps: {bad}")
    if raw['timestamp'].duplicated().any():
        raise ValueError(f"{label} {path} has duplicate timestamps")
    m = raw.set_index('timestamp')
    if not m.index.is_monotonic_increasing:
        raise ValueError(f"{label} {path} is not sorted by timestamp")
    if m.empty or len(m.columns) == 0:
        raise ValueError(f"{label} {path} is empty")
    for col in m.columns:
        m[col] = _parse_strict_bool(m[col], f"{label}:{col}")
    return m.astype(bool)


def load_fault_mask(file_path, config):
    """Load the aggregate DQA fault mask for the selected IQR variant."""
    if file_path is None:
        return None
    p = _resolve_dqa_artifact_path(file_path, config.FAULT_PREFIX, config)
    required = (bool(getattr(config, 'REQUIRE_DQA_HANDOFF', True)) and
                bool(getattr(config, 'REPORT_FAULT_STRATIFIED', True)))
    m = _read_boolean_mask(p, 'aggregate fault mask', required=required)
    if m is None:
        print(f"[Fault] No fault mask at {p}; stratified metrics skipped.")
        return None
    frac = 100.0 * m.mean()
    print(f"[Fault] Fault mask loaded from {p}. DQA-flagged fraction (%):")
    print(frac[frac > 0].round(2).to_string() if (frac > 0).any() else "  (none)")
    return m


def load_observation_mask(file_path, config):
    """Load the DQA source-retention mask for the selected IQR variant."""
    if file_path is None:
        return None
    mask_path = _resolve_dqa_artifact_path(file_path, config.MASK_PREFIX, config)
    required = (bool(getattr(config, 'REQUIRE_DQA_HANDOFF', True)) and
                bool(getattr(config, 'REPORT_OBSERVED_ONLY', True)))
    m = _read_boolean_mask(mask_path, 'source-retention mask', required=required)
    if m is None:
        print(f"[R3] No source-retention mask at {mask_path}; restricted metrics skipped.")
        return None
    frac = 100.0 * m.mean()
    print(f"[R3] Source-retention mask loaded from {mask_path}. "
          "Non-reconstructed fraction (%):")
    print(frac.round(2).to_string())
    return m


