def set_all_seeds(seed):
    """Internal experiment utility."""
    import random as _random
    _random.seed(seed)
    np.random.seed(seed)
    os.environ['PYTHONHASHSEED'] = str(seed)
    try:
        tf.random.set_seed(seed)
        tf.keras.utils.set_random_seed(seed)
    except Exception as _e:
        print(f"    [seed] TF seeding unavailable: {_e}")


def conformal_correction_bound(cal_residuals, alpha, target_vars, min_n=30):
    """Calibrate a split-conformal bound on correction magnitude."""
    n_t = len(target_vars)
    bounds = np.full(n_t, np.inf)
    diag = {}
    for j, v in enumerate(target_vars):
        s = np.abs(cal_residuals[:, j])
        s = s[np.isfinite(s)]
        n = len(s)
        if n < min_n:
            # Refuse to calibrate on too few points rather than emit a bound
            # that looks principled and is not.
            print(f"    [conformal] '{v}': only {n} calibration points "
                  f"(< {min_n}) -- leaving UNBOUNDED and reporting it.")
            diag[v] = dict(n_cal=n, level=np.nan, bound=np.inf, calibrated=False)
            continue
        
        # applied min(1.0, .), which does not fail loudly -- it silently turns
        # the bound into max(|residual|) and destroys the alpha interpretation.
        # The visible symptom was a bind rate non-monotone in alpha. Refuse.
        level_raw = np.ceil((n + 1) * (1.0 - alpha)) / n
        n_required = int(np.ceil(1.0 / alpha)) - 1
        if level_raw > 1.0:
            print(f"    [conformal] '{v}': alpha={alpha} NOT ATTAINABLE at "
                  f"n={n} (needs n >= {n_required}; level would be "
                  f"{level_raw:.4f} > 1). Leaving UNBOUNDED and reporting it "
                  f"rather than clamping to max|residual|.")
            diag[v] = dict(n_cal=n, level=np.nan, bound=np.inf,
                           calibrated=False, attainable=False,
                           n_required=n_required)
            continue
        level = level_raw
        q = float(np.quantile(s, level, method='higher'))
        bounds[j] = q
        diag[v] = dict(n_cal=n, level=level, bound=q, calibrated=True,
                       attainable=True, n_required=n_required,
                       cal_exceed_rate=float((s > q).mean()))
    return bounds, diag


def write_environment_manifest(config):
    """Internal experiment utility."""
    import platform
    rows = {'python': sys.version.split()[0],
            'platform': platform.platform(),
            'numpy': np.__version__,
            'pandas': pd.__version__}
    for mod, key in [('tensorflow', 'tensorflow'), ('xgboost', 'xgboost'),
                     ('lightgbm', 'lightgbm'), ('sklearn', 'scikit-learn'),
                     ('statsmodels', 'statsmodels'), ('scipy', 'scipy'),
                     ('neuralforecast', 'neuralforecast'), ('prophet', 'prophet'),
                     ('torch', 'torch')]:
        try:
            rows[key] = __import__(mod).__version__
        except Exception:
            rows[key] = 'not installed'
    out = pd.DataFrame(sorted(rows.items()), columns=['component', 'version'])
    p = os.path.join(config.OUTPUT_DIR, 'environment_manifest.csv')
    out.to_csv(p, index=False)
    print("\n[P2] ENVIRONMENT MANIFEST (quote these, not remembered versions):")
    print(out.to_string(index=False))
    return out


def profile_deployment_cost(experiments, config, dataset_name):
    """Internal experiment utility."""
    import platform, subprocess
    rows = []
    try:
        import psutil
        _proc = psutil.Process()
    except Exception:
        _proc = None

    hw = f"{platform.processor() or platform.machine()} / {os.cpu_count()} logical cores"
    try:
        gpu = subprocess.run(['nvidia-smi', '--query-gpu=name',
                              '--format=csv,noheader'],
                             capture_output=True, text=True, timeout=10).stdout.strip()
    except Exception:
        gpu = ''
    gpu = gpu.splitlines()[0] if gpu else 'none detected'

    for exp in experiments:
        name = getattr(exp, 'model_name', str(exp))
        n_par, disk_mb, rss_mb, lat_ms = np.nan, np.nan, np.nan, np.nan
        mdl = getattr(exp, '_last_keras_model', None)
        try:
            if mdl is not None:
                n_par = int(mdl.count_params())
                p = os.path.join(config.OUTPUT_DIR, f'_profile_{name}.h5'.replace(' ', '_'))
                mdl.save(p)
                disk_mb = os.path.getsize(p) / 1e6
                os.remove(p)
                # CPU-only latency, batch size 1, after a warm-up.
                with tf.device('/CPU:0'):
                    shapes = [tuple([1] + list(i.shape[1:])) for i in mdl.inputs]
                    xs = [np.zeros(s, dtype='float32') for s in shapes]
                    for _ in range(5):
                        mdl.predict(xs, verbose=0)
                    if _proc is not None:
                        rss_mb = _proc.memory_info().rss / 1e6
                    t0 = time.time()
                    for _ in range(50):
                        mdl.predict(xs, verbose=0)
                    lat_ms = 1000.0 * (time.time() - t0) / 50.0
        except Exception as e:
            print(f"    [C1] profile failed for '{name}': {e}")
        rows.append(dict(model_name=name, n_parameters=n_par,
                         disk_size_MB=disk_mb, peak_rss_MB=rss_mb,
                         cpu_latency_ms_per_sample=lat_ms,
                         cpu_hardware=hw, gpu_present=gpu,
                         note='CPU-only, batch=1, 50 reps after 5 warm-up'))
    out = pd.DataFrame(rows)
    if len(out):
        out.to_csv(os.path.join(config.OUTPUT_DIR,
                   f'deployment_cost_{dataset_name}.csv'), index=False)
        print(f"    [C1] wrote deployment_cost_{dataset_name}.csv")
    return out


def correction_gate(cal_corrections, cal_baseline_err, target_vars,
                    threshold, quantile=0.90):
    """Internal experiment utility."""
    n_t = len(target_vars)
    diag = {}
    if threshold is None:
        for v in target_vars:
            diag[v] = dict(gate=np.nan, applied=True, reason='gating disabled')
        return np.ones(n_t, dtype=bool), diag

    apply_mask = np.ones(n_t, dtype=bool)
    for j, v in enumerate(target_vars):
        d = np.abs(np.asarray(cal_corrections)[:, j])
        b = np.abs(np.asarray(cal_baseline_err)[:, j])
        d = d[np.isfinite(d)]
        b = b[np.isfinite(b)]
        if len(d) == 0 or len(b) == 0 or not np.isfinite(np.nanmean(b)) \
                or np.nanmean(b) <= 0:
            # Cannot evaluate the rule -> default to CORRECTING, and say so.
            # Defaulting to "skip" would let a missing statistic silently
            # disable the contribution.
            diag[v] = dict(gate=np.nan, applied=True,
                           reason='gate not computable; defaulted to correct')
            continue
        q = float(np.quantile(d, quantile))
        mae_b = float(np.nanmean(b))
        g = q / mae_b
        ok = bool(g > threshold)
        apply_mask[j] = ok
        diag[v] = dict(gate=g, q_corr=q, mae_base_val=mae_b, applied=ok,
                       threshold=threshold, quantile=quantile,
                       reason=('correct' if ok else
                               'declined: correction is noise-scale vs '
                               'baseline error -> exact baseline parity'))
    return apply_mask, diag


def _one_sided_mean_bound(values, confidence=0.95, side='lower'):
    """One-sided Student-t bound on independent validation evidence units."""
    x = np.asarray(values, dtype=float).reshape(-1)
    x = x[np.isfinite(x)]
    n = int(x.size)
    if n == 0:
        return np.nan, np.nan, n
    mean = float(np.mean(x))
    if n < 2:
        return mean, (-np.inf if side == 'lower' else np.inf), n
    sem = float(scipy_stats.sem(x, nan_policy='omit'))
    if not np.isfinite(sem):
        return mean, (-np.inf if side == 'lower' else np.inf), n
    crit = float(scipy_stats.t.ppf(float(confidence), n - 1))
    bound = mean - crit * sem if side == 'lower' else mean + crit * sem
    return mean, float(bound), n


def _contiguous_episode_means(values, mask):
    """Collapse adjacent degraded rows to episode means (the evidence units)."""
    x = np.asarray(values, dtype=float).reshape(-1)
    m = np.asarray(mask, dtype=bool).reshape(-1) & np.isfinite(x)
    out, start = [], None
    for i, active in enumerate(np.r_[m, False]):
        if active and start is None:
            start = i
        elif not active and start is not None:
            out.append(float(np.mean(x[start:i])))
            start = None
    return np.asarray(out, dtype=float)


def _masked_block_means(values, mask, block_len):
    """Create chronological block means without joining across missing rows."""
    x = np.asarray(values, dtype=float).reshape(-1)
    m = np.asarray(mask, dtype=bool).reshape(-1) & np.isfinite(x)
    block_len = max(1, int(block_len))
    out = []
    for start in range(0, len(x), block_len):
        stop = min(len(x), start + block_len)
        keep = m[start:stop]
        if keep.any():
            out.append(float(np.mean(x[start:stop][keep])))
    return np.asarray(out, dtype=float)


def _safety_evidence(pre_error, post_error, degraded, config):
    """Return fail-closed, autocorrelation-aware evidence for one target."""
    pre = np.asarray(pre_error, dtype=float).reshape(-1)
    post = np.asarray(post_error, dtype=float).reshape(-1)
    deg = np.asarray(degraded, dtype=bool).reshape(-1)
    finite = np.isfinite(pre) & np.isfinite(post)
    deg &= finite
    nom = finite & ~deg
    confidence = float(getattr(config, 'R19_SAFETY_CONFIDENCE', 0.95))
    block_len = max(2, min(_seasonality_of(config), max(2, int(finite.sum()) // 4)))

    # Positive gain is beneficial.  Adjacent fault rows are one episode rather
    # than pseudo-independent observations.
    gain = pre - post
    deg_units = _contiguous_episode_means(gain, deg)
    rescue_mean, rescue_lcb, n_deg_units = _one_sided_mean_bound(
        deg_units, confidence=confidence, side='lower')

    # Positive harm is adverse.  Chronological blocks avoid treating serially
    # correlated rows as independent evidence.
    harm = post - pre
    nom_units = _masked_block_means(harm, nom, block_len)
    all_units = _masked_block_means(harm, finite, block_len)
    nom_harm_mean, nom_harm_ucb, n_nom_units = _one_sided_mean_bound(
        nom_units, confidence=confidence, side='upper')
    all_harm_mean, all_harm_ucb, n_all_units = _one_sided_mean_bound(
        all_units, confidence=confidence, side='upper')

    pre_deg = float(np.mean(pre[deg])) if deg.any() else np.nan
    pre_nom = float(np.mean(pre[nom])) if nom.any() else np.nan
    pre_all = float(np.mean(pre[finite])) if finite.any() else np.nan
    post_deg = float(np.mean(post[deg])) if deg.any() else np.nan
    post_nom = float(np.mean(post[nom])) if nom.any() else np.nan
    post_all = float(np.mean(post[finite])) if finite.any() else np.nan
    return dict(
        n=int(finite.sum()), n_degraded=int(deg.sum()), n_nominal=int(nom.sum()),
        n_degraded_units=int(n_deg_units), n_nominal_units=int(n_nom_units),
        n_all_units=int(n_all_units), block_len=int(block_len),
        pre_degraded=pre_deg, post_degraded=post_deg,
        pre_nominal=pre_nom, post_nominal=post_nom,
        pre_all=pre_all, post_all=post_all,
        rescue=rescue_mean, rescue_lcb=rescue_lcb,
        nominal_harm=nom_harm_mean, nominal_harm_ucb=nom_harm_ucb,
        all_harm=all_harm_mean, all_harm_ucb=all_harm_ucb,
        degraded_rescue_rel=(rescue_mean / max(pre_deg, 1e-12)
                             if np.isfinite(rescue_mean) and np.isfinite(pre_deg)
                             else np.nan),
        degraded_rescue_lcb_rel=(rescue_lcb / max(pre_deg, 1e-12)
                                 if np.isfinite(rescue_lcb) and np.isfinite(pre_deg)
                                 else np.nan),
        nominal_penalty_rel=(nom_harm_mean / max(pre_nom, 1e-12)
                             if np.isfinite(nom_harm_mean) and np.isfinite(pre_nom)
                             else np.nan),
        nominal_penalty_ucb_rel=(nom_harm_ucb / max(pre_nom, 1e-12)
                                 if np.isfinite(nom_harm_ucb) and np.isfinite(pre_nom)
                                 else np.nan),
        mae_multiplier=(post_all / max(pre_all, 1e-12)
                        if np.isfinite(post_all) and np.isfinite(pre_all)
                        else np.nan),
        mae_multiplier_ucb=(1.0 + all_harm_ucb / max(pre_all, 1e-12)
                            if np.isfinite(all_harm_ucb) and np.isfinite(pre_all)
                            else np.nan),
    )


def _selector_name_token(value):
    """Normalise a target/context name for robust target-specific matching."""
    return re.sub(r'[^0-9a-z]+', '_', str(value).casefold()).strip('_')


def build_dynamic_selector_features(prob, correction, context, context_cols,
                                    target, config):
    """Build a causal state vector for the train-fitted selective gate.

    Every row uses only quantities available when that row is forecast: the
    current model outputs (p_fault and proposed correction), trailing p_fault
    history, and the already-causal context tensor.  No target truth, fault mask,
    future probability, or future context value enters this feature matrix.
    """
    p = np.asarray(prob, dtype=float).reshape(-1)
    c = np.asarray(correction, dtype=float).reshape(-1)
    ctx = np.asarray(context, dtype=float)
    if ctx.ndim == 1:
        ctx = ctx.reshape(-1, 1)
    if not (len(p) == len(c) == len(ctx)):
        raise ValueError(
            f"[R21] selector feature length mismatch: p={len(p)}, "
            f"correction={len(c)}, context={len(ctx)}")

    ps = pd.Series(p, dtype=float)
    short_span = max(2, int(getattr(config, 'R21_SELECTOR_SHORT_SPAN', 3)))
    long_cfg = getattr(config, 'R21_SELECTOR_LONG_SPAN', None)
    long_span = (max(short_span + 1,
                     min(12, max(4, int(round(_seasonality_of(config) / 4.0)))))
                 if long_cfg is None else max(short_span + 1, int(long_cfg)))

    # Trailing/persistent detector state.  All rolling windows are backward
    # looking and may include the current p_fault, which is itself a causal model
    # output at forecast row t.
    p_lag1 = ps.shift(1).fillna(ps.iloc[0] if len(ps) else 0.0).values
    p_ewma_s = ps.ewm(span=short_span, adjust=False).mean().values
    p_ewma_l = ps.ewm(span=long_span, adjust=False).mean().values
    p_roll_mean = ps.rolling(short_span, min_periods=1).mean().values
    p_roll_min = ps.rolling(short_span, min_periods=1).min().values
    p_delta = p - p_lag1

    cols = [str(x) for x in (context_cols or [])]
    if len(cols) != ctx.shape[1]:
        # Context values are still valid; names are telemetry only.  Do not
        # guess target-specific columns when the persisted layout is absent.
        cols = [f'context_{i}' for i in range(ctx.shape[1])]
    tkn = _selector_name_token(target)
    norm_cols = [_selector_name_token(x) for x in cols]
    target_idx = [i for i, x in enumerate(norm_cols)
                  if x == tkn or x.startswith(tkn + '_')]
    jump_idx = [i for i in target_idx if '_jump_' in ('_' + norm_cols[i] + '_')]

    def _row_abs_mean(indices):
        if not indices:
            return np.zeros(len(ctx), dtype=float)
        return np.nanmean(np.abs(ctx[:, indices]), axis=1)

    def _row_abs_max(indices):
        if not indices:
            return np.zeros(len(ctx), dtype=float)
        return np.nanmax(np.abs(ctx[:, indices]), axis=1)

    ctx_target_mean = _row_abs_mean(target_idx)
    ctx_target_max = _row_abs_max(target_idx)
    ctx_jump_max = _row_abs_max(jump_idx)
    ctx_global_mean = (np.nanmean(np.abs(ctx), axis=1)
                       if ctx.shape[1] else np.zeros(len(ctx), dtype=float))

    # asinh/log1p keep very different physical target scales numerically tame
    # without introducing any fitted operating threshold.
    corr_signed = np.arcsinh(np.nan_to_num(c, nan=0.0))
    corr_abs = np.log1p(np.abs(np.nan_to_num(c, nan=0.0)))
    X = np.column_stack([
        p, p_lag1, p_delta, p_ewma_s, p_ewma_l, p_roll_mean, p_roll_min,
        corr_signed, corr_abs,
        ctx_target_mean, ctx_target_max, ctx_jump_max, ctx_global_mean,
        p * ctx_target_max, p * corr_abs,
    ]).astype(float)
    names = [
        'p_fault', 'p_fault_lag1', 'p_fault_delta',
        f'p_fault_ewma_{short_span}', f'p_fault_ewma_{long_span}',
        f'p_fault_mean_{short_span}', f'p_fault_min_{short_span}',
        'correction_asinh', 'correction_logabs',
        'target_context_absmean', 'target_context_absmax',
        'anchor_jump_absmax', 'global_context_absmean',
        'p_x_target_context', 'p_x_correction_abs',
    ]
    X = np.nan_to_num(X, nan=0.0, posinf=1e6, neginf=-1e6)
    return X, names


def verify_dynamic_selector_feature_causality(prob, correction, context,
                                              context_cols, target, config):
    """Prefix-invariance audit for R21's own feature transformation."""
    p = np.asarray(prob, dtype=float).reshape(-1)
    c = np.asarray(correction, dtype=float).reshape(-1)
    x = np.asarray(context, dtype=float)
    if len(p) < 8:
        return True, 0.0
    probe = max(2, len(p) // 2)
    f0, _ = build_dynamic_selector_features(p, c, x, context_cols, target, config)
    p2, c2, x2 = p.copy(), c.copy(), x.copy()
    # Perturb only strictly FUTURE rows.  Any change at or before `probe`
    # therefore proves that the selector transformation itself leaks backward.
    p2[probe + 1:] = np.clip(p2[probe + 1:] * 0.01 + 0.97, 0.0, 1.0)
    c2[probe + 1:] = c2[probe + 1:] + 1e4
    if x2.ndim == 2 and x2.shape[1]:
        x2[probe + 1:, :] = x2[probe + 1:, :] + 1e4
    f1, _ = build_dynamic_selector_features(p2, c2, x2, context_cols, target, config)
    max_before = float(np.max(np.abs(f1[:probe + 1] - f0[:probe + 1])))
    if max_before > 1e-10:
        raise AssertionError(
            f"[R21] selector feature leakage for '{target}': future perturbation "
            f"changed prefix features by {max_before:.3g}.")
    return True, max_before


def build_r30_health_state_features(context, context_cols, target):
    """Return target-specific CAUSAL health-state features only.

    Deliberately excludes p_fault and proposed correction magnitude.  The input
    context has already been built causally and standardised on TRAIN only by
    PTACExperiment.  We keep only target-specific sensor-health, multi-scale
    drift-bank, and lagged anchor-reliability evidence.
    """
    X = np.asarray(context, dtype=float)
    if X.ndim == 1:
        X = X.reshape(-1, 1)
    cols = [str(c) for c in (context_cols or [])]
    if len(cols) != X.shape[1]:
        raise ValueError(f"[R30] context name/width mismatch: {len(cols)} != {X.shape[1]}")
    tkn = _selector_name_token(target)
    keep_idx, keep_names = [], []
    health_tokens = (
        'cusum', 'ewma', 'tstat', 'signrun', 'sdratio', 'sd_ratio',
        'repeat', 'consensus', 'sat_resid', 'r17_', 'jump_'
    )
    for i, c in enumerate(cols):
        n = _selector_name_token(c)
        target_specific = (n == tkn or n.startswith(tkn + '_'))
        health_like = any(tok in n for tok in health_tokens)
        if target_specific and health_like:
            keep_idx.append(i); keep_names.append(c)
    if not keep_idx:
        # Fail loudly rather than silently train a detector on arbitrary level
        # features. This is a structural experiment, not a fishing expedition.
        raise ValueError(f"[R30] no target-specific causal health features for {target}")
    Z = X[:, keep_idx].astype(float)
    Z = np.nan_to_num(Z, nan=0.0, posinf=1e6, neginf=-1e6)
    return Z, keep_names


def _r30_fit_models(X, y, observed, config, target='target'):
    """Fit the three predeclared TRAIN-only health classifiers."""
    X = np.asarray(X, dtype=float)
    y = np.asarray(y, dtype=bool).reshape(-1)
    obs = np.asarray(observed, dtype=bool).reshape(-1)
    finite = np.isfinite(X).all(axis=1) & obs
    Xf, yf = X[finite], y[finite].astype(int)
    n, npos = int(len(yf)), int(yf.sum()); nneg = int(n - npos)
    min_n = int(getattr(config, 'R30_MIN_TRAIN', 48))
    min_pos = int(getattr(config, 'R30_MIN_TRAIN_POS', 6))
    min_neg = int(getattr(config, 'R30_MIN_TRAIN_NEG', 12))
    diag = dict(target=str(target), n_train=n, n_pos=npos, n_neg=nneg)
    if n < min_n or npos < min_pos or nneg < min_neg:
        diag['reason'] = f'underpowered train labels n={n}, pos={npos}, neg={nneg}'
        return {}, diag

    rs = int(getattr(config, '_active_rescue_seed', getattr(config, 'SEED', 42)))
    sc = StandardScaler().fit(Xf)
    Xs = sc.transform(Xf)
    models = {}

    lr = LogisticRegression(C=1.0, class_weight='balanced', solver='lbfgs',
                            max_iter=1000, random_state=rs)
    lr.fit(Xs, yf)
    models['logistic'] = (sc, lr)

    mlp = MLPClassifier(hidden_layer_sizes=(32,), activation='relu', solver='adam',
                        alpha=1e-4, learning_rate_init=1e-3, max_iter=300,
                        early_stopping=False, random_state=rs)
    mlp.fit(Xs, yf)
    models['shallow_mlp'] = (sc, mlp)

    spw = float(nneg / max(npos, 1))
    xgbc = xgb.XGBClassifier(
        objective='binary:logistic', eval_metric='logloss',
        n_estimators=300, max_depth=3, learning_rate=0.05,
        subsample=0.8, colsample_bytree=0.8,
        reg_lambda=1.0, reg_alpha=0.0,
        scale_pos_weight=spw, random_state=rs, n_jobs=4,
        tree_method='hist')
    xgbc.fit(Xs, yf, verbose=False)
    models['xgboost_health'] = (sc, xgbc)
    return models, diag


def _r30_prob(model_pair, X):
    sc, mdl = model_pair
    Xs = sc.transform(np.asarray(X, dtype=float))
    p = mdl.predict_proba(Xs)
    return np.asarray(p[:, 1], dtype=float)


def _r30_select_candidate(models, Xcal, ycal, ocal, config, target='target'):
    """Select one model FAMILY on CAL; probability threshold stays fixed at .5.

    No threshold search.  Among candidates retaining >=50% degraded recall,
    select the lowest nominal false-positive rate; break ties by higher recall,
    then higher balanced accuracy, then fixed model order.
    """
    thr = float(getattr(config, 'R30_DECISION_THRESHOLD', 0.50))
    min_rec = float(getattr(config, 'R30_MIN_CAL_RECALL', 0.50))
    y = np.asarray(ycal, dtype=bool).reshape(-1)
    o = np.asarray(ocal, dtype=bool).reshape(-1)
    pos = o & y; neg = o & ~y
    npos, nneg = int(pos.sum()), int(neg.sum())
    min_pos = int(getattr(config, 'R30_MIN_CAL_POS', 8))
    min_neg = int(getattr(config, 'R30_MIN_CAL_NEG', 8))
    rows = []
    if npos < min_pos or nneg < min_neg:
        return None, rows, f'underpowered CAL pos/neg={npos}/{nneg}'
    order = {'logistic':0, 'shallow_mlp':1, 'xgboost_health':2}
    feasible=[]
    for name, pair in models.items():
        p = _r30_prob(pair, Xcal)
        act = p >= thr
        rec = float(act[pos].mean()) if npos else np.nan
        fpr = float(act[neg].mean()) if nneg else np.nan
        tnr = 1.0 - fpr
        bal = 0.5 * (rec + tnr)
        recrow = dict(target=str(target), candidate=name, threshold=thr,
                      n_cal_pos=npos, n_cal_neg=nneg, recall=rec, fpr=fpr,
                      balanced_accuracy=bal, feasible=bool(np.isfinite(rec) and rec >= min_rec))
        rows.append(recrow)
        if recrow['feasible']:
            feasible.append((fpr, -rec, -bal, order.get(name,99), name))
    if not feasible:
        return None, rows, f'no candidate reached CAL recall >= {min_rec:.2f}'
    feasible.sort()
    return feasible[0][-1], rows, ''

def fit_dynamic_selector(train_features, train_labels, train_observed, config,
                         feature_names=None, target='target'):
    """Fit one auditable train-only selector; fail back to p_fault if weak."""
    X = np.asarray(train_features, dtype=float)
    y = np.asarray(train_labels, dtype=bool).reshape(-1)
    obs = np.asarray(train_observed, dtype=bool).reshape(-1)
    if X.ndim != 2 or len(X) != len(y) or len(y) != len(obs):
        raise ValueError(f"[R21] malformed selector training arrays for {target}")
    finite = np.isfinite(X).all(axis=1) & obs
    Xf, yf = X[finite], y[finite].astype(int)
    n = int(len(yf))
    n_pos = int(yf.sum())
    n_neg = int(n - n_pos)
    min_n = int(getattr(config, 'R21_SELECTOR_MIN_TRAIN', 48))
    min_pos = int(getattr(config, 'R21_SELECTOR_MIN_POS', 6))
    min_neg = int(getattr(config, 'R21_SELECTOR_MIN_NEG', 12))
    diag = dict(target=str(target), n_train=n, n_pos=n_pos, n_neg=n_neg,
                fitted=False, fallback='p_fault', feature_names=list(feature_names or []))
    if n < min_n or n_pos < min_pos or n_neg < min_neg:
        diag['reason'] = (f'underpowered train selector: n={n}/{min_n}, '
                          f'pos={n_pos}/{min_pos}, neg={n_neg}/{min_neg}')
        return None, None, diag

    scaler = StandardScaler().fit(Xf)
    Xs = scaler.transform(Xf)
    clf = LogisticRegression(
        C=float(getattr(config, 'R21_SELECTOR_LOGREG_C', 1.0)),
        class_weight='balanced', solver='lbfgs',
        max_iter=int(getattr(config, 'R21_SELECTOR_MAX_ITER', 1000)),
        random_state=int(getattr(config, 'SEED', 42)))
    clf.fit(Xs, yf)
    diag.update(
        fitted=True, fallback='', reason='train-only state-aware logistic selector',
        intercept=float(clf.intercept_[0]),
        coefficients={str(nm): float(co)
                      for nm, co in zip(feature_names or range(X.shape[1]),
                                        clf.coef_[0])})
    return scaler, clf, diag


def fit_benefit_aware_selector(train_features, correction, base, truth,
                               train_observed, config,
                               feature_names=None, target='target'):
    """TRAIN-only selector aligned with intervention usefulness.

    helpful_t = 1 iff applying the graph's proposed correction reduces
    absolute anchor error. The proposed correction is the ordinary bounded,
    p_fault-gated graph output before R20/R19 post-hoc suppression.

    Rows with exactly zero proposed action are excluded because their selector
    score cannot change the forecast. Threshold selection remains on the
    disjoint CAL block; authorization remains on the unchanged R19 SAFETY block.
    """
    X = np.asarray(train_features, dtype=float)
    c = np.asarray(correction, dtype=float).reshape(-1)
    b = np.asarray(base, dtype=float).reshape(-1)
    y = np.asarray(truth, dtype=float).reshape(-1)
    obs = np.asarray(train_observed, dtype=bool).reshape(-1)
    if not (len(X) == len(c) == len(b) == len(y) == len(obs)):
        raise ValueError(f"[BENEFIT] malformed train arrays for {target}")

    pre = np.abs(y - b)
    post = np.abs(y - (b + c))
    gain = pre - post
    min_action = float(getattr(config, 'BENEFIT_SELECTOR_MIN_ACTION', 1e-12))
    eligible = (obs & np.isfinite(pre) & np.isfinite(post)
                & np.isfinite(c) & (np.abs(c) > min_action))
    helpful = gain > 0.0

    scaler, clf, diag = fit_dynamic_selector(
        X, helpful, eligible, config,
        feature_names=feature_names, target=target)

    ge = gain[eligible]
    diag = dict(diag)
    diag.update(
        selector_objective='correction_benefit',
        n_action_train=int(eligible.sum()),
        helpful_rate=(float(helpful[eligible].mean()) if eligible.any() else np.nan),
        mean_gain=(float(np.mean(ge)) if ge.size else np.nan),
        median_gain=(float(np.median(ge)) if ge.size else np.nan),
        mean_positive_gain=(float(np.mean(ge[ge > 0])) if np.any(ge > 0) else np.nan),
        mean_harm=(float(np.mean(-ge[ge < 0])) if np.any(ge < 0) else np.nan),
    )
    if diag.get('fitted'):
        diag['reason'] = 'train-only correction-benefit logistic selector'
    return scaler, clf, diag


def score_dynamic_selector(features, scaler, model, fallback_prob):
    """Return selector scores, preserving p_fault as the fail-safe fallback."""
    fb = np.clip(np.asarray(fallback_prob, dtype=float).reshape(-1), 0.0, 1.0)
    if scaler is None or model is None:
        return fb
    X = np.asarray(features, dtype=float)
    try:
        return np.clip(model.predict_proba(scaler.transform(X))[:, 1], 0.0, 1.0)
    except Exception:
        return fb


def calibrate_utility_gate_threshold(score, correction, base, truth, degraded,
                                     config, observed=None):
    """Select a validation-only operating threshold on any causal gate score."""
    p = np.asarray(score, dtype=float).reshape(-1)
    c = np.asarray(correction, dtype=float).reshape(-1)
    b = np.asarray(base, dtype=float).reshape(-1)
    y = np.asarray(truth, dtype=float).reshape(-1)
    d = np.asarray(degraded).astype(bool).reshape(-1)
    if observed is None:
        observed = np.ones_like(d, dtype=bool)
    observed = np.asarray(observed, dtype=bool).reshape(-1)
    ok = (np.isfinite(p) & np.isfinite(c) & np.isfinite(b) & np.isfinite(y)
          & observed)
    p, c, b, y, d = p[ok], c[ok], b[ok], y[ok], d[ok]
    min_deg = int(getattr(config, 'R20_MIN_DEGRADED', 8))
    min_nom = int(getattr(config, 'R20_MIN_NOMINAL', 8))
    min_units = int(getattr(config, 'R19_SAFETY_MIN_EVIDENCE_UNITS', 2))
    max_nom = float(getattr(config, 'R20_MAX_NOMINAL_PENALTY_REL', 0.02))
    max_mult = float(getattr(config, 'R20_MAX_MAE_MULTIPLIER', 1.10))
    min_rescue_rel = float(getattr(config, 'R20_MIN_DEGRADED_RESCUE_REL', 0.0))
    n_grid = max(int(getattr(config, 'R20_THRESHOLD_GRID_SIZE', 101)), 11)
    if p.size == 0 or int(d.sum()) < min_deg or int((~d).sum()) < min_nom:
        return dict(threshold=1.000001, feasible=False, n=int(p.size),
                    n_degraded=int(d.sum()), n_nominal=int((~d).sum()),
                    degraded_rescue_rel=np.nan, degraded_rescue_lcb_rel=np.nan,
                    nominal_penalty_rel=np.nan, mae_multiplier=np.nan,
                    reason=(f'underpowered calibration: degraded '
                            f'{int(d.sum())}<{min_deg} or nominal '
                            f'{int((~d).sum())}<{min_nom}'))

    fixed = np.linspace(0.0, 1.0, n_grid)
    qs = np.quantile(p, np.linspace(0.0, 1.0, min(51, max(3, p.size))))
    candidates = np.unique(np.clip(np.r_[fixed, qs, 1.0], 0.0, 1.0))
    pre = np.abs(y - b)
    feasible = []
    telemetry = []
    for t in candidates:
        cc = np.where(p >= t, c, 0.0)
        post = np.abs(y - (b + cc))
        ev = _safety_evidence(pre, post, d, config)
        rescue_rel = ev['degraded_rescue_rel']
        rescue_lcb_rel = ev['degraded_rescue_lcb_rel']
        nom_rel = ev['nominal_penalty_rel']
        nom_ucb_rel = ev['nominal_penalty_ucb_rel']
        mult = ev['mae_multiplier']
        mult_ucb = ev['mae_multiplier_ucb']
        acted = float(np.mean(np.abs(cc) > 1e-12))
        enough_units = (ev['n_degraded_units'] >= min_units
                        and ev['n_nominal_units'] >= min_units)
        good = (enough_units
                and np.isfinite(rescue_lcb_rel)
                and rescue_lcb_rel > min_rescue_rel
                and np.isfinite(nom_ucb_rel) and nom_ucb_rel <= max_nom
                and np.isfinite(mult_ucb) and mult_ucb <= max_mult)
        rec = dict(threshold=float(t), degraded_rescue_rel=float(rescue_rel),
                   degraded_rescue_lcb_rel=float(rescue_lcb_rel),
                   nominal_penalty_rel=float(nom_rel),
                   nominal_penalty_ucb_rel=float(nom_ucb_rel),
                   mae_multiplier=float(mult), mae_multiplier_ucb=float(mult_ucb),
                   n_degraded_units=ev['n_degraded_units'],
                   n_nominal_units=ev['n_nominal_units'],
                   acted_fraction=float(acted), feasible=bool(good))
        telemetry.append(rec)
        if good:
            feasible.append(rec)
    if not feasible:
        
        # because it violated the prespecified nominal/safety constraints.
        best_any = max(telemetry, key=lambda z: (
            np.nan_to_num(z['degraded_rescue_lcb_rel'], nan=-np.inf), z['threshold']))
        return dict(threshold=1.000001, feasible=False, n=int(p.size),
                    n_degraded=int(d.sum()), n_nominal=int((~d).sum()),
                    acted_fraction=0.0,
                    reason=('no threshold passed lower-bound rescue, upper-bound '
                            'nominal harm, and upper-bound total-MAE constraints'),
                    **{k: v for k, v in best_any.items()
                       if k not in {'threshold', 'feasible', 'acted_fraction'}})
    best = max(feasible, key=lambda z: (z['degraded_rescue_lcb_rel'], z['threshold']))
    best = dict(best)
    best.update(n=int(p.size), n_degraded=int(d.sum()), n_nominal=int((~d).sum()),
                reason='confidence-bound utility-feasible')
    return best


def calibrate_point_utility_gate_threshold(score, correction, base, truth, degraded,
                                             config, observed=None):
    """R26: CAL-only point-estimate operating-threshold selection.

    This is deliberately *selection*, not authorization.  It keeps the same
    prespecified R20 degraded/nominal sample floors and the same 2% nominal
    penalty / 1.10 total-MAE limits, but does not demand a confidence bound on
    the calibration block.  The completely disjoint R19 safety block still
    performs the unchanged 95% lower/upper-bound authorization afterwards.
    """
    p = np.asarray(score, dtype=float).reshape(-1)
    c = np.asarray(correction, dtype=float).reshape(-1)
    b = np.asarray(base, dtype=float).reshape(-1)
    y = np.asarray(truth, dtype=float).reshape(-1)
    d = np.asarray(degraded).astype(bool).reshape(-1)
    if observed is None:
        observed = np.ones_like(d, dtype=bool)
    observed = np.asarray(observed, dtype=bool).reshape(-1)
    ok = (np.isfinite(p) & np.isfinite(c) & np.isfinite(b) & np.isfinite(y)
          & observed)
    p, c, b, y, d = p[ok], c[ok], b[ok], y[ok], d[ok]
    min_deg = int(getattr(config, 'R20_MIN_DEGRADED', 8))
    min_nom = int(getattr(config, 'R20_MIN_NOMINAL', 8))
    min_units = int(getattr(config, 'R19_SAFETY_MIN_EVIDENCE_UNITS', 2))
    max_nom = float(getattr(config, 'R20_MAX_NOMINAL_PENALTY_REL', 0.02))
    max_mult = float(getattr(config, 'R20_MAX_MAE_MULTIPLIER', 1.10))
    min_rescue_rel = float(getattr(config, 'R20_MIN_DEGRADED_RESCUE_REL', 0.0))
    n_grid = max(int(getattr(config, 'R20_THRESHOLD_GRID_SIZE', 101)), 11)
    if p.size == 0 or int(d.sum()) < min_deg or int((~d).sum()) < min_nom:
        return dict(threshold=1.000001, feasible=False, n=int(p.size),
                    n_degraded=int(d.sum()), n_nominal=int((~d).sum()),
                    degraded_rescue_rel=np.nan, nominal_penalty_rel=np.nan,
                    mae_multiplier=np.nan, acted_fraction=0.0,
                    reason='underpowered point-estimate calibration')

    fixed = np.linspace(0.0, 1.0, n_grid)
    qs = np.quantile(p, np.linspace(0.0, 1.0, min(51, max(3, p.size))))
    candidates = np.unique(np.clip(np.r_[fixed, qs, 1.0], 0.0, 1.0))
    pre = np.abs(y - b)
    feasible = []
    telemetry = []
    for t in candidates:
        cc = np.where(p >= t, c, 0.0)
        post = np.abs(y - (b + cc))
        ev = _safety_evidence(pre, post, d, config)
        rescue_rel = ev['degraded_rescue_rel']
        nom_rel = ev['nominal_penalty_rel']
        mult = ev['mae_multiplier']
        enough_units = (ev['n_degraded_units'] >= min_units
                        and ev['n_nominal_units'] >= min_units)
        good = (enough_units
                and np.isfinite(rescue_rel) and rescue_rel > min_rescue_rel
                and np.isfinite(nom_rel) and nom_rel <= max_nom
                and np.isfinite(mult) and mult <= max_mult)
        rec = dict(threshold=float(t), degraded_rescue_rel=float(rescue_rel),
                   nominal_penalty_rel=float(nom_rel), mae_multiplier=float(mult),
                   n_degraded_units=ev['n_degraded_units'],
                   n_nominal_units=ev['n_nominal_units'],
                   acted_fraction=float(np.mean(np.abs(cc) > 1e-12)),
                   feasible=bool(good))
        telemetry.append(rec)
        if good:
            feasible.append(rec)
    if not feasible:
        best_any = max(telemetry, key=lambda z: (
            np.nan_to_num(z['degraded_rescue_rel'], nan=-np.inf), z['threshold']))
        out = dict(best_any)
        out.update(threshold=1.000001, feasible=False, n=int(p.size),
                   n_degraded=int(d.sum()), n_nominal=int((~d).sum()),
                   acted_fraction=0.0, reason='no point-estimate utility-feasible threshold')
        return out
    best = max(feasible, key=lambda z: (z['degraded_rescue_rel'], z['threshold']))
    best = dict(best)
    best.update(n=int(p.size), n_degraded=int(d.sum()), n_nominal=int((~d).sum()),
                reason='point-estimate utility-feasible')
    return best


def _r26_safety_pass(ev, config):
    """Apply the exact current R19 target-wise safety acceptance rule."""
    min_deg = int(getattr(config, 'R19_SAFETY_MIN_DEGRADED', 8))
    min_nom = int(getattr(config, 'R19_SAFETY_MIN_NOMINAL', 8))
    min_units = int(getattr(config, 'R19_SAFETY_MIN_EVIDENCE_UNITS', 2))
    min_rescue = float(getattr(config, 'R19_SAFETY_MIN_RESCUE', 0.0))
    max_nom = float(getattr(config, 'R19_SAFETY_MAX_NOMINAL_PENALTY_REL', 0.05))
    max_mult = float(getattr(config, 'R19_SAFETY_MAX_MAE_MULTIPLIER', 1.10))
    reasons = []
    if ev['n_degraded'] < min_deg:
        reasons.append('degraded_n')
    if ev['n_nominal'] < min_nom:
        reasons.append('nominal_n')
    if ev['n_degraded_units'] < min_units:
        reasons.append('degraded_units')
    if ev['n_nominal_units'] < min_units:
        reasons.append('nominal_units')
    if not (np.isfinite(ev['rescue_lcb']) and ev['rescue_lcb'] > min_rescue):
        reasons.append('rescue_lcb')
    if not (np.isfinite(ev['nominal_penalty_ucb_rel'])
            and ev['nominal_penalty_ucb_rel'] <= max_nom):
        reasons.append('nominal_ucb')
    if not (np.isfinite(ev['mae_multiplier_ucb'])
            and ev['mae_multiplier_ucb'] <= max_mult):
        reasons.append('multiplier_ucb')
    return len(reasons) == 0, reasons


def dm_test_hln(e1, e2, h=1, power=1):
    """Compute the Harvey-Leybourne-Newbold corrected Diebold-Mariano test."""
    d = np.abs(e1) ** power - np.abs(e2) ** power
    d = d[np.isfinite(d)]
    n = len(d)
    if n < 10:
        return np.nan, np.nan, n
    dbar = d.mean()
    gamma0 = np.mean((d - dbar) ** 2)
    acc = gamma0
    for k in range(1, h):
        gk = np.mean((d[k:] - dbar) * (d[:-k] - dbar))
        acc += 2.0 * gk
    if acc <= 0:
        return np.nan, np.nan, n
    dm = dbar / np.sqrt(acc / n)
    # HLN correction factor and t reference distribution
    corr = np.sqrt((n + 1 - 2 * h + (h * (h - 1)) / n) / n)
    stat = dm * corr
    p = 2.0 * (1.0 - scipy_stats.t.cdf(abs(stat), df=n - 1))
    return float(stat), float(p), n


def _align_error_pair(err_a, err_b):
    """Align forecast errors by timestamp, or by common tail as a fallback."""
    if isinstance(err_a, pd.Series) and isinstance(err_b, pd.Series):
        pair = pd.concat([err_a.rename('a'), err_b.rename('b')], axis=1,
                         join='inner').dropna()
        return pair['a'].values.astype(float), pair['b'].values.astype(float)
    a = np.asarray(err_a, dtype=float).reshape(-1)
    b = np.asarray(err_b, dtype=float).reshape(-1)
    n = min(len(a), len(b))
    if n == 0:
        return np.asarray([], dtype=float), np.asarray([], dtype=float)
    # Forecast protocols with different warm-up lengths share their common
    # chronological tail.  Prefix alignment compares different timestamps.
    return a[-n:], b[-n:]


def _timestamp_error_dict(errors, reference_index):
    """Attach the common-tail timestamps to a model's per-target errors."""
    out = {}
    ref = pd.Index(reference_index)
    for target, values in dict(errors or {}).items():
        if isinstance(values, pd.Series):
            out[target] = values.sort_index()
            continue
        arr = np.asarray(values, dtype=float).reshape(-1)
        if len(arr) > len(ref):
            raise ValueError(
                f"Error vector for '{target}' has {len(arr)} rows but the "
                f"reference timeline has only {len(ref)}.")
        idx = ref[:0] if len(arr) == 0 else ref[-len(arr):]
        out[target] = pd.Series(arr, index=idx, name=str(target))
    return out


def paired_bootstrap_mae(err_a, err_b, n_boot=2000, seed=0, ci=95,
                         block_len=None):
    """Moving-block paired bootstrap interval for the MAE difference."""
    a, b = _align_error_pair(err_a, err_b)
    ok = np.isfinite(a) & np.isfinite(b)
    a, b = np.abs(a[ok]), np.abs(b[ok])
    n = len(a)
    if n < 10:
        return dict(point=np.nan, lo=np.nan, hi=np.nan, n=n, p_sign=np.nan)
    rng = np.random.default_rng(seed)
    if block_len is None:
        block_len = max(2, int(round(n ** (1.0 / 3.0))))
    block_len = min(max(1, int(block_len)), n)
    n_blocks = int(np.ceil(n / block_len))
    starts = rng.integers(0, n, size=(int(n_boot), n_blocks))
    idx = ((starts[:, :, None] + np.arange(block_len)[None, None, :]) % n)
    idx = idx.reshape(int(n_boot), -1)[:, :n]
    paired_diff = a - b
    diffs = paired_diff[idx].mean(axis=1)
    lo, hi = np.percentile(diffs, [(100 - ci) / 2, 100 - (100 - ci) / 2])
    return dict(point=float(a.mean() - b.mean()), lo=float(lo), hi=float(hi),
                n=n, block_len=int(block_len), method='circular_moving_block',
                frac_favouring_a=float((diffs < 0).mean()))


def holm_correct(pvals):
    """Internal experiment utility."""
    p = np.asarray(pvals, dtype=float)
    ok = np.isfinite(p)
    out = np.full_like(p, np.nan)
    idx = np.argsort(p[ok])
    m = ok.sum()
    adj = np.empty(m)
    run = 0.0
    for rank, i in enumerate(idx):
        run = max(run, (m - rank) * p[ok][i])
        adj[i] = min(1.0, run)
    out[ok] = adj
    return out


def contiguous_observed_windows(obs_mask, target_vars, min_len):
    """Internal experiment utility."""
    cols = [v for v in target_vars if v in obs_mask.columns]
    if not cols:
        return pd.Series(False, index=obs_mask.index)
    all_obs = obs_mask[cols].all(axis=1).values
    keep = np.zeros(len(all_obs), dtype=bool)
    start = None
    for i, val in enumerate(list(all_obs) + [False]):
        if val and start is None:
            start = i
        elif not val and start is not None:
            if i - start >= min_len:
                keep[start:i] = True
            start = None
    return pd.Series(keep, index=obs_mask.index)


def count_physical_violations(pred_df, target_vars, limits):
    """Internal experiment utility."""
    rows = []
    for v in target_vars:
        if v not in pred_df.columns:
            continue
        lo, hi = limits.get(v, (-np.inf, np.inf))
        x = pred_df[v].values.astype(float)
        fin = np.isfinite(x)
        rows.append(dict(target=v, n=int(fin.sum()),
                         n_below=int((x[fin] < lo).sum()),
                         n_above=int((x[fin] > hi).sum()),
                         frac_violating=float(((x[fin] < lo) | (x[fin] > hi)).mean())
                         if fin.sum() else np.nan,
                         worst_below=float(np.nanmin(x[fin]) if fin.sum() else np.nan),
                         worst_above=float(np.nanmax(x[fin]) if fin.sum() else np.nan),
                         lo=lo, hi=hi))
    return pd.DataFrame(rows)


def _persist_slice(config, index, target_vars):
    """Internal experiment utility."""
    ref = getattr(config, '_persist_truth', None)
    if ref is None:
        return None
    cols = [v for v in target_vars if v in ref.columns]
    if len(cols) != len(target_vars):
        return None
    return ref.reindex(index)[list(target_vars)].values


def _slice_kind_masks(kind_masks, index):
    """Internal experiment utility."""
    if not kind_masks:
        return {}
    return {k: m.reindex(index).fillna(False)
            for k, m in kind_masks.items() if m is not None}


def load_fault_kind_masks(file_path, config,
                          kinds=('stuck', 'zero', 'excursion', 'sentinel', 'drift')):
    """Load available per-kind masks with the same strict parser and suffix."""
    if file_path is None:
        return {}
    out = {}
    for kind in kinds:
        p = _resolve_dqa_artifact_path(
            file_path, f"fault_mask_{kind}_", config)
        if not os.path.exists(p):
            continue
        m = _read_boolean_mask(p, f"'{kind}' fault mask", required=True)
        out[kind] = m
        print(f"    [C-T5] loaded '{kind}' mask: "
              f"{int(m.values.sum())} flagged cells.")
    if not out:
        msg = ("no per-fault-type masks found; expected "
               "fault_mask_<kind>_*.csv from the audited DQA")
        if bool(getattr(config, 'REQUIRE_DQA_HANDOFF', True)):
            raise FileNotFoundError(msg)
        print(f"    [C-T5] {msg}; per-kind metrics skipped.")
    return out


def validate_dqa_handoff(df, target_vars, obs_mask, fault_mask, kind_masks,
                         config, dataset_name):
    """Require exact data/mask alignment before any target reaches a model."""
    required = bool(getattr(config, 'REQUIRE_DQA_HANDOFF', True))
    if required and obs_mask is None:
        raise RuntimeError(f"[{dataset_name}] required source-retention mask absent")
    if required and fault_mask is None:
        raise RuntimeError(f"[{dataset_name}] required aggregate fault mask absent")

    masks = []
    if obs_mask is not None:
        masks.append(('source-retention', obs_mask))
    if fault_mask is not None:
        masks.append(('aggregate fault', fault_mask))
    masks.extend((f"{kind} fault", m) for kind, m in (kind_masks or {}).items())
    for label, mask in masks:
        if not mask.index.equals(df.index):
            missing = int((~df.index.isin(mask.index)).sum())
            extra = int((~mask.index.isin(df.index)).sum())
            raise ValueError(
                f"[{dataset_name}] {label} mask/data timestamp mismatch: "
                f"data={len(df)}, mask={len(mask)}, missing={missing}, extra={extra}")
        absent = sorted(set(target_vars) - set(mask.columns))
        if absent:
            raise ValueError(
                f"[{dataset_name}] {label} mask lacks targets: {absent}")

    # Every typed fault must also be present in the aggregate fault mask, and
    # the typed masks must jointly reproduce the aggregate exactly. A subset
    # check alone can miss an entire omitted fault class.
    if fault_mask is not None:
        union = pd.DataFrame(False, index=df.index,
                             columns=[c for c in target_vars
                                      if c in fault_mask.columns])
        for kind, mask in (kind_masks or {}).items():
            cols = [c for c in target_vars
                    if c in mask.columns and c in fault_mask.columns]
            if cols:
                outside = mask[cols] & ~fault_mask[cols]
                if bool(outside.values.any()):
                    raise ValueError(
                        f"[{dataset_name}] '{kind}' mask contains flags outside "
                        "the aggregate fault mask")
                union.loc[:, cols] = union[cols] | mask[cols]
        if kind_masks and len(union.columns):
            missing_kind = fault_mask[union.columns] & ~union
            if bool(missing_kind.values.any()):
                counts = {c: int(missing_kind[c].sum())
                          for c in union.columns if missing_kind[c].any()}
                raise ValueError(
                    f"[{dataset_name}] aggregate fault flags are missing from "
                    f"the per-kind masks: {counts}")
    print(f"[DQA] handoff validated for '{dataset_name}': {len(df)} timestamps, "
          f"{len(target_vars)} candidate target(s), suffix="
          f"{_validated_mask_suffix(config)!r}.")


def stuck_truth_is_degenerate(y_true_fault, min_unique=3):
    """Internal experiment utility."""
    y = np.asarray(y_true_fault, dtype=float)
    y = y[np.isfinite(y)]
    if y.size == 0:
        return True, 0
    n_uni = int(len(np.unique(np.round(y, 9))))
    return bool(n_uni < int(min_unique)), n_uni


def get_eval_truth(df, config, target_vars, verbose=True):
    """Build the common causal evaluation-truth frame used by all models."""
    eval_df = df.copy()
    if not isinstance(eval_df.index, pd.DatetimeIndex):
        eval_df.index = pd.to_datetime(eval_df.index)
    # Belgian file asfreq('h') manufactured 16,997 rows from 740 -- 95.8% of the
    # scored window was interpolant, and a one-step forecast of an interpolated
    # row measures smoothness rather than sensor forecasting.
    _ef = _freq_of(config)
    eval_df = eval_df.sort_index().asfreq(_ef)

    n_inserted = len(eval_df) - len(df)
    missing_before = {v: int(eval_df[v].isna().sum())
                      for v in target_vars if v in eval_df.columns}

    n = len(eval_df)
    val_end = int(n * (getattr(config, 'TRAIN_SPLIT', 0.7)
                       + getattr(config, 'VAL_SPLIT', 0.15)))

    filled = eval_df[target_vars].copy()
    # Pre-test region: no model forecasts these rows, so two-sided time
    # interpolation is legitimate and preserves within-gap shape.
    filled.iloc[:val_end] = (filled.iloc[:val_end]
                             .interpolate(method='time', limit_direction='both')
                             .values)
    # Test region: carry the last observed value forward. ffill() over the whole
    # column (not just the tail) is what lets a gap straddling the boundary be
    # filled from the last pre-boundary observation.
    filled = filled.ffill()
    eval_df[target_vars] = filled

    residual = {v: int(eval_df[v].isna().sum())
                for v in target_vars if int(eval_df[v].isna().sum()) > 0}
    if residual:
        raise ValueError(
            f"[R15-D] get_eval_truth cannot repair {residual} -- the target is "
            f"entirely or almost entirely absent, or has no observation at all "
            f"before the test window. Add it to target_exclusions.csv; do not "
            f"score it. (The test-window fill is deliberately causal, so a "
            f"target whose only observations are late in the test window cannot "
            f"be repaired without leaking future information.)")

    if verbose and (n_inserted or any(missing_before.values())):
        print(f"    [R15-D] eval truth: asfreq('{_ef}') inserted {n_inserted} rows; "
              f"time-interpolated gaps per target {missing_before} "
              f"(causal fill after row {val_end}). "
              f"All experiments score against THIS frame.")
    return eval_df


def compute_metrics(y_true, y_pred, y_train, target_vars,
                    obs_mask=None, baseline_pred=None, fault_mask=None,
                    kind_masks=None, persist_pred=None, config=None,
                    seasonality=None):
    """Compute per-target forecasting, robustness, and safety metrics."""
    results = {}
    
    
    # mean_absolute_error with no indication of WHICH array or which target --
    # it took a traceback plus a source read to establish it was y_true, not
    # y_pred. Check both, name the offender, and say what to do about it.
    y_true = np.asarray(y_true, dtype=float)
    y_pred = np.asarray(y_pred, dtype=float)
    for _arr, _who in ((y_true, 'y_true (ground truth)'),
                       (y_pred, 'y_pred (model output)')):
        if not np.all(np.isfinite(_arr)):
            _bad = {target_vars[j]: int((~np.isfinite(_arr[:, j])).sum())
                    for j in range(_arr.shape[1])
                    if not np.all(np.isfinite(_arr[:, j]))}
            raise ValueError(
                f"[R15-E] non-finite values in {_who} at metric time: {_bad} "
                f"(of {_arr.shape[0]} test points). Ground-truth gaps mean the "
                f"evaluation frame was not repaired -- route it through "
                f"get_eval_truth(), which is the single place truth is built. "
                f"Prediction gaps mean the model emitted NaN and the run should "
                f"fail, not be scored.")

    for i, name in enumerate(target_vars):
        yt, yp = y_true[:, i], y_pred[:, i]
        _train_values = pd.to_numeric(y_train[name], errors='coerce').values
        _train_values = _train_values[np.isfinite(_train_values)]
        results[f'{name}_TrainStd'] = (float(np.std(_train_values))
                                       if _train_values.size else np.nan)
        results[f'{name}_MAE'] = mean_absolute_error(yt, yp)
        results[f'{name}_RMSE'] = np.sqrt(mean_squared_error(yt, yp))
        _m = int(seasonality if seasonality is not None
                 else (_seasonality_of(config) if config is not None else 24))
        results[f'{name}_MASE'] = calculate_mase(yt, yp, y_train[name].values,
                                                seasonality=_m)
        results['mase_seasonality'] = _m
        
        results[f'{name}_MASE_1'] = calculate_mase_h1(yt, yp, y_train[name].values)

        # The observation mask is provenance, not a quality prediction:
        # True means the target value was retained from the supplied source;
        # False means DQA reconstructed it. It is the mandatory denominator for
        # every primary and natural-fault forecasting metric.
        observed = np.ones(yt.shape[0], dtype=bool)
        has_observation_provenance = False
        if obs_mask is not None:
            if name not in obs_mask.columns:
                raise ValueError(
                    f"[R3] source-retention mask lacks target '{name}'")
            observed = obs_mask[name].fillna(False).values.astype(bool)
            if len(observed) != len(y_true):
                raise ValueError(
                    f"[R3] Mask/truth length mismatch for '{name}': mask has "
                    f"{len(observed)} rows, evaluation window has {len(y_true)}. "
                    "The mask must be reindexed onto test_indices before this "
                    "call, never positionally sliced.")
            has_observation_provenance = True
            results[f'{name}_N_obs'] = int(observed.sum())
            results[f'{name}_N_reconstructed'] = int((~observed).sum())
            results[f'{name}_N_total'] = int(observed.shape[0])
            if observed.sum() >= 10:
                results[f'{name}_MAE_obs'] = mean_absolute_error(
                    yt[observed], yp[observed])

        # ---------------------------------------------------------------- R16-B
        # TEST-WINDOW persistence. The MASE columns above divide by a TRAINING-
        # window error; these divide by the naive one-step error measured on the
        # very points being scored. On a non-stationary station the two disagree
        # -- recomputing the benchmark on the test window flipped the verdict on
        
        # answers "does the model beat carrying the last reading forward, here".
        if persist_pred is not None:
            _pp = np.asarray(persist_pred, dtype=float)
            if _pp.ndim == 2 and _pp.shape == y_true.shape:
                _pv = _pp[:, i]
                _ok = np.isfinite(_pv) & np.isfinite(yt) & np.isfinite(yp)
                if has_observation_provenance:
                    _ok &= observed
                if _ok.sum() >= 10:
                    _mp = float(np.mean(np.abs(yt[_ok] - _pv[_ok])))
                    _mm = float(np.mean(np.abs(yt[_ok] - yp[_ok])))
                    results[f'{name}_MAE_persist'] = _mp
                    results[f'{name}_N_persist'] = int(_ok.sum())
                    results[f'{name}_persist_metric_observed_only'] = bool(
                        has_observation_provenance)
                    if _mp > 1e-12:
                        results[f'{name}_RelMAE_persist'] = _mm / _mp
                        results[f'{name}_Beats_persist'] = bool(_mm < _mp)

        if fault_mask is not None:
            if name not in fault_mask.columns:
                raise ValueError(f"[Fault] aggregate mask lacks target '{name}'")
            fault_raw = fault_mask[name].fillna(False).values.astype(bool)
            if fault_raw.shape[0] != yt.shape[0]:
                raise ValueError(
                    f"[Fault] Mask/truth length mismatch for '{name}': mask has "
                    f"{len(fault_raw)} rows, truth has {len(yt)}")

            # Only source-retained values are defensible forecasting truth.
            # Reconstructed fault cells remain counted for transparency but are
            # never scored against the interpolator.
            fault_eval = (fault_raw & observed
                          if has_observation_provenance else fault_raw)
            healthy_eval = ((~fault_raw) & observed
                            if has_observation_provenance else ~fault_raw)
            reconstructed_fault = (fault_raw & ~observed
                                   if has_observation_provenance
                                   else np.zeros_like(fault_raw, dtype=bool))

            results[f'{name}_N_fault_dqa'] = int(fault_raw.sum())
            results[f'{name}_N_fault_obs'] = int(fault_eval.sum())
            results[f'{name}_N_fault_reconstructed'] = int(
                reconstructed_fault.sum())
            # Backward-compatible names now have an explicit, safe meaning.
            results[f'{name}_N_fault'] = int(fault_eval.sum())
            results[f'{name}_N_healthy'] = int(healthy_eval.sum())
            results[f'{name}_fault_metric_observed_only'] = bool(
                has_observation_provenance)

            # can hand every model the same value, rewarding flatness rather
            # than reconstruction. Carry that caveat with the metric.
            _n_uni = (int(len(np.unique(np.round(yt[fault_eval], 9))))
                      if fault_eval.sum() else 0)
            _metric_cfg = config if config is not None else Config
            _min_uni = int(getattr(_metric_cfg,
                                   'FAULT_METRIC_MIN_UNIQUE', 3))
            _min_n = int(getattr(_metric_cfg, 'FAULT_METRIC_MIN_N', 10))
            results[f'{name}_fault_truth_unique'] = _n_uni
            results[f'{name}_fault_truth_degenerate'] = bool(
                fault_eval.sum() >= _min_n and _n_uni < _min_uni)
            if fault_eval.sum() >= _min_n:
                results[f'{name}_MAE_fault'] = mean_absolute_error(
                    yt[fault_eval], yp[fault_eval])
            if healthy_eval.sum() >= _min_n:
                results[f'{name}_MAE_healthy'] = mean_absolute_error(
                    yt[healthy_eval], yp[healthy_eval])

        # Per-kind metrics use the same source-retained denominator. Sentinel
        # cells are descriptive only because their target values were removed
        # and reconstructed by DQA.
        if kind_masks:
            _kind_cfg = config if config is not None else Config
            _kind_min_n = int(getattr(_kind_cfg, 'FAULT_METRIC_MIN_N', 10))
            for kind, km in kind_masks.items():
                if km is None or name not in km.columns:
                    continue
                kind_raw = km[name].fillna(False).values.astype(bool)
                if kind_raw.shape[0] != yt.shape[0]:
                    raise ValueError(
                        f"[Fault/{kind}] Mask/truth length mismatch for "
                        f"'{name}': mask has {len(kind_raw)}, truth has {len(yt)}")
                kind_eval = (kind_raw & observed
                             if has_observation_provenance else kind_raw)
                kind_reconstructed = (kind_raw & ~observed
                                      if has_observation_provenance
                                      else np.zeros_like(kind_raw, dtype=bool))
                results[f'{name}_N_{kind}_dqa'] = int(kind_raw.sum())
                results[f'{name}_N_{kind}_reconstructed'] = int(
                    kind_reconstructed.sum())
                results[f'{name}_N_{kind}'] = int(kind_eval.sum())
                if kind == 'sentinel':
                    results[f'{name}_{kind}_descriptive_only'] = True
                    continue
                if kind_eval.sum() >= _kind_min_n:
                    results[f'{name}_MAE_{kind}'] = mean_absolute_error(
                        yt[kind_eval], yp[kind_eval])
                else:
                    # A missing MAE_<kind> means insufficient retained events in
                    # this chronological window, not absence from the series.
                    results[f'{name}_N_{kind}_window'] = int(kind_raw.sum())

        if baseline_pred is not None:
            worse = np.abs(yt - yp) > np.abs(yt - baseline_pred[:, i])
            results[f'{name}_ParityViol'] = float(worse.mean())

    # -------------------------------------------------------------------- R16-D
    # PHYSICAL VIOLATIONS FOR EVERY MODEL, COUNTED IN ONE PLACE.
    #
    
    # only, so physical_violations_<ds>.csv had a number for the proposal and
    # NaN for all ~24 comparators -- which is precisely the comparison the
    # safety argument requires. An unbounded deep baseline emitting negative
    # dissolved oxygen is the hazard the guard exists to prevent, and there was
    # no column in which that could appear.
    #
    # Counting here means every model that reaches this block is counted on
    # identical footing, with identical limits, before any guard is applied. The
    # post-guard count is zero by construction for all models alike, so the
    # pre-guard number is the honest hazard measure.
    _limits = getattr(config, 'PHYSICAL_LIMITS', None) if config is not None \
        else getattr(Config, 'PHYSICAL_LIMITS', {})
    if _limits is None:
        _limits = getattr(Config, 'PHYSICAL_LIMITS', {})
    _pred_df = pd.DataFrame(y_pred, columns=list(target_vars))
    _viol = count_physical_violations(_pred_df, list(target_vars), _limits)
    if len(_viol):
        results['n_physical_violations'] = int(_viol.n_below.sum()
                                               + _viol.n_above.sum())
        results['physviol_counted'] = True
        for _r in _viol.itertuples():
            results[f'{_r.target}_PhysViol'] = _r.frac_violating
        _guarded, _nclip = apply_physical_guard(_pred_df, list(target_vars),
                                                _limits, return_counts=True)
        results['n_physical_violations_post_guard'] = 0
        results['n_clipped_by_guard'] = int(_nclip)
        # What the guard is worth in accuracy terms, so the safety argument is
        # not made on a metric nobody checked.
        if _nclip:
            _gm = float(np.mean(np.abs(y_true - _guarded.values)))
            _um = float(np.mean(np.abs(y_true - y_pred)))
            results['guard_MacroMAE_delta'] = _gm - _um
    return results


def flag_degenerate_targets(results_df, target_vars, config,
                            naive_name='SeasonalNaive (24h)'):
    """Internal experiment utility."""
    degenerate = []
    if naive_name not in results_df.index:
        return degenerate
    for v in target_vars:
        col = f'{v}_MAE'
        if col not in results_df.columns:
            continue
        naive_mae = pd.to_numeric(pd.Series([results_df.loc[naive_name, col]]),
                                  errors='coerce').iloc[0]
        std_col = f'{v}_TrainStd'
        train_std = (pd.to_numeric(pd.Series(
            [results_df.loc[naive_name, std_col]]), errors='coerce').iloc[0]
            if std_col in results_df.columns else np.nan)
        rel = (float(naive_mae / max(float(train_std), 1e-12))
               if pd.notna(naive_mae) and pd.notna(train_std)
               and float(train_std) > 0 else np.nan)
        rel_thr = float(getattr(config, 'DEGENERACY_REL_NAIVE_THRESHOLD',
                                0.01))
        is_degenerate = (np.isfinite(rel) and rel < rel_thr)
        # Absolute fallback is retained only for legacy result tables lacking
        # a training scale; new runs always take the scale-free branch.
        if not np.isfinite(rel):
            is_degenerate = (pd.notna(naive_mae)
                             and naive_mae < config.DEGENERACY_MAE_THRESHOLD)
        if is_degenerate:
            degenerate.append(v)
            print(f"[Sec 2.4] DEGENERATE TARGET: '{v}' -- {naive_name} MAE = "
                  f"{naive_mae:.6f}, train std={train_std:.6f}, "
                  f"relative naive MAE={rel:.6g} < {rel_thr}. The series is "
                  f"effectively constant; excluding from aggregates.")
    return degenerate


def assert_run_integrity(results_df, target_vars, dataset_name, config,
                         anchor_name=CORRECTOR_ATTRIBUTION_ANCHOR):
    """Audit protocol, target, and prediction consistency in a result table."""
    print("\n" + "=" * 78)
    print(f"[R15-G] RUN INTEGRITY AUDIT -- {dataset_name}")

    # --- 1. protocol partition -------------------------------------------
    if 'eval_protocol' in results_df.columns:
        prot = results_df['eval_protocol'].fillna('UNTAGGED')
        groups = {p: sorted(prot.index[prot == p].tolist()) for p in prot.unique()}
        print(f"    eval protocols present: {len(groups)}")
        for p, mods in groups.items():
            print(f"      {p:28s} n={len(mods):2d}  e.g. {mods[:3]}")
        if len(groups) > 1:
            print("    !! Rows above span MORE THAN ONE evaluation protocol. MAE/MASE")
            print("       are NOT comparable across these groups. Any table or figure")
            print("       ranking them together is invalid -- compare WITHIN a group,")
            print("       and state the protocol in every caption.")
        if 'UNTAGGED' in groups:
            raise ValueError(
                f"[R15-G] {len(groups['UNTAGGED'])} model(s) on '{dataset_name}' "
                f"returned no eval_protocol tag: {groups['UNTAGGED'][:6]}. An "
                f"untagged row cannot be placed in a comparison table. Set "
                f"results['eval_protocol'] in that experiment's run().")
    else:
        raise ValueError(
            f"[R15-G] no eval_protocol column on '{dataset_name}'. This is the "
            f"r14 defect: the shipped table gave no way to tell rolling h=1 rows "
            f"from open-loop ones.")

    # --- 2. target-mode partition ----------------------------------------
    if 'target_mode' in results_df.columns:
        tm = results_df['target_mode'].fillna('untagged')
        print(f"    target modes: {tm.value_counts().to_dict()}")

    # --- 3. anchor pass-through ------------------------------------------
    mae_cols = [f'{v}_MAE' for v in target_vars
                if f'{v}_MAE' in results_df.columns]
    if anchor_name in results_df.index:
        anchor = results_df.loc[anchor_name, mae_cols].apply(pd.to_numeric,
                                                            errors='coerce')
        for mod in results_df.index:
            if mod == anchor_name:
                continue
            row = results_df.loc[mod, mae_cols].apply(pd.to_numeric,
                                                      errors='coerce')
            same = [c for c in mae_cols
                    if np.isfinite(row[c]) and np.isfinite(anchor[c])
                    and abs(row[c] - anchor[c]) <= 1e-12 * max(1.0, abs(anchor[c]))]
            if same:
                _names = [c.replace('_MAE', '') for c in same]
                _gated = ('gate_n_declined' in results_df.columns
                          and np.isfinite(pd.to_numeric(
                              results_df.loc[mod, 'gate_n_declined'],
                              errors='coerce')))
                if _gated:
                    # A corrector on top of this anchor: identity means the gate
                    # declined and the anchor's own prediction was passed through.
                    _why = ("the gate declined there, so on those targets this row "
                            "IS the anchor -- report Frac_targets_corrected beside "
                            "any aggregate")
                else:
                    # An independent model has no reason to match the anchor to
                    # machine precision. That is a plumbing bug, not a result.
                    _why = ("this model does not wrap the anchor, so identical MAE "
                            "to 1e-12 is not a coincidence -- suspect the wrong "
                            "prediction array was scored (copy/paste of the "
                            "baseline's preds) and check this experiment's run()")
                print(f"    !! {mod}: MAE identical to {anchor_name} on "
                      f"{len(same)}/{len(mae_cols)} targets {_names} -- {_why}.")

    # --- 3b. ROWS THAT ARE THE SAME MODEL TWICE --------------------------- R16-J
    # Check 3 compares every row with the requested feature-matched differenced
    # anchor. This pairwise scan additionally detects arbitrary duplicate model
    # rows, including architecture ablations that are bit-identical to Full.
    #
    # On the r16 synthetic run the headline arm, the unbounded arm, the
    # differenced-target XGBoost, and the 'No Attention' / 'No CNN' ablations all
    # shared the same MAE to every printed digit on 4/4 targets. Two readings are
    # possible and the audit must not choose between them silently:
    #   (a) the corrector contributed nothing, so the deep stack is decoration on
    #       a gradient-boosted anchor and the ablations remove a component that
    #       was never doing work; or
    #   (b) the scored array is the anchor's, i.e. the correction was computed
    #       and then dropped on the way to the metric.
    # Either way an architecture claim, an ablation table, and a "beats the tree"
    # claim are all unsupported, so this is reported as a group with the reading
    # spelled out rather than as a per-row footnote.
    if len(mae_cols) and len(results_df.index) > 1:
        _num = results_df[mae_cols].apply(pd.to_numeric, errors='coerce')
        _tol = float(getattr(config, 'DUPLICATE_ROW_TOL', 1e-12))
        _groups, _seen = [], set()
        for _m in _num.index:
            if _m in _seen or not np.isfinite(_num.loc[_m]).all():
                continue
            _tw = [_m]
            for _o in _num.index:
                if _o == _m or _o in _seen or not np.isfinite(_num.loc[_o]).all():
                    continue
                _rel = np.abs(_num.loc[_m].values - _num.loc[_o].values) \
                    / np.maximum(1.0, np.abs(_num.loc[_m].values))
                if (_rel <= _tol).all():
                    _tw.append(_o)
            if len(_tw) > 1:
                _groups.append(_tw)
                _seen.update(_tw)
        for _g in _groups:
            print(f"    !! IDENTICAL MAE on all {len(mae_cols)} targets "
                  f"(rel tol {_tol:g}) across {len(_g)} rows: {_g}")
            # Decide between (a) and (b) from the gate counts rather than
            # leaving it to the reader: if every corrector in the group declined
            # on every target, the identity is the parity guarantee operating as
            # designed (pass-through), which is a legitimate result but makes the
            # ablation uninformative. If any member corrected something and the
            # MAE still matches to 1e-12, the correction did not reach the
            # scored array and the run is a plumbing failure.
            _nc = pd.to_numeric(
                results_df.loc[_g, 'gate_n_corrected'], errors='coerce') \
                if 'gate_n_corrected' in results_df.columns else None
            _any_corrected = bool(_nc is not None and (_nc.fillna(0) > 0).any())
            if _nc is not None and _nc.notna().any() and not _any_corrected:
                print(f"       CAUSE: every corrector in this group DECLINED on "
                      f"every target (gate_n_corrected == 0), so each of these "
                      f"rows is the anchor passed through. That is the parity "
                      f"guarantee working, not a bug -- but it means the "
                      f"components separating these rows made no difference to "
                      f"any prediction. An ablation table built from them shows "
                      f"only that the gate was closed; it is NOT evidence that a "
                      f"component is unnecessary, and no member of this group "
                      f"can be reported as beating another.")
            elif _any_corrected:
                # FINAL RR: gate_n_corrected is a TARGET-LEVEL authorisation,
                # not proof that any TEST ROW survived the row-wise probability
                # threshold/deadband. The previous heuristic called valid
                # challenged_89509 rows a plumbing bug even though the direct
                # assembly invariant reported assembly_max_err=0 and
                # n_corrections_lost=0. Defer to those direct row-level checks.
                _sub = results_df.loc[_g]
                _invalid = (pd.to_numeric(_sub.get('row_invalid', False),
                                          errors='coerce').fillna(0).astype(bool)
                            if 'row_invalid' in results_df.columns
                            else pd.Series(False, index=_sub.index))
                _lost = (pd.to_numeric(_sub.get('n_corrections_lost', 0),
                                       errors='coerce').fillna(0)
                         if 'n_corrections_lost' in results_df.columns
                         else pd.Series(0, index=_sub.index))
                _asm = (pd.to_numeric(_sub.get('assembly_max_err', 0.0),
                                      errors='coerce').fillna(0.0)
                        if 'assembly_max_err' in results_df.columns
                        else pd.Series(0.0, index=_sub.index))
                if bool(_invalid.any() or (_lost > 0).any() or (_asm > 1e-10).any()):
                    print(f"       CAUSE: direct row-level assembly invariant FAILED "
                          f"for at least one row (row_invalid/lost corrections/" 
                          f"assembly error). Treat only those flagged rows as invalid.")
                else:
                    _inert_cols = [c for c in results_df.columns
                                   if c.endswith('_CorrectionInert')]
                    _ninert = int(_sub[_inert_cols].fillna(False).astype(bool).sum().sum()) \
                        if _inert_cols else 0
                    print(f"       CAUSE: target-level gating opened somewhere, "
                          f"but the DIRECT assembly checks pass for every member "
                          f"(row_invalid=False, n_corrections_lost=0, "
                          f"assembly_max_err~0). Identical MAE is therefore valid "
                          f"passthrough/deadband behaviour, not a plumbing bug. "
                          f"Correction-inert target slots in this group: {_ninert}.")
            else:
                print(f"       These rows are ONE model reported under {len(_g)} "
                      f"names, and no gate diagnostics are present to say why. "
                      f"Do NOT report an ablation, an architecture contribution, "
                      f"or a win over any other member of this group until the "
                      f"prediction arrays are shown to differ (compare "
                      f"last_corrections, not just MAE).")

    # --- 4. bounds that never bind ---------------------------------------
    if 'realised_bind_rate' in results_df.columns:
        br = pd.to_numeric(results_df['realised_bind_rate'], errors='coerce')
        dead = [m for m in results_df.index
                if np.isfinite(br.get(m, np.nan)) and br[m] == 0.0
                and ('clip' in str(m) or 'conformal' in str(m))]
        if dead:
            print(f"    !! bound never binds (rate 0.0000) on {len(dead)} row(s): "
                  f"{dead}. These are the UNBOUNDED model relabelled; they cannot "
                  f"support -- or refute -- a bounded-correction claim. See R15-C "
                  f"for the scale argument.")
    print("=" * 78, flush=True)
    return results_df


def add_aggregate_columns(results_df, target_vars, config, degenerate=()):
    """Internal experiment utility."""
    keep = [v for v in target_vars if v not in degenerate]
    mae_cols = [f'{v}_MAE' for v in target_vars if f'{v}_MAE' in results_df.columns]
    keep_cols = [f'{v}_MAE' for v in keep if f'{v}_MAE' in results_df.columns]
    obs_mae_cols = [f'{v}_MAE_obs' for v in target_vars
                    if f'{v}_MAE_obs' in results_df.columns]
    obs_keep_cols = [f'{v}_MAE_obs' for v in keep
                     if f'{v}_MAE_obs' in results_df.columns]
    mase_cols = [f'{v}_MASE' for v in keep if f'{v}_MASE' in results_df.columns]

    num = results_df[mae_cols].apply(pd.to_numeric, errors='coerce')
    results_df['Macro_MAE'] = num.mean(axis=1)
    if keep_cols:
        results_df['Macro_MAE_ex_degen'] = \
            results_df[keep_cols].apply(pd.to_numeric, errors='coerce').mean(axis=1)
    if obs_mae_cols:
        results_df['Macro_MAE_obs'] = results_df[obs_mae_cols].apply(
            pd.to_numeric, errors='coerce').mean(axis=1)
        results_df['N_targets_MAE_obs'] = results_df[obs_mae_cols].apply(
            pd.to_numeric, errors='coerce').notna().sum(axis=1)
    if obs_keep_cols:
        results_df['Macro_MAE_obs_ex_degen'] = results_df[obs_keep_cols].apply(
            pd.to_numeric, errors='coerce').mean(axis=1)
    if mase_cols:
        results_df['Mean_MASE'] = \
            results_df[mase_cols].apply(pd.to_numeric, errors='coerce').mean(axis=1)

    # The audited release treats source-retained targets as the primary
    # forecasting result. All-point metrics remain available as a sensitivity
    # analysis because they include DQA-reconstructed truth.
    if 'Macro_MAE_obs_ex_degen' in results_df.columns:
        results_df['Primary_Macro_MAE'] = results_df['Macro_MAE_obs_ex_degen']
        results_df['Primary_MAE_scope'] = 'source-retained only'
    elif 'Macro_MAE_obs' in results_df.columns:
        results_df['Primary_Macro_MAE'] = results_df['Macro_MAE_obs']
        results_df['Primary_MAE_scope'] = 'source-retained only'
    elif 'Macro_MAE_ex_degen' in results_df.columns:
        results_df['Primary_Macro_MAE'] = results_df['Macro_MAE_ex_degen']
        results_df['Primary_MAE_scope'] = 'all points (no observation mask)'
    else:
        results_df['Primary_Macro_MAE'] = results_df['Macro_MAE']
        results_df['Primary_MAE_scope'] = 'all points (no observation mask)'

    
    # one-step-ahead task; Mean_MASE (seasonal m=24) is retained beside it only
    
    # for the measured size of the difference.
    mase1_cols = [f'{v}_MASE_1' for v in keep if f'{v}_MASE_1' in results_df.columns]
    if mase1_cols:
        results_df['Mean_MASE_1'] = \
            results_df[mase1_cols].apply(pd.to_numeric, errors='coerce').mean(axis=1)
        # Explicit verdict column: no reader should have to remember which way
        
        results_df['Beats_naive_h1'] = results_df['Mean_MASE_1'] < 1.0

    
    # HOW MANY TARGETS DID THE CORRECTOR ACTUALLY TOUCH?
    #
    # The gate passes the baseline through unchanged on any target where the
    # calibration-half correction is small relative to baseline MAE. When it
    # declines, M2P-PTAC's row IS the anchor's row -- identical to the last
    
    
    # M2P-PTAC (C=0.001), so the headline aggregate is 70% anchor and 30%
    # corrector, and on the 3 touched slots the corrector improved temperature
    # and pH by 9-17%.
    #
    # That is a legitimate result -- selective correction is the design -- but a
    # Macro_MAE that averages 7 pass-through columns with 3 corrected ones does
    # not communicate it, and a reader comparing "M2P-PTAC vs XGBoost" over such
    # a row is mostly comparing XGBoost with itself. Frac_targets_corrected makes
    # the denominator visible in the results table itself.
    if {'gate_n_corrected', 'gate_n_declined'}.issubset(results_df.columns):
        _c = pd.to_numeric(results_df['gate_n_corrected'], errors='coerce')
        _d = pd.to_numeric(results_df['gate_n_declined'], errors='coerce')
        _tot = _c + _d
        results_df['Frac_targets_corrected'] = _c / _tot.where(_tot > 0)
        results_df['Anchor_passthrough'] = _c.eq(0) & _tot.gt(0)
    return results_df


def per_target_attribution(results_df, target_vars, config, dataset_name,
                           model_name,
                           baseline_name=CORRECTOR_ATTRIBUTION_ANCHOR,
                           degenerate=()):
    """Attribute the neural delta to its feature-matched XGBoost anchor.

    ``model_MAE`` equals ``nn_delta_mae`` algebraically because the final
    prediction is ``anchor + neural_delta``. Explicit names prevent this effect
    from being confused with an end-to-end comparison against level XGBoost.
    """
    if model_name not in results_df.index or baseline_name not in results_df.index:
        print(f"[Sec 2.1] Cannot attribute: missing '{model_name}' or '{baseline_name}'.")
        return None

    rows = []
    for v in target_vars:
        obs_col = f'{v}_MAE_obs'
        all_col = f'{v}_MAE'
        col = (obs_col if obs_col in results_df.columns
               and pd.notna(results_df.loc[baseline_name, obs_col])
               and pd.notna(results_df.loc[model_name, obs_col])
               else all_col)
        if col not in results_df.columns:
            continue
        b = pd.to_numeric(pd.Series([results_df.loc[baseline_name, col]]), errors='coerce').iloc[0]
        m = pd.to_numeric(pd.Series([results_df.loc[model_name, col]]), errors='coerce').iloc[0]
        if pd.isna(b) or pd.isna(m):
            continue
        rows.append({
            'dataset': dataset_name, 'target': v,
            'attribution_scope': 'neural_corrector_vs_feature_matched_delta_anchor',
            'anchor_model': baseline_name,
            'baseline_MAE': b, 'model_MAE': m,
            'abs_gain': b - m,
            'pct_improvement': 100.0 * (b - m) / b if b else np.nan,
            'xgb_diff_anchor_mae': b,
            'nn_delta_mae': m,
            'm2p_final_mae': m,
            'abs_mae_gain_vs_xgb_diff': b - m,
            'pct_mae_gain_vs_xgb_diff': (
                100.0 * (b - m) / b if b else np.nan),
            'degenerate': v in degenerate,
            'metric_scope': ('source-retained only'
                             if col == obs_col else 'all points'),
            'direction': 'improved' if m < b else ('WORSE' if m > b else 'unchanged'),
        })
    if not rows:
        return None

    att = pd.DataFrame(rows)
    total_gain = att.loc[~att['degenerate'], 'abs_gain'].sum()
    att['share_of_macro_gain_%'] = (100.0 * att['abs_gain'] / total_gain
                                    if total_gain else np.nan)
    # a degenerate target contributes to no aggregate, so it has no share.
    att.loc[att['degenerate'], 'share_of_macro_gain_%'] = np.nan

    out = os.path.join(config.OUTPUT_DIR, f'attribution_per_target_{dataset_name}.csv')
    att.to_csv(out, index=False)

    print("\n" + "=" * 78)
    print(f"[Sec 2.1] PER-TARGET ATTRIBUTION -- {dataset_name}")
    print(f"          neural delta in {model_name}  vs  {baseline_name}")
    print("=" * 78)
    print(att.round(4).to_string(index=False))

    dom = att.loc[~att['degenerate']].sort_values('abs_gain', ascending=False)
    if len(dom):
        top = dom.iloc[0]
        print(f"\n  -> '{top['target']}' supplies {top['share_of_macro_gain_%']:.2f}% "
              f"of the total Macro-MAE gain.")
        if top['share_of_macro_gain_%'] > 80:
            print("  -> WARNING: the headline improvement is a SINGLE-CHANNEL result. "
                  "Report it as single-channel fault rescue with demonstrated "
                  "non-degradation elsewhere, not as a system-level improvement.")
    worse = att[att['direction'] == 'WORSE']
    if len(worse):
        print(f"  -> {len(worse)} target(s) got WORSE: "
              f"{', '.join(worse['target'].tolist())}. State this in the text.")

    # Equal-weight (scale-free) counterpart to the Macro-MAE headline.
    nd = att.loc[~att['degenerate']]
    if len(nd):
        macro_pct = 100.0 * (nd['baseline_MAE'].mean() - nd['model_MAE'].mean()) \
            / nd['baseline_MAE'].mean()
        equal_pct = nd['pct_improvement'].mean()
        print(f"\n[Sec 2.2] Macro-MAE improvement      : {macro_pct:6.2f}%  (unit-mixed)")
        print(f"[Sec 2.2] Equal-weight improvement   : {equal_pct:6.2f}%  (scale-free)")
        if equal_pct and abs(macro_pct / equal_pct) > 1.5:
            print(f"[Sec 2.2] WARNING: unit-mixing inflates the claim by "
                  f"{macro_pct / equal_pct:.1f}x. Report the scale-free number too.")
    return att


def assert_test_window_usable(df, target_vars, config, dataset_name, obs_mask=None):
    """Secondary gate that distinguishes source-retained flatness from fill."""
    requested = list(target_vars)
    mode = str(getattr(config, 'SECONDARY_WINDOW_GATE_MODE',
                       'diagnostic')).strip().lower()
    n = len(df)
    eval_start = config.LONG_WINDOW_SIZE + int((n - config.LONG_WINDOW_SIZE) * 0.85)
    keep, dropped = [], []
    for v in target_vars:
        if v not in df.columns:
            continue
        seg = df[v].iloc[eval_start:]
        if seg.isna().all():
            dropped.append((v, "column is entirely NaN"))
            continue
        grp = (seg != seg.shift()).cumsum()
        sizes = seg.groupby(grp).transform('size')
        flat = sizes >= 6
        flat_pct = 100.0 * flat.mean()
        dominant_pct = 100.0 * seg.value_counts(normalize=True, dropna=True).max()
        source_pct = np.nan
        flat_source_pct = np.nan
        flat_reconstructed_pct = np.nan
        if obs_mask is not None and v in obs_mask.columns:
            m = obs_mask[v].reindex(df.index)
            if m.isna().any():
                raise ValueError(
                    f"[Gate] source-retention mask is not aligned for {dataset_name}/{v}")
            source = m.iloc[eval_start:].astype(bool)
            source_pct = 100.0 * source.mean()
            flat_source_pct = 100.0 * (flat & source).mean()
            flat_reconstructed_pct = 100.0 * (flat & ~source).mean()

        if np.isfinite(source_pct) and source_pct < 40:
            dropped.append((v, f"only {source_pct:.1f}% of the {len(seg)}-point "
                               f"test window is source-retained/non-reconstructed; "
                               f"longest constant run {int(sizes.max())}"))
        elif flat_pct > 60:
            if np.isfinite(flat_source_pct) and flat_source_pct >= flat_reconstructed_pct:
                origin = (f"source-retained flat/stuck signature "
                          f"({flat_source_pct:.1f}% source-retained flat cells)")
            elif np.isfinite(flat_reconstructed_pct):
                origin = (f"reconstructed plateau "
                          f"({flat_reconstructed_pct:.1f}% reconstructed flat cells)")
            else:
                origin = "constant-run signature of unknown origin"
            dropped.append((v, f"{flat_pct:.1f}% of the test window has {origin}; "
                               f"dominant value {dominant_pct:.1f}%, longest run "
                               f"{int(sizes.max())}"))
        else:
            keep.append(v)
            if flat_pct > 25 or (np.isfinite(source_pct) and source_pct < 80):
                print(f"[Gate] CAUTION '{v}' @ {dataset_name}: "
                      f"{source_pct:.1f}% source-retained, {flat_pct:.1f}% in "
                      f"long constant runs (source-flat {flat_source_pct:.1f}%, "
                      f"reconstructed-flat {flat_reconstructed_pct:.1f}%). "
                      "Report _MAE_obs as the restricted sensitivity metric.")

    if dropped:
        print("\n" + "="*78)
        print(f"[Gate] EXCLUDED from '{dataset_name}' -- unusable evaluation window")
        print("="*78)
        for v, why in dropped:
            print(f"   {v:26s} {why}")
        print("   These windows are dominated by reconstruction or a flat/stuck source")
        print("   channel, so their MAE is not a defensible forecast target. State the")
        print("   exclusion and its reason")
        print("   in the manuscript -- a declared exclusion is defensible, a silent")
        print("   one is what Sec 2.5 objected to.")
        if mode != 'enforce':
            print("   DIAGNOSTIC ONLY: target membership is unchanged. The DQA")
            print("   target_exclusions.csv registry is the sole exclusion authority.")
        print("="*78 + "\n")
    if mode != 'enforce':
        return requested
    if not keep:
        raise RuntimeError(f"[Gate] No usable targets remain for '{dataset_name}'.")
    return keep


def assert_target_completeness(results_df, target_vars, dataset_name):
    """Internal experiment utility."""
    missing = [v for v in target_vars if f'{v}_MAE' not in results_df.columns]
    if missing:
        raise RuntimeError(
            f"[Sec 2.5] Dataset '{dataset_name}': targets {missing} are present in "
            f"the data but absent from the results table. Every target that is "
            f"modelled must be reported, including those where the corrector does "
            f"not help. Fix the pipeline rather than dropping the row.")
    print(f"[Sec 2.5] Completeness OK: all {len(target_vars)} targets reported "
          f"for '{dataset_name}'.")


def build_physics_mlp(input_dim, target_vars, config, name_suffix="_PhysicsMLP"):
    inputs = layers.Input(shape=(input_dim,), name='physics_input')
    x = layers.Dense(128, activation='relu')(inputs)
    x = layers.Dropout(config.DROPOUT_RATE)(x)
    x = layers.Dense(64, activation='relu')(x)
    outputs = []
    for var in target_vars:
        out = layers.Dense(1, name=f'head_{var.replace(" ", "_")}')(x)
        outputs.append(out)
    return Model(inputs=inputs, outputs=outputs, name=f"PhysicsMLP{name_suffix}")


def split_ptac_outputs(model, raw_out, n_targets):
    """Internal experiment utility."""
    outs = [np.asarray(o).reshape(-1) for o in
            (raw_out if isinstance(raw_out, list) else [raw_out])]
    delta = np.stack(outs[:n_targets], axis=1)
    # a training-time gradient path only and is never applied to a forecast:
    # the deployed correction is always the GATED delta, so the parity
    # guarantee is unaffected by the ablation arm being present.
    prob = (np.stack(outs[n_targets:2 * n_targets], axis=1)
            if len(outs) >= 2 * n_targets else None)
    return delta, prob


def ptac_fit_targets(model, y_scaled, n_targets, fault_labels=None):
    """Internal experiment utility."""
    n = y_scaled.shape[0]

    # needs the per-row stratum to weight episodes and to restrict its
    # auxiliary term to drift rows, and a Keras loss receives exactly one
    # target tensor per head -- packing is how the label reaches it.  The
    # -1 sentinel means "unlabelled" and contributes zero, which is the
    # correct handling for the 3/16 channel-slots with no mask column.
    if fault_labels is not None:
        _lab = np.asarray(fault_labels).astype('float32')
    else:
        _lab = np.full((n, n_targets), -1.0, dtype='float32')

    if bool(getattr(model, '_m2p_r17', False)):
        ys = [np.stack([y_scaled[:, i].astype('float32'), _lab[:, i]], axis=1)
              for i in range(n_targets)]
    else:
        ys = [y_scaled[:, i] for i in range(n_targets)]

    if not bool(getattr(model, '_m2p_gated', False)):
        return ys
    for i in range(n_targets):
        ys.append(_lab[:, i])
    # Bare-c ablation heads consume the same packed target as the main heads.
    if bool(getattr(model, '_m2p_bare', False)):
        for i in range(n_targets):
            ys.append(np.stack([y_scaled[:, i].astype('float32'), _lab[:, i]],
                               axis=1))
    return ys


def build_m2p_attention_network(
    config, target_vars, num_dynamic_vars,
    short_window_features, long_window_features,
    context_dim,
    name_suffix="", use_attention=True, use_cnn=True, unified_encoder=False,
    use_fault_gating=None, tau_per_target=None
):
    total_input_features = (config.SHORT_WINDOW_SIZE * short_window_features) + (config.LONG_WINDOW_SIZE * long_window_features)
    unified_input = layers.Input(shape=(total_input_features,), name='unified_input')
    context_input = layers.Input(shape=(context_dim,), name='context_input')

    split_point = config.SHORT_WINDOW_SIZE * short_window_features
    short_term_flat = layers.Lambda(lambda x: x[:, :split_point], name='slice_short_term')(unified_input)
    long_term_flat = layers.Lambda(lambda x: x[:, split_point:], name='slice_long_term')(unified_input)
    short_term_input = layers.Reshape((config.SHORT_WINDOW_SIZE, short_window_features), name='reshape_short_term')(short_term_flat)
    long_term_input = layers.Reshape((config.LONG_WINDOW_SIZE, long_window_features), name='reshape_long_term')(long_term_flat)

    if unified_encoder:
        x_dynamic = layers.Bidirectional(layers.LSTM(config.BILSTM_UNITS, return_sequences=True))(short_term_input)
        x_static = layers.Lambda(lambda x: x[:, -1, :])(x_dynamic)
    else:
        dynamic_inputs = layers.Lambda(lambda x: x[:, :, :num_dynamic_vars], name='dynamic_split')(short_term_input)
        static_inputs = layers.Lambda(lambda x: x[:, :, num_dynamic_vars:], name='static_split')(short_term_input)
        x_dynamic = layers.Bidirectional(layers.LSTM(config.BILSTM_UNITS, return_sequences=True))(dynamic_inputs)
        x_static = layers.GRU(config.GRU_UNITS_STATIC)(static_inputs)

    if use_cnn:
        x_long = layers.Conv1D(config.CONV_FILTERS, kernel_size=8, activation='relu', padding='causal')(long_term_input)
        x_long = layers.GlobalAveragePooling1D()(x_long)
    else:
        x_long = layers.GRU(config.GRU_UNITS_STATIC)(long_term_input)

    if use_attention:
        _mha = layers.MultiHeadAttention(
            num_heads=config.ATTENTION_HEADS,
            key_dim=config.BILSTM_UNITS * 2,
            name='temporal_mha'
        )
        attention_output = _mha(query=x_dynamic, value=x_dynamic)
        attention_output = layers.LayerNormalization()(layers.Add()([x_dynamic, attention_output]))
        attention_output = layers.GlobalAveragePooling1D()(attention_output)
    else:
        attention_output = layers.GlobalAveragePooling1D()(x_dynamic)

    # --- GATED FUSION: proper dual-linear GLU (A ⊗ σ(B)) ---
    combined_features = layers.Concatenate()([attention_output, x_static, x_long, context_input])
    
    glu_dim = combined_features.shape[-1]
    linear_branch = layers.Dense(glu_dim, name='glu_linear')(combined_features)          # A
    gate_branch = layers.Dense(glu_dim, activation='sigmoid', name='glu_gate')(combined_features)  # σ(B)
    fused_representation = layers.Multiply(name='glu_fusion')([linear_branch, gate_branch])
    
    fused_representation = layers.Dropout(config.DROPOUT_RATE)(fused_representation)

    # =========================================================================
    #
    # WHAT THE AUDIT ESTABLISHED
    # --------------------------
    
    # 100.01% of it to differencing the anchor's target and -0.01% to this
    # network and its adapters. The corrector was not contributing. The reason is
    # not capacity: at h=1 the anchor's residual on these series is very close to
    # unpredictable noise, so a head trained to predict that residual at every
    # point is fitting noise, and the L1 cost then correctly shrinks it to
    # nothing. Enlarging the network cannot fix an estimand problem.
    #
    # THE CHANGE OF ESTIMAND
    # ----------------------
    # Degradation is predictable even when the residual is not. So each target
    # gets TWO heads:
    #
    #     delta_raw_j   what to correct    (linear, zero-initialised)
    #     p_fault_j     whether this point is degraded  (sigmoid)
    #     delta_eff_j = p_fault_j * delta_raw_j        <-- the applied correction
    #
    # p_fault_j is SUPERVISED against the real fault mask (FaultDetectionLoss),
    # so it is a detector fitted to detectable structure -- frozen-channel and
    # drift signatures accumulated by the R16-C health features -- rather than another
    # attempt at the noise.
    #
    # THREE PROPERTIES THIS BUYS, BY CONSTRUCTION RATHER THAN BY GATING
    # -----------------------------------------------------------------
    # 1. NO CROSS-CHANNEL CONTAMINATION. The product is formed per target:
    #    target j's correction is scaled by target j's OWN fault probability and
    #    by nothing else. A degradation detected on conductivity cannot scale the
    #    temperature correction, whatever the shared trunk has learned. This is
    #    the architectural guarantee the "decoupled" framing claimed and the
    
    # 2. CLEAN-STATION PARITY. On a station with no degradation the detector's
    #    output collapses toward zero, so delta_eff -> 0 and the model reproduces
    #    the anchor. Parity on the clean testbed stops depending on a gate that
    #    declined 7 of 10 slots and becomes a limit of the architecture.
    # 3. CORRECTION WHERE IT IS EARNED. Capacity is spent on the minority of
    #    points that are actually degraded, instead of being averaged away over a
    #    majority of healthy ones.
    #
    # The zero-initialised delta head is kept, so at step 0 the model is an exact
    # identity on the anchor and training departs from parity rather than
    # arriving at it.
    #
    
    # =========================================================================
    # use_fault_gating=None -> follow Config. Comparator architectures pass
    # False explicitly: the monolithic ablation exists to represent an
    # unconstrained end-to-end network, so giving it the gating mechanism would
    # destroy the contrast the ablation is there to draw.
    use_gating = (bool(getattr(config, 'USE_FAULT_GATING', False))
                  if use_fault_gating is None else bool(use_fault_gating))
    prob_floor = float(getattr(config, 'FAULT_PROB_FLOOR', 0.0))

    # ---------------------------------------------------------------- R17
    # BOUNDED CORRECTION HEAD.  c = tau * tanh(raw / tau) bounds the
    # correction by construction (|c| <= tau) instead of relying on the
    # optimiser to keep it small, and is near-linear at small argument so it
    # does not itself introduce gradient starvation at the origin -- unlike
    # the saturated sigmoid that produced the measured logit of -42.
    # tau is per target: kappa * MAD(diff(y)) on TRAIN, in the channel's own
    # step units.  tau_per_target=None disables the bound (r16 behaviour).
    _r17 = bool(getattr(config, 'R17_ENABLE', False))
    _aux_mode = str(getattr(config, 'R17_AUX_MODE', 'off')).lower()
    _taus = dict(tau_per_target or {})

    outputs = []
    fault_outputs = []
    bare_outputs = []
    _native_model_mode = str(getattr(config, 'NATIVE_MODEL_MODE', 'direct')).lower()
    for var in target_vars:
        safe = var.replace(" ", "_")

        # A supervised degradation representation is always available when
        # USE_FAULT_GATING is on. Architecture-tournament arms decide whether
        # the correction head ignores it, consumes it as a feature, is built
        # directly from it, or is softly routed by it. This keeps the comparison
        # structural while preserving exactly the same labels and safety layer.
        det = None
        p_fault = None
        p_gate = None
        if use_gating:
            det = layers.Dense(max(8, config.HEAD_DENSE_UNITS // 2),
                               activation='relu', name=f'det_trunk_{safe}')(
                fused_representation)
            _gb = (float(getattr(config, 'R17_GATE_BIAS_INIT', 0.0))
                   if _r17 else -1.0)
            p_fault = layers.Dense(1, activation='sigmoid',
                                   bias_initializer=tf.keras.initializers.Constant(_gb),
                                   name=f'pfault_{safe}')(det)
            fault_outputs.append(p_fault)

            deadband = float(getattr(config, 'FAULT_PROB_DEADBAND', 1e-4))
            if _r17:
                deadband = float(getattr(config, 'R17_GATE_DEADBAND', deadband))
            if deadband > 0.0 and _r17:
                p_gate = layers.Lambda(
                    lambda p, d=deadband: tf.nn.relu(p - d) / (1.0 - d),
                    name=f'deadband_{safe}')(p_fault)
            elif deadband > 0.0:
                p_gate = layers.Lambda(
                    lambda p, d=deadband: p * tf.cast(p >= d, p.dtype),
                    name=f'deadband_{safe}')(p_fault)
            else:
                p_gate = p_fault

            if prob_floor > 0.0:
                p_gate = layers.Lambda(
                    lambda p, f=prob_floor: f + (1.0 - f) * p,
                    name=f'pscale_{safe}')(p_gate)

        # ---------------- architecture/representation tournament ----------------
        # control/direct: frozen shared representation + target-specific head.
        corr_source = fused_representation
        if _native_model_mode == 'detector_conditioned_direct' and p_fault is not None:
            # Feed the supervised drift score/latent to the correction head without
            # multiplying the output by it. stop_gradient on p_fault preserves the
            # detector's classification meaning while the detector latent remains a
            # learnable representation feature for the correction branch.
            p_stop = layers.Lambda(lambda p: tf.stop_gradient(p),
                                   name=f'pfault_feature_{safe}')(p_fault)
            corr_source = layers.Concatenate(name=f'corr_condition_{safe}')(
                [fused_representation, det, p_stop])
        elif _native_model_mode == 'detector_latent_direct' and det is not None:
            # Explicit degradation representation: the correction head is built from
            # a detector-specific latent plus a small general skip connection.
            drift_repr = layers.Dense(config.HEAD_DENSE_UNITS, activation='relu',
                                      name=f'drift_repr_{safe}')(det)
            general_skip = layers.Dense(config.HEAD_DENSE_UNITS, activation='relu',
                                        name=f'general_skip_{safe}')(fused_representation)
            corr_source = layers.Concatenate(name=f'dual_repr_{safe}')(
                [drift_repr, general_skip])
        elif _native_model_mode == 'deep_target_adapter':
            # Stronger target separation while retaining the shared temporal encoder.
            z = layers.LayerNormalization(name=f'adapter_ln_{safe}')(fused_representation)
            z = layers.Dense(max(96, config.HEAD_DENSE_UNITS * 2), activation='relu',
                             name=f'adapter1_{safe}')(z)
            z = layers.Dropout(float(getattr(config, 'DROPOUT', 0.3)),
                               name=f'adapter_drop_{safe}')(z)
            corr_source = layers.Dense(config.HEAD_DENSE_UNITS, activation='relu',
                                       name=f'adapter2_{safe}')(z)

        head = layers.Dense(config.HEAD_DENSE_UNITS, activation='relu',
                            name=f'trunk_{safe}')(corr_source)
        delta_raw = layers.Dense(1,
                                 kernel_initializer='zeros',
                                 bias_initializer='zeros',
                                 name=f'delta_{safe}')(head)
        _tau = float(_taus.get(var, 0.0) or 0.0)
        _disable_tanh_bound = bool(getattr(config, 'STUDY_B_DISABLE_TANH_BOUND', False))
        if _r17 and _tau > 0.0 and not _disable_tanh_bound:
            delta_raw = layers.Lambda(
                lambda x, t=_tau: t * tf.math.tanh(x / t),
                name=f'bounded_{safe}')(delta_raw)

        if not use_gating:
            delta_eff = layers.Activation('linear', name=f'head_{safe}')(delta_raw)
        elif _native_model_mode == 'moe':
            # Retained for compatibility; not a primary architecture-tournament arm.
            delta_nom = layers.Dense(1, kernel_initializer='zeros', bias_initializer='zeros',
                                     name=f'delta_nom_{safe}')(head)
            if _r17 and _tau > 0.0 and not _disable_tanh_bound:
                delta_nom = layers.Lambda(
                    lambda x, t=_tau: t * tf.math.tanh(x / t),
                    name=f'bounded_nom_{safe}')(delta_nom)
            one_minus = layers.Lambda(lambda p: 1.0 - p, name=f'one_minus_p_{safe}')(p_fault)
            drift_part = layers.Multiply(name=f'drift_expert_{safe}')([delta_raw, p_fault])
            nom_part = layers.Multiply(name=f'nom_expert_{safe}')([delta_nom, one_minus])
            delta_eff = layers.Add(name=f'head_{safe}')([drift_part, nom_part])
        elif _native_model_mode == 'gated_auxiliary_rescue':
            # Structural nominal suppression with a full-gradient rescue path.
            # The deployed output is softly routed by p_fault, while the same raw
            # correction is exposed below as a BARE auxiliary head and trained on
            # degraded rows only. This directly addresses the previously observed
            # gate-gradient starvation without reintroducing a post-hoc selector.
            delta_eff = layers.Multiply(name=f'head_{safe}')([delta_raw, p_gate])
        else:
            # direct, detector-conditioned, detector-latent and target-adapter arms.
            delta_eff = layers.Activation('linear', name=f'head_{safe}')(delta_raw)
        outputs.append(delta_eff)

        if _r17 and _aux_mode == 'bare':
            bare_outputs.append(
                layers.Activation('linear', name=f'bare_{safe}')(delta_raw))

    all_outputs = outputs + fault_outputs + bare_outputs
    model = Model(inputs=[unified_input, context_input], outputs=all_outputs,
                  name=f"M2P_PTAC{name_suffix}")
    # Recorded on the model so callers can build matching loss/target lists
    # without re-deriving the convention. The output order is
    # [delta_eff per target] + [p_fault per target].
    model._m2p_n_targets = len(target_vars)
    model._m2p_gated = bool(use_gating and fault_outputs)
    model._m2p_bare = bool(bare_outputs)
    model._m2p_r17 = _r17
    model._m2p_taus = dict(_taus)
    model._m2p_target_vars = list(target_vars)
    if use_attention:
        model._m2p_attention_sequence_tensor = x_dynamic
        model._m2p_attention_layer_name = 'temporal_mha'
    return model


def save_live_attention_scores(model, X_seq, X_ctx, test_index, config,
                               model_name, dataset_name, target_vars):
    """Internal experiment utility."""
    if not bool(getattr(config, 'SAVE_LIVE_ATTENTION_SCORES', False)):
        return None
    seq_tensor = getattr(model, '_m2p_attention_sequence_tensor', None)
    layer_name = getattr(model, '_m2p_attention_layer_name', None)
    if seq_tensor is None or not layer_name:
        return None
    try:
        n = min(len(X_seq), int(getattr(config, 'ATTENTION_SCORE_MAX_SAMPLES', 64)))
        if n <= 0:
            return None
        seq_model = Model(inputs=model.inputs, outputs=seq_tensor)
        q = seq_model.predict([np.asarray(X_seq)[:n], np.asarray(X_ctx)[:n]],
                              verbose=0)
        att = model.get_layer(layer_name)
        _, scores = att(query=q, value=q, return_attention_scores=True,
                        training=False)
        scores = np.asarray(scores, dtype=np.float32)
        ds = _safe_filename(dataset_name)
        arm = _safe_filename(model_name)
        path = os.path.join(config.OUTPUT_DIR,
                            f'attention_scores_live_{ds}__{arm}.npz')
        np.savez_compressed(
            path, scores=scores,
            test_index=np.asarray(pd.DatetimeIndex(test_index)[:n].astype(str)),
            model_name=np.asarray([str(model_name)]),
            dataset_name=np.asarray([str(dataset_name)]),
            targets=np.asarray([str(v) for v in target_vars]))
        print(f"    [ATTN-LIVE] saved TRUE attention probabilities from the "
              f"trained graph -> {os.path.basename(path)} "
              f"shape={scores.shape}")
        return path
    except Exception as e:
        print(f"    [ATTN-LIVE] export failed ({type(e).__name__}: {e}); "
              "forecast metrics are unaffected.")
        return None


class SyntheticDriftInjector:
    """Internal experiment utility."""

    def __init__(self, config):
        self.config = config

    @staticmethod
    def _reference_scale(df_clean, var, train_val_end):
        """Internal experiment utility."""
        _v = df_clean[var].values.astype(float)[:train_val_end]
        _v = _v[np.isfinite(_v)]
        if _v.size == 0:
            return {'std': 1.0, 'abs_mean': 1.0}
        return {'std': max(float(np.std(_v)), 1e-12),
                'abs_mean': max(float(np.mean(np.abs(_v))), 1e-12)}

    def apply_drift(self, df, drift_type, intensity, target_vars,
                    history_episodes=0, history_seed=None,
                    history_intensity=None):
        """Internal experiment utility."""
        df_drifted = df.copy()
        df_clean_truth = df.copy()          # pristine signal, never corrupted
        
        # discarded that knowledge, so downstream the only fault labels available
        # were the DQA-derived ones -- which do not mark synthetically drifted
        # rows at all. The rescue metric therefore found zero positives on every
        # arm of the stress sweep and returned an empty curve, which reads as
        # "no rescue" when it actually means "never measured". The mask is now
        # returned so the drift arm can label its own injected episodes.
        drift_mask = pd.DataFrame(False, index=df.index, columns=df.columns)
        self.last_drift_mask = drift_mask
        n = len(df)
        _train_end, train_val_end, _test_start = _raw_split_boundaries(
            self.config, n)
        test_len = n - _test_start
        if test_len <= 0:
            return df, df_clean_truth

        # that the I=0 control arm has them too -- otherwise the null control
        # would differ from the drift arms in two ways at once (no test drift
        # AND no gate supervision) and could not isolate the corrector's
        # behaviour when nothing is wrong.
        if history_episodes and drift_type not in (None, 'none'):
            _history_intensity = (float(intensity) if history_intensity is None
                                  else float(history_intensity))
            self._inject_history(df_drifted, df_clean_truth, drift_mask,
                                 drift_type, _history_intensity, target_vars,
                                 train_val_end, history_episodes, history_seed)

        # independently of intensity, so criterion (c) is evaluable.
        #
        # The null control was structurally unevaluable before this. At I=0 no
        # value moves, so the moved-rows mask is empty, n_drift_rows is 0, and
        # R(0) comes back "unavailable" on every channel -- which is precisely
        # the cell the acceptance gate needs in order to ask "does the corrector
        # harm clean data?". Every run therefore reported null=None and REJECTed
        # for want of evidence rather than because of evidence. The footprint is
        # the same row set the episode would occupy at any intensity, so R(0)
        # measured over it answers the intended question: on exactly the rows
        # that WOULD be fouled, what does the corrector do when they are clean?
        self.last_episode_footprint = pd.DataFrame(
            False, index=df.index, columns=df.columns)
        _fp = np.zeros(n, dtype=bool)
        if drift_type == 'gradual_bias':
            _fp[_test_start:] = True
        elif drift_type == 'sudden_shift':
            _fp[_test_start + test_len // 2:] = True
        elif drift_type == 'noise_spikes':
            _fp[_test_start:] = True
        for _v in target_vars:
            if _v in df.columns:
                self.last_episode_footprint[_v] = _fp

        # I = 0 is the mandatory control arm: identical pipeline, zero drift.
        if intensity == 0 or drift_type in (None, 'none'):
            # NULL CONTROL: no value moves, so no row is *drifted*. The mask
            # handed downstream is the episode FOOTPRINT, not the moved-rows
            # set: the rows are clean, and R over them is exactly the harm
            # measurement criterion (c) asks for. Returning an all-False mask
            # here (the R17 behaviour) made the null control unevaluable.
            for _v in target_vars:
                if _v in df.columns:
                    drift_mask[_v] = (drift_mask[_v].values.astype(bool) | _fp)
            self.last_null_control = True
            return df_drifted, df_clean_truth
        self.last_null_control = False

        rng = np.random.default_rng(self.config.SEED)
        for var in target_vars:
            if var not in df.columns:
                continue
            original_signal = df_drifted[var].values.astype(float).copy()
            test_signal = original_signal[_test_start:].copy()
            #
            # Both the history episodes and the test episode previously scaled
            # `intensity` by the statistics of their OWN window. On this station
            # EC has train sigma 198.2 and test sigma 17.7 -- an 11x difference
            # -- so I=2 meant +365 uS/cm in the history episodes and +35 uS/cm
            
            # drift almost perfectly on validation (mean p_fault 0.81 on drifted
            # rows vs 0.013 on clean) and almost not at all on test (0.023 vs
            # 0.008), because the test signature was an order of magnitude
            # smaller than anything it was trained on. Every sudden_shift arm
            # abstained and the curve read as a flat zero.
            #
            # Scaling both against the reference window makes `intensity` one
            # physical magnitude across the whole run, which is also what the
            # sweep's x-axis has to mean for the rescue curve to be readable.
            _ref = self._reference_scale(df_clean_truth, var, train_val_end)

            if drift_type == 'gradual_bias':
                ramp = np.linspace(0, intensity * _ref['abs_mean'], test_len)
                test_signal = test_signal + ramp
            elif drift_type == 'sudden_shift':
                shift_val = intensity * _ref['std']
                test_signal[test_len // 2:] += shift_val
            elif drift_type == 'noise_spikes':
                mask = rng.choice([0, 1], size=test_len, p=[0.9, 0.1])
                noise = rng.normal(0, intensity * np.std(test_signal), test_len)
                test_signal = test_signal + (mask * noise)

            original_signal[_test_start:] = test_signal
            df_drifted[var] = original_signal
            # Mark the rows whose value actually moved. Using a tolerance
            # relative to the signal scale rather than exact inequality keeps
            # float round-trip noise from being labelled as drift, and keeps
            # the leading rows of a ramp (where the added bias is numerically
            # negligible) out of the positive class -- labelling those would
            # inflate the denominator of R with rows that carry no drift.
            _tol = 1e-9 + 1e-6 * float(np.nanstd(df_clean_truth[var].values))
            _moved = np.abs(original_signal
                            - df_clean_truth[var].values.astype(float)) > _tol
            drift_mask[var] = _moved

        return df_drifted, df_clean_truth

    # ================================================================== R19-P
    # MODEL-VISIBLE HISTORY PROVISIONING.
    #
    # The previous injector split RAW pre-test rows into train/calibration/
    # safety regions. PTACExperiment later splits POST-FEATURE/POST-WINDOW
    # `common_indices`. The two coordinate systems do not coincide. This is why
    # the September-1 run could request two safety episodes yet R19 saw only
    # 7 degraded rows from one episode.
    # ================================================================== R19-P

    @staticmethod
    def _r19_contiguous_runs(positions):
        """Split sorted integer dataframe positions into contiguous runs."""
        p = np.asarray(positions, dtype=int).reshape(-1)
        if p.size == 0:
            return []
        p = np.unique(p)
        cuts = np.where(np.diff(p) != 1)[0] + 1
        return [x for x in np.split(p, cuts) if x.size]

    def _r19_allocate_role_episodes(self, role_positions, count, length, rng,
                                    role):
        """Allocate separated episodes wholly inside model-visible role rows."""
        p = np.asarray(role_positions, dtype=int).reshape(-1)
        p = np.unique(p[p >= 0])
        count = int(count)
        length = int(length)
        if count <= 0:
            return []
        if p.size == 0:
            raise RuntimeError(
                f"[R19-P] role={role}: no model-visible rows are available.")

        edges = np.linspace(0, len(p), count + 1, dtype=int)
        episodes = []
        for k in range(count):
            slot = p[edges[k]:edges[k + 1]]
            if slot.size <= length:
                raise RuntimeError(
                    f"[R19-P] role={role}: slot {k+1}/{count} has only "
                    f"{slot.size} visible rows; cannot fit episode length "
                    f"{length} plus a nominal separator.")

            # Reserve one model-visible row at the end of every slot. This
            # guarantees that adjacent intended episodes cannot collapse into a
            # single evidence unit after reindexing.
            usable = slot[:-1]
            runs = [r for r in self._r19_contiguous_runs(usable)
                    if len(r) >= length]
            if not runs:
                raise RuntimeError(
                    f"[R19-P] role={role}: no contiguous model-visible run of "
                    f"length {length} exists in slot {k+1}/{count}.")
            run = max(runs, key=len)
            slack = len(run) - length
            offset = int(rng.integers(0, slack + 1)) if slack > 0 else 0
            s = int(run[offset])
            e = int(s + length)
            episodes.append((s, e, role))
        return episodes

    def _r19_model_visible_history_plan(self, df_clean_truth, target_vars,
                                        drift_type, n_episodes, seed):
        """Plan R18 history episodes on PTAC's exact forecast-origin index."""
        rng = np.random.default_rng(
            self.config.SEED + 977 if seed is None else int(seed))
        n_episodes = int(n_episodes)
        if n_episodes <= 0:
            return []

        # Reproduce the first lines of PTACExperiment.run() on the pristine
        # frame. Injection changes values, not timestamps. A second audit inside
        # PTACExperiment verifies the actual post-injection visible index before
        # any expensive model fitting begins.
        X_tab, _, _ = create_tabular_features(
            df_clean_truth, target_vars, config=self.config, return_delta=True)
        df_m2p_input = df_clean_truth.copy()
        time_features = ['hour_sin', 'hour_cos']
        df_m2p_input['hour_sin'] = np.sin(
            2 * np.pi * df_m2p_input.index.hour / 24.0)
        df_m2p_input['hour_cos'] = np.cos(
            2 * np.pi * df_m2p_input.index.hour / 24.0)
        _, m2p_indices = create_m2p_features(
            df_m2p_input, target_vars, time_features, self.config)
        common_indices = X_tab.index.intersection(m2p_indices)

        if len(common_indices) < 30:
            raise RuntimeError(
                f"[R19-P] only {len(common_indices)} model-visible rows; "
                "cannot provision an audited synthetic curriculum.")

        # ------------------------------------------------------------- R27B
        # FIXED RAW-TIME CHRONOLOGICAL SPLIT.
        #
        # Never derive train/val/test cutoffs from len(common_indices): that
        # length is data-dependent because create_tabular_features().dropna()
        # can retain/drop TEST rows differently under different held-out drift
        # intensities. Using a fraction of the post-feature length therefore
        # lets future test conditions move the earlier validation boundary.
        #
        # Define chronology on the pristine RAW index first, then intersect each
        # immutable time block with the model-visible index.
        _raw_n = len(df_clean_truth)
        _raw_train_end, _raw_val_end, _raw_test_start = _raw_split_boundaries(
            self.config, _raw_n)
        _raw_train_idx = pd.Index(df_clean_truth.index[:_raw_train_end])
        _raw_val_idx = pd.Index(df_clean_truth.index[_raw_train_end:_raw_val_end])
        _raw_test_idx = pd.Index(df_clean_truth.index[_raw_test_start:])

        train_idx = pd.Index([ix for ix in common_indices if ix in _raw_train_idx])
        val_idx = pd.Index([ix for ix in common_indices if ix in _raw_val_idx])
        test_idx = pd.Index([ix for ix in common_indices if ix in _raw_test_idx])
        train_end = len(train_idx)
        val_end = train_end + len(val_idx)

        if train_end == 0 or len(val_idx) == 0 or len(test_idx) == 0:
            raise RuntimeError(
                "[R27B] raw-time split produced an empty model-visible block: "
                f"train={train_end}, val={len(val_idx)}, test={len(test_idx)}")

        n_val = len(val_idx)
        n_cal, n_safe, n_csel = _resolve_validation_roles(self.config, n_val)

        cal_idx = pd.Index(val_idx[:n_cal])
        safe_idx = pd.Index(val_idx[n_cal:n_cal + n_safe])
        csel_idx = pd.Index(val_idx[n_cal + n_safe:n_cal + n_safe + n_csel])

        _r22_active = bool(getattr(self.config, '_r22_stress_active', False))
        _custom_counts = dict(getattr(self.config, 'R19_HISTORY_ROLE_COUNTS', {}) or {})
        if bool(getattr(self.config, 'R19_FULL_EVIDENCE_MODE', False)):
            counts = {
                'train': int(_custom_counts.get('train', 6)),
                'calibration': int(_custom_counts.get('calibration', 2)),
                'safety': int(_custom_counts.get('safety', 6)),
                'c_selection': int(_custom_counts.get('c_selection', 0)),
            }
            _planned = int(sum(counts.values()))
            if _planned != n_episodes:
                raise RuntimeError(
                    f"[R19-FULL] history_episodes={n_episodes}, but role counts "
                    f"sum to {_planned}: {counts}.")
            print(f"[R19-FULL] history role counts: {counts}")
        elif _r22_active:
            _cfg_counts = dict(getattr(
                self.config, 'R22_STRESS_HISTORY_ROLE_COUNTS', {}) or {})
            counts = {
                'train': int(_cfg_counts.get('train', 4)),
                'calibration': int(_cfg_counts.get('calibration', 4)),
                'safety': int(_cfg_counts.get('safety', 4)),
                'c_selection': int(_cfg_counts.get('c_selection', 2)),
            }
            _planned = int(sum(counts.values()))
            if _planned != n_episodes:
                raise RuntimeError(
                    f"[R22] history_episodes={n_episodes}, but configured role "
                    f"counts sum to {_planned}: {counts}. Keep these identical "
                    "so the stress curriculum is auditable.")
        elif n_episodes >= 6:
            counts = {'train': n_episodes - 4,
                      'calibration': 2, 'safety': 2, 'c_selection': 0}
        elif n_episodes >= 4:
            counts = {'train': n_episodes - 2,
                      'calibration': 1, 'safety': 1, 'c_selection': 0}
        else:
            counts = {'train': max(1, n_episodes - 1),
                      'calibration': int(n_episodes >= 2), 'safety': 0,
                      'c_selection': 0}

        min_units = int(getattr(
            self.config, 'R19_SAFETY_MIN_EVIDENCE_UNITS', 2))
        if bool(getattr(self.config, 'R19_SAFETY_VETO', False)) \
                and counts['safety'] < min_units:
            raise RuntimeError(
                f"[R19-P] n_episodes={n_episodes} provisions only "
                f"{counts['safety']} safety episode(s), but R19 requires "
                f"{min_units}.")
        if bool(getattr(self.config, 'R20_UTILITY_GATE', False)) \
                and counts['calibration'] < min_units:
            raise RuntimeError(
                f"[R19-P] n_episodes={n_episodes} provisions only "
                f"{counts['calibration']} calibration episode(s), but the "
                f"utility gate requires {min_units}.")

        raw_index = pd.Index(df_clean_truth.index)
        role_idx = {'train': train_idx,
                    'calibration': cal_idx,
                    'safety': safe_idx,
                    'c_selection': csel_idx}
        role_pos = {}
        for role, idx in role_idx.items():
            pos = raw_index.get_indexer(idx)
            if np.any(pos < 0):
                raise RuntimeError(
                    f"[R19-P] role={role}: a model-visible timestamp is "
                    "missing from the raw dataframe index.")
            role_pos[role] = pos.astype(int)

        min_ep = max(2, int(getattr(
            self.config, 'R19_SYNTHETIC_MIN_EPISODE_LEN', 6)))
        req_deg = {
            'calibration': int(getattr(self.config, 'R20_MIN_DEGRADED', 8)),
            'safety': int(getattr(self.config, 'R19_SAFETY_MIN_DEGRADED', 8)),
            'c_selection': int(getattr(
                self.config, 'R22_STRESS_CSEL_MIN_DEGRADED', 8)),
        }
        req_nom = {
            'calibration': int(getattr(self.config, 'R20_MIN_NOMINAL', 8)),
            'safety': int(getattr(self.config, 'R19_SAFETY_MIN_NOMINAL', 8)),
            'c_selection': int(getattr(
                self.config, 'R22_STRESS_CSEL_MIN_NOMINAL', 8)),
        }

        lengths = {}
        _evidence_roles = [r for r in ('calibration', 'safety')
                           if int(counts.get(r, 0)) > 0]
        if counts.get('c_selection', 0) > 0:
            _evidence_roles.append('c_selection')
        for role in _evidence_roles:
            c = max(1, int(counts[role]))
            if drift_type == 'gradual_bias':
                # First ramp point is exactly unchanged, so k points produce
                # k-1 genuinely degraded rows.
                need = int(np.ceil(req_deg[role] / c)) + 1
                max_by_nom = int(np.floor(
                    (len(role_pos[role]) - req_nom[role]) / c)) + 1
            else:
                need = int(np.ceil(req_deg[role] / c))
                max_by_nom = int(np.floor(
                    (len(role_pos[role]) - req_nom[role]) / c))
            length = max(min_ep, need)
            if counts[role] > 0 and length > max_by_nom:
                raise RuntimeError(
                    f"[R19-P] role={role}: visible rows={len(role_pos[role])}, "
                    f"episodes={counts[role]}, required degraded={req_deg[role]}, "
                    f"required nominal={req_nom[role]}; episode length "
                    f"{length} cannot satisfy both without weakening R19/R20.")
            lengths[role] = length

        # ------------------------------------------------------------- R23
        # Restore model-visible degradation DENSITY without weakening the
        # safety policy.  The older high-rescue implementation exposed many
        # more degraded validation rows; the first model-visible repair fixed
        # alignment but shortened every evidence episode to the minimum.  Here
        # we request the longest pre-specified episode lengths that still leave
        # the required nominal support.  The existing max_by_nom calculation is
        # re-evaluated below, so this cannot silently consume the clean control
        # rows or relax R19/R20.
        if (_r22_active and bool(getattr(
                self.config, 'R23_STRESS_DENSE_EPISODES', False))):
            _dense_all = dict(getattr(
                self.config, 'R23_STRESS_ROLE_EPISODE_LENGTHS', {}) or {})
            _dense = dict(_dense_all.get(drift_type, {}) or {})
            for role in _evidence_roles:
                if role not in _dense or int(counts.get(role, 0)) <= 0:
                    continue
                _want = int(_dense[role])
                _c = max(1, int(counts[role]))
                _reserve = max(
                    int(req_nom[role]),
                    int(getattr(self.config, 'R24_STRESS_NOMINAL_RESERVE',
                                req_nom[role])))
                if drift_type == 'gradual_bias':
                    _mx = int(np.floor(
                        (len(role_pos[role]) - _reserve) / _c)) + 1
                else:
                    _mx = int(np.floor(
                        (len(role_pos[role]) - _reserve) / _c))
                if _mx < int(lengths[role]):
                    raise RuntimeError(
                        f"[R24] {drift_type}/{role}: nominal reserve {_reserve} "
                        f"would force episode length {_mx} below the minimum "
                        f"length {lengths[role]} required for >="
                        f"{req_deg[role]} degraded rows.")
                _use = min(_want, _mx)
                if _use < _want:
                    print(f"[R24] capped {drift_type}/{role} dense episode "
                          f"length {_want}->{_use} to reserve >="
                          f"{_reserve} nominal model-visible rows.")
                lengths[role] = max(int(lengths[role]), int(_use))
            print(f"[R23] dense model-visible episode lengths for "
                  f"{drift_type}: {lengths}")

        # Preserve the previous training-curriculum duration scale as closely
        # as possible: the legacy formula used total pre-test length divided by
        # (all history episodes * 3). Only the COORDINATE SYSTEM changes here.
        visible_pretest = len(train_idx) + len(val_idx)
        lengths['train'] = max(
            8, int(visible_pretest // max(3 * n_episodes, 1)))

        # ------------------------------------------------------------- R38-A
        # Causal-isolation experiment: duration-matched gradual curriculum.
        #
        # fold) but evaluated a 90-d ramp. With the same terminal fraction 0.15,
        # the historical per-day slope was therefore ~6.85x to 12.71x faster.
        #
        # This flag changes ONLY TRAIN gradual-bias episode duration so that the
        # ramp duration equals the immutable held-out TEST duration of the fold.
        # Terminal intensity remains 0.15; architecture, anchor, gates, C,
        # validation roles, safety evidence thresholds, and test injection are
        # unchanged.
        if bool(getattr(
                self.config, 'R38_DURATION_MATCHED_GRADUAL', False))                 and drift_type == 'gradual_bias':
            _raw_n = len(df_clean_truth)
            _, _, _raw_test_start = _raw_split_boundaries(
                self.config, _raw_n)
            _test_len = int(_raw_n - _raw_test_start)
            if _test_len < 2:
                raise RuntimeError(
                    '[R38-A] invalid raw test duration for duration matching.')
            lengths['train'] = int(_test_len)
            _hist_I = float((getattr(
                self.config, 'R18_FIXED_HISTORY_INTENSITY', {}) or {})
                .get('gradual_bias', 0.15))
            _slope = _hist_I / float(_test_len - 1)
            print(
                f"[R38-A] duration-matched gradual TRAIN ramps: "
                f"duration={_test_len} rows, terminal_fraction={_hist_I:g}, "
                f"fractional_slope_per_row={_slope:.8f}; "
                f"train_episodes={int(counts.get('train', 0))}"
            )

        episodes = []
        for role in ('train', 'calibration', 'safety', 'c_selection'):
            c = int(counts.get(role, 0))
            if c <= 0:
                continue
            _len = lengths['train'] if role == 'train' else lengths[role]
            episodes.extend(self._r19_allocate_role_episodes(
                role_pos[role], c, _len, rng, role))
        episodes.sort(key=lambda x: x[0])

        if bool(getattr(
                self.config, 'R38_DURATION_MATCHED_GRADUAL', False))                 and drift_type == 'gradual_bias':
            _raw_n = len(df_clean_truth)
            _, _, _raw_test_start = _raw_split_boundaries(
                self.config, _raw_n)
            _test_len = int(_raw_n - _raw_test_start)
            _train_eps = [(s, e, r) for s, e, r in episodes if r == 'train']
            _expected_n = int(getattr(
                self.config, 'R38_DURATION_MATCHED_TRAIN_EPISODES', 2))
            if len(_train_eps) != _expected_n:
                raise RuntimeError(
                    f"[R38-A] expected {_expected_n} train gradual episodes, "
                    f"got {len(_train_eps)}.")
            _dur = [int(e - s) for s, e, _ in _train_eps]
            if any(d != _test_len for d in _dur):
                raise RuntimeError(
                    f"[R38-A] duration audit failed: train durations={_dur}, "
                    f"expected all {_test_len}.")
            print(
                f"[R38-A] AUDIT PASS: train gradual episodes={_train_eps}; "
                f"all durations exactly match held-out test duration={_test_len}."
            )

        return episodes

    def _inject_history(self, df_drifted, df_clean_truth, drift_mask,
                        drift_type, intensity, target_vars, train_val_end,
                        n_episodes, seed):
        """Inject audited history episodes on the exact model-visible splits."""
        rng = np.random.default_rng(
            self.config.SEED + 977 if seed is None else int(seed))
        n_episodes = int(n_episodes)
        self.last_history_episodes = []
        if train_val_end < 40 or n_episodes <= 0:
            return

        try:
            episodes = self._r19_model_visible_history_plan(
                df_clean_truth, target_vars, drift_type, n_episodes, seed)
        except Exception as exc:
            _register_release_failure(
                self.config, 'SYNTHETIC_CURRICULUM_PROVISIONING_FAILED',
                str(exc))
            raise

        _r22_active = bool(getattr(self.config, '_r22_stress_active', False))
        _r22_specs = (getattr(
            self.config, 'R22_STRESS_HISTORY_ROLE_INTENSITIES', {}) or {})
        _r22_specs = dict(_r22_specs.get(drift_type, {}) or {})
        _role_ord = {}
        _ep_specs = []
        for s, e, role in episodes:
            k = int(_role_ord.get(role, 0))
            _role_ord[role] = k + 1
            _ival = float(intensity)
            if _r22_active and role in _r22_specs:
                _vals = _r22_specs[role]
                if np.isscalar(_vals):
                    _ival = float(_vals)
                else:
                    _vals = list(_vals)
                    if not _vals:
                        raise RuntimeError(
                            f"[R22] empty history-intensity schedule for "
                            f"{drift_type}/{role}.")
                    _ival = float(_vals[k % len(_vals)])
            _ep_specs.append((int(s), int(e), role, _ival))

        self.last_history_episodes = [
            {'start': s, 'stop': e, 'role': role, 'intensity': ival}
            for s, e, role, ival in _ep_specs]
        role_counts = {
            role: sum(1 for _, _, r, _ in _ep_specs if r == role)
            for role in ('train', 'calibration', 'safety', 'c_selection')
        }
        print("[R19-P] model-visible synthetic curriculum: "
              + ", ".join(f"{k}={v} episode(s)"
                          for k, v in role_counts.items()))
        if _r22_active:
            print(f"[R22] fixed multi-severity history schedule for "
                  f"{drift_type}: {self.last_history_episodes}")
        else:
            print("[R19-P] raw-position episodes: "
                  + str(self.last_history_episodes))

        for var in target_vars:
            if var not in df_drifted.columns:
                continue
            sig = df_drifted[var].values.astype(float).copy()
            clean = df_clean_truth[var].values.astype(float)
            scale = float(np.nanstd(clean[:train_val_end]))
            base = float(np.nanmean(np.abs(clean[:train_val_end])))
            if not np.isfinite(scale) or scale <= 0:
                scale = 1.0
            if not np.isfinite(base) or base <= 0:
                base = 1.0

            marks = np.zeros(len(sig), dtype=bool)
            for s, e, _role, _ival in _ep_specs:
                k = int(e - s)
                if k <= 1:
                    continue
                if drift_type == 'gradual_bias':
                    sig[s:e] += np.linspace(0.0, _ival * base, k)
                elif drift_type == 'sudden_shift':
                    sig[s:e] += _ival * scale
                elif drift_type == 'noise_spikes':
                    hit = rng.random(k) < 0.10
                    sig[s:e] += hit * rng.normal(
                        0.0, _ival * scale, k)
                marks[s:e] = True

            df_drifted[var] = sig
            tol = 1e-9 + 1e-6 * scale
            moved = np.abs(sig - clean) > tol
            drift_mask[var] = (
                np.asarray(drift_mask[var].values, dtype=bool)
                | (moved & marks))


# ============================================================================
# --- PATCH-A1: SHARED CAUSAL DRIFT-BANK BLOCK (feature parity) ------------
# ============================================================================
def _safe_filename(name, maxlen=80):
    """Internal experiment utility."""
    s = re.sub(r'[^0-9A-Za-z._-]+', '_', str(name)).strip('_')
    return (s[:maxlen] or 'unnamed')


def attach_drift_bank_block(df, target_vars, config, index, train_end,
                            tag='unknown'):
    """Internal experiment utility."""
    empty = pd.DataFrame(index=index)
    if not (bool(getattr(config, 'R17_ENABLE', False)) and
            bool(getattr(config, 'R17_DRIFT_BANK', False))):
        return empty
    if not target_vars or train_end <= 1:
        return empty
    _per_day = float(getattr(config, '_steps_per_day', 24) or 24)
    # Battery voltage is deliberately unavailable to every model so the
    # in-house and VUB feature contracts are identical.
    _hc = None
    _banks = []
    for _v in target_vars:
        _b = build_drift_bank(df, _v, _per_day, config, health_channel=_hc,
                              max_history_rows=train_end)
        if _b.shape[1]:
            _b = _b.add_prefix(f"{_v.replace(' ', '_')}__")
            _banks.append(_b)
    if not _banks:
        return empty
    _bank = pd.concat(_banks, axis=1).reindex(index)
    # Train-slice medians only: an imputation value computed over the whole
    # frame would import test-window information.
    _fill = _bank.iloc[:train_end].median(numeric_only=True)
    _bank = _bank.fillna(_fill).fillna(0.0)
    # Drop columns that are constant on TRAIN -- they carry no information and
    # would be divided by a clamped sigma.
    _keep = [c for c in _bank.columns
             if float(_bank[c].iloc[:train_end].std()) > 1e-12]
    _bank = _bank[_keep]
    # Record the realised layout so a post-run parity check can compare the
    # PTAC and comparator arms without re-deriving anything.
    try:
        _reg = getattr(config, '_r17_bank_registry', None)
        if _reg is None:
            _reg = {}
            config._r17_bank_registry = _reg
        _reg[str(tag)] = dict(n_cols=int(_bank.shape[1]),
                              cols=[str(c) for c in _bank.columns],
                              n_rows=int(len(index)), train_end=int(train_end))
    except Exception:
        pass
    return _bank


def build_causal_anchor_jump_context(anchor_residuals, target_vars, config):
    """Internal experiment utility."""
    if anchor_residuals is None or len(anchor_residuals) == 0:
        return pd.DataFrame(index=getattr(anchor_residuals, 'index', None))
    _spd = int(getattr(config, '_steps_per_day', 24) or 24)
    _w = getattr(config, 'STUDY_A_JUMP_WINDOW', None)
    _w = int(_w if _w is not None else (max(6, _spd) if _spd > 1 else 7))
    _short = max(3, min(_w // 4, 6))
    _minp = max(4, min(_w, _w // 3))
    out = pd.DataFrame(index=anchor_residuals.index)

    def _mad(x):
        a = np.asarray(x, dtype=float)
        a = a[np.isfinite(a)]
        if a.size == 0:
            return np.nan
        m = np.median(a)
        return float(np.median(np.abs(a - m)))

    for v in target_vars:
        if v not in anchor_residuals.columns:
            continue
        r = pd.to_numeric(anchor_residuals[v], errors='coerce').astype(float)
        newest = r.shift(1)                  # known at forecast row t
        previous = r.shift(2)
        hist = r.shift(2)                    # reference ends at t-2
        med = hist.rolling(_w, min_periods=_minp).median()
        mad = hist.rolling(_w, min_periods=_minp).apply(_mad, raw=True)
        robust = (1.4826 * mad).abs() + 1e-6
        z = (newest - med) / robust
        dz = (newest - previous) / robust
        short_mean = newest.rolling(_short, min_periods=2).mean()
        long_med = hist.rolling(_w, min_periods=_minp).median()
        level_sep = (short_mean - long_med) / robust
        z0 = z.replace([np.inf, -np.inf], np.nan).fillna(0.0).values
        cpos, cneg = _one_sided_cusum(z0, k=0.5)
        sig = np.where(np.abs(z0) >= 1.0, np.sign(z0), 0.0)
        persist = np.clip(_signed_run_length(sig), -float(_w), float(_w))
        safe = v.replace(' ', '_')
        out[f'{safe}__jump_signed_lag1'] = z
        out[f'{safe}__jump_abs_lag1'] = z.abs()
        out[f'{safe}__jump_derivative_lag1'] = dz
        out[f'{safe}__jump_levelsep_lag1'] = level_sep
        out[f'{safe}__jump_cusum_pos_lag1'] = cpos
        out[f'{safe}__jump_cusum_neg_lag1'] = cneg
        out[f'{safe}__jump_persist_lag1'] = persist
    return out.replace([np.inf, -np.inf], np.nan)

def parity_report(config, verbose=True, dataset=None):
    """Internal experiment utility."""
    _reg = dict(getattr(config, '_r17_bank_registry', {}) or {})
    # The registry lives on the config object, which is REUSED across testbeds,
    # so it accumulates arms from every dataset run so far. Comparing a
    # comparator on one testbed against a PTAC arm on another would be
    # meaningless (different channels, different lengths), so scope to the
    # dataset under report. Tags are 'ptac:<dataset>:<arm>' / 'cmp:<dataset>:<arm>'.
    if dataset:
        _scoped = {k: v for k, v in _reg.items()
                   if len(str(k).split(':')) > 1
                   and str(k).split(':')[1] == str(dataset)}
        if _scoped:
            _reg = _scoped
        elif verbose:
            print(f"    [A1] no drift-bank records tagged for dataset "
                  f"'{dataset}'; reporting all {len(_reg)} recorded arm(s).")
    if not _reg:
        if verbose:
            print("    [A1] drift-bank registry empty (R17 bank disabled?).")
        return pd.DataFrame()
    rows = []
    _sets = {k: set(v['cols']) for k, v in _reg.items()}
    _ref_key = next((k for k in _reg if k.startswith('ptac')), sorted(_reg)[0])
    _ref = _sets[_ref_key]
    for k, v in sorted(_reg.items()):
        rows.append(dict(arm=k, n_bank_cols=v['n_cols'], n_rows=v['n_rows'],
                         train_end=v['train_end'],
                         identical_set_to_ref=bool(_sets[k] == _ref),
                         n_missing_vs_ref=len(_ref - _sets[k]),
                         n_extra_vs_ref=len(_sets[k] - _ref)))
    out = pd.DataFrame(rows)
    if verbose:
        print(f"    [A1] drift-bank parity (reference arm = '{_ref_key}'):")
        print(out.to_string(index=False))
        _bad = out[~out.identical_set_to_ref]
        if len(_bad):
            print(f"    [A1] NOTE: {len(_bad)} arm(s) differ from the reference "
                  f"column set. Differences arise only from each arm's own "
                  f"constant-on-train filter; no arm is missing the bank.")
    return out


