# ============================================================================
def _raw_split_boundaries(config, n):
    """Return (train_end, val_end, test_start) in RAW dataframe coordinates.

    Ordinary runs preserve the historical contiguous split, where test_start
    equals val_end. R32 confirmation freezes the exact development chronology
    while leaving rows [val_end:test_start) out of fitting, authorization and
    scoring. Those bridge rows remain available only as observed past context
    for causal h=1 features at the later confirmation timestamps.
    """
    n = int(n)
    if bool(getattr(config, 'R32_EXPLICIT_RAW_SPLIT', False)):
        tr = int(getattr(config, 'R32_RAW_TRAIN_END', 428))
        va = int(getattr(config, 'R32_RAW_VAL_END', 550))
        te = int(getattr(config, 'R32_RAW_TEST_START', 612))
        if not (0 < tr < va <= te < n):
            raise ValueError(
                f"[R32] invalid raw boundaries train={tr}, val={va}, "
                f"test_start={te}, n={n}")
        return tr, va, te
    tr = int(n * float(getattr(config, 'TRAIN_SPLIT', 0.70)))
    va = int(n * float(
        getattr(config, 'TRAIN_SPLIT', 0.70)
        + getattr(config, 'VAL_SPLIT', 0.15)))
    return tr, va, va


# ============================================================================
# ============================================================================
def _resolve_validation_roles(config, n_val):
    """Return (n_calibration, n_safety, n_csel) for outer validation.

    In R19_FULL_EVIDENCE_MODE we retain the historical R18 detector operating
    threshold calibration on a small disjoint prefix, dedicate essentially all
    remaining rows to R19, and keep one final row only because legacy telemetry
    expects a non-empty C-selection slice. No C selection is performed in this
    development branch.
    """
    n_val = int(n_val)
    if n_val < 3:
        raise RuntimeError('[R19-P] outer validation has fewer than 3 rows.')
    if bool(getattr(config, 'R19_FULL_EVIDENCE_MODE', False)):
        if bool(getattr(config, 'R20_UTILITY_GATE', False)):
            raise RuntimeError('[R19-FULL] R20 must be disabled in full-evidence mode.')
        if bool(getattr(config, '_r22_stress_active', False)):
            raise RuntimeError('[R19-FULL] R22 stress selection is incompatible with full-evidence mode.')
        # Preserve only the calibration role genuinely still used by the old
        # mechanism: R18's validation-side detector operating threshold.
        n_cal = max(8, int(round(float(getattr(config, 'VALIDATION_CAL_FRACTION', 0.20)) * n_val)))
        n_cal = min(n_cal, n_val - 2)
        n_csel = 1  # legacy read-only telemetry only; C is fixed outside PTACExperiment
        n_safe = n_val - n_cal - n_csel
        if n_safe < 1:
            raise RuntimeError('[R19-FULL] no rows remain for safety evidence.')
        return int(n_cal), int(n_safe), int(n_csel)

    n_cal = max(1, int(round(float(getattr(config, 'VALIDATION_CAL_FRACTION', 0.40)) * n_val)))
    n_safe = max(1, int(round(float(getattr(config, 'VALIDATION_SAFETY_FRACTION', 0.30)) * n_val)))
    if n_cal + n_safe >= n_val:
        n_safe = max(1, n_val - n_cal - 1)
    return int(n_cal), int(n_safe), int(n_val - n_cal - n_safe)


# ============================================================================
# ============================================================================
def _r19_mask_episode_count(mask):
    """Count contiguous True runs in one chronological Boolean mask."""
    m = np.asarray(mask, dtype=bool).reshape(-1)
    if m.size == 0:
        return 0
    return int(np.sum(m & ~np.r_[False, m[:-1]]))


def _audit_synthetic_curriculum_visibility(
        config, model_name, target_vars, val_indices,
        synthetic_mask, authorization_mask=None, obs_mask=None):
    """Fail before training if R19/R20 cannot see the intended evidence."""
    if not bool(getattr(config, 'R19_SYNTHETIC_CURRICULUM_AUDIT', True)):
        return None
    if synthetic_mask is None:
        return None

    val_indices = pd.Index(val_indices)
    n_val = len(val_indices)
    if n_val < 3:
        raise RuntimeError("[R19-P] outer validation has fewer than 3 rows.")

    n_cal, n_safe, n_csel = _resolve_validation_roles(config, n_val)

    role_slices = {}
    if n_cal > 0:
        role_slices['calibration'] = slice(0, n_cal)
    if n_safe > 0:
        role_slices['safety'] = slice(n_cal, n_cal + n_safe)
    min_units = int(getattr(config, 'R19_SAFETY_MIN_EVIDENCE_UNITS', 2))
    thresholds = {
        'calibration': (
            int(getattr(config, 'R20_MIN_DEGRADED', 8)),
            int(getattr(config, 'R20_MIN_NOMINAL', 8))),
        'safety': (
            int(getattr(config, 'R19_SAFETY_MIN_DEGRADED', 8)),
            int(getattr(config, 'R19_SAFETY_MIN_NOMINAL', 8))),
    }
    if bool(getattr(config, '_r22_stress_active', False)):
        role_slices['c_selection'] = slice(n_cal + n_safe, n_cal + n_safe + n_csel)
        thresholds['c_selection'] = (
            int(getattr(config, 'R22_STRESS_CSEL_MIN_DEGRADED', 8)),
            int(getattr(config, 'R22_STRESS_CSEL_MIN_NOMINAL', 8)))

    syn = (synthetic_mask.reindex(index=val_indices, columns=target_vars)
           .fillna(False).astype(bool))
    auth_src = authorization_mask if authorization_mask is not None else synthetic_mask
    auth = (auth_src.reindex(index=val_indices, columns=target_vars)
            .fillna(False).astype(bool))
    if obs_mask is not None:
        obs = (obs_mask.reindex(index=val_indices, columns=target_vars)
               .fillna(False).astype(bool))
    else:
        obs = pd.DataFrame(True, index=val_indices, columns=target_vars)

    rows = []
    failures = []
    for target in target_vars:
        for role, sl in role_slices.items():
            min_deg, min_nom = thresholds[role]
            for scope, frame in (('synthetic', syn), ('authorization', auth)):
                d = (frame[target].iloc[sl].values.astype(bool)
                     & obs[target].iloc[sl].values.astype(bool))
                finite = obs[target].iloc[sl].values.astype(bool)
                nominal = finite & ~d
                n_deg = int(d.sum())
                n_nom = int(nominal.sum())
                n_ep = _r19_mask_episode_count(d)

                block_len = max(
                    2, min(_seasonality_of(config),
                           max(2, int(finite.sum()) // 4)))
                n_nom_blocks = 0
                for start in range(0, len(d), block_len):
                    stop = min(len(d), start + block_len)
                    if nominal[start:stop].any():
                        n_nom_blocks += 1

                _role_min_units = (min_units if role == 'safety' else
                                   (min_units if bool(getattr(config, 'R20_UTILITY_GATE', False)) else 1))
                ok = (n_deg >= min_deg and n_nom >= min_nom
                      and n_ep >= _role_min_units and n_nom_blocks >= _role_min_units)
                rows.append(dict(
                    model=str(model_name), target=str(target), role=role,
                    scope=scope, n_visible=int(len(d)),
                    n_degraded=n_deg, min_degraded=min_deg,
                    n_nominal=n_nom, min_nominal=min_nom,
                    n_degraded_episodes=n_ep,
                    min_degraded_episodes=_role_min_units,
                    n_nominal_blocks=n_nom_blocks,
                    min_nominal_blocks=_role_min_units,
                    passed=bool(ok)))
                if not ok:
                    failures.append(
                        f"{target}/{role}/{scope}: n_deg={n_deg} "
                        f"(need {min_deg}), episodes={n_ep} (need {_role_min_units}), "
                        f"n_nom={n_nom} (need {min_nom}), nominal_blocks="
                        f"{n_nom_blocks} (need {_role_min_units})")

    out = pd.DataFrame(rows)
    safe = _safe_filename(str(model_name))
    path = os.path.join(
        config.OUTPUT_DIR, f"r19_curriculum_visibility_{safe}.csv")
    try:
        out.to_csv(path, index=False)
    except Exception as exc:
        print(f"[R19-P] warning: could not write curriculum audit CSV: {exc}")

    print("\n" + "=" * 78)
    print(f"[R19-P] PRE-TRAINING CURRICULUM VISIBILITY -- {model_name}")
    print(out.to_string(index=False))
    print("=" * 78)

    if failures:
        msg = ("model-visible synthetic evidence is underpowered after "
               "feature/window alignment: " + " | ".join(failures))
        _register_release_failure(
            config, 'SYNTHETIC_CURRICULUM_VISIBILITY_FAILED', msg)
        raise RuntimeError("[R19-P] " + msg)

    _roles_msg = ("calibration, safety and C-selection"
                  if bool(getattr(config, '_r22_stress_active', False))
                  else "calibration and safety")
    print(f"[R19-P] PASS: {_roles_msg} evidence floors are met on "
          "the exact model-visible validation index before training.")
    return out


# ============================================================================
# --- Experiment Classes ---
# ============================================================================

class BenchmarkExperiment:
    def __init__(self, model_name, config):
        self.model_name, self.config = model_name, config

    def run(self, df, target_vars):
        raise NotImplementedError


class PTACExperiment(BenchmarkExperiment):
    """Internal experiment utility."""

    def __init__(self, model_name, config, base_lambda, unified_encoder=False,
                 use_attention=True, use_cnn=True, clip_k=None,
                 conformal_alpha=None, seed=None, gate_threshold='inherit',
                 eval_truth_df=None, obs_mask=None, fault_mask=None,
                 train_truth_df=None, corrector_target_df=None,
                 rescue_mask=None, authorization_mask=None):
        super().__init__(model_name, config)
        self.base_lambda = base_lambda
        # window, decoupled from `train_truth_df` (which supervises the ANCHOR).
        # None == inherit y_tab, i.e. byte-identical to the frozen path.
        # See the R19 block at the df_residuals override site.
        self.corrector_target_df = corrector_target_df
        # See the note at the y_tab retarget site for why this is required and
        # why it is not leakage.
        self.train_truth_df = train_truth_df
        self.unified_encoder = unified_encoder
        self.use_attention = use_attention
        self.use_cnn = use_cnn
        self.clip_k = clip_k
        self.conformal_alpha = conformal_alpha
        self.seed = seed
        self.gate_threshold = (getattr(config, 'GATE_THRESHOLD', None)
                               if gate_threshold == 'inherit' else gate_threshold)
        # the model still sees the drifted inputs in `df`.
        self.eval_truth_df = eval_truth_df
        self.obs_mask = obs_mask
        self.fault_mask = fault_mask
        # Synthetic proof-of-rescue must not be diluted by unrelated natural
        # DQA flags. `fault_mask` remains the TRAINING/detection-label mask and
        # may include natural DQA flags. `authorization_mask` is the independent
        # mask used by controlled T2 R20/R19/C-selection decisions. In ordinary
        # field runs it falls back to fault_mask, preserving the frozen path.
        self.rescue_mask = rescue_mask
        self.authorization_mask = (authorization_mask
                                   if authorization_mask is not None
                                   else fault_mask)
        self._anchor_supervision = ('clean_reference' if train_truth_df is not None
                                    else 'observed_or_degraded')
        self._corrector_supervision = ('T2_clean_minus_deployed_anchor'
                                       if corrector_target_df is not None
                                       else 'anchor_residual')

    def run(self, df, target_vars):
        start_time_total = time.time()
        # the hourly lag/window defaults and omits the health bank entirely, which
        # is how the corrector came to receive a context input with zero health
        # columns while the log claimed the bank was built.
        X_tab, y_tab, lag1_tab = create_tabular_features(
            df, target_vars, config=self.config, return_delta=True)
        df_m2p_input = df.copy()
        time_features = ['hour_sin', 'hour_cos']
        df_m2p_input['hour_sin'] = np.sin(2 * np.pi * df.index.hour / 24.0)
        df_m2p_input['hour_cos'] = np.cos(2 * np.pi * df.index.hour / 24.0)
        _, m2p_indices = create_m2p_features(df_m2p_input, target_vars, time_features, self.config)
        common_indices = X_tab.index.intersection(m2p_indices)
        X_tab, y_tab = X_tab.loc[common_indices], y_tab.loc[common_indices]
        # ------------------------------------------------------------- R27B
        # FIXED RAW-TIME CHRONOLOGICAL SPLIT.
        #
        # The old split used fractions of post-feature common_indices. Because
        # feature dropna is data-dependent, held-out TEST drift could change
        # the number of surviving test rows and therefore move train/validation
        # boundaries backward in time. This is future-dependent partitioning.
        #
        # Freeze the time cutoffs on the raw dataframe first; only then intersect
        # each block with model-visible rows. Test-row survival can change test
        # sample size, but can never change which timestamps belong to train/val.
        _raw_n = len(df)
        _raw_train_end, _raw_val_end, _raw_test_start = _raw_split_boundaries(
            self.config, _raw_n)
        _raw_train_idx = pd.Index(df.index[:_raw_train_end])
        _raw_val_idx = pd.Index(df.index[_raw_train_end:_raw_val_end])
        _raw_test_idx = pd.Index(df.index[_raw_test_start:])

        train_indices = pd.Index([ix for ix in common_indices if ix in _raw_train_idx])
        val_indices = pd.Index([ix for ix in common_indices if ix in _raw_val_idx])
        test_indices = pd.Index([ix for ix in common_indices if ix in _raw_test_idx])
        train_end = len(train_indices)
        val_end = train_end + len(val_indices)

        if train_end == 0 or len(val_indices) == 0 or len(test_indices) == 0:
            raise RuntimeError(
                "[R27B] raw-time split produced an empty model-visible block: "
                f"train={train_end}, val={len(val_indices)}, test={len(test_indices)}")

        # In ordinary runs the three blocks exhaust common_indices. R32 has an
        # intentional bridge [VAL_END:TEST_START) excluded from fitting,
        # authorization and scoring but retained in the raw series as causal
        # observed history for the later h=1 test rows.
        _allowed = _raw_train_idx.union(_raw_val_idx).union(_raw_test_idx)
        _expected = pd.Index([ix for ix in common_indices if ix in _allowed])
        _reassembled = pd.Index(
            list(train_indices) + list(val_indices) + list(test_indices))
        if not _reassembled.equals(_expected):
            raise RuntimeError(
                "[R32/R27B] raw-time split no longer partitions the intended "
                "model-visible TRAIN/VAL/TEST rows.")
        _gap_raw = int(_raw_test_start - _raw_val_end)
        print(f"    [R32/R27B] fixed raw-time split: raw cutoffs="
              f"{_raw_train_end}/{_raw_val_end}/gap={_gap_raw}/"
              f"test_start={_raw_test_start}/{_raw_n}; "
              f"visible train/val/test="
              f"{len(train_indices)}/{len(val_indices)}/{len(test_indices)}")
        X_train_tab = X_tab.loc[train_indices]
        X_val_tab = X_tab.loc[val_indices]
        X_test_tab = X_tab.loc[test_indices]
        y_train_tab = y_tab.loc[train_indices]
        y_val_tab = y_tab.loc[val_indices]
        y_test_tab = y_tab.loc[test_indices]

        # ------------------------------------------------------------- R19-P
        # PRE-TRAINING evidence audit for CONTROLLED T2 experiments only.
        # Ordinary/natural field benchmarks have corrector_target_df=None and
        # are intentionally untouched by this provisioning check.
        if (self.corrector_target_df is not None
                and (self.rescue_mask is not None or self.fault_mask is not None)):
            _synthetic_audit_mask = (
                self.rescue_mask if self.rescue_mask is not None
                else self.fault_mask)
            self._r19_curriculum_visibility = (
                _audit_synthetic_curriculum_visibility(
                    self.config, self.model_name, target_vars, val_indices,
                    synthetic_mask=_synthetic_audit_mask,
                    authorization_mask=self.authorization_mask,
                    obs_mask=self.obs_mask))

        # ------------------------------------------------------------- R18
        # CALIBRATION-REFERENCE TRAINING TARGETS (train/val windows only).
        #
        # Measurement that forced this. create_tabular_features() derives y_tab
        # from `df`, which in a drift arm is the FOULED series. The corrector's
        # regression target on a drifted training row was therefore the drifted
        # value: it was being taught to REPRODUCE the ramp. That is the same
        
        # against the corrupted column), transplanted to the training side, and
        # it is why the correction head learned a near-zero weight -- with a
        # fouled target the honest optimum for a bias-correcting head IS zero.
        #
        # train_truth_df supplies the reference values a maintenance visit would
        # provide (a grab sample, a bench-calibrated replacement probe) for the
        # HISTORICAL window only. Inputs stay fouled -- the model still sees what
        # the sensor reported -- so the mapping learned is (fouled input,
        # context) -> true value, which is exactly the deployment task.
        #
        # This is NOT test leakage: the assertion below fails if any test-window
        # index is retargeted. The test window keeps its fouled inputs AND its
        # fouled y; evaluation continues to use eval_truth_df separately. What
        # the model gains is supervision from PAST episodes, which a real
        # deployment has in its maintenance record.
        # THE OBJECT THAT MUST BE RETARGETED IS y_tab, NOT THE SPLIT FRAMES.
        # First attempt patched y_train_tab / y_val_tab only. That was wrong and
        # the run said so: the corrector fired (per-row delta spread appeared,
        # scaling with intensity) but corrected the WRONG WAY, harm reaching
        # -4.1% at I=0.20. The reason is that the corrector's regression target
        # is df_residuals = y_tab - baseline, computed from y_tab further down;
        # the split frames feed the baseline fit and the loss weights only. So
        # the corrector was still chasing the fouled residual while the baseline
        # had been retargeted to the clean one -- an inconsistency worse than
        # either convention alone, which is exactly what a large negative rescue
        # that grows with intensity looks like.
        self._r18_retargeted = 0
        if self.train_truth_df is not None:
            _tt = self.train_truth_df
            _cols = [c for c in y_tab.columns if c in _tt.columns]
            if _cols:
                _fit_idx = train_indices.union(val_indices)
                assert len(set(_fit_idx) & set(test_indices)) == 0, (
                    "[R18] calibration-reference retargeting would touch the "
                    "test window. That is leakage, not supervision.")
                _ref = _tt.reindex(index=_fit_idx, columns=_cols)
                _n_ch = int((~np.isclose(
                    _ref.values,
                    y_tab.loc[_fit_idx, _cols].values,
                    rtol=0.0, atol=1e-12, equal_nan=True)).sum())
                y_tab = y_tab.copy()
                y_tab.loc[_fit_idx, _cols] = _ref.values
                # Re-slice so every consumer (baseline fit, residual target,
                # loss weights) sees ONE consistent convention.
                y_train_tab = y_tab.loc[train_indices]
                y_val_tab = y_tab.loc[val_indices]
                y_test_tab = y_tab.loc[test_indices]
                self._r18_retargeted = _n_ch
                print(f"    [R18] train/val targets set to calibration "
                      f"reference on {_n_ch} cell(s) "
                      f"({len(_fit_idx)} rows x {len(_cols)} channels); "
                      f"test window untouched")

        # '_roll_mean_24' / '_roll_std_24'. On any cadence whose derived rolling
        # windows do not happen to include 24 that matched NOTHING, so the
        # corrector silently received a zero-width context input. Select by the
        # cadence's own daily window instead.
        # detection heads are trained on.
        _ctx_w = int(getattr(self.config, '_steps_per_day', 24))
        if _ctx_w <= 1:
            _ctx_w = max(_roll_windows_of(self.config))
        context_cols = [c for c in X_tab.columns
                        if f'_roll_mean_{_ctx_w}' in c or f'_roll_std_{_ctx_w}' in c]
        if not context_cols:
            _w = max(_roll_windows_of(self.config))
            context_cols = [c for c in X_tab.columns
                            if f'_roll_mean_{_w}' in c or f'_roll_std_{_w}' in c]
        _health_cols = [c for c in X_tab.columns
                        if str(c).endswith(_HEALTH_NAME_SUFFIXES)]
        context_cols = context_cols + _health_cols

        # ------------------------------------------------------------- R17
        # CAUSAL MULTI-SCALE DRIFT BANK appended to the context block.  The
        # pre-patch context carried only 24h rolling mean/std, whose
        # receptive field is one day -- structurally unable to see a bias
        # that develops over a week.  build_drift_bank adds EWMA departure,
        # CUSUM accumulation, robust median departure, variance-collapse
        # ratio (a frozen-channel signature) and diel attenuation at 1/3/7/14
        # days, plus a cross-channel consensus residual. Leak-freedom is
        # VERIFIED, not asserted: the first
        # version of this bank failed verify_leak_free() because its
        # cross-channel z-scores used whole-series statistics.
        self._r17_drift_cols = []
        # PATCH-A1: the bank arithmetic moved into attach_drift_bank_block() so
        # the external comparators call the SAME code path. Numerically
        # identical to the inline version it replaces -- same builder, same
        # train-slice imputation, same constant-on-train filter, same order.
        _bank = attach_drift_bank_block(
            df, target_vars, self.config, common_indices, train_end,
            tag=f"ptac:{getattr(self.config, '_dataset_name', '?')}:{self.model_name}")
        if _bank.shape[1]:
            # X_train_tab / X_val_tab / X_test_tab were sliced out of X_tab
            # ABOVE this block, so writing only into X_tab leaves the split
            # frames without the new columns and the context selection then
            # raises KeyError. Write into all four.
            for _c in _bank.columns:
                X_tab[_c] = _bank[_c].values
            X_train_tab = X_train_tab.copy()
            X_val_tab = X_val_tab.copy()
            X_test_tab = X_test_tab.copy()
            for _c in _bank.columns:
                X_train_tab[_c] = _bank[_c].reindex(train_indices).values
                X_val_tab[_c] = _bank[_c].reindex(val_indices).values
                X_test_tab[_c] = _bank[_c].reindex(test_indices).values
            self._r17_drift_cols = list(_bank.columns)
            context_cols = context_cols + self._r17_drift_cols
            print(f"    [R17] drift bank: +{_bank.shape[1]} causal context "
                  f"columns over {getattr(self.config, 'R17_DRIFT_WINDOWS_DAYS', ())} day windows")
        if bool(getattr(self.config, 'R17_VERIFY_LEAK_FREE', False)) and target_vars:
            verify_leak_free(df, target_vars[0],
                             float(getattr(self.config, '_steps_per_day', 24) or 24),
                             self.config,
                             t_probe=min(len(df) // 2, len(df) - 2))

        if not context_cols:
            raise AssertionError(
                "[R16-A] the corrector's context input resolved to zero columns. "
                "That is the defect this check exists to catch: r15 selected it "
                "with hard-coded '_roll_mean_24' substrings, which match nothing "
                "on a non-hourly cadence.")
        print(f"    [R16-A/C] context input: {len(context_cols)} columns "
              f"({len(context_cols) - len(_health_cols)} rolling @ w={_ctx_w}, "
              f"{len(_health_cols)} health).")
        X_train_context = X_train_tab[context_cols].values
        X_val_context = X_val_tab[context_cols].values
        X_test_context = X_test_tab[context_cols].values

        # ------------------------------------------------------------------ DEV
        # CONTEXT SCALE. The sequence inputs are MinMax-scaled to [0,1] via
        # df_scaled above; this context block is NOT scaled anywhere, so raw
        # rolling means (EC in uS/cm, order 1e2-1e4) enter the same fused
        # trunk. DEV_SCALE_CONTEXT standardises it with a scaler fitted on
        # TRAIN ROWS ONLY, which is the causal test of whether the input scale
        # is what saturates the detection sigmoid. Default False => the
        # benchmark path is unchanged.
        if bool(getattr(self.config, 'DEV_DELTA_TELEMETRY', False)):
            _cs = np.abs(X_train_context)
            print(f"    [DEV] context input scale (raw): "
                  f"mean|x|={_cs.mean():.4g}  max|x|={_cs.max():.4g}  "
                  f"per-col max mean|x|={np.abs(X_train_context).mean(0).max():.4g}")
        # ------------------------------------------------------------- R17
        # CONTEXT STANDARDISATION IS NOW ON BY DEFAULT, not a DEV flag.
        #
        # Measured on the real 35-column context matrix (see CTX_INSPECTION.md),
        # all three candidates fitted on TRAIN ROWS ONLY:
        #
        #   scaler    train max|z|  val max|z|  test max|z|  degenerate cols
        #   Standard      7.42         3.73        2.96      scale_=1 -> exact 0.0
        #   MinMax        1.00         1.13        1.20      5.4% of test escapes [0,1]
        #   Robust       45.3          3.70        3.30      3 zero-IQR cols left near-raw
        #
        # Standard is the only one of the three that bounds every split AND
        # handles the degenerate columns without a special case.  Robust is
        # rejected because it divides three zero-IQR columns by 1.0 and leaves
        # them essentially unscaled -- precisely the failure being fixed.
        # MinMax only guarantees its range on the rows it was fit on.
        #
        
        # (EC rolling means in uS/cm) against pH ~ 7 entering the SAME fused
        # trunk.  That is the measured cause of the detection sigmoid reaching
        # a pre-activation logit of -42, i.e. a gate welded shut.
        #
        # All columns are standardised uniformly.  Carving out exceptions for
        # already-bounded features would introduce a second free choice with
        # no measurement behind it.
        _scale_ctx = (bool(getattr(self.config, 'R17_ENABLE', False))
                      or bool(getattr(self.config, 'DEV_SCALE_CONTEXT', False)))
        if _scale_ctx:
            _ctx_scaler = StandardScaler().fit(X_train_context)
            X_train_context = _ctx_scaler.transform(X_train_context)
            X_val_context = _ctx_scaler.transform(X_val_context)
            X_test_context = _ctx_scaler.transform(X_test_context)
            self._r17_ctx_scaler = _ctx_scaler
            print(f"    [R17] context STANDARDISED (fit on train only): "
                  f"mean|x|={np.abs(X_train_context).mean():.4g}  "
                  f"max|x|={np.abs(X_train_context).max():.4g}  "
                  f"({int((_ctx_scaler.scale_ == 1).sum())} degenerate cols "
                  f"-> exact 0.0)")
        # exactly 0, one unique value per channel, identical across drift
        # intensities). Either the context matrix reaching the trunk is itself
        # row-constant, or the variation is there and the trunk cannot use it.
        # Stash the matrices so that can be decided from data rather than read
        # off the architecture.
        self._r17_ctx_train = np.array(X_train_context, dtype=float, copy=True)
        self._r17_ctx_test = np.array(X_test_context, dtype=float, copy=True)
        self._r17_ctx_cols = list(context_cols)

        # ---------------------------------------------------------- PATCH-F15
        # Persist the context SPEC (ordered column list + the train-fitted
        # standardiser) next to the checkpoint. Without it, any consumer that
        # reloads the weights later -- generate_manuscript_assets being the one
        # that actually did -- has no way to rebuild the exact 111-column input
        # the trunk was trained on, and silently builds a narrower one. Writing
        # it is inert: it records what this run already computed and changes no
        # tensor, no fit and no reported metric.
        try:
            _spec = {
                'context_cols': [str(c) for c in context_cols],
                'context_dim': int(len(context_cols)),
                'rolling_window': int(_ctx_w),
                'n_health': int(len(_health_cols)),
                'n_drift_bank': int(len(self._r17_drift_cols)),
                'scaled': bool(_scale_ctx),
                'scaler_mean': ([float(x) for x in _ctx_scaler.mean_]
                                if _scale_ctx else None),
                'scaler_scale': ([float(x) for x in _ctx_scaler.scale_]
                                 if _scale_ctx else None),
            }
            # ------------------------------------------------------ PATCH-A4
            # PER-DATASET SPEC FILE (audit F5). This wrote to a single global
            # 'context_spec.json' in OUTPUT_DIR, which is shared by all four
            # testbeds AND by every arm within a testbed, so each write
            # clobbered the last. In the r3 run the surviving file held 95
            # columns (with turbidity rolling features, i.e. the stable
            # testbed's layout) while the log recorded writes of 111 -- so the
            # only consumer, generate_manuscript_assets, could load a spec
            # belonging to a different testbed and rebuild a context that
            # matched no checkpoint. Key the filename by dataset and by the
            # arm's own name, and keep writing the generic name as an alias for
            # the CURRENT dataset so existing consumers keep working.
            _ds = str(getattr(self.config, '_dataset_name', None) or 'unknown')
            _spec['dataset_name'] = _ds
            _spec['model_name'] = str(self.model_name)
            _spec_paths = [f'context_spec_{_ds}.json',
                           f'context_spec_{_ds}__{_safe_filename(self.model_name)}.json']
            for _p in _spec_paths:
                with open(os.path.join(self.config.OUTPUT_DIR, _p), 'w') as _fh:
                    json.dump(_spec, _fh, indent=1)
            print(f"    [F15] context spec persisted "
                  f"({_spec['context_dim']} cols = "
                  f"{_spec['context_dim'] - _spec['n_health'] - _spec['n_drift_bank']} "
                  f"rolling + {_spec['n_health']} health + "
                  f"{_spec['n_drift_bank']} drift bank; "
                  f"scaled={_spec['scaled']}) -> {_spec_paths[0]}")
        except Exception as _se:
            print(f"    [F15] WARNING: could not persist context spec "
                  f"({type(_se).__name__}: {_se}). Attention-map export will "
                  f"refuse to plot rather than guess the context layout.")

        stds = y_train_tab.std()
        normalized_stds = stds / stds.mean() + 1e-6
        lambdas = self.base_lambda / normalized_stds

        # FIX #3: Removed stray `df_baseline_preds[...] = xgb_baseline.predict(X_tab)` line
        # that appeared before df_baseline_preds was defined.
        df_baseline_preds = pd.DataFrame(index=y_tab.index)
        lag1_aligned = lag1_tab.loc[common_indices]
        for i, var in enumerate(target_vars):
            xgb_baseline = xgb.XGBRegressor(
                objective='reg:squarederror', n_estimators=1000,
                learning_rate=0.01, random_state=42, n_jobs=-1,
                early_stopping_rounds=50
            )
            # Train on increments (y_t - y_{t-1})
            y_diff_train = y_train_tab.iloc[:, i] - lag1_aligned.loc[train_indices, var]
            y_diff_val = y_val_tab.iloc[:, i] - lag1_aligned.loc[val_indices, var]
            
            xgb_baseline.fit(
                X_train_tab, y_diff_train,
                eval_set=[(X_val_tab, y_diff_val)],
                verbose=False
            )
            # Reconstruct level: y_hat = y_{t-1} + predicted_diff
            df_baseline_preds[f'{var}_pred'] = xgb_baseline.predict(X_tab) + lag1_aligned[var].values
            if "PTAC" in self.model_name and i == 0:
                xgb_baseline.save_model(os.path.join(self.config.OUTPUT_DIR, "baseline_xgb.json"))

        df_residuals = y_tab - df_baseline_preds.rename(columns=lambda c: c.replace('_pred', ''))

        # ---------------------------------------------------------- STUDY A
        # CAUSAL ANCHOR-RELIABILITY CONTEXT, CORRECTOR-ONLY.  The feature uses
        # only realised anchor residuals through t-1, is scaled on training
        # rows, and never changes the deployed differenced XGBoost anchor.
        self._study_a_jump_cols = []
        if (bool(getattr(self.config, 'ENABLE_CAUSAL_ANCHOR_CONTEXT', True))
                or bool(getattr(self.config, 'STUDY_A_ENABLE_JUMP_CONTEXT', False))):
            _j = build_causal_anchor_jump_context(df_residuals.copy(), target_vars,
                                                  self.config).reindex(common_indices)
            if _j.shape[1]:
                _jfill = _j.loc[train_indices].median(numeric_only=True)
                _j = _j.fillna(_jfill).fillna(0.0)
                _jsc = StandardScaler().fit(_j.loc[train_indices].values)
                _jtr = _jsc.transform(_j.loc[train_indices].values)
                _jva = _jsc.transform(_j.loc[val_indices].values)
                _jte = _jsc.transform(_j.loc[test_indices].values)
                X_train_context = np.concatenate([X_train_context, _jtr], axis=1)
                X_val_context = np.concatenate([X_val_context, _jva], axis=1)
                X_test_context = np.concatenate([X_test_context, _jte], axis=1)
                self._study_a_jump_cols = list(_j.columns)
                self._r17_ctx_cols = list(getattr(self, '_r17_ctx_cols', [])) + self._study_a_jump_cols
                self._r17_ctx_train = np.array(X_train_context, dtype=float, copy=True)
                self._r17_ctx_test = np.array(X_test_context, dtype=float, copy=True)
                print(f"    [ANCHOR-CONTEXT] +{len(self._study_a_jump_cols)} "
                      f"causal anchor-reliability columns (corrector only; "
                      f"anchor frozen).")
                try:
                    with open(os.path.join(self.config.OUTPUT_DIR,
                                           'anchor_reliability_context_spec.json'), 'w') as _fh:
                        json.dump(dict(
                            columns=self._study_a_jump_cols,
                            mean=[float(x) for x in _jsc.mean_],
                            scale=[float(x) for x in _jsc.scale_],
                            causal_definition='r[t-1] vs rolling median/MAD through t-2',
                            anchor_unchanged=True), _fh, indent=1)
                except Exception as _je:
                    print(f"    [ANCHOR-CONTEXT] spec write failed: {_je}")

        # ------------------------------------------------------------ C1/OOF
        # Replace the CORRECTOR'S TRAINING TARGET on train rows with a strictly
        
        # IN-SAMPLE on train rows (the anchor just predicted its own training
        # data) but out-of-sample on val/test, so its measured sigma is 0.2-0.5x
        # the deployment sigma on 7/9 channels.  The corrector is fit on a
        # target several times narrower than the one it faces, and a Huber
        # minimiser correctly answers ~0.
        #
        # WHAT IS *NOT* TOUCHED: df_baseline_preds.  That is the forecast behind
        # every reported baseline metric, the validation selection and the test
        # evaluation.  Only df_residuals (the corrector's target) changes, and
        # only on train rows -- val/test residuals are already out-of-sample and
        # are left exactly as computed above.
        self._oof_covered_mask = None
        self._oof_diag_rows = []
        if getattr(self.config, 'USE_OOF_CORRECTOR_RESIDUALS', False):
            _bp_checksum = float(np.asarray(df_baseline_preds.values, dtype=float).sum())
            print(f"    [C1/OOF] rebuilding CORRECTOR residual target out-of-fold "
                  f"({getattr(self.config, 'OOF_N_BLOCKS', 5)} expanding folds inside TRAIN); "
                  f"final anchor untouched.")
            _cov_all = None
            for i, var in enumerate(target_vars):
                _kw = dict(objective='reg:squarederror', n_estimators=1000,
                           learning_rate=0.01, random_state=42, n_jobs=-1)
                _ydiff_tr = (y_train_tab.iloc[:, i]
                             - lag1_aligned.loc[train_indices, var])
                _r_oof, _cov = oof_anchor_residuals(
                    X_train_tab, _ydiff_tr.values,
                    lag1_aligned.loc[train_indices, var].values,
                    n_blocks=int(getattr(self.config, 'OOF_N_BLOCKS', 5)),
                    inner_eval_frac=float(getattr(self.config, 'OOF_INNER_EVAL_FRAC', 0.10)),
                    xgb_kwargs=_kw, verbose=(i == 0))
                _ins = df_residuals.loc[train_indices, var].values.astype(float)
                _sd_ins = float(np.nanstd(_ins[_cov])) if _cov.any() else float('nan')
                _sd_oof = float(np.nanstd(_r_oof[_cov])) if _cov.any() else float('nan')
                _sd_val = float(np.nanstd(df_residuals.loc[val_indices, var].values.astype(float)))
                _sd_te = float(np.nanstd(df_residuals.loc[test_indices, var].values.astype(float)))
                _corr = (float(np.corrcoef(_ins[_cov], _r_oof[_cov])[0, 1])
                         if _cov.sum() > 2 else float('nan'))
                self._oof_diag_rows.append(dict(
                    dataset=getattr(self.config, '_ACTIVE_DATASET', ''),
                    model=self.model_name, target=var,
                    n_train=int(len(train_indices)), n_oof=int(_cov.sum()),
                    sigma_in_sample=_sd_ins, sigma_oof=_sd_oof,
                    sigma_val=_sd_val, sigma_test=_sd_te,
                    oof_over_in_sample=(_sd_oof / _sd_ins if _sd_ins else float('nan')),
                    in_sample_over_test=(_sd_ins / _sd_te if _sd_te else float('nan')),
                    oof_over_test=(_sd_oof / _sd_te if _sd_te else float('nan')),
                    corr_in_sample_vs_oof=_corr,
                    mean_abs_in_sample=float(np.nanmean(np.abs(_ins[_cov]))) if _cov.any() else float('nan'),
                    mean_abs_oof=float(np.nanmean(np.abs(_r_oof[_cov]))) if _cov.any() else float('nan')))
                print(f"      [C1/OOF] {var}: sigma in-sample={_sd_ins:.4f} -> "
                      f"OOF={_sd_oof:.4f} (x{_sd_oof / _sd_ins if _sd_ins else float('nan'):.2f}); "
                      f"val={_sd_val:.4f} test={_sd_te:.4f}; corr(in,oof)={_corr:.3f}")
                # write OOF residual onto train rows only; val/test untouched
                _col = df_residuals[var].values.astype(float).copy()
                _pos = df_residuals.index.get_indexer(train_indices)
                _col[_pos] = _r_oof
                df_residuals[var] = _col
                _cov_all = _cov if _cov_all is None else (_cov_all & _cov)
            self._oof_covered_mask = _cov_all
            # The final anchor must be bit-identical after this block.
            assert float(np.asarray(df_baseline_preds.values, dtype=float).sum()) == _bp_checksum, \
                "C1/OOF changed df_baseline_preds -- the reported anchor must not move."
            print(f"    [C1/OOF] final-anchor checksum unchanged; "
                  f"{int(_cov_all.sum())}/{len(train_indices)} train rows usable for the corrector.")
            try:
                _dp = os.path.join(self.config.OUTPUT_DIR,
                                   'residual_target_oof_diagnostics.csv')
                _dd = pd.DataFrame(self._oof_diag_rows)
                _dd.to_csv(_dp, mode=('a' if os.path.exists(_dp) else 'w'),
                           header=(not os.path.exists(_dp)), index=False)
            except Exception as _de:
                print(f"    [C1/OOF] WARNING: diagnostics not written ({_de}).")

        # ------------------------------------------------------------- R19
        # DECOUPLE CORRECTOR SUPERVISION FROM ANCHOR SUPERVISION.
        #
        # Why this exists. `train_truth_df` retargets y_tab to clean truth on
        # train union val BEFORE the anchor is fit, so it moves BOTH the anchor's
        
        # (anchor_absorption.csv): the retargeted anchor removes ~97% of the
        # injected displacement before the corrector sees anything, leaving a
        # target 7-31x smaller. The two effects are therefore not separable on
        # that path, and "rescue" measured there is largely anchor behaviour.
        #
        # This block changes ONLY df_residuals -- the corrector's training
        # target -- and only on the FIT window (train union val). It is the same
        # surgical point the C1/OOF block above uses, and for the same reason:
        # df_residuals has exactly one consumer (the residual scaler and hence
        # y_m2p_target). df_baseline_preds is NOT touched, so every reported
        # baseline metric, the validation selection and the test evaluation are
        # unchanged, and the assertion below enforces that.
        #
        # T2 (pre-registered):  c_t* := y_t^clean - yhat_t^degraded
        # Passing corrector_target_df=<clean frame> supervises the corrector on
        # T2. Passing the degraded frame reproduces the rejected one-step
        # residual r_t = y_t^d - yhat_t^d. None == inherit y_tab (frozen path).
        #
        # Test rows are deliberately left as computed: they are never used for
        # corrector training, and rewriting them would touch the test protocol.
        self._r19_corrector_target = 0
        self._r19_target_sd = {}
        if self.corrector_target_df is not None:
            _ct = self.corrector_target_df
            _bp = df_baseline_preds.rename(
                columns=lambda c: c.replace('_pred', ''))
            _cols19 = [c for c in df_residuals.columns if c in _ct.columns]
            _fit19 = train_indices.union(val_indices)
            assert len(set(_fit19) & set(test_indices)) == 0, (
                "[R19] corrector-target override would touch the test window.")
            _bp_ck19 = float(np.asarray(df_baseline_preds.values,
                                        dtype=float).sum())
            for _v in _cols19:
                _new = (_ct.reindex(index=_fit19)[_v].astype(float)
                        - _bp.reindex(index=_fit19)[_v].astype(float))
                _old = df_residuals.loc[_fit19, _v].astype(float)
                _col19 = df_residuals[_v].values.astype(float).copy()
                _pos19 = df_residuals.index.get_indexer(_fit19)
                _col19[_pos19] = _new.values
                df_residuals[_v] = _col19
                self._r19_target_sd[_v] = dict(
                    sd_before=float(np.nanstd(_old.values)),
                    sd_after=float(np.nanstd(_new.values)),
                    n_changed=int((~np.isclose(_old.values, _new.values,
                                               rtol=0.0, atol=1e-12,
                                               equal_nan=True)).sum()))
                print(f"    [R19] corrector target '{_v}': "
                      f"sd {self._r19_target_sd[_v]['sd_before']:.4f} -> "
                      f"{self._r19_target_sd[_v]['sd_after']:.4f} on "
                      f"{len(_fit19)} fit rows "
                      f"({self._r19_target_sd[_v]['n_changed']} changed)")
            self._r19_corrector_target = len(_cols19)
            assert float(np.asarray(df_baseline_preds.values,
                                    dtype=float).sum()) == _bp_ck19, \
                "[R19] corrector-target override moved df_baseline_preds."
        # ------------------------------------------------------------- R17
        # THE CORRECTION SCALER MUST NOT CENTRE.
        #
        
        # worth stating precisely because it is invisible in every aggregate.
        # The gate abstains by driving delta to EXACTLY 0.0 in scaled space.
        # With a centring StandardScaler, inverse_transform(0) = mean_, so an
        # abstention was re-inflated into a CONSTANT non-zero correction equal
        # to the mean training residual of that channel.
        #
        # Measured on the stable station (gradual_bias, I=0.20):
        #   scaler mean_          = [ 0.005362, 0.000802, -0.189848, 0.000634]
        #   applied "correction"  = [ 0.005362, 0.0     , -0.189848, 0.0     ]
        # -- bit-identical to mean_ on the two channels the gate let through,
        # identical across BOTH drift types, and identical at I=0.05 and
        # I=0.20 (max abs difference between intensities: exactly 0.0).
        # Per-row standard deviation of the applied correction was exactly 0
        # with one unique value per channel: the corrector was not responding
        # to the data at all, it was adding a fixed bias.
        #
        # That artefact is what produced the apparent "rescue" of +3.0% decaying
        # to +1.1%: a constant offset removes a constant fraction of error, so R
        # falls as 1/I purely because the denominator grows. It would have been
        # reported as a corrector that works best on small drift -- the exact
        # opposite of the truth, which is that it never fired.
        #
        # with_mean=False keeps the per-channel scale normalisation the loss
        # needs to balance channels, while making zero mean zero. Abstention is
        # then exact end-to-end and the bound bounds a centred quantity.
        _r17_on = bool(getattr(self.config, 'R17_ENABLE', False))
        scaler_residuals = StandardScaler(with_mean=not _r17_on)
        # C1/OOF: fit the scaler on the SAME residuals the corrector is trained
        # on.  If it were still fit on the in-sample residuals the corrector
        
        # would be silently undone by normalisation.  Warm-up rows are NaN under
        # C1 and must be excluded or every scale becomes NaN.
        _fit_res = df_residuals.loc[train_indices]
        if getattr(self.config, 'USE_OOF_CORRECTOR_RESIDUALS', False):
            _fit_res = _fit_res.dropna()
            print(f"    [C1/OOF] residual scaler refit on {len(_fit_res)} "
                  f"out-of-fold train rows (was {len(train_indices)} in-sample). "
                  f"scale={np.round(np.asarray(_fit_res.std().values, dtype=float), 4).tolist()}")
        scaler_residuals.fit(_fit_res)
        if _r17_on:
            print("    [R17] correction scaler: with_mean=False "
                  "(scaled delta == 0 <=> zero applied correction; a centring "
                  "scaler turns gate abstention into a constant bias)")
        df_residuals_scaled = pd.DataFrame(
            scaler_residuals.transform(df_residuals),
            columns=df_residuals.columns,
            index=df_residuals.index
        )
        scaler = MinMaxScaler().fit(df.loc[train_indices][target_vars])
        df_scaled = pd.DataFrame(scaler.transform(df[target_vars]), columns=target_vars, index=df.index)
        df_scaled[time_features] = df_m2p_input[time_features]
        X_m2p_full, m2p_indices_full = create_m2p_features(df_scaled, target_vars, time_features, self.config)
        X_m2p_short_aligned = (
            pd.DataFrame([r.flatten() for r in X_m2p_full['short_term_input']], index=m2p_indices_full)
            .loc[common_indices].values
            .reshape(len(common_indices), self.config.SHORT_WINDOW_SIZE, -1)
        )
        X_m2p_long_aligned = (
            pd.DataFrame([r.flatten() for r in X_m2p_full['long_term_input']], index=m2p_indices_full)
            .loc[common_indices].values
            .reshape(len(common_indices), self.config.LONG_WINDOW_SIZE, -1)
        )
        X_short_flat = X_m2p_short_aligned.reshape(X_m2p_short_aligned.shape[0], -1)
        X_long_flat = X_m2p_long_aligned.reshape(X_m2p_long_aligned.shape[0], -1)
        X_unified = np.concatenate([X_short_flat, X_long_flat], axis=1)
        y_m2p_target = df_residuals_scaled.loc[common_indices].values

        # [VAL_END:TEST_START). Therefore X_unified[val_end:] would incorrectly
        # concatenate the 62 bridge rows with the 108 confirmation rows.
        # Select every split by its explicit timestamp positions instead.
        _train_pos32 = common_indices.get_indexer(train_indices)
        _val_pos32 = common_indices.get_indexer(val_indices)
        _test_pos32 = common_indices.get_indexer(test_indices)
        if ((_train_pos32 < 0).any() or (_val_pos32 < 0).any()
                or (_test_pos32 < 0).any()):
            raise RuntimeError(
                "[R32-P2] split index was not found in common_indices.")

        X_train_m2p = X_unified[_train_pos32]
        X_val_m2p = X_unified[_val_pos32]
        X_test_m2p = X_unified[_test_pos32]
        y_train_m2p = y_m2p_target[_train_pos32]
        y_val_m2p = y_m2p_target[_val_pos32]
        y_test_m2p = y_m2p_target[_test_pos32]

        if not (len(X_test_m2p) == len(X_test_context) == len(test_indices)):
            raise RuntimeError(
                "[R32-P2] confirmation cardinality mismatch before Keras: "
                f"sequence={len(X_test_m2p)}, context={len(X_test_context)}, "
                f"index={len(test_indices)}")
        if bool(getattr(self.config, 'R32_EXPLICIT_RAW_SPLIT', False)):
            print(f"    [R32-P2] neural split cardinality train/val/test="
                  f"{len(X_train_m2p)}/{len(X_val_m2p)}/{len(X_test_m2p)}; "
                  f"bridge excluded from neural TEST input")

        # ------------------------------------------------------------- R17
        # PER-TARGET tau FOR THE BOUNDED HEAD, from TRAIN residuals only.
        # The correction head is c = tau*tanh(raw/tau), so |c| <= tau holds by
        # construction under any input distribution.  tau is measured in the
        # SCALED residual space the head actually operates in, which is why it
        # is computed from y_train_m2p rather than from the raw channel.
        _taus = {}
        if bool(getattr(self.config, 'R17_ENABLE', False)):
            _kap = float(getattr(self.config, 'R17_TAU_KAPPA', 3.0))
            _flr = float(getattr(self.config, 'R17_TAU_FLOOR', 1e-6))
            for _i, _v in enumerate(target_vars):
                _taus[_v] = channel_tau(y_train_m2p[:, _i], kappa=_kap, floor=_flr,
                                        kappa_level=float(getattr(
                                            self.config, 'R17_TAU_KAPPA_LEVEL', 0.0)))
            print("    [R17] bounded head tau (scaled units): "
                  + ", ".join(f"{v}={_taus[v]:.4g}" for v in target_vars))

        tf.keras.backend.clear_session()
        model = build_m2p_attention_network(
            config=self.config,
            target_vars=target_vars,
            num_dynamic_vars=len(target_vars),
            short_window_features=X_m2p_short_aligned.shape[2],
            long_window_features=X_m2p_long_aligned.shape[2],
            context_dim=X_train_context.shape[1],
            use_attention=self.use_attention,
            use_cnn=self.use_cnn,
            unified_encoder=self.unified_encoder,
            tau_per_target=_taus
        )
        lr_scheduler = keras.callbacks.ReduceLROnPlateau(
            monitor='val_loss', factor=0.5, patience=15, min_lr=1e-6, verbose=1
        )
        early_stop = keras.callbacks.EarlyStopping(
            monitor='val_loss', patience=self.config.PATIENCE, restore_best_weights=True
        )
        optimizer = tf.keras.optimizers.Adam(learning_rate=self.config.LEARNING_RATE, clipnorm=1.0)
        # ------------------------------------------------------------- R16-E/F
        # One AdaptiveLoss per correction head (now carrying the parity hinge and
        # the previously-ignored HUBER_DELTA), plus one FaultDetectionLoss per
        # detection head when gating is on. The lists must be the same length as
        # model.outputs or Keras silently recycles losses across heads, so the
        # length is asserted rather than assumed.
        _n_t = len(target_vars)
        _gated = bool(getattr(model, '_m2p_gated', False))
        _hd = float(getattr(self.config, 'HUBER_DELTA', 1.0))
        _lp = float(getattr(self.config, 'LAMBDA_PARITY', 0.0))
        _r17_on = bool(getattr(model, '_m2p_r17', False))

        # --------------------------------------------------------------- R17
        # PER-CHANNEL PREVALENCE.  Measured prevalence spans 0.0 to 0.954
        # across the 16 channel-slots; on ch90234 the per-row majority is
        # FAULTED, so the weight inverts.  A single global constant is wrong
        # by ~20x at the extremes, which is why this is computed per target
        # and on the TRAIN slice only.
        _prev = []
        for _v in target_vars:
            _p = 0.1
            if self.fault_mask is not None and _v in self.fault_mask.columns:
                _fmv = self.fault_mask.reindex(common_indices).fillna(False)
                _p = float(_fmv[_v].values.astype(bool)[:train_end].mean())
            _prev.append(_p)

        _cap = float(getattr(self.config, 'R17_EPISODE_W_CAP', 20.0))
        _ep_on = (_r17_on
                  and bool(getattr(self.config, 'R17_EPISODE_WEIGHTS', False)))
        _ep_w = [float(np.clip((1.0 - p) / max(p, 1e-3), 1.0, _cap))
                 if (_ep_on and p > 0.0) else 1.0 for p in _prev]

        _aux_mode = str(getattr(self.config, 'R17_AUX_MODE', 'off')).lower()
        _lam_aux = (float(getattr(self.config, 'R17_LAMBDA_AUX', 0.0))
                    if (_r17_on and _aux_mode == 'product') else 0.0)

        if _r17_on:
            _native_obj = bool(getattr(self.config, 'NATIVE_ZERO_NOMINAL_OBJECTIVE', False))
            _ndw = float(getattr(self.config, 'NATIVE_DRIFT_LOSS_WEIGHT', 1.0))
            _nnw = float(getattr(self.config, 'NATIVE_NOMINAL_LOSS_WEIGHT', 1.0))
            _objmode = str(getattr(self.config, 'NATIVE_OBJECTIVE_MODE', 'native_balanced')).lower()
            _lharm = float(getattr(self.config, 'NATIVE_HARM_WEIGHT', 0.0))
            _losses = [DriftRescueLoss(lambdas[var], huber_delta=_hd,
                                       lambda_parity=_lp, lambda_aux=_lam_aux,
                                       episode_w=w,
                                       native_zero_nominal=_native_obj,
                                       native_drift_weight=_ndw,
                                       native_nominal_weight=_nnw,
                                       objective_mode=_objmode,
                                       lambda_harm=_lharm)
                       for var, w in zip(target_vars, _ep_w)]
            if _native_obj:
                print("    [TOURNAMENT/NATIVE] objective=" + _objmode +
                      "; nominal -> ZERO; degraded -> clean/reference residual; " +
                      f"weights drift={_ndw:g}, nominal={_nnw:g}, harm={_lharm:g}; " +
                      "detector supervision is auxiliary unless the model arm learns a joint router.")
            else:
                print(f"    [R17] corrector objective: aux_mode={_aux_mode}, "
                      f"lambda_aux={_lam_aux:g}, episode weights "
                      + ", ".join(f"{v}={w:.1f}" for v, w in zip(target_vars, _ep_w)))
        else:
            _losses = [AdaptiveLoss(lambdas[var], huber_delta=_hd,
                                    lambda_parity=_lp)
                       for var in target_vars]
        _lw = [1.0] * _n_t
        if _gated:
            _bce_w = float(getattr(self.config, 'FAULT_BCE_WEIGHT', 0.3))
            # Inverse-prevalence weight, capped so a channel with a handful
            # of faulted rows cannot dominate the objective.
            _pos_w = [float(np.clip((1.0 - p) / max(p, 1e-3), 1.0, 20.0))
                      for p in _prev]
            _losses += [FaultDetectionLoss(pos_weight=w) for w in _pos_w]
            _lw += [_bce_w] * _n_t
            print(f"    [R16-E] detection heads active; BCE weight {_bce_w:g}, "
                  f"per-target pos_weight "
                  + ", ".join(f"{v}={w:.1f}" for v, w in zip(target_vars, _pos_w)))
        if bool(getattr(model, '_m2p_bare', False)):
            # Ablation arm: supervise the UNGATED correction on drift rows.
            _losses += [BareCorrectionLoss(
                lambda_aux=float(getattr(self.config, 'R17_LAMBDA_AUX', 1.0)),
                huber_delta=_hd) for _ in target_vars]
            _lw += [1.0] * _n_t
            print("    [R17] bare-c auxiliary heads active (ablation arm)")
        assert len(_losses) == len(model.outputs), (
            f"[R16-E] {len(_losses)} losses for {len(model.outputs)} model "
            f"outputs. Keras would recycle them across heads.")
        model.compile(optimizer=optimizer, loss=_losses, loss_weights=_lw)
        # ==================================================================
        #
        
        # were degraded. fault_mask was carried through PTACExperiment purely
        # to STRATIFY the test metrics -- grep the class: before this block its
        # only uses were reindex(test_indices) and the compute_metrics call.
        # The residual head was therefore fitted with uniform weight over a
        # training window in which faulted points are a small minority, so the
        # correction it learned was dominated by healthy-point residuals. That
        # is a sufficient explanation for [NO RESCUE]: nothing in the objective
        # ever asked the model to do well on degraded readings.
        #
        # Fix: upweight faulted TRAINING rows by FAULT_TRAIN_WEIGHT, PER TARGET.
        # Keras accepts one sample_weight vector per output head, and per-target
        # is the only version that does any work here: on station
        # 861513064189509 the fault fractions of the training window are 43.5%
        # (temperature), 46.7% (EC) and 75.8% (DO), so a single vector OR-ed
        # across targets flags 77.2% of all rows -- upweighting three quarters
        # of the data is close to a no-op, and it also upweights rows for heads
        # whose own target is perfectly healthy. Each head therefore gets the
        # mask of its OWN target.
        #
        # This changes only the OBJECTIVE, never the evaluation: no test point
        # is read here, the gate and the conformal bound are untouched, and
        
        # ==================================================================
        train_sw = None
        _ftw = float(getattr(self.config, 'FAULT_TRAIN_WEIGHT', 1.0))
        if self.fault_mask is not None and _ftw != 1.0:
            _fm_tr = self.fault_mask.reindex(common_indices).fillna(False)
            _n_rows = int(len(X_train_m2p))
            # Map the training index onto positions within common_indices so the
            # mask is aligned by TIMESTAMP, never positionally: the lag/rolling
            # features drop the first rows, so a positional slice is off by ~72.
            _tr_pos = np.searchsorted(np.asarray(common_indices),
                                      np.asarray(train_indices))
            _tr_pos = _tr_pos[_tr_pos < len(_fm_tr)][:_n_rows]
            _vecs, _report = [], []
            for _v in target_vars:
                _sw = np.ones(_n_rows, dtype='float32')
                if _v in _fm_tr.columns:
                    _m = _fm_tr[_v].values.astype(bool)[_tr_pos]
                    _sw[:len(_m)][_m] = _ftw
                    _report.append((_v, int(_m.sum())))
                else:
                    _report.append((_v, 0))
                _vecs.append(_sw)
            _tot = sum(n for _, n in _report)
            if _tot >= 5:
                train_sw = _vecs
                print(f"    [C-T15] fault-aware training x{_ftw:g} over "
                      f"{_n_rows} training rows -- "
                      + ", ".join(f"{v}={n} ({100.0 * n / max(_n_rows, 1):.1f}%)"
                                  for v, n in _report))
            else:
                print(f"    [C-T15] only {_tot} faulted training rows across "
                      f"all targets (<5); uniform weights retained so the "
                      f"objective is not driven by a handful of points.")

        # ------------------------------------------------------------------ R16-E
        # DETECTION LABELS. The fault mask stops being metadata used only to
        # stratify the test table and becomes a training TARGET for the
        # degradation-probability heads. Labels are aligned by TIMESTAMP through
        # common_indices -- never positionally, because the feature builder drops
        # the leading warm-up rows -- and any row without mask coverage is
        # labelled -1, which FaultDetectionLoss treats as unlabelled and skips.
        # ------------------------------------------------------------- R17
        # Assemble the per-target drift-label columns ONCE, so both the packed
        # correction targets and the detection heads read the same vector.
        # A row with no mask coverage is -1 (unlabelled) and contributes zero
        # to every R17 term -- never 0.0, which would assert "healthy" and
        # train the gate shut.
        _fm_al0 = (self.fault_mask.reindex(common_indices).fillna(False)
                   if self.fault_mask is not None else None)
        _labs = []
        for _v in target_vars:
            if _fm_al0 is not None and _v in _fm_al0.columns:
                _labs.append(_fm_al0[_v].values.astype('float32'))
            else:
                _labs.append(np.full(len(common_indices), -1.0, dtype='float32'))

        if bool(getattr(model, '_m2p_r17', False)):
            # DriftRescueLoss reads y_true as (batch, 2) = (residual, label).
            _y_train = [np.stack([y_train_m2p[:, i].astype('float32'),
                                  _labs[i][:train_end]], axis=1)
                        for i in range(len(target_vars))]
            _y_val = [np.stack([y_val_m2p[:, i].astype('float32'),
                                _labs[i][train_end:val_end]], axis=1)
                      for i in range(len(target_vars))]
        else:
            _y_train = [y_train_m2p[:, i] for i in range(len(target_vars))]
            _y_val = [y_val_m2p[:, i] for i in range(len(target_vars))]
        _sw = list(train_sw) if train_sw is not None else None
        if _gated:
            _fm_al = _fm_al0
            _n_lab = 0
            for _i_v, _v in enumerate(target_vars):
                _lab = _labs[_i_v]
                if _fm_al is not None and _v in _fm_al.columns:
                    _n_lab += int(np.clip(_lab, 0.0, 1.0)[:train_end].sum())
                _y_train.append(_lab[:train_end])
                _y_val.append(_lab[train_end:val_end])
            if _sw is not None:
                # Detection heads get uniform weight: their own class weighting
                # is inside FaultDetectionLoss, and applying the correction
                # head's fault upweight here would double-count it.
                _sw = _sw + [np.ones(len(X_train_m2p), dtype='float32')] * len(target_vars)
            print(f"    [R16-E] detection labels: {_n_lab} faulted training "
                  f"rows across {len(target_vars)} heads.")
        if bool(getattr(model, '_m2p_bare', False)):
            # Bare-c ablation heads consume the same packed target.
            for _i_v in range(len(target_vars)):
                _y_train.append(np.stack(
                    [y_train_m2p[:, _i_v].astype('float32'),
                     _labs[_i_v][:train_end]], axis=1))
                _y_val.append(np.stack(
                    [y_val_m2p[:, _i_v].astype('float32'),
                     _labs[_i_v][train_end:val_end]], axis=1))
            if _sw is not None:
                _sw = _sw + [np.ones(len(X_train_m2p), dtype='float32')] * len(target_vars)
            if _n_lab < 20:
                print("    [R16-E] WARNING: fewer than 20 faulted training rows. "
                      "The detection heads have almost nothing to fit, so "
                      "p_fault will stay near its prior and the effective "
                      "correction will be near zero. That is the correct "
                      "behaviour -- it means this station shows no learnable "
                      "degradation, and detection_metrics_*.csv will say so -- "
                      "but it must not be read as the corrector failing.")

        # ------------------------------------------------------------ C1/OOF
        
        # the OOF scheme cannot be predicted (no earlier data to fit on), so its
        # target is NaN and it must leave the corrector's training set.
        #
        # WHY THE FILTER IS HERE AND NOT AT THE CONSTRUCTION SITE: eight arrays
        # above are positionally paired through [:train_end] slices -- including
        # the detection-head label arrays (_labs[i][:train_end]) and the
        # per-target sample-weight vectors -- and train_sw may be None entirely,
        # so zero-weighting is not universally available.  Editing every slice
        
        # filter applied after ALL assembly and before the fit keeps every array
        # consistent by construction.  train_indices itself is NOT touched, so
        # the anchor fit and every reported baseline metric stay byte-identical.
        if getattr(self, '_oof_covered_mask', None) is not None:
            _keep = np.asarray(self._oof_covered_mask, dtype=bool)
            _n0 = int(len(X_train_m2p))
            if _keep.shape[0] != _n0:
                # train_indices and the m2p feature rows can differ in length
                # (the feature builder drops leading warm-up rows). Align on the
                # TAIL, which is the overlap both share.
                _keep = _keep[-_n0:] if _keep.shape[0] > _n0 else np.concatenate(
                    [np.zeros(_n0 - _keep.shape[0], dtype=bool), _keep])
            X_train_m2p = X_train_m2p[_keep]
            X_train_context = X_train_context[_keep]
            _y_train = [np.asarray(a)[_keep] for a in _y_train]
            if _sw is not None:
                _sw = [np.asarray(a)[_keep] for a in _sw]
            _nk = int(_keep.sum())
            assert all(len(np.asarray(a)) == _nk for a in _y_train), \
                "C1/OOF row filter desynchronised the corrector target arrays."
            assert len(X_train_m2p) == _nk and len(X_train_context) == _nk, \
                "C1/OOF row filter desynchronised the corrector input arrays."
            if _sw is not None:
                assert all(len(np.asarray(a)) == _nk for a in _sw), \
                    "C1/OOF row filter desynchronised the sample weights."
            print(f"    [C1/OOF] corrector training rows {_n0} -> {_nk} "
                  f"({_n0 - _nk} warm-up rows without an out-of-fold residual "
                  f"dropped). Anchor fit and reported baselines unaffected.")

        # ------------------------------------------------------- INNER HOLDOUT
        # The outer validation interval is reserved for calibration, the R19
        # safety decision, and C selection.  Early stopping on that same interval
        # made all three downstream uses optimistic.  Reserve the chronological
        # tail of TRAINING instead; no test or outer-validation observation is
        # seen by the optimiser or its callbacks.
        _n_train_inner = int(len(X_train_m2p))
        if _n_train_inner < 20:
            raise ValueError(
                f"Only {_n_train_inner} corrector-training rows remain after "
                "OOF filtering; at least 20 are required for a disjoint inner "
                "early-stopping holdout.")
        _es_fraction = float(getattr(
            self.config, 'INNER_EARLY_STOP_FRACTION', 0.15))
        _es_min = int(getattr(self.config, 'INNER_EARLY_STOP_MIN_N', 16))
        _n_es = max(4, int(round(_es_fraction * _n_train_inner)))
        _n_es = min(max(_n_es, min(_es_min, _n_train_inner // 3)),
                    _n_train_inner - 16)
        _inner_cut = _n_train_inner - _n_es
        _x_fit = [X_train_m2p[:_inner_cut], X_train_context[:_inner_cut]]
        _x_es = [X_train_m2p[_inner_cut:], X_train_context[_inner_cut:]]
        _y_fit = [np.asarray(a)[:_inner_cut] for a in _y_train]
        _y_es = [np.asarray(a)[_inner_cut:] for a in _y_train]
        _sw_fit = (None if _sw is None else
                   [np.asarray(a)[:_inner_cut] for a in _sw])
        print(f"    [VALIDATION] optimiser fit={_inner_cut}, inner early-stop="
              f"{_n_es}; outer validation ({len(X_val_m2p)} rows) remains "
              "untouched for calibration/safety/selection.")

        # ------------------------------------------------------------- DEV
        # Gradient-norm probe on the delta head. Off unless
        # PTAC_DELTA_TELEMETRY=1, and it appends a callback rather than
        # replacing the list, so the benchmark path is byte-identical.
        _cbs = [early_stop, lr_scheduler]
        _gn = None
        if bool(getattr(self.config, 'DEV_DELTA_TELEMETRY', False)):
            _nb = min(256, len(_x_fit[0]))
            _gn = DeltaGradNorm(
                probe_x=[_x_fit[0][:_nb], _x_fit[1][:_nb]],
                probe_y=[np.asarray(a)[:_nb] for a in _y_fit],
                target_vars=target_vars)
            _cbs.append(_gn)
        # ------------------------------------------------------------- R27
        # FIXED-MODEL REPLAY.  The first arm for a (drift family, seed) is
        # trained normally.  Subsequent test intensities build the identical
        # architecture/preprocessing state but receive the exact cached Keras
        # weights.  This isolates test-intensity response from stochastic
        # retraining while leaving the anchor and all validation policy code
        # unchanged.
        _r27_on = bool(getattr(self.config, 'R27_FIXED_MODEL_REPLAY', False))
        _r27_key = getattr(self.config, '_r27_replay_key', None)
        _r27_cache = getattr(self.config, '_r27_weight_cache', None)
        self._r27_weights_reused = False
        # ------------------------------------------------------------- R35B
        # EXACT R34D CHECKPOINT REPLAY.  R35 must be a post-hoc audit of the
        # already reported R34D models, not a stochastic retraining.  R34D
        # persisted one native Keras checkpoint per challenged dataset.  When
        # PTAC_R35_FROZEN_CHECKPOINT_ROOT is supplied, load those exact weights
        # and SKIP model.fit() entirely.  The freshly built graph is retained
        # only so all causal preprocessing, R31 gates and R34 safety logic are
        # recomputed on the same data/chronology around the frozen network.
        _r35_root = os.environ.get('PTAC_R35_FROZEN_CHECKPOINT_ROOT', '').strip()
        _r35_loaded = False
        self._r35_checkpoint_path = None
        self._r35_checkpoint_sha256 = None
        if _r35_root:
            _ds35 = str(getattr(self.config, '_dataset_name', '') or '')
            if not _ds35:
                raise RuntimeError('[R35B] dataset name missing; cannot resolve frozen checkpoint')
            _ckdir35 = os.path.join(os.path.abspath(_r35_root), _ds35)
            _stem35 = f'model_ptac_{_ds35}'
            _keras35 = os.path.join(_ckdir35, _stem35 + '.keras')
            _h535 = os.path.join(_ckdir35, _stem35 + '.h5')
            _man35 = os.path.join(_ckdir35, _stem35 + '.manifest.json')
            if not os.path.isfile(_man35):
                raise RuntimeError(f'[R35B] checkpoint manifest missing: {_man35}')
            with open(_man35, 'r') as _fh35:
                _meta35 = json.load(_fh35)
            _expected_name35 = 'M2P-PTAC (R34 frozen C=0.0001)'
            if str(_meta35.get('dataset_name')) != _ds35:
                raise RuntimeError(
                    f'[R35B] checkpoint dataset mismatch: manifest={_meta35.get("dataset_name")} current={_ds35}')
            if str(_meta35.get('model_name')) != _expected_name35:
                raise RuntimeError(
                    f'[R35B] checkpoint arm mismatch: manifest={_meta35.get("model_name")!r}; '
                    f'expected {_expected_name35!r}')
            _ctxdim35 = int(_meta35.get('context_dim', -1))
            if _ctxdim35 != int(X_train_context.shape[1]):
                raise RuntimeError(
                    f'[R35B] context dimension mismatch: checkpoint={_ctxdim35}, '
                    f'current={X_train_context.shape[1]}')
            _arch35 = _meta35.get('architecture', {}) or {}
            _arch_expect35 = {
                'BILSTM_UNITS': int(getattr(self.config, 'BILSTM_UNITS', 0)),
                'CONV_FILTERS': int(getattr(self.config, 'CONV_FILTERS', 0)),
                'GRU_UNITS_STATIC': int(getattr(self.config, 'GRU_UNITS_STATIC', 0)),
                'ATTENTION_HEADS': int(getattr(self.config, 'ATTENTION_HEADS', 0)),
                'HEAD_DENSE_UNITS': int(getattr(self.config, 'HEAD_DENSE_UNITS', 0)),
                'DROPOUT_RATE': float(getattr(self.config, 'DROPOUT_RATE', 0.0)),
                'USE_FAULT_GATING': bool(getattr(self.config, 'USE_FAULT_GATING', False)),
                'R17_ENABLE': bool(getattr(self.config, 'R17_ENABLE', False)),
            }
            for _k35, _v35 in _arch_expect35.items():
                _mv35 = _arch35.get(_k35, None)
                if isinstance(_v35, float):
                    _ok35 = (_mv35 is not None and np.isclose(float(_mv35), _v35, rtol=0.0, atol=1e-12))
                else:
                    _ok35 = (_mv35 == _v35)
                if not _ok35:
                    raise RuntimeError(
                        f'[R35B] architecture mismatch {_k35}: checkpoint={_mv35!r}, current={_v35!r}')

            _load_errors35 = []
            if os.path.isfile(_keras35):
                try:
                    _frozen35 = tf.keras.models.load_model(
                        _keras35, compile=False, safe_mode=False)
                    _fw35 = _frozen35.get_weights()
                    _cw35 = model.get_weights()
                    if len(_fw35) != len(_cw35):
                        raise ValueError(
                            f'weight-count mismatch frozen={len(_fw35)} current={len(_cw35)}')
                    for _iw35, (_a35, _b35) in enumerate(zip(_fw35, _cw35)):
                        if np.shape(_a35) != np.shape(_b35):
                            raise ValueError(
                                f'weight[{_iw35}] shape mismatch frozen={np.shape(_a35)} current={np.shape(_b35)}')
                    model.set_weights([np.asarray(w).copy() for w in _fw35])
                    del _frozen35
                    _used35 = _keras35
                    _r35_loaded = True
                except Exception as _e35:
                    _load_errors35.append(f'.keras load failed: {type(_e35).__name__}: {_e35}')
            if not _r35_loaded and os.path.isfile(_h535):
                try:
                    model.load_weights(_h535)
                    _used35 = _h535
                    _r35_loaded = True
                except Exception as _e35:
                    _load_errors35.append(f'.h5 load failed: {type(_e35).__name__}: {_e35}')
            if not _r35_loaded:
                raise RuntimeError(
                    '[R35B] unable to load exact frozen R34D checkpoint from '
                    f'{_ckdir35}: ' + ' | '.join(_load_errors35))
            import hashlib as _hashlib35
            _hh35 = _hashlib35.sha256()
            with open(_used35, 'rb') as _fh35:
                for _chunk35 in iter(lambda: _fh35.read(1024 * 1024), b''):
                    _hh35.update(_chunk35)
            self._r35_checkpoint_path = os.path.abspath(_used35)
            self._r35_checkpoint_sha256 = _hh35.hexdigest()
            print(f'    [R35B] LOADED EXACT R34D CHECKPOINT; model.fit SKIPPED: '
                  f'{self._r35_checkpoint_path} sha256={self._r35_checkpoint_sha256[:16]}')

        if _r35_loaded:
            pass
        elif _r27_on and _r27_key is not None and isinstance(_r27_cache, dict) and _r27_key in _r27_cache:
            _cached27 = _r27_cache[_r27_key]
            model.set_weights([np.array(w, copy=True) for w in _cached27])
            self._r27_weights_reused = True
            print(f'    [R27] REUSED exact frozen Keras weights for {_r27_key} '
                  f'at test intensity={getattr(self.config, "_r27_replay_level", "?")}')
        else:
            model.fit(
                x=_x_fit,
                y=_y_fit,
                sample_weight=_sw_fit,
                validation_data=(_x_es, _y_es),
                epochs=self.config.EPOCHS,
                batch_size=self.config.BATCH_SIZE,
                callbacks=_cbs,
                shuffle=False,
                verbose=0
            )
            if _r27_on and _r27_key is not None and isinstance(_r27_cache, dict):
                _r27_cache[_r27_key] = [np.array(w, copy=True) for w in model.get_weights()]
                print(f'    [R27] CACHED frozen Keras weights for {_r27_key}; '
                      'all later intensities will reuse this exact fit.')
        if _gn is not None and _gn.history:
            _gdf = pd.DataFrame(_gn.history)
            _gp = os.path.join(self.config.OUTPUT_DIR,
                               f"dev_grad_norms_{_safe_name(self.model_name)}.csv")
            _gdf.to_csv(_gp, index=False)
            _last = _gdf[_gdf.epoch == _gdf.epoch.max()]
            print(f"    [DEV] delta-head gradient norms -> {_gp}")
            for _, _r in _last.iterrows():
                print(f"      {_r['target'][:22]:22s} final epoch: "
                      f"||g_delta||={_r['g_delta']:.4g}  "
                      f"||g_trunk||={_r['g_trunk']:.4g}  "
                      f"||W_delta||={_r['w_delta']:.4g}  "
                      f"p_fault_mean={_r['p_fault_mean']:.4g}")
            _g0 = _gdf.groupby('target').g_delta.max()
            for _t, _v in _g0.items():
                if not (_v > 1e-8):
                    print(f"      [DEV] ||g_delta|| never exceeded 1e-8 for "
                          f"{_t}: NO GRADIENT reaches the correction head. "
                          f"This is a wiring/gating problem, not a "
                          f"regularisation one -- no lambda setting can fix it.")
        timings = {'Training Time (s)': time.time() - start_time_total}

        start_time_forecast = time.time()
        
        # predict() prints a Keras progress bar per call.
        # n_targets are the EFFECTIVE corrections (already multiplied by p_fault
        # inside the graph) and the rest are the probabilities themselves, kept
        # for the detection report. Slicing by _n_t rather than assuming the
        # output count is what keeps the ungated path byte-identical.
        if not (len(X_test_m2p) == len(X_test_context) == len(test_indices)):
            raise RuntimeError(
                "[R32-P2] refusing Keras prediction with misaligned confirmation "
                f"inputs: sequence={len(X_test_m2p)}, "
                f"context={len(X_test_context)}, index={len(test_indices)}")
        _raw_out = model.predict([X_test_m2p, X_test_context], verbose=0)
        _outs = [np.asarray(o).reshape(-1) for o in
                 (_raw_out if isinstance(_raw_out, list) else [_raw_out])]
        predicted_residuals_scaled = np.stack(_outs[:_n_t], axis=1)
        self.last_fault_prob = (np.stack(_outs[_n_t:2 * _n_t], axis=1)
                                if _gated and len(_outs) >= 2 * _n_t else None)
        if (self.use_attention and bool(getattr(self.config, 'SAVE_LIVE_ATTENTION_SCORES', False))
                and str(self.model_name).startswith('M2P-PTAC (C=')):
            save_live_attention_scores(
                model, X_test_m2p, X_test_context, test_indices, self.config,
                self.model_name, str(getattr(self.config, '_dataset_name', 'unknown')),
                target_vars)
        num_forecasts = len(X_test_m2p)
        timings['Forecast Time (s)'] = (time.time() - start_time_forecast) / num_forecasts

        self._r17_res_scaler = scaler_residuals
        self._r17_delta_scaled = np.array(predicted_residuals_scaled, dtype=float, copy=True)
        predicted_residuals = scaler_residuals.inverse_transform(predicted_residuals_scaled)
        
        self._r19_test_corr_raw = np.array(predicted_residuals, dtype=float,
                                           copy=True)

        # -------------------------------------------------------------- R25
        # MECHANISM TAP 1: bounded correction BEFORE p_fault multiplication.
        # Same fitted weights, same test inputs, no retraining and no threshold
        # changes. The ordinary graph output above is Tap 2: p_fault-gated
        # correction BEFORE R20/R19/R21 post-hoc suppression.
        self._r25_test_corr_bounded = None
        self._r25_test_corr_bounded_scaled = None
        self._r25_tau_scaled = np.asarray(
            [float(_taus.get(v, np.nan)) for v in target_vars], dtype=float)
        if bool(getattr(self.config, 'R25_MECHANISM_DIAGNOSTIC', False)):
            try:
                _tap_outputs = []
                for _v25 in target_vars:
                    _safe25 = _v25.replace(' ', '_')
                    try:
                        _tap_outputs.append(model.get_layer(f'bounded_{_safe25}').output)
                    except Exception:
                        _tap_outputs.append(model.get_layer(f'delta_{_safe25}').output)
                _tap_model = Model(inputs=model.inputs, outputs=_tap_outputs)
                _tap_pred = _tap_model.predict([X_test_m2p, X_test_context], verbose=0)
                _tap_pred = _tap_pred if isinstance(_tap_pred, list) else [_tap_pred]
                _tap_scaled = np.stack(
                    [np.asarray(a).reshape(-1) for a in _tap_pred], axis=1)
                self._r25_test_corr_bounded_scaled = np.asarray(
                    _tap_scaled, dtype=float)
                self._r25_test_corr_bounded = scaler_residuals.inverse_transform(
                    _tap_scaled)
                print('    [R25-MECH] tapped bounded pre-p_fault correction from '
                      'the SAME fitted graph.')
            except Exception as _e25:
                print(f'    [R25-MECH] bounded-correction tap failed: '
                      f'{type(_e25).__name__}: {_e25}')

        # Violated by a centring residual scaler, which silently converts gate
        # abstention into a constant bias equal to mean_ -- reported as rescue.
        # This is checked rather than trusted because the failure is invisible
        # in every aggregate: MAE moves, the sign looks favourable, and only the
        # per-row spread (exactly 0) gives it away.
        if bool(getattr(self.config, 'R17_ENABLE', False)):
            _z = scaler_residuals.inverse_transform(
                np.zeros((1, predicted_residuals_scaled.shape[1])))
            assert np.abs(_z).max() < 1e-12, (
                "[R17] the correction scaler re-inflates a zero correction to "
                f"{np.round(_z.ravel(), 6).tolist()}. Gate abstention would be "
                "reported as a constant non-zero correction. Refit the residual "
                "scaler with with_mean=False.")

        # ------------------------------------------------------------------
        # ------------------------------------------------------------------
        # Two bound families, selected by which kwarg the caller passes.
        #
        
        
        #              hit rate as 0.000 on every target of every testbed even
        #              at k=1.0, because std(y_train) is the spread of the
        #              TARGET VALUES while the bounded quantity is a residual
        #              correction two orders of magnitude smaller. Bounded and
        #              unbounded were therefore the same function.
        #
        
        #              corrections, which binds at ~alpha by construction.
        #
        # The correction on the CALIBRATION half of validation must be computed
        # before the bound exists, so validation inference is hoisted above the
        # bound and the test-time clip is applied afterwards.
        # ------------------------------------------------------------------
        # ------------------------------------------------------------------
        
        #
        
        # of the TARGET LEVEL -- while the thing being clipped is a CORRECTION,
        # whose scale is the baseline's residual, not the signal's. Measured on
        
        #
        #     std(residual) / std(level):  median 0.238  (range 0.096 - 0.709)
        #     k on the LEVEL scale that would bind even 10% of points:
        #                                  median 0.424  (range 0.105 - 1.562)
        #
        # The sweep offers k = 1, 2, 3. On 8 of 9 (testbed, target) channels
        # every one of those sits above the k at which the bound could clip even
        # 10% of points; the exception is challenged_89509 / ph, where k_10% =
        # 1.562, so k=1 would bind there on this proxy. That single exception is
        
        # empirically, because the bound is applied per target and the realised
        # rate was zero everywhere --
        # realised_bind_rate == 0.0000 on 9 of 9 clip_k rows, all three testbeds,
        # all three k. The manuscript's "bounded correction" was therefore
        # untestable as run -- not violated, but never exercised, so the ablation
        # measured nothing and clip_k=1,2,3 were three names for the unbounded
        # model.
        #
        # Fix: scale to the correction's own dispersion, estimated on the
        # calibration half of validation (the same data the conformal bound
        # uses, so the two are directly comparable). sigma_level is kept and
        
        # ------------------------------------------------------------------
        sigma_level = y_train_tab.std().values             

        # first _n_t outputs (effective corrections) and ignore the probability
        # heads here, so the conformal bound and the gate are calibrated on the
        # correction that will actually be applied.
        _vraw = model.predict([X_val_m2p, X_val_context], verbose=0)
        _vouts = [np.asarray(o).reshape(-1) for o in
                  (_vraw if isinstance(_vraw, list) else [_vraw])]
        val_res_scaled = np.stack(_vouts[:_n_t], axis=1)
        self.last_val_fault_prob = (np.stack(_vouts[_n_t:2 * _n_t], axis=1)
                                    if _gated and len(_vouts) >= 2 * _n_t else None)
        val_residuals_raw = scaler_residuals.inverse_transform(val_res_scaled)

        # ------------------------------------------------------------- R28
        # FIXED TRAIN-ONLY HARD INNOVATION SWITCH.
        #
        # This deliberately does NOT use p_fault as an amplitude multiplier.
        # The correction graph may still carry an auxiliary supervised detector
        # head, but the deployed candidate correction is the unattenuated bounded
        # delta. Micro-corrections are snapped to literal zero using a threshold
        # derived only from the clean/reference chronological TRAIN target in the
        # SAME physical units as the inverse-scaled correction:
        #
        #   tau_j = alpha * 1.4826 * MAD(diff(y_train,j)).
        #
        # This is a robust TRAIN innovation scale, not an asserted sensor-noise
        # standard deviation. alpha is fixed a priori at 1.0 in the dedicated
        # development branch; it is never swept on validation/test results. Because this
        # mechanism was proposed after prior development runs, a successful result
        # requires a fresh independent confirmation before manuscript claims.
        self._r28_switch_thresholds = None
        self._r28_switch_action_rate_val = None
        self._r28_switch_action_rate_test = None
        if bool(getattr(self.config, 'R28_HARD_INNOVATION_SWITCH', False)):
            _alpha28 = float(getattr(self.config, 'R28_HARD_SWITCH_ALPHA', 1.0))
            _floor28 = float(getattr(self.config, 'R28_HARD_SWITCH_FLOOR', 1e-12))
            _thr28 = []
            for _j28, _v28 in enumerate(target_vars):
                _yt28 = pd.to_numeric(y_train_tab[_v28], errors='coerce').values.astype(float)
                _yt28 = _yt28[np.isfinite(_yt28)]
                _d28 = np.diff(_yt28) if _yt28.size >= 2 else np.asarray([], dtype=float)
                _d28 = _d28[np.isfinite(_d28)]
                if _d28.size:
                    _m28 = float(np.median(_d28))
                    _s28 = 1.4826 * float(np.median(np.abs(_d28 - _m28)))
                else:
                    _s28 = 0.0
                _thr28.append(max(_floor28, _alpha28 * _s28))
            _thr28 = np.asarray(_thr28, dtype=float)
            self._r28_switch_thresholds = dict(zip(target_vars, _thr28.tolist()))

            _val_pre28 = np.asarray(val_residuals_raw, dtype=float).copy()
            _test_pre28 = np.asarray(predicted_residuals, dtype=float).copy()
            val_residuals_raw = np.where(np.abs(_val_pre28) >= _thr28.reshape(1, -1),
                                         _val_pre28, 0.0)
            predicted_residuals = np.where(np.abs(_test_pre28) >= _thr28.reshape(1, -1),
                                           _test_pre28, 0.0)
            self._r28_switch_action_rate_val = dict(zip(
                target_vars, np.mean(np.abs(val_residuals_raw) > 1e-12, axis=0).tolist()))
            self._r28_switch_action_rate_test = dict(zip(
                target_vars, np.mean(np.abs(predicted_residuals) > 1e-12, axis=0).tolist()))
            print('    [R28-SWITCH] fixed TRAIN innovation thresholds (physical units): ' +
                  ', '.join(f"{v}={self._r28_switch_thresholds[v]:.6g}" for v in target_vars))
            print('    [R28-SWITCH] action rate val/test: ' + ', '.join(
                f"{v}={100*self._r28_switch_action_rate_val[v]:.1f}%/"
                f"{100*self._r28_switch_action_rate_test[v]:.1f}%" for v in target_vars))


        # ------------------------------------------------------------- R31
        # FROZEN PER-TARGET HYBRID GATE — CONFIRMATION ONLY.
        #
        # Development evidence selected this mapping ONCE:
        # temperature / pH / dissolved oxygen -> R28 train-innovation switch
        # electric conductivity               -> R30 causal health-state gate
        #
        # No target mapping or threshold search occurs here.
        self._r31_gate_kind = {}
        self._r31_val_action_rate = {}
        self._r31_test_action_rate = {}
        # DQA/action alignment. These are PRE-safety masks; final applied action
        # is reconstructed from the post-R19 correction array.
        self._r31_val_gate_mask_by_target = {}
        self._r31_test_gate_mask_by_target = {}
        self._r31_health_diag = []
        if bool(getattr(self.config, 'R31_HYBRID_TARGET_GATE', False)):
            _health_targets31 = set(str(x) for x in getattr(
                self.config, 'R31_HEALTH_TARGETS', ('electric conductivity',)))
            _innovation_targets31 = set(str(x) for x in getattr(
                self.config, 'R31_INNOVATION_TARGETS',
                ('temperature','ph','dissolved oxygen')))
            _known31 = _health_targets31 | _innovation_targets31
            _missing31 = [v for v in target_vars if str(v) not in _known31]
            if _missing31:
                raise ValueError(f"[R31] no frozen gate mapping for targets: {_missing31}")
            if self.fault_mask is None:
                raise ValueError('[R31] fault labels required for EC health-state gate')

            _ctx_names31 = list(getattr(self, '_r17_ctx_cols', []))
            _tridx31 = pd.Index(train_indices[-len(X_train_context):])
            _fmtr31 = (self.fault_mask.reindex(index=_tridx31, columns=target_vars)
                       .fillna(False).astype(bool).values)
            _fmva31 = (self.fault_mask.reindex(index=val_indices, columns=target_vars)
                       .fillna(False).astype(bool).values)
            if self.obs_mask is not None:
                _omtr31 = (self.obs_mask.reindex(index=_tridx31, columns=target_vars)
                           .fillna(False).astype(bool).values)
                _omva31 = (self.obs_mask.reindex(index=val_indices, columns=target_vars)
                           .fillna(False).astype(bool).values)
            else:
                _omtr31 = np.ones_like(_fmtr31, dtype=bool)
                _omva31 = np.ones_like(_fmva31, dtype=bool)

            # resolve its CAL slice locally here. This is the same helper and
            # therefore the same chronological role allocation used later by
            _nval31 = int(len(val_residuals_raw))
            if _nval31 < 3:
                raise ValueError('[R31] outer validation requires at least three rows.')
            _ncal31, _nsafe31, _ncsel31 = _resolve_validation_roles(
                self.config, _nval31)
            _cal_slice31 = slice(0, _ncal31)
            print(f"    [R31] local validation roles: calibration={_ncal31}, "
                  f"safety={_nsafe31}, telemetry={_ncsel31}.")

            _thr31 = float(getattr(self.config, 'R30_DECISION_THRESHOLD', 0.50))
            _alpha31 = float(getattr(self.config, 'R28_HARD_SWITCH_ALPHA', 1.0))
            _floor31 = float(getattr(self.config, 'R28_HARD_SWITCH_FLOOR', 1e-12))

            _innov_thr31 = {}
            for _v31 in target_vars:
                if str(_v31) not in _innovation_targets31:
                    continue
                _yt31 = pd.to_numeric(y_train_tab[_v31], errors='coerce').values.astype(float)
                _yt31 = _yt31[np.isfinite(_yt31)]
                _d31 = np.diff(_yt31) if _yt31.size >= 2 else np.asarray([], dtype=float)
                _d31 = _d31[np.isfinite(_d31)]
                if _d31.size:
                    _m31 = float(np.median(_d31))
                    _s31 = 1.4826 * float(np.median(np.abs(_d31 - _m31)))
                else:
                    _s31 = 0.0
                _innov_thr31[str(_v31)] = max(_floor31, _alpha31 * _s31)

            for _j31, _v31 in enumerate(target_vars):
                _name31 = str(_v31)
                _vpre31 = np.asarray(val_residuals_raw[:, _j31], dtype=float).copy()
                _tpre31 = np.asarray(predicted_residuals[:, _j31], dtype=float).copy()

                # ----------------------------------------------------- R36
                # SEALED DQA-DISTILLED EXTERNAL GATE.  The probability model is
                # fitted before the holdout test labels are scored, using only
                # development-station DQA labels and causal telemetry features.
                # It is an explicit replacement for R31 on the sealed holdout;
                # there is no threshold search and no holdout-label fitting.
                _ext36 = getattr(self.config, 'R36_EXTERNAL_GATE_SERIES_BY_TARGET', {}) or {}
                if bool(getattr(self.config, 'R36_DQA_DISTILLED_GATE', False)) and _name31 in _ext36:
                    _ser36 = _ext36[_name31]
                    if not isinstance(_ser36, pd.Series):
                        raise TypeError('[R36] external gate must be a timestamp-indexed pandas Series')
                    _gva31 = _ser36.reindex(val_indices).fillna(False).astype(bool).values
                    _gte31 = _ser36.reindex(test_indices).fillna(False).astype(bool).values
                    _thr36 = float(getattr(self.config, 'R36_DECISION_THRESHOLD', 0.50))
                    self._r31_gate_kind[_name31] = f'r36_dqa_distilled_logreg_p{_thr36:.2f}'
                    if len(_gva31) != len(_vpre31) or len(_gte31) != len(_tpre31):
                        raise RuntimeError('[R36] external gate cardinality mismatch')

                elif _name31 in _innovation_targets31:
                    _tau31 = float(_innov_thr31[_name31])
                    _gva31 = np.abs(_vpre31) >= _tau31
                    _gte31 = np.abs(_tpre31) >= _tau31
                    self._r31_gate_kind[_name31] = f'innovation_MAD_alpha1_tau={_tau31:.8g}'

                elif _name31 in _health_targets31:
                    _xtr31, _fn31 = build_r30_health_state_features(
                        X_train_context, _ctx_names31, _v31)
                    _xva31, _ = build_r30_health_state_features(
                        X_val_context, _ctx_names31, _v31)
                    _xte31, _ = build_r30_health_state_features(
                        X_test_context, _ctx_names31, _v31)
                    _mods31, _td31 = _r30_fit_models(
                        _xtr31, _fmtr31[:, _j31], _omtr31[:, _j31],
                        self.config, target=_v31)
                    if not _mods31:
                        _sel31, _rows31, _why31 = None, [], _td31.get(
                            'reason','train fit failed')
                    else:
                        _sel31, _rows31, _why31 = _r30_select_candidate(
                            _mods31, _xva31[_cal_slice31], _fmva31[_cal_slice31, _j31],
                            _omva31[_cal_slice31, _j31], self.config, target=_v31)
                    for _rr31 in _rows31:
                        _rr31.update(
                            n_features=int(len(_fn31)),
                            selected=bool(_rr31['candidate'] == _sel31),
                            seed=int(getattr(self.config, '_active_rescue_seed',
                                             getattr(self.config,'SEED',42))))
                        self._r31_health_diag.append(_rr31)
                    if _sel31 is None:
                        _gva31 = np.zeros(len(X_val_context), dtype=bool)
                        _gte31 = np.zeros(len(X_test_context), dtype=bool)
                        self._r31_gate_kind[_name31] = f'health_CLOSED:{_why31}'
                    else:
                        _pva31 = _r30_prob(_mods31[_sel31], _xva31)
                        _pte31 = _r30_prob(_mods31[_sel31], _xte31)
                        _gva31 = _pva31 >= _thr31
                        _gte31 = _pte31 >= _thr31
                        self._r31_gate_kind[_name31] = f'health_{_sel31}_p0.50'
                else:
                    raise AssertionError(f'[R31] unmapped target {_name31}')

                self._r31_val_gate_mask_by_target[_name31] = np.asarray(_gva31, dtype=bool).copy()
                self._r31_test_gate_mask_by_target[_name31] = np.asarray(_gte31, dtype=bool).copy()
                val_residuals_raw[~_gva31, _j31] = 0.0
                predicted_residuals[~_gte31, _j31] = 0.0
                self._r31_val_action_rate[_name31] = float(np.mean(_gva31))
                self._r31_test_action_rate[_name31] = float(np.mean(_gte31))

            print('    [R31] FROZEN hybrid mapping: ' + ', '.join(
                f"{v}={self._r31_gate_kind[str(v)]}" for v in target_vars))
            print('    [R31] action rate val/test: ' + ', '.join(
                f"{v}={100*self._r31_val_action_rate[str(v)]:.1f}%/"
                f"{100*self._r31_test_action_rate[str(v)]:.1f}%"
                for v in target_vars))
            try:
                if self._r31_health_diag:
                    _df31 = pd.DataFrame(self._r31_health_diag)
                    _tag31 = _safe_filename(self.model_name)
                    _sd31 = int(getattr(self.config, '_active_rescue_seed',
                                        getattr(self.config,'SEED',42)))
                    _df31.to_csv(os.path.join(
                        self.config.OUTPUT_DIR,
                        f'r31_ec_health_selection_{_tag31}_seed{_sd31}.csv'),
                        index=False)
            except Exception as _e31:
                print(f'    [R31] audit write skipped: {_e31}')


        # ------------------------------------------------------------- R21
        # TRAIN-ONLY DYNAMIC SELECTOR.
        #
        # p_fault is still the neural detector.  R21 refines its *ranking* with
        # causal state (persistence, correction magnitude and target-specific
        # anchor/health context) using only training fault labels.  No operating
        # threshold is learned here.  R20/validation chooses that threshold and
        self._r21_selector_diag = {}
        self._r21_selector_models = {}
        self._r21_selector_val_score = self.last_val_fault_prob
        self.last_selector_score = self.last_fault_prob
        if (bool(getattr(self.config, 'R21_DYNAMIC_SELECTOR', False))
                and _gated and self.last_fault_prob is not None
                and self.last_val_fault_prob is not None
                and self.fault_mask is not None):
            try:
                _trraw21 = model.predict([X_train_m2p, X_train_context], verbose=0)
                _tro21 = [np.asarray(o).reshape(-1) for o in
                          (_trraw21 if isinstance(_trraw21, list) else [_trraw21])]
                if len(_tro21) < 2 * _n_t:
                    raise ValueError('trained graph did not expose p_fault heads')
                _trc21 = scaler_residuals.inverse_transform(
                    np.stack(_tro21[:_n_t], axis=1))
                _trp21 = np.stack(_tro21[_n_t:2 * _n_t], axis=1)

                # OOF mode can drop only the early corrector-training rows.
                # Align labels to the chronological tail actually reaching the
                # corrector, then continue seamlessly through val and test so
                # persistence features never reset at a split boundary.
                _tr_idx21 = pd.Index(train_indices[-len(X_train_m2p):])
                _all_p21 = np.vstack([_trp21, self.last_val_fault_prob,
                                      self.last_fault_prob])
                _all_c21 = np.vstack([_trc21, val_residuals_raw,
                                      predicted_residuals])
                _all_ctx21 = np.vstack([X_train_context, X_val_context,
                                        X_test_context])
                _ctx_cols21 = list(getattr(self, '_r17_ctx_cols', []))
                if len(_ctx_cols21) != _all_ctx21.shape[1]:
                    _ctx_cols21 = [f'context_{i}'
                                   for i in range(_all_ctx21.shape[1])]

                _fmtr21 = (self.fault_mask.reindex(index=_tr_idx21,
                                                   columns=target_vars)
                           .fillna(False).astype(bool).values)
                if self.obs_mask is not None:
                    _omtr21 = (self.obs_mask.reindex(index=_tr_idx21,
                                                     columns=target_vars)
                               .fillna(False).astype(bool).values)
                else:
                    _omtr21 = np.ones_like(_fmtr21, dtype=bool)

                _scores21 = np.zeros_like(_all_p21, dtype=float)
                _ntr21 = len(_trp21)

                _benefit21 = (bool(getattr(self.config, 'BENEFIT_AWARE_SELECTOR', False))
                              and self.corrector_target_df is not None)
                _btr21 = None
                _ytr21 = None
                if _benefit21:
                    if len(set(_tr_idx21) & set(test_indices)):
                        raise AssertionError("[BENEFIT] train selector overlaps test")
                    _btr21 = np.asarray(
                        df_baseline_preds.reindex(_tr_idx21).values, dtype=float)
                    _ytr21 = np.asarray(
                        self.corrector_target_df.reindex(
                            index=_tr_idx21, columns=target_vars).values,
                        dtype=float)
                    if not (_btr21.shape == _trc21.shape == _ytr21.shape):
                        raise ValueError(
                            f"[BENEFIT] shape mismatch base={_btr21.shape} "
                            f"corr={_trc21.shape} truth={_ytr21.shape}")
                    print("    [BENEFIT] selector objective=correction usefulness "
                          "(TRAIN-only reference supervision)")

                if bool(getattr(self.config, 'R21_VERIFY_CAUSAL', True)) and target_vars:
                    _ok21, _mx21 = verify_dynamic_selector_feature_causality(
                        _all_p21[:, 0], _all_c21[:, 0], _all_ctx21,
                        _ctx_cols21, target_vars[0], self.config)
                    print(f"    [R21 leak] {target_vars[0]}: PASS "
                          f"max prefix change={_mx21:.3g}")
                for _j21, _v21 in enumerate(target_vars):
                    _xf21, _fn21 = build_dynamic_selector_features(
                        _all_p21[:, _j21], _all_c21[:, _j21], _all_ctx21,
                        _ctx_cols21, _v21, self.config)
                    if _benefit21:
                        _sc21, _md21, _dg21 = fit_benefit_aware_selector(
                            _xf21[:_ntr21], _trc21[:, _j21],
                            _btr21[:, _j21], _ytr21[:, _j21],
                            _omtr21[:, _j21], self.config,
                            feature_names=_fn21, target=_v21)
                    else:
                        _sc21, _md21, _dg21 = fit_dynamic_selector(
                            _xf21[:_ntr21], _fmtr21[:, _j21],
                            _omtr21[:, _j21], self.config,
                            feature_names=_fn21, target=_v21)
                        _dg21 = dict(_dg21)
                        _dg21['selector_objective'] = 'fault_presence'
                    _scores21[:, _j21] = score_dynamic_selector(
                        _xf21, _sc21, _md21, _all_p21[:, _j21])
                    self._r21_selector_diag[_v21] = _dg21
                    self._r21_selector_models[_v21] = (_sc21, _md21, list(_fn21))
                    _obj21 = _dg21.get('selector_objective', 'fault_presence')
                    _hr21 = _dg21.get('helpful_rate', np.nan)
                    print(f"    [SELECTOR] {_v21}: objective={_obj21}; "
                          f"{'fitted' if _dg21.get('fitted') else 'p_fault fallback'} "
                          f"(train n={_dg21.get('n_train')}, "
                          f"pos/neg={_dg21.get('n_pos')}/{_dg21.get('n_neg')}"
                          + (f", helpful={_hr21:.3f}" if np.isfinite(_hr21) else "")
                          + ")"
                          + ('' if _dg21.get('fitted') else
                             f" -- {_dg21.get('reason', '')}"))
                _nv21 = len(self.last_val_fault_prob)
                self._r21_selector_train_score = _scores21[:_ntr21]
                self._r21_selector_val_score = _scores21[_ntr21:_ntr21 + _nv21]
                self.last_selector_score = _scores21[_ntr21 + _nv21:]
            except Exception as _e21:
                print(f"    [R21] dynamic selector unavailable ({type(_e21).__name__}: "
                      f"{_e21}); falling back to raw p_fault. Safety logic unchanged.")
                self._r21_selector_diag = {
                    _v: dict(target=_v, fitted=False, fallback='p_fault',
                             reason=repr(_e21)) for _v in target_vars}
                self._r21_selector_val_score = self.last_val_fault_prob
                self.last_selector_score = self.last_fault_prob

        # ------------------------------------------------------------- R19
        # CORRECTION FIDELITY, corr(c_hat, c*), on the VALIDATION window.
        #
        # Read-only: computes and stores, changes nothing downstream. Validation
        # (not test) because the test protocol is frozen and because this is a
        # selection-side diagnostic. c_hat is the correction as LEARNED, taken
        # before the conformal bound / clip / gate, so a null here is a statement
        # about the learned mapping and not about the gate declining to fire.
        #
        # c* is reconstructed from the SAME definition the arm was trained on:
        # (target frame) - (anchor forecast) on validation rows.
        self._r19_fidelity = []
        try:
            _tf19 = (self.corrector_target_df if self.corrector_target_df is not None
                     else (y_tab if getattr(self, '_r18_retargeted', 0) else df))
            _bp19 = df_baseline_preds.rename(
                columns=lambda c: c.replace('_pred', ''))
            for _i19, _v19 in enumerate(target_vars):
                if _v19 not in _tf19.columns:
                    continue
                _cs = (_tf19.reindex(index=val_indices)[_v19].astype(float).values
                       - _bp19.reindex(index=val_indices)[_v19].astype(float).values)
                _ch = np.asarray(val_residuals_raw[:, _i19], dtype=float)
                _ok19 = np.isfinite(_cs) & np.isfinite(_ch)
                _r19 = (float(np.corrcoef(_ch[_ok19], _cs[_ok19])[0, 1])
                        if _ok19.sum() > 2 and np.std(_ch[_ok19]) > 1e-12
                        and np.std(_cs[_ok19]) > 1e-12 else float('nan'))
                self._r19_fidelity.append(dict(
                    target=_v19, n=int(_ok19.sum()), corr_chat_cstar=_r19,
                    sd_chat=float(np.std(_ch[_ok19])) if _ok19.any() else float('nan'),
                    sd_cstar=float(np.std(_cs[_ok19])) if _ok19.any() else float('nan'),
                    mean_abs_chat=float(np.mean(np.abs(_ch[_ok19]))) if _ok19.any() else float('nan'),
                    mean_abs_cstar=float(np.mean(np.abs(_cs[_ok19]))) if _ok19.any() else float('nan')))
                print(f"    [R19] fidelity '{_v19}': corr(c_hat,c*)={_r19:.4f} "
                      f"sd(c_hat)={np.std(_ch[_ok19]):.4f} "
                      f"sd(c*)={np.std(_cs[_ok19]):.4f} (n={int(_ok19.sum())})")
        except Exception as _fe19:
            print(f"    [R19] WARNING: fidelity telemetry skipped ({_fe19}).")

        # ------------------------------------------------------------- DEV
        # delta_RAW telemetry. Placed here because it needs scaler_residuals
        # and the split arrays, and deliberately BEFORE the conformal bound /
        # clip / gate so it reports the correction as LEARNED, not as applied.
        # Read-only; see the docstring on leakage.
        if bool(getattr(self.config, 'DEV_DELTA_TELEMETRY', False)):
            try:
                
                # while y_train_m2p was NOT (it is only read for tau, which
                # drops non-finite itself). Filter the telemetry's copy so the
                # pair stays aligned; without this the train row raises a
                # broadcast error and the whole telemetry block is skipped.
                _ytr_tel = y_train_m2p
                if len(_ytr_tel) != len(X_train_m2p):
                    _km = np.asarray(self._oof_covered_mask, dtype=bool)
                    _ytr_tel = _ytr_tel[_km[-len(_ytr_tel):]] \
                        if _km.shape[0] >= len(_ytr_tel) else _ytr_tel[-len(X_train_m2p):]
                dev_delta_telemetry(
                    model, target_vars,
                    {'train': (X_train_m2p, X_train_context, _ytr_tel),
                     'val':   (X_val_m2p, X_val_context, y_val_m2p),
                     'test':  (X_test_m2p, X_test_context,
                               y_test_m2p)},
                    scaler_residuals, self.config, self.config.OUTPUT_DIR,
                    _safe_name(self.model_name))
            except Exception as _e:
                print(f"    [DEV] telemetry failed: {_e}")

        # Three chronological, disjoint uses of the OUTER validation interval:
        # correction/bound calibration, safety veto, and C/model selection.
        n_val = len(val_residuals_raw)
        if n_val < 3:
            raise ValueError('Outer validation requires at least three rows.')
        n_cal, n_safe, n_csel = _resolve_validation_roles(self.config, n_val)
        cal_slice = slice(0, n_cal)
        safety_slice = slice(n_cal, n_cal + n_safe)
        csel_slice = slice(n_cal + n_safe, n_cal + n_safe + n_csel)
        print(f"    [VALIDATION] outer blocks: calibration={n_cal}, "
              f"safety={n_safe}, C-selection/telemetry={n_csel}.")
        if bool(getattr(self.config, 'R19_FULL_EVIDENCE_MODE', False)):
            print('    [R19-FULL] C is fixed externally; final slice is telemetry only, not model selection.')

        conformal_diag = {}
        if self.conformal_alpha is not None:
            bound, conformal_diag = conformal_correction_bound(
                val_residuals_raw[cal_slice], self.conformal_alpha, target_vars)
            print(f"    [R8] conformal alpha={self.conformal_alpha}: "
                  f"per-target bound "
                  + ", ".join(f"{v}={conformal_diag.get(v, {}).get('bound', np.nan):.4g}"
                              for v in target_vars))
        elif self.clip_k is not None:
            
            # of the level. Falls back to the level scale only if calibration is
            # too small to estimate a dispersion (guarding a divide-by-nothing).
            _cal_corr = val_residuals_raw[cal_slice]
            if _cal_corr.shape[0] >= 8:
                sigma_corr = _cal_corr.std(axis=0)
            else:
                sigma_corr = sigma_level
                print(f"    [R15-C] calibration half has {_cal_corr.shape[0]} "
                      f"points -- too few for a correction-scale sigma; falling "
                      f"back to the level scale. The bound will not bind.")
            sigma_corr = np.where(sigma_corr > 1e-12, sigma_corr, sigma_level)
            bound = self.clip_k * sigma_corr                  # shape (n_targets,)
            print(f"    [R15-C] clip_k={self.clip_k} on the CORRECTION scale: "
                  + ", ".join(f"{v}: sigma_corr={s:.4g} (level {l:.4g}, "
                              f"ratio {s / l:.3f}) -> bound {b:.4g}"
                              for v, s, l, b in zip(target_vars, sigma_corr,
                                                    sigma_level, bound)))
        else:
            bound = None

        # ------------------------------------------------------------------
        # using the UNBOUNDED correction and the baseline's own validation
        # error. Targets that fail the gate are passed through untouched.
        # ------------------------------------------------------------------
        # ------------------------------------------------------------------ R18
        # THE GATE MUST SCORE AGAINST THE SAME TRUTH THE CORRECTOR WAS FITTED TO.
        #
        # `df` is the FOULED frame. Once training targets were retargeted to the
        # calibration reference on historical episodes (R18), scoring the gate
        # against `df` on those same rows asked the corrector to reproduce the
        # drifted value it had just been correctly taught to remove -- so its
        # measured "skill" on a drifted validation row was penalised in exact
        # proportion to how well it did its job. Measured effect on the
        # sudden_shift arm: the skill statistic collapsed from 0.59 at I=1 to
        # 0.0002 at I=2-3, every channel was DECLINED, and the arm reported flat
        # zero rescue -- read as "cannot handle step faults" when it meant
        # "was graded against the fault". Full-budget training (400 epochs vs
        # 10) did not move it, which ruled the training budget out.
        #
        # y_tab already carries the retargeting, so it is the consistent truth
        # for the gate; df remains correct wherever no retargeting applied.
        self._r18_resid_diag = (df_residuals.copy(), df_baseline_preds.copy())
        _val_base_cal = df_baseline_preds.loc[val_indices].values[cal_slice]
        # frame, the calibration gate must judge it against that SAME target.
        # Grading a T2 correction against the fouled frame would reward
        # reproducing the degradation and suppress the very correction being
        # trained.  No test row is involved: this is validation only.
        if self.corrector_target_df is not None:
            _gate_truth = self.corrector_target_df
        elif getattr(self, '_r18_retargeted', 0):
            _gate_truth = y_tab
        else:
            _gate_truth = df
        _val_true_cal = _gate_truth.loc[val_indices, target_vars].values[cal_slice]
        gate_mask, gate_diag = correction_gate(
            val_residuals_raw[cal_slice],
            _val_true_cal - _val_base_cal,
            target_vars,
            threshold=self.gate_threshold,
            quantile=getattr(self.config, 'GATE_QUANTILE', 0.90))
        if self.gate_threshold is not None:
            _off = [v for v, d in gate_diag.items() if not d['applied']]
            print(f"    [R9 gate] threshold={self.gate_threshold}: "
                  + ", ".join(f"{v}={gate_diag[v].get('gate', float('nan')):.4f}"
                              f"{'' if gate_diag[v]['applied'] else ' (DECLINED)'}"
                              for v in target_vars))
            if _off:
                print(f"    [R9 gate] declining to correct {_off} -> exact "
                      f"baseline parity (delta == 0) on those targets.")

        # ------------------------------------------------------------- R30
        # ONE-SHOT HARD HEALTH-STATE TOURNAMENT.
        #
        # The matched anchor is the DIFFERENCED-TARGET XGBoost + drift-bank
        # forecaster.  The neural corrector remains the direct bounded residual
        # head.  R30 changes only the row-wise ACT/ANCHOR decision.  It never
        # multiplies correction amplitude and never thresholds |c_raw|.
        #
        # TRAIN: fit three fixed classifier families on synthetic T2 fault
        # labels using only causal target-specific health/drift/jump context.
        # CAL: select the family at a FIXED probability threshold 0.5, prioritising
        # lowest nominal FPR subject to >=50% degraded recall.  No threshold sweep.
        # SAFETY: unchanged R19 independently authorises the exact gated
        # intervention. TEST: never used for fitting or family selection.
        self._r30_diag = []
        self._r30_selected = {}
        self._r30_test_action_rate = {}
        self._r30_val_action_rate = {}
        if bool(getattr(self.config, 'R30_HEALTH_STATE_TOURNAMENT', False)):
            if self.fault_mask is None:
                raise ValueError('[R30] fault labels required for health-state tournament')
            _ctx_names30 = list(getattr(self, '_r17_ctx_cols', []))
            _tridx30 = pd.Index(train_indices[-len(X_train_context):])
            _fmtr30 = (self.fault_mask.reindex(index=_tridx30, columns=target_vars)
                       .fillna(False).astype(bool).values)
            _fmva30 = (self.fault_mask.reindex(index=val_indices, columns=target_vars)
                       .fillna(False).astype(bool).values)
            if self.obs_mask is not None:
                _omtr30 = (self.obs_mask.reindex(index=_tridx30, columns=target_vars)
                           .fillna(False).astype(bool).values)
                _omva30 = (self.obs_mask.reindex(index=val_indices, columns=target_vars)
                           .fillna(False).astype(bool).values)
            else:
                _omtr30 = np.ones_like(_fmtr30, dtype=bool)
                _omva30 = np.ones_like(_fmva30, dtype=bool)
            _thr30 = float(getattr(self.config, 'R30_DECISION_THRESHOLD', 0.50))
            print(f'    [R30] hard health-state tournament; fixed probability threshold={_thr30:.2f}; '
                  'features exclude p_fault and correction magnitude.')
            for _j30, _v30 in enumerate(target_vars):
                _xtr30, _fn30 = build_r30_health_state_features(
                    X_train_context, _ctx_names30, _v30)
                _xva30, _ = build_r30_health_state_features(
                    X_val_context, _ctx_names30, _v30)
                _xte30, _ = build_r30_health_state_features(
                    X_test_context, _ctx_names30, _v30)
                _mods30, _td30 = _r30_fit_models(
                    _xtr30, _fmtr30[:, _j30], _omtr30[:, _j30], self.config,
                    target=_v30)
                if not _mods30:
                    _sel30, _rows30, _why30 = None, [], _td30.get('reason','train fit failed')
                else:
                    _sel30, _rows30, _why30 = _r30_select_candidate(
                        _mods30, _xva30[cal_slice], _fmva30[cal_slice, _j30],
                        _omva30[cal_slice, _j30], self.config, target=_v30)
                for _rr30 in _rows30:
                    _rr30.update(n_features=int(len(_fn30)), selected=bool(_rr30['candidate'] == _sel30),
                                 seed=int(getattr(self.config, '_active_rescue_seed', getattr(self.config,'SEED',42))))
                    self._r30_diag.append(_rr30)
                if _sel30 is None:
                    _gva30 = np.zeros(len(X_val_context), dtype=bool)
                    _gte30 = np.zeros(len(X_test_context), dtype=bool)
                    self._r30_selected[_v30] = 'CLOSED'
                    print(f'    [R30] {_v30}: CLOSED ({_why30})')
                else:
                    _pva30 = _r30_prob(_mods30[_sel30], _xva30)
                    _pte30 = _r30_prob(_mods30[_sel30], _xte30)
                    _gva30 = _pva30 >= _thr30
                    _gte30 = _pte30 >= _thr30
                    self._r30_selected[_v30] = _sel30
                    _sr30 = next(r for r in _rows30 if r['candidate'] == _sel30)
                    print(f"    [R30] {_v30}: {_sel30} SELECTED | CAL recall={_sr30['recall']:.3f}, "
                          f"FPR={_sr30['fpr']:.3f}, bal_acc={_sr30['balanced_accuracy']:.3f}, "
                          f"features={len(_fn30)}")
                # Exact hard switch: nominal state -> literal zero, degraded ->
                # full direct bounded correction. No amplitude attenuation.
                val_residuals_raw[~_gva30, _j30] = 0.0
                predicted_residuals[~_gte30, _j30] = 0.0
                self._r30_val_action_rate[_v30] = float(np.mean(_gva30))
                self._r30_test_action_rate[_v30] = float(np.mean(_gte30))
            print('    [R30] action rate val/test: ' + ', '.join(
                f"{v}={100*self._r30_val_action_rate[v]:.1f}%/{100*self._r30_test_action_rate[v]:.1f}%"
                for v in target_vars))
            try:
                _df30 = pd.DataFrame(self._r30_diag)
                _tag30 = _safe_filename(self.model_name)
                _sd30 = int(getattr(self.config, '_active_rescue_seed', getattr(self.config,'SEED',42)))
                _df30.to_csv(os.path.join(self.config.OUTPUT_DIR,
                    f'r30_health_tournament_{_tag30}_seed{_sd30}.csv'), index=False)
            except Exception as _e30:
                print(f'    [R30] audit write skipped: {_e30}')

        # ---------------------------------------------------------- R21/R20
        # DYNAMIC SELECTIVE-GATE CALIBRATION ON VALIDATION.
        #
        # The neural graph emits p_fault continuously and applies no release
        # probability cutoff (R17_GATE_DEADBAND = 0). R21 optionally refines
        # that detector into a causal state-aware score using a TRAIN-only
        # logistic meta-selector. The operating threshold is then chosen per
        # target on the disjoint calibration block: R20 maximises confidence-
        # bound degraded rescue subject to fixed nominal/overall safety limits
        # when clean T2 truth exists; ordinary runs use validation detection
        # labels and Youden J. No test truth chooses a threshold. If calibration
        # is underpowered, the row gate fails closed.
        #
        # `_r18_deadband` is retained as the historical attribute name because
        # study/replay code reads it; its value is now the calibrated OPERATING
        # THRESHOLD on the active selector score, not a graph-level hard floor.
        self._r18_deadband = {}
        self._r26_policy_val = None
        _val_p = None  # retained for the validation safety veto below
        if (bool(getattr(self.config, 'R17_ENABLE', False))
                and bool(getattr(self.config, 'R18_CALIBRATE_DEADBAND', False))
                and self.last_fault_prob is not None
                and self.fault_mask is not None):
            _val_p = self.last_val_fault_prob
            _val_score = (self._r21_selector_val_score
                          if getattr(self, '_r21_selector_val_score', None) is not None
                          else _val_p)
            _test_score = (self.last_selector_score
                           if getattr(self, 'last_selector_score', None) is not None
                           else self.last_fault_prob)
            if _val_p is not None and _val_score is not None:
                if self.authorization_mask is not None:
                    _vf = (self.authorization_mask.reindex(index=val_indices,
                                                           columns=target_vars)
                           .fillna(False).astype(bool).values)
                else:
                    _vf = np.zeros_like(_val_p, dtype=bool)
                if self.obs_mask is not None:
                    _vo = (self.obs_mask.reindex(index=val_indices,
                                                 columns=target_vars)
                           .fillna(False).astype(bool).values)
                else:
                    _vo = np.ones_like(_vf, dtype=bool)
                _min_pos = int(getattr(self.config, 'R18_DEADBAND_MIN_POS', 8))
                _msgs = []
                self._r20_gate_diag = {}
                _utility_mode = (bool(getattr(self.config, 'R20_UTILITY_GATE', False))
                                 and self.corrector_target_df is not None)
                for _j, _v in enumerate(target_vars):
                    _pos = _vf[:, _j]
                    _p = _val_p[:, _j]
                    _score = _val_score[:, _j]
                    if _utility_mode:
                        _cc = np.asarray(val_residuals_raw[cal_slice, _j], dtype=float)
                        if bound is not None:
                            _cc = np.clip(_cc, -float(np.asarray(bound)[_j]),
                                          float(np.asarray(bound)[_j]))
                        _benefit_mode20 = bool(
                            getattr(self.config, 'BENEFIT_AWARE_SELECTOR', False))
                        # CAL chooses a point-estimate utility threshold.
                        # remain unchanged.
                        _cal_fun20 = calibrate_point_utility_gate_threshold
                        _ud = _cal_fun20(
                            _score[cal_slice], _cc,
                            _val_base_cal[:, _j], _val_true_cal[:, _j],
                            _pos[cal_slice], self.config,
                            observed=_vo[cal_slice, _j])
                        _ud = dict(_ud)
                        _ud['selection_mode'] = 'point_CAL_then_independent_R19'
                        self._r20_gate_diag[_v] = _ud
                        self._r18_deadband[_v] = float(_ud['threshold'])
                        _msgs.append(
                            f"{_v}={float(_ud['threshold']):.3f} "
                            f"({_ud.get('selection_mode','R20')}; "
                            f"rescue={_ud.get('degraded_rescue_rel', np.nan):+.3f}, "
                            f"nom={_ud.get('nominal_penalty_rel', np.nan):+.3f}, "
                            f"nD={_ud.get('n_degraded', 0)}, "
                            f"{'OK' if _ud.get('feasible') else 'FAIL-CLOSED'})")
                        continue
                    # Ordinary (non-T2) detection calibration must use only the
                    # calibration block.  Using all validation rows here would
                    # let the later safety block help choose its own threshold.
                    _eligible = (_vo[cal_slice, _j]
                                 & np.isfinite(_score[cal_slice]))
                    _p_cal = _score[cal_slice]
                    _pos_cal = _pos[cal_slice] & _eligible
                    _neg_cal = (~_pos[cal_slice]) & _eligible
                    _npos = int(_pos_cal.sum())
                    _nneg = int(_neg_cal.sum())
                    if _npos < _min_pos or _nneg < _min_pos:
                        # No evidence to choose an operating point -> do not
                        # silently open the gate.  1.000001 is an unreachable
                        # score sentinel, i.e. exact fail-closed passthrough.
                        self._r18_deadband[_v] = 1.000001
                        _msgs.append(f"{_v}=CLOSED "
                                     f"(underpowered calibration pos/neg="
                                     f"{_npos}/{_nneg})")
                        continue
                    _best_j, _best_t = -np.inf, float(
                        getattr(self.config, 'R17_GATE_DEADBAND', 0.0))
                    for _t in np.unique(np.round(_p_cal[_eligible], 4)):
                        _tpr = float((_p_cal[_pos_cal] >= _t).mean())
                        _fpr = float((_p_cal[_neg_cal] >= _t).mean())
                        if _tpr - _fpr > _best_j:
                            _best_j, _best_t = _tpr - _fpr, float(_t)
                    self._r18_deadband[_v] = _best_t
                    _msgs.append(f"{_v}={_best_t:.3f} (J={_best_j:.3f}, "
                                 f"calibration pos/neg={_npos}/{_nneg})")
                print("    [R21/R20] dynamic operating gate calibrated on validation: "
                      + ", ".join(_msgs))
                try:
                    _r21_out = {}
                    for _v in target_vars:
                        _r21_out[_v] = dict(
                            getattr(self, '_r21_selector_diag', {}).get(_v, {}))
                        _r21_out[_v]['operating_threshold'] = float(
                            self._r18_deadband.get(_v, np.nan))
                        if _v in getattr(self, '_r20_gate_diag', {}):
                            _r21_out[_v]['utility_calibration'] = dict(
                                self._r20_gate_diag[_v])
                    _r21_path = os.path.join(
                        self.config.OUTPUT_DIR,
                        f"dynamic_selector_{_safe_filename(getattr(self.config, '_dataset_name', 'dataset'))}__{_safe_filename(self.model_name)}.json")
                    with open(_r21_path, 'w') as _fh:
                        json.dump(_r21_out, _fh, indent=2, default=lambda x: float(x) if np.isscalar(x) else str(x))
                    print(f"    [R21] selector audit -> {os.path.basename(_r21_path)}")
                    if bool(getattr(self.config, 'BENEFIT_AWARE_SELECTOR', False)):
                        _br = []
                        for _tv, _dd in self._r21_selector_diag.items():
                            _br.append(dict(
                                target=_tv,
                                objective=_dd.get('selector_objective', ''),
                                fitted=bool(_dd.get('fitted', False)),
                                n_train=_dd.get('n_train', np.nan),
                                n_pos=_dd.get('n_pos', np.nan),
                                n_neg=_dd.get('n_neg', np.nan),
                                n_action_train=_dd.get('n_action_train', np.nan),
                                helpful_rate=_dd.get('helpful_rate', np.nan),
                                mean_gain=_dd.get('mean_gain', np.nan),
                                mean_harm=_dd.get('mean_harm', np.nan),
                                reason=_dd.get('reason', '')))
                        pd.DataFrame(_br).to_csv(
                            os.path.join(
                                self.config.OUTPUT_DIR,
                                f"benefit_selector_train_{_safe_filename(getattr(self.config, '_dataset_name', 'dataset'))}__{_safe_filename(self.model_name)}.csv"),
                            index=False)
                except Exception as _r21e:
                    print(f"    [R21] selector audit write skipped: {_r21e}")
                # Apply the validation-selected operating point to the
                # TEST selector score.  With R21 this is a target-specific,
                # state-aware score, not a universal p_fault cutoff.  The graph
                # deadband remains zero in the release configuration, so no
                # irreversible threshold precedes this calibration.
                _raw_deadband = float(getattr(self.config,
                                              'R17_GATE_DEADBAND', 0.0))
                _dynamic_on = bool(getattr(self.config, 'R21_DYNAMIC_SELECTOR', False))
                for _j, _v in enumerate(target_vars):
                    _t = float(self._r18_deadband.get(_v, _raw_deadband))
                    if _dynamic_on and _test_score is not None:
                        _kill = _test_score[:, _j] < _t
                    elif _t > _raw_deadband:
                        _kill = self.last_fault_prob[:, _j] < (
                            (_t - _raw_deadband) / max(1.0 - _raw_deadband, 1e-9))
                    else:
                        _kill = np.zeros(len(predicted_residuals), dtype=bool)
                    predicted_residuals[_kill, _j] = 0.0
                self._r18_deadband_floor = _raw_deadband

                # ------------------------------------------------------ R26
                # Persist ONLY validation-side arrays needed to replay alternative
                # post-hoc policies from this SAME fitted model.  CAL selects an
                # operating threshold; SAFETY independently authorizes it.  No
                # test quantity enters either decision.
                try:
                    _vc26 = np.asarray(val_residuals_raw, dtype=float).copy()
                    if bound is not None:
                        _bd26 = np.asarray(bound, dtype=float).reshape(1, -1)
                        _vc26 = np.clip(_vc26, -_bd26, _bd26)
                    if not gate_mask.all():
                        _vc26[:, ~np.asarray(gate_mask, dtype=bool)] = 0.0
                    self._r26_policy_val = dict(
                        base=np.asarray(df_baseline_preds.loc[val_indices].values, dtype=float),
                        truth=np.asarray(_gate_truth.loc[val_indices, target_vars].values, dtype=float),
                        degraded=np.asarray(_vf, dtype=bool),
                        observed=np.asarray(_vo, dtype=bool),
                        corr_graph=np.asarray(_vc26, dtype=float),
                        p_fault=np.asarray(_val_p, dtype=float),
                        r21_score=np.asarray(_val_score, dtype=float),
                        n_cal=int(n_cal), n_safe=int(n_safe), n_val=int(n_val),
                        gate_mask=np.asarray(gate_mask, dtype=bool),
                        internal_threshold=np.asarray(
                            [float(self._r18_deadband.get(v, 1.000001))
                             for v in target_vars], dtype=float))
                except Exception as _e26:
                    print(f'    [R26] validation policy harvest failed: {_e26!r}')
                    self._r26_policy_val = None

        per_target_hit = None
        if bound is not None:
            hit = np.abs(predicted_residuals) > bound
            clip_hit_rate = float(hit.mean())
            per_target_hit = hit.mean(axis=0)
            predicted_residuals = np.clip(predicted_residuals, -bound, bound)
            tag = (f"conformal a={self.conformal_alpha}"
                   if self.conformal_alpha is not None else f"clip_k={self.clip_k}")
            print(f"    [bound] {tag}: binds on {100 * clip_hit_rate:.2f}% of "
                  f"(point, target) pairs. Per-target: "
                  + ", ".join(f"{v}={100 * r:.1f}%"
                              for v, r in zip(target_vars, per_target_hit)))
            if self.conformal_alpha is not None:
                # The whole point of the change: realised rate should track
                # nominal alpha. A large gap is a drift signal, not a bug -- the
                # calibration and test distributions differ (Barber et al. 2023),
                # and reporting the gap is the honest treatment.
                print(f"    [bound] nominal alpha={self.conformal_alpha:.3f} vs "
                      f"realised {clip_hit_rate:.3f} "
                      f"(gap {clip_hit_rate - self.conformal_alpha:+.3f})")
        else:
            clip_hit_rate = float('nan')
            per_target_hit = np.full(len(target_vars), np.nan)

        # -------------------------------------------------------------- R26
        # Exact test correction after R20/R21 operating threshold and bound,
        # but BEFORE the target-wise R19 safety veto.  This isolates whether
        # zero action is caused before or by R19.
        self._r26_test_corr_post_selector = np.asarray(
            predicted_residuals, dtype=float).copy()

        # ------------------------------------------------------------------ R19-S
        # FINAL VALIDATION SAFETY VETO (fail closed, target by target).
        #
        # The pointwise detector answers "does this look degraded?"; it does
        # not answer "is THIS learned correction beneficial?".  Local T2
        # replication found a catastrophic case where p_fault saturated at 1
        # while the correction had the wrong sign.  Scalar shrinkage and
        
        #
        # This second-line veto therefore uses ONLY the held-out SAFETY block
        # of validation and asks whether the already-fitted correction earned the
        # right to act for each target.  No parameter is fitted on test data.
        # A failed/underpowered target is set to exact anchor parity.
        self._r19_safety_mask = np.ones(len(target_vars), dtype=bool)
        self._r19_safety_diag = {}
        if bool(getattr(self.config, 'R19_SAFETY_VETO', False)):
            _vsc = np.asarray(val_residuals_raw, dtype=float).copy()
            if bound is not None:
                _vsc = np.clip(_vsc, -bound, bound)
            if not gate_mask.all():
                _vsc[:, ~gate_mask] = 0.0

            # Replay any validation-calibrated post-hoc deadband on validation
            # itself, so the safety decision evaluates the same intervention
            # rule that will be applied at test time.
            if _val_p is not None and self._r18_deadband:
                _raw_db = float(getattr(self.config, 'R17_GATE_DEADBAND', 0.0))
                _dynamic_on = bool(getattr(self.config, 'R21_DYNAMIC_SELECTOR', False))
                for _j, _v in enumerate(target_vars):
                    _t = float(self._r18_deadband.get(_v, _raw_db))
                    if _dynamic_on and _val_score is not None:
                        _vsc[_val_score[:, _j] < _t, _j] = 0.0
                    elif _t > _raw_db:
                        _thr = (_t - _raw_db) / max(1.0 - _raw_db, 1e-9)
                        _vsc[_val_p[:, _j] < _thr, _j] = 0.0

            _truth_src_s = self.eval_truth_df
            if _truth_src_s is None:
                _truth_src_s = getattr(self.config, '_eval_truth', None)
            if _truth_src_s is None:
                _truth_src_s = df
            _vb_s = df_baseline_preds.loc[val_indices].values
            _vt_s = _truth_src_s.reindex(val_indices)[target_vars].values
            if self.authorization_mask is not None:
                _vf_s = (self.authorization_mask.reindex(index=val_indices, columns=target_vars)
                         .fillna(False).values.astype(bool))
            else:
                _vf_s = np.zeros_like(_vsc, dtype=bool)
            if self.obs_mask is not None:
                _vo_s = (self.obs_mask.reindex(index=val_indices, columns=target_vars)
                         .fillna(False).values.astype(bool))
            else:
                _vo_s = np.ones_like(_vsc, dtype=bool)

            _min_deg = int(getattr(self.config, 'R19_SAFETY_MIN_DEGRADED', 8))
            _min_nom = int(getattr(self.config, 'R19_SAFETY_MIN_NOMINAL', 8))
            _min_units = int(getattr(
                self.config, 'R19_SAFETY_MIN_EVIDENCE_UNITS', 2))
            _min_rescue = float(getattr(self.config, 'R19_SAFETY_MIN_RESCUE', 0.0))
            _max_nom_rel = float(getattr(
                self.config, 'R19_SAFETY_MAX_NOMINAL_PENALTY_REL', 0.05))
            _max_mult = float(getattr(self.config, 'R19_SAFETY_MAX_MAE_MULTIPLIER', 1.10))
            _req_use = bool(getattr(
                self.config, 'R19_SAFETY_REQUIRE_USEFUL_GT_HARMFUL', True))

            for _j, _v in enumerate(target_vars):
                _b = _vb_s[safety_slice, _j]
                _c = _vsc[safety_slice, _j]
                _t = _vt_s[safety_slice, _j]
                _d = _vf_s[safety_slice, _j]
                _o = _vo_s[safety_slice, _j]
                _pre = np.abs(_t - _b)
                _post = np.abs(_t - (_b + _c))
                _fin = np.isfinite(_pre) & np.isfinite(_post) & _o
                _deg = _fin & _d
                _nom = _fin & ~_d
                _act = _fin & (np.abs(_c) > 1e-12)
                _ev = _safety_evidence(
                    np.where(_fin, _pre, np.nan),
                    np.where(_fin, _post, np.nan),
                    _d & _fin, self.config)
                _n_deg = int(_ev['n_degraded'])
                _n_nom = int(_ev['n_nominal'])
                _rescue = _ev['rescue']
                _rescue_lcb = _ev['rescue_lcb']
                _nom_pen = _ev['nominal_harm']
                _nom_pen_rel = _ev['nominal_penalty_rel']
                _nom_pen_ucb_rel = _ev['nominal_penalty_ucb_rel']
                _mult = _ev['mae_multiplier']
                _mult_ucb = _ev['mae_multiplier_ucb']
                _n_act = int(_act.sum())
                _use = (float((_post[_act] < _pre[_act]).mean())
                        if _n_act else np.nan)
                _harm = (float((_post[_act] > _pre[_act]).mean())
                         if _n_act else np.nan)

                _r34 = bool(getattr(self.config, 'R34_CHALLENGED_ONLY', False))
                _global_qualified = False
                _local_nominal_safe = False
                _local_degraded_supported = False
                _reasons = []

                if _r34:
                    _qmap34 = getattr(
                        self.config, 'R34_OFFLINE_QUALIFICATION_BY_TARGET', {}) or {}
                    _global_qualified = bool(_qmap34.get(str(_v), False))
                    _local_nominal_safe = bool(
                        _n_nom >= _min_nom
                        and _ev['n_nominal_units'] >= _min_units
                        and np.isfinite(_nom_pen_ucb_rel)
                        and _nom_pen_ucb_rel <= _max_nom_rel
                        and np.isfinite(_mult_ucb)
                        and _mult_ucb <= _max_mult)
                    _local_degraded_supported = bool(
                        _n_deg >= _min_deg
                        and _ev['n_degraded_units'] >= _min_units
                        and np.isfinite(_rescue_lcb)
                        and _rescue_lcb > _min_rescue)

                    if not _global_qualified:
                        _reasons.append('target lacks frozen R32 offline qualification')
                    if _n_nom < _min_nom:
                        _reasons.append(f'underpowered nominal validation ({_n_nom}<{_min_nom})')
                    if _ev['n_nominal_units'] < _min_units:
                        _reasons.append(
                            f"only {_ev['n_nominal_units']} nominal time block(s) "
                            f"< {_min_units}")
                    if not (np.isfinite(_nom_pen_ucb_rel)
                            and _nom_pen_ucb_rel <= _max_nom_rel):
                        _reasons.append(
                            f'nominal-harm UCB {_nom_pen_ucb_rel} > {_max_nom_rel:.3f}')
                    if not (np.isfinite(_mult_ucb) and _mult_ucb <= _max_mult):
                        _reasons.append(
                            f'MAE-multiplier UCB {_mult_ucb} > {_max_mult:.3f}')
                    if not bool(gate_mask[_j]):
                        _reasons.append('upstream target gate declined')
                else:
                    if _n_deg < _min_deg:
                        _reasons.append(f'underpowered degraded validation ({_n_deg}<{_min_deg})')
                    if _n_nom < _min_nom:
                        _reasons.append(f'underpowered nominal validation ({_n_nom}<{_min_nom})')
                    if _ev['n_degraded_units'] < _min_units:
                        _reasons.append(
                            f"only {_ev['n_degraded_units']} independent degradation "
                            f"episode(s) < {_min_units}")
                    if _ev['n_nominal_units'] < _min_units:
                        _reasons.append(
                            f"only {_ev['n_nominal_units']} nominal time block(s) "
                            f"< {_min_units}")
                    if not (np.isfinite(_rescue_lcb) and _rescue_lcb > _min_rescue):
                        _reasons.append(f'rescue lower bound not positive ({_rescue_lcb})')
                    if not (np.isfinite(_nom_pen_ucb_rel)
                            and _nom_pen_ucb_rel <= _max_nom_rel):
                        _reasons.append(
                            f'nominal-harm UCB {_nom_pen_ucb_rel} > {_max_nom_rel:.3f}')
                    if not (np.isfinite(_mult_ucb) and _mult_ucb <= _max_mult):
                        _reasons.append(
                            f'MAE-multiplier UCB {_mult_ucb} > {_max_mult:.3f}')
                    if _req_use and _n_act and np.isfinite(_use) and np.isfinite(_harm) and not (_use > _harm):
                        _reasons.append(f'useful {_use:.3f} <= harmful {_harm:.3f}')
                    if not bool(gate_mask[_j]):
                        _reasons.append('upstream target gate declined')

                _pass = (len(_reasons) == 0)
                self._r19_safety_mask[_j] = _pass
                self._r19_safety_diag[_v] = dict(
                    passed=bool(_pass),
                    offline_qualified=bool(_global_qualified) if _r34 else np.nan,
                    local_nominal_safe=bool(_local_nominal_safe) if _r34 else np.nan,
                    local_degraded_supported=(bool(_local_degraded_supported)
                                              if _r34 else np.nan),
                    n_degraded=_n_deg, n_nominal=_n_nom,
                    n_degraded_units=_ev['n_degraded_units'],
                    n_nominal_units=_ev['n_nominal_units'],
                    degraded_rescue=_rescue, degraded_rescue_lcb=_rescue_lcb,
                    nominal_penalty=_nom_pen,
                    nominal_penalty_rel=_nom_pen_rel,
                    nominal_penalty_ucb_rel=_nom_pen_ucb_rel,
                    mae_multiplier=_mult, mae_multiplier_ucb=_mult_ucb,
                    useful_rate=_use, harmful_rate=_harm, n_acted=_n_act,
                    reason='; '.join(_reasons))
                _tag34 = '[R34-S]' if _r34 else '[R19-S]'
                print(f"    {_tag34} {_v}: {'PASS' if _pass else 'VETO'} | "
                      + (f"Q={int(_global_qualified)}, Snom={int(_local_nominal_safe)}, "
                         f"Sdeg={int(_local_degraded_supported)} | " if _r34 else '')
                      + f"n_deg={_n_deg}/{_ev['n_degraded_units']}ep, "
                      f"n_nom={_n_nom}/{_ev['n_nominal_units']}blk, "
                      f"rescue={_rescue}, rescueLCB={_rescue_lcb}, "
                      f"nomUCB={_nom_pen_ucb_rel}, multUCB={_mult_ucb}, "
                      f"useful={_use}, harmful={_harm}"
                      + (f" | {self._r19_safety_diag[_v]['reason']}" if _reasons else ''))

            # Safety veto is stricter than the upstream column gate.
            gate_mask = np.asarray(gate_mask, dtype=bool) & self._r19_safety_mask

        # the original gate and the validation safety veto. Done AFTER the bound
        # so the reported bind rate describes the fitted corrector, and before
        # final prediction so fail-closed parity is exact.
        if not gate_mask.all():
            predicted_residuals[:, ~gate_mask] = 0.0

        baseline_test_pred = df_baseline_preds.loc[test_indices].values

        final_prediction = baseline_test_pred + predicted_residuals

        # post-hoc DQA/action audit. This does not alter inference or metrics.
        self.last_test_indices = pd.Index(test_indices).copy()
        self.last_target_vars = list(target_vars)
        self.last_anchor_prediction = np.asarray(baseline_test_pred, dtype=float).copy()
        self.last_final_prediction = np.asarray(final_prediction, dtype=float).copy()
        try:
            self.last_recorded_test = df.loc[test_indices, target_vars].apply(
                pd.to_numeric, errors='coerce').values.astype(float)
        except Exception:
            self.last_recorded_test = np.full_like(self.last_final_prediction, np.nan, dtype=float)


        # ------------------------------------------------------------------
        # one. The sensor fouls; the water does not change.
        # ------------------------------------------------------------------
        
        # else the per-testbed shared frame, else the local split.
        _truth = self.eval_truth_df
        if _truth is None:
            _truth = getattr(self.config, '_eval_truth', None)
        if _truth is not None:
            y_true_final = _truth.loc[test_indices, target_vars].values
        else:
            y_true_final = y_test_tab.values

        # reference. It is what a station operator reads off the instrument
        # before any model touches it, so MAE against it is the TOTAL drift the
        # pipeline has to remove. Needed to report how much of that removal is
        # the anchor's and how much is the corrector's. `df` is the fouled frame
        # by construction; y_tab is NOT usable here because R18 retargeting may
        # have replaced its history rows with calibration-reference values.
        fouled_test_obs = None
        try:
            fouled_test_obs = df.loc[test_indices, target_vars].values
        except Exception:
            fouled_test_obs = None

        obs_test = None
        fault_test = None
        rescue_test = None
        if self.fault_mask is not None:
            fault_test = self.fault_mask.reindex(test_indices).fillna(False)
        if self.rescue_mask is not None:
            rescue_test = self.rescue_mask.reindex(test_indices).fillna(False)
        if self.obs_mask is not None:
            obs_test = self.obs_mask.reindex(test_indices).fillna(False)

        # Persist the exact reported ingredients for every Stage-1 C candidate.
        # Manuscript plots must load this bundle; they must never retrain a
        # different hybrid/level-target model after the benchmark has finished.
        if re.fullmatch(r'M2P-PTAC \(C=[0-9.eE+-]+\)', str(self.model_name)):
            _bundle_path = os.path.join(
                self.config.OUTPUT_DIR,
                f"prediction_bundle_{getattr(self.config, '_dataset_name', 'unknown')}"
                f"__{_safe_filename(self.model_name)}.npz")
            np.savez_compressed(
                _bundle_path,
                timestamp_ns=pd.to_datetime(test_indices).asi8.astype('int64'),
                target_names=np.asarray([str(v) for v in target_vars], dtype='U'),
                y_true=np.asarray(y_true_final, dtype='float64'),
                anchor=np.asarray(baseline_test_pred, dtype='float64'),
                correction=np.asarray(predicted_residuals, dtype='float64'),
                final=np.asarray(final_prediction, dtype='float64'),
                source_retained=(np.asarray(
                    obs_test.reindex(columns=target_vars).fillna(False),
                    dtype=bool)
                                 if obs_test is not None
                                 else np.ones_like(y_true_final, dtype=bool)))
            print(f"    [PREDICTION-BUNDLE] wrote "
                  f"{os.path.basename(_bundle_path)} ({len(test_indices)} rows).")


        # ------------------------------------------------------------------
        # structure can be inspected. A correction whose max is identical
        # across drift intensities is either row-constant (a learned bias,
        # input-independent) or insensitive to the injected drift; the two
        # have different fixes, and the per-row spread distinguishes them.
        self._r17_delta = np.array(predicted_residuals, dtype=float, copy=True)

        #
        #     R = 1 - MAE(corrected | drift rows) / MAE(anchor | drift rows)
        #
        # The denominator is THE SAME RUN'S OWN uncorrected anchor, so the
        # delta-target reformulation gain (measured 33.7-96.8% across cells)
        # cancels exactly. This is the only formulation that isolates the
        # neural contribution; a rescue number computed against any other
        # baseline is measuring the reformulation, not the corrector.
        #
        # Placed HERE, after the R4 truth precedence has resolved
        # y_true_final, because in a drift arm the rescue must be measured
        # against the PRISTINE signal -- measuring it against the fouled
        # observation would reward the corrector for reproducing the injected
        
        #
        # Cells with no drift-labelled test rows report NaN, never 0.0. Six of
        # sixteen channel-slots have zero test-window faults, and calling that
        # "0% rescue" would convert an absence of evidence into a measured null.
        # ------------------------------------------------------------------
        self._r17_rescue = None
        if bool(getattr(self.config, 'R17_ENABLE', False)):
            _rows = []
            for _i_v, _v in enumerate(target_vars):
                _rescue_source = (rescue_test if rescue_test is not None
                                  else fault_test)
                _dm = (_rescue_source[_v].values.astype(bool)
                       if (_rescue_source is not None
                           and _v in _rescue_source.columns)
                       else np.zeros(len(test_indices), dtype=bool))
                if obs_test is not None and _v in obs_test.columns:
                    _dm &= obs_test[_v].values.astype(bool)
                _r = rescue_ratio(y_true_final[:, _i_v],
                                  baseline_test_pred[:, _i_v],
                                  final_prediction[:, _i_v], _dm)
                # Distinguish ABSTENTION from HARM. A target the R9 gate
                # declined, or one the deadband suppressed, carries delta == 0
                # identically, so R is exactly 0.0 -- the corrector did nothing
                # and neither helped nor hurt. Filing that under HARM would
                # overstate the failure exactly as filing it under 'rescue'
                # would overstate the success; both are wrong and the
                # distinction is decidable from the correction itself.
                _applied = float(np.abs(predicted_residuals[_dm, _i_v]).max()) \
                    if _dm.any() else 0.0

                # ---------------------------------------------------------- R18
                # ANCHOR STRENGTH -- without it R is uninterpretable.
                #
                # R is normalised by the anchor's own error, so a SMALL R can
                # mean either "the corrector adds little" or "the anchor left
                # almost nothing to add". On this station's EC at sudden_shift
                # I=2 the second is what happens, and by a wide margin:
                #
                #   injected offset on the test episode      365.57 uS/cm
                #   MAE of the raw degraded observation      365.57
                #   MAE of the retargeted tree anchor         14.60
                #
                # The anchor removes 96% of the drift BY ITSELF on an episode
                # it never saw. That is a consequence of the R18 calibration-
                # reference retargeting: the tree is fitted on degraded inputs
                # against clean targets, so it learns the correction map too --
                # and it generalises. The corrector is therefore competing for
                # the last 4%, not for the drift. Reporting R alone would read
                # as a weak corrector; reporting it with the anchor's own drift
                
                # the honest one. Both go in the curve so no reader can quote
                # one without the other.
                _resid_frac = float('nan')
                _anchor_removal = float('nan')
                _total_removal = float('nan')
                _drift_snr = float('nan')
                _identifiable = False
                if _dm.any():
                    _yt = y_true_final[_dm, _i_v]
                    _ya = baseline_test_pred[_dm, _i_v]
                    _yo = (fouled_test_obs[_dm, _i_v]
                           if fouled_test_obs is not None else np.full_like(_yt, np.nan))
                    _total_removal = float('nan')
                    _mae_a = float(np.nanmean(np.abs(_yt - _ya)))
                    _mae_o = float(np.nanmean(np.abs(_yt - _yo)))
                    # ---------------------------------------------------- R18
                    # IDENTIFIABILITY GUARD ON THE REMOVAL FRACTIONS.
                    #
                    # Both removal fractions divide by MAE_obs, the deviation
                    # the injected degradation puts on the reading. When the
                    # drift is SMALLER than the model's own forecast error, that
                    # denominator is below the error floor and the fraction
                    # stops being a measurement of removal: it reports the ratio
                    # of a fixed forecast error to a shrinking drift, and goes
                    # large and negative. Measured on this station's DO channel
                    # under gradual_bias, where the ramp reaches only 0.28 sigma:
                    #
                    #   I      MAE_a/MAE_o   (MAE_a/MAE_o) * I
                    #   0.05      5.099            0.2550
                    #   0.10      2.798            0.2798
                    #   0.15      2.079            0.3119
                    #   0.20      1.524            0.3048
                    #
                    # The product is constant to 7.8% CV: MAE_a does not depend
                    # on the drift at all and MAE_o scales with I. The -188%
                    # "anchor removal" previously printed for that channel was
                    # this artefact, not a harmful anchor. Below the floor the
                    # fractions are left NaN and the drift's size relative to
                    # the floor is reported instead, so the channel is marked
                    # not-identifiable rather than given a fabricated number.
                    # The error floor is a property of the MODEL, not of the
                    # test window, and it must be estimated on rows with no
                    # drift. Clean TEST rows cannot supply it: the gradual_bias
                    # ramp covers the entire test window (98 of 108 rows drifted,
                    # and the remainder are the un-featurisable head), so
                    # `(~_dm).any()` was False on that arm and every removal
                    # fraction came back NaN -- including EC, whose 22% anchor
                    # removal is real and identifiable. The un-faulted VALIDATION
                    # rows are the correct estimator: same model, same fitted
                    # state, drift-free by construction, and already in scope.
                    _mae_floor = float('nan')
                    try:
                        _vi = y_tab.index.intersection(val_indices)
                        if self.authorization_mask is not None:
                            _vfm = (self.authorization_mask.reindex(index=_vi)
                                    .reindex(columns=[_v]).iloc[:, 0]
                                    .fillna(False).astype(bool).values)
                            _vi = _vi[~_vfm]
                        _bcol = (_v + '_pred' if _v + '_pred'
                                 in df_baseline_preds.columns else _v)
                        _fl_t = y_tab.loc[_vi, _v].values.astype(float)
                        _fl_a = df_baseline_preds.loc[_vi, _bcol].values.astype(float)
                        _fl_ok = np.isfinite(_fl_t) & np.isfinite(_fl_a)
                        if int(_fl_ok.sum()) >= 20:
                            _mae_floor = float(np.mean(np.abs(
                                _fl_t[_fl_ok] - _fl_a[_fl_ok])))
                    except Exception:
                        _mae_floor = float('nan')
                    if not np.isfinite(_mae_floor) and (~_dm).any():
                        # fallback: clean test rows, when the arm leaves any
                        _fl_t = y_true_final[~_dm, _i_v]
                        _fl_a = baseline_test_pred[~_dm, _i_v]
                        _fl_ok = np.isfinite(_fl_t) & np.isfinite(_fl_a)
                        if _fl_ok.any():
                            _mae_floor = float(np.mean(np.abs(
                                _fl_t[_fl_ok] - _fl_a[_fl_ok])))
                    _drift_snr = (_mae_o / _mae_floor
                                  if (np.isfinite(_mae_o) and np.isfinite(_mae_floor)
                                      and _mae_floor > 1e-12) else float('nan'))
                    _identifiable = bool(np.isfinite(_drift_snr) and _drift_snr >= 1.0)
                    if (np.isfinite(_mae_o) and _mae_o > 1e-12) and _identifiable:
                        _anchor_removal = 1.0 - _mae_a / _mae_o
                        _resid_frac = _mae_a / _mae_o
                        # corrected forecast. This is the only figure that
                        # answers the deployment question ("how much of the
                        # injected degradation does the deployed pipeline remove?").
                        # R answers a narrower one -- the corrector's share of
                        # whatever the anchor left -- and the two diverge by an
                        # order of magnitude on this data:
                        #   sudden_shift I=2 EC: A=96.0%, R=-1.0%, total=96.0%
                        #   gradual_bias I=0.2 EC: A=24.2%, R=+20.7%, total=39.9%
                        # Quoting R alone understates the step case; quoting
                        # total alone would credit the corrector with the
                        # anchor's work. Both are reported, neither is optional.
                        _mae_c = float(np.nanmean(np.abs(
                            _yt - final_prediction[_dm, _i_v])))
                        _total_removal = 1.0 - _mae_c / _mae_o
                if not np.isfinite(_r):
                    _st = 'unavailable -- no test-window positives'
                elif _applied <= 0.0:
                    _st = 'abstained -- no correction applied'
                elif _r > 0:
                    _st = 'rescue'
                else:
                    _st = 'HARM'
                _rows.append(dict(
                    dataset=getattr(self.config, '_dataset_name', 'unknown'),
                    model=self.model_name, target=_v,
                    n_drift_rows=int(_dm.sum()),
                    max_abs_correction=_applied, rescue_ratio=_r,
                    rescue_pct=(100.0 * _r) if np.isfinite(_r) else np.nan,
                    anchor_drift_removal=_anchor_removal,
                    anchor_residual_fraction=_resid_frac,
                    total_drift_removal=_total_removal,
                    drift_snr=_drift_snr,
                    removal_identifiable=_identifiable,
                    status=_st))
            self._r17_rescue = pd.DataFrame(_rows)
            self._r17_rescue.to_csv(os.path.join(
                self.config.OUTPUT_DIR,
                f"r17_rescue_{_safe_name(self.model_name)}.csv"), index=False)
            _ev = self._r17_rescue.dropna(subset=['rescue_ratio'])
            if len(_ev):
                print("    [R17 rescue] "
                      + ", ".join(f"{r.target}={r.rescue_pct:+.1f}%"
                                  for r in _ev.itertuples())
                      + f"  ({len(self._r17_rescue) - len(_ev)} unavailable)")
                
                # anchor, and on this data it is the latter.
                _an = _ev.dropna(subset=['anchor_drift_removal'])
                if len(_an):
                    print("    [R18 anchor] drift already removed by the "
                          "uncorrected anchor: "
                          + ", ".join(f"{r.target}={100.0 * r.anchor_drift_removal:.1f}%"
                                      for r in _an.itertuples())
                          + "  -- R is the corrector's share of what REMAINS")
                _tt = _ev.dropna(subset=['total_drift_removal'])
                if len(_tt):
                    print("    [R18 end-to-end] fouled observation -> corrected "
                          "forecast, total drift removed: "
                          + ", ".join(f"{r.target}={100.0 * r.total_drift_removal:.1f}%"
                                      for r in _tt.itertuples()))
                _harm = _ev[(_ev.rescue_ratio < 0) & (_ev.max_abs_correction > 0)]
                _abst = _ev[_ev.max_abs_correction <= 0]
                if len(_abst):
                    print(f"    [R17 rescue] {len(_abst)} target(s) ABSTAINED "
                          "(gate declined or deadband suppressed -> delta == 0 "
                          "exactly, R = 0 by construction, not a measurement "
                          "of the corrector): "
                          + ", ".join(str(r.target) for r in _abst.itertuples()))
                if len(_harm):
                    # Reported, not suppressed. A corrector that HARMS on
                    # faulted rows is the failure this redesign exists to
                    # detect, and folding it into an aggregate is how a
                    # negative result becomes a positive one.
                    print(f"    [R17 rescue] WARNING: corrector HARMS on "
                          f"{len(_harm)} of {len(_ev)} evaluable targets: "
                          + ", ".join(f"{r.target}={r.rescue_pct:+.1f}%"
                                      for r in _harm.itertuples()))
            else:
                print("    [R17 rescue] unavailable on every target -- no "
                      "drift-labelled rows in the test window. Reported as "
                      "NaN, not as zero.")

        # C1: keep a handle so profile_deployment_cost() can measure this model
        # without retraining it.
        self._last_keras_model = model
        if "PTAC" in self.model_name:
            
            # the LightGBM array carried nothing at all), so each of the four
            # testbeds overwrote the previous one's arrays and the paradox figure
            # was drawn from whichever testbed happened to run last, whatever its
            # title said. Four figures were produced from one testbed's data.
            _ds = getattr(self.config, '_dataset_name', 'unknown')
            # F11: Keras 3 emits "WARNING:absl:You are saving your model as an
            # HDF5 file ... This file format is considered legacy" on EVERY
            # save. The last run produced 232 of them, which is the single
            # largest source of log noise and buries the substantive warnings
            # the harness prints. Write the native .keras format and keep the
            # .h5 alongside it, because generate_manuscript_assets() loads
            # weights from model_ptac.h5 and downstream tooling may expect it.
            # ------------------------------------------------------- PATCH-A5
            # CHECKPOINT/SPEC PAIRING. 'model_ptac.h5' is overwritten by every
            
            # (PATCH-A4). A loader that picks up one arm's weights and another
            # arm's spec passes the width assertion and still rebuilds the wrong
            # context. Write a manifest naming the arm and the spec file that
            # belong to THESE weights, so the loader can verify the pair instead
            # of assuming it.
            _ckpt_meta = {
                'dataset_name': str(_ds),
                'model_name': str(self.model_name),
                'context_spec': f'context_spec_{_ds}__{_safe_filename(self.model_name)}.json',
                'context_dim': int(len(self._r17_ctx_cols)
                                   if getattr(self, '_r17_ctx_cols', None) else 0),
                'architecture': {
                    'BILSTM_UNITS': int(getattr(self.config, 'BILSTM_UNITS', 0)),
                    'CONV_FILTERS': int(getattr(self.config, 'CONV_FILTERS', 0)),
                    'GRU_UNITS_STATIC': int(getattr(self.config, 'GRU_UNITS_STATIC', 0)),
                    'ATTENTION_HEADS': int(getattr(self.config, 'ATTENTION_HEADS', 0)),
                    'HEAD_DENSE_UNITS': int(getattr(self.config, 'HEAD_DENSE_UNITS', 0)),
                    'DROPOUT_RATE': float(getattr(self.config, 'DROPOUT_RATE', 0.0)),
                    'USE_FAULT_GATING': bool(getattr(self.config, 'USE_FAULT_GATING', False)),
                    'R17_ENABLE': bool(getattr(self.config, 'R17_ENABLE', False)),
                },
            }
            # PATCH-A5b: the generic and per-dataset stems are overwritten by
            # EVERY PTAC arm, and the ablation arms run LAST, so whatever the
            # loader finds under those names is the last ablation -- in the r4
            # smoke run 'model_ptac_stable_final.h5' resolved to
            # 'M2P-PTAC (ungated control)'. The attention figure was therefore
            # never drawn from the reported arm. The reported arm is not known
            # here (it is the validation argmin over Stage 1), so keep a
            # per-arm checkpoint for the Stage-1 CANDIDATES only -- the
            # headline is always one of them -- and let the reporting block
            # promote the selected one and prune the rest. 5 candidates x ~16MB
            # per testbed, transient; per-arm for all ~15 arms would not be.
            _is_stage1 = bool(re.match(r'^M2P-PTAC \(C=', str(self.model_name)))
            _stems = [f"model_ptac_{_ds}", "model_ptac"]
            if _is_stage1:
                _stems.append(
                    f"model_ptac_{_ds}__{_safe_filename(self.model_name)}")
            for _stem in _stems:
                _p_keras = os.path.join(self.config.OUTPUT_DIR, _stem + ".keras")
                model.save(_p_keras)
                try:
                    with open(os.path.join(self.config.OUTPUT_DIR,
                                           _stem + ".manifest.json"), 'w') as _mf:
                        json.dump(_ckpt_meta, _mf, indent=1)
                except Exception as _me:
                    print(f"    [A5] checkpoint manifest failed for {_stem}: {_me}")
                try:
                    with warnings.catch_warnings():
                        warnings.simplefilter("ignore")
                        _absl = logging.getLogger('absl')
                        _lvl = _absl.level
                        _absl.setLevel(logging.ERROR)
                        model.save(os.path.join(self.config.OUTPUT_DIR,
                                                _stem + ".h5"))
                        _absl.setLevel(_lvl)
                except Exception as _he:
                    print(f"    [F11] legacy .h5 mirror failed for {_stem}: {_he}")
            if "electric conductivity" in target_vars:
                ec_idx = target_vars.index("electric conductivity")
                # ------------------------------------------------------ PATCH-D3
                # FILENAME COLLISION. These names are keyed by (dataset, C) only,
                # but base_lambda is NOT unique across arms: every Stage-2 arm
                # (clip k=*, conformal a=*, ungated control, the ablations) is
                # constructed with base_lambda=global_optimal_c, so all of them
                # write the SAME two filenames as the selected Stage-1 arm and
                # the last writer wins. Verified on the current run: the stored
                # y_pred_ptac_ec_challenged_89509_0.02.npy has EC MAE 1.772638,
                # which is the ungated control's value, while the C=0.02 row in
                # the metrics table is 0.821502 -- the array on disk is not the
                # arm its filename claims. Same collision on belgian_vub for
                # C=0.0005 and C=0.001.
                #
                # Keying by the model name makes each array attributable. The
                # legacy (dataset, C) name is still written FOR THE SELECTED
                # STAGE-1 ARM ONLY, so generate_robustness_figure() and any
                # existing tooling keep working, but no Stage-2 arm can
                # overwrite it any more.
                _safe_nm = re.sub(r'[^0-9A-Za-z._=-]+', '_', str(self.model_name))
                np.save(os.path.join(self.config.OUTPUT_DIR,
                                     f"y_true_ec_{_ds}__{_safe_nm}.npy"),
                        y_true_final[:, ec_idx])
                np.save(os.path.join(self.config.OUTPUT_DIR,
                                     f"y_pred_ptac_ec_{_ds}__{_safe_nm}.npy"),
                        final_prediction[:, ec_idx])
                # Legacy names: only the plain C-sweep arm may write them.
                if re.fullmatch(r'M2P-PTAC \(C=[0-9.eE+-]+\)',
                                str(self.model_name)):
                    np.save(os.path.join(self.config.OUTPUT_DIR,
                                         f"y_true_ec_{_ds}_{self.base_lambda}.npy"),
                            y_true_final[:, ec_idx])
                    np.save(os.path.join(self.config.OUTPUT_DIR,
                                         f"y_pred_ptac_ec_{_ds}_{self.base_lambda}.npy"),
                            final_prediction[:, ec_idx])
                else:
                    print(f"    [PATCH-D3] '{self.model_name}' shares "
                          f"base_lambda={self.base_lambda} with the C sweep; "
                          f"writing only the name-keyed arrays so it cannot "
                          f"overwrite the selected arm's.")

        results = compute_metrics(y_true_final, final_prediction, y_train_tab,
                                  target_vars, obs_mask=obs_test, fault_mask=fault_test,
                                  baseline_pred=baseline_test_pred,
                                  kind_masks=_slice_kind_masks(
                                      getattr(self.config, '_kind_masks', {}),
                                      test_indices),
                                  persist_pred=_persist_slice(self.config,
                                                              test_indices,
                                                              target_vars),
                                  config=self.config)

        # ------------------------------------------------------------------
        
        # script selected it by minimising test MAE, which gives the proposed
        # model a best-of-five while every baseline gets a single shot; the
        # selector value printed in the log was bit-identical to the reported
        # test Macro-MAE at all four testbeds. Score the VALIDATION split here
        # -- disjoint from the training-tail early-stop block -- and let Stage 1
        # select on '_val_MAE_for_selection'. The
        # test metrics above are untouched and remain the reported numbers.
        # ------------------------------------------------------------------
        # Selection score is computed on the C-selection block only; the prior
        # blocks calibrated bounds/thresholds and authorised safety.
        val_residuals = val_residuals_raw.copy()
        if bound is not None:
            val_residuals = np.clip(val_residuals, -bound, bound)
        # Replay the row-level probability threshold before selecting C.
        # Otherwise validation would rank a different intervention from the
        # one actually applied on test rows.
        if _val_p is not None and self._r18_deadband:
            _raw_db = float(getattr(self.config, 'R17_GATE_DEADBAND', 0.0))
            _dynamic_on = bool(getattr(self.config, 'R21_DYNAMIC_SELECTOR', False))
            for _j, _v in enumerate(target_vars):
                _t = float(self._r18_deadband.get(_v, _raw_db))
                if _dynamic_on and _val_score is not None:
                    val_residuals[_val_score[:, _j] < _t, _j] = 0.0
                elif _t > _raw_db:
                    _thr = ((_t - _raw_db)
                            / max(1.0 - _raw_db, 1e-9))
                    val_residuals[_val_p[:, _j] < _thr, _j] = 0.0
        # Select C for the gated model, not for a model we will not deploy.
        if not gate_mask.all():
            val_residuals[:, ~gate_mask] = 0.0
        val_pred_all = df_baseline_preds.loc[val_indices].values + val_residuals
        # Validation selection must use the same truth convention as the
        # reported evaluation.  In R19/T2 drift runs that is pristine truth;
        # in ordinary runs config._eval_truth resolves to the audited shared
        # frame and is equivalent to df on observed rows.
        _val_truth_src = self.eval_truth_df
        if _val_truth_src is None:
            _val_truth_src = getattr(self.config, '_eval_truth', None)
        if _val_truth_src is None:
            _val_truth_src = df
        val_true_all = _val_truth_src.loc[val_indices, target_vars].values

        # ------------------------------------------------------------- R19-B
        # Read-only validation-window safety telemetry for the T2 seed
        # replication. Nothing below writes to `results`, to `val_residuals`,
        # or to any selection/test quantity -- it only reads the arrays that
        # already exist at this point and records them on `self`.
        #
        # Deliberately measured on the disjoint SAFETY block only; neither the
        # calibration block nor the C-selection block is reused here.
        # Truth is `eval_truth_df` (pristine) where supplied, so "useful" means
        # moved toward the undegraded series, not toward the fouled reading.
        try:
            _b19 = df_baseline_preds.loc[val_indices].values[safety_slice]
            _c19 = val_residuals[safety_slice]               # applied, post-gate
            _t19src = (self.eval_truth_df if self.eval_truth_df is not None
                       else df)
            _t19 = _t19src.reindex(val_indices)[target_vars].values[safety_slice]
            if self.authorization_mask is not None:
                _d19 = (self.authorization_mask.reindex(index=val_indices,
                                                        columns=target_vars)
                        .fillna(False).values.astype(bool)[safety_slice])
            else:
                _d19 = np.zeros_like(_c19, dtype=bool)
            _e_pre = np.abs(_t19 - _b19)
            _e_post = np.abs(_t19 - (_b19 + _c19))
            _acted = np.isfinite(_e_pre) & np.isfinite(_e_post) & (_c19 != 0.0)
            _n_act = int(_acted.sum())
            _fin = np.isfinite(_e_pre) & np.isfinite(_e_post)
            _nom = _fin & ~_d19
            _deg = _fin & _d19
            self._r19_safety = {
                'n_sel_rows': int(_c19.shape[0]),
                'n_acted_cells': _n_act,
                'action_rate': (float(_acted.sum() / max(int(_fin.sum()), 1))),
                # among cells the corrector actually moved:
                'useful_rate': (float((_e_post[_acted] < _e_pre[_acted]).mean())
                                if _n_act else np.nan),
                'harmful_rate': (float((_e_post[_acted] > _e_pre[_acted]).mean())
                                 if _n_act else np.nan),
                # worst single-cell degradation, in level units
                'worst_harm': (float(np.max(_e_post[_acted] - _e_pre[_acted]))
                               if _n_act else np.nan),
                'gate_frac_open': float(np.mean(gate_mask)),
                'n_targets_gated_off': int((~np.asarray(gate_mask)).sum()),
                # nominal penalty: >0 means the corrector HURT clean rows
                'nominal_penalty': (float(np.nanmean(_e_post[_nom])
                                          - np.nanmean(_e_pre[_nom]))
                                    if _nom.any() else np.nan),
                'n_nominal': int(_nom.sum()),
                # degraded rescue: >0 means the corrector HELPED drifted rows
                'degraded_rescue': (float(np.nanmean(_e_pre[_deg])
                                          - np.nanmean(_e_post[_deg]))
                                    if _deg.any() else np.nan),
                'n_degraded': int(_deg.sum()),
            }
            print(f"    [R19-B] val-safety (disjoint safety block): "
                  f"acted {_n_act}/{int(_fin.sum())} cells, "
                  f"useful {self._r19_safety['useful_rate']}, "
                  f"harmful {self._r19_safety['harmful_rate']}, "
                  f"nominal penalty {self._r19_safety['nominal_penalty']}, "
                  f"degraded rescue {self._r19_safety['degraded_rescue']}")
        except Exception as _e19:                      # telemetry must never
            self._r19_safety = {'error': repr(_e19)}   # break the run
            print(f"    [R19-B] telemetry unavailable: {_e19!r}")

        # ------------------------------------------------------------- R19-C
        # Amplitude-shrinkage harvest. `c_applied = alpha * c_raw` is applied at
        # INFERENCE and nothing in training depends on alpha, so scaling the
        # already-computed correction is exact -- not an approximation of a
        # re-run. Recording the arrays lets all five alphas be evaluated without
        # 5x the fits. Read-only: nothing here feeds `results`.
        #
        # `predicted_residuals` / `val_residuals` are post-bound and post-gate,
        # so alpha shrinks the correction the deployed pipeline would actually
        # apply -- the bound and the gate stay exactly as frozen.
        try:
            self._r19_arrays = {
                'val_base': df_baseline_preds.loc[val_indices].values[csel_slice],
                'val_corr': val_residuals[csel_slice],
                'val_true': ((self.eval_truth_df if self.eval_truth_df is not None
                              else df).reindex(val_indices)[target_vars]
                             .values[csel_slice]),
                'val_drift': (self.authorization_mask.reindex(index=val_indices,
                                                              columns=target_vars)
                              .fillna(False).values.astype(bool)[csel_slice]
                              if self.authorization_mask is not None else None),
                'test_base': baseline_test_pred,
                'test_corr': predicted_residuals,
                'test_true': y_true_final,
                'test_index': np.asarray(test_indices),
                'val_index': np.asarray(val_indices)[csel_slice],
                'targets': list(target_vars),
                
                # `*_prob` remains the raw neural p_fault for detection
                # diagnostics. R21's actual state-aware operating signal is
                # stored separately as `*_selector_score`; replay code should
                # use that score with `selector_threshold` when R21 is enabled.
                'val_corr_raw': val_residuals_raw[csel_slice],
                'val_prob': (self.last_val_fault_prob[csel_slice]
                             if self.last_val_fault_prob is not None else None),
                'test_corr_raw': getattr(self, '_r19_test_corr_raw', None),
                'test_prob': self.last_fault_prob,
                'val_selector_score': (self._r21_selector_val_score[csel_slice]
                                       if getattr(self, '_r21_selector_val_score', None) is not None
                                       else None),
                'test_selector_score': getattr(self, 'last_selector_score', None),
                'gate_mask': np.asarray(gate_mask, dtype=bool),
                'bound': (np.asarray(bound, dtype=float)
                          if bound is not None else None),
                'deadband_floor': np.asarray(
                    [float(getattr(self.config, 'R17_GATE_DEADBAND', 0.0))]),
                'r18_thresh': np.asarray(
                    [float(self._r18_deadband.get(v, getattr(
                        self.config, 'R17_GATE_DEADBAND', 0.0)))
                     for v in target_vars], dtype=float),
                'selector_threshold': np.asarray(
                    [float(self._r18_deadband.get(v, 1.000001))
                     for v in target_vars], dtype=float),
                # --- R19-D: causal/context feature block for the benefit-probe
                # diagnostic. Read-only. These are the SCALED context inputs the
                # graph itself consumes (drift bank + rolling health), taken on
                # the C-selection block only, so a probe fitted here sees exactly
                # what the gate could see at inference and no test truth.
                'val_ctx': np.asarray(X_val_context, dtype=float)[csel_slice],
                'ctx_cols': np.asarray(
                    [str(c) for c in getattr(self, '_r17_ctx_cols', [])]),
            }
        except Exception as _e19c:
            self._r19_arrays = {'error': repr(_e19c)}
            print(f"    [R19-C] harvest unavailable: {_e19c!r}")
        with np.errstate(invalid='ignore'):
            _val_abs = np.abs(val_true_all - val_pred_all)
            _base_abs = np.abs(
                val_true_all - df_baseline_preds.loc[val_indices].values)
            _val_all_sel = float(np.nanmean(_val_abs[csel_slice]))
            results['_val_MAE_for_selection_all'] = _val_all_sel
            results['_val_MAE_full'] = float(np.nanmean(_val_abs))

            # Choose C on source-retained validation cells when provenance is
            # available. Otherwise reconstruction density can influence which
            # model is selected even though the primary test metric excludes it.
            _val_obs = None
            if self.obs_mask is not None:
                _om = (self.obs_mask.reindex(index=val_indices,
                                             columns=target_vars)
                       .fillna(False).values.astype(bool))
                _om_sel = _om[csel_slice]
                _finite_sel = np.isfinite(_val_abs[csel_slice]) & _om_sel
                if _finite_sel.any():
                    _val_obs = float(np.mean(_val_abs[csel_slice][_finite_sel]))
                    _finite_full = np.isfinite(_val_abs) & _om
                    results['_val_MAE_full_obs'] = float(
                        np.mean(_val_abs[_finite_full]))
                    results['_val_N_obs_for_selection'] = int(
                        _finite_sel.sum())
            # Equal-target, feature-matched selection: every channel contributes
            # one MAE ratio against the corrector's own differenced XGBoost
            # anchor.  Raw-unit averaging let conductivity dominate C.
            _ratios = []
            for _j, _v in enumerate(target_vars):
                _mask_j = (np.isfinite(_val_abs[csel_slice, _j])
                           & np.isfinite(_base_abs[csel_slice, _j]))
                if self.obs_mask is not None:
                    _mask_j &= _om_sel[:, _j]
                if not _mask_j.any():
                    results[f'_val_ratio_{_v}'] = np.nan
                    continue
                _m_model = float(np.mean(_val_abs[csel_slice, _j][_mask_j]))
                _m_anchor = float(np.mean(_base_abs[csel_slice, _j][_mask_j]))
                _ratio = (_m_model / _m_anchor
                          if np.isfinite(_m_anchor) and _m_anchor > 1e-12
                          else np.nan)
                results[f'_val_ratio_{_v}'] = _ratio
                if np.isfinite(_ratio):
                    _ratios.append(_ratio)
            if not _ratios:
                raise ValueError(
                    'No finite source-retained target ratio is available on '
                    'the disjoint C-selection block.')
            results['_val_MAE_for_selection'] = float(np.mean(_ratios))
            results['_val_selection_metric'] = (
                'equal_target_MAE_ratio_to_matched_differenced_XGBoost_anchor')
            results['_val_MAE_for_selection_raw_units'] = (
                _val_obs if _val_obs is not None else _val_all_sel)
            results['_val_selection_scope'] = (
                'source-retained disjoint C-selection block' if _val_obs is not None
                else 'all cells in disjoint C-selection block')

        # Conformal diagnostics, one row's worth per target.
        results['conformal_alpha'] = (self.conformal_alpha
                                      if self.conformal_alpha is not None else np.nan)
        for v in target_vars:
            d = conformal_diag.get(v, {})
            results[f'{v}_ConfBound'] = d.get('bound', np.nan)
            results[f'{v}_ConfNCal'] = d.get('n_cal', np.nan)
        results['bound_family'] = ('conformal' if self.conformal_alpha is not None
                                   else ('k_sigma' if self.clip_k is not None else 'none'))
        # as if they were calibrated.
        for v in target_vars:
            d = conformal_diag.get(v, {})
            results[f'{v}_ConfAttainable'] = d.get('attainable', np.nan)
            results[f'{v}_ConfNRequired'] = d.get('n_required', np.nan)
        results['conformal_all_attainable'] = bool(all(
            conformal_diag.get(v, {}).get('attainable', True) for v in target_vars))
        results['gate_threshold'] = (self.gate_threshold
                                     if self.gate_threshold is not None else np.nan)
        results['gate_n_corrected'] = int(gate_mask.sum())
        results['gate_n_declined'] = int((~gate_mask).sum())
        results['anchor_supervision'] = self._anchor_supervision
        results['corrector_supervision'] = self._corrector_supervision
        results['r19_safety_veto_enabled'] = bool(
            getattr(self.config, 'R19_SAFETY_VETO', False))
        results['r19_safety_n_passed'] = int(np.asarray(
            getattr(self, '_r19_safety_mask', np.ones(len(target_vars), dtype=bool))).sum())
        results['r19_safety_n_vetoed'] = int(len(target_vars) - results['r19_safety_n_passed'])
        for _v in target_vars:
            _sdg = getattr(self, '_r19_safety_diag', {}).get(_v, {})
            results[f'{_v}_SafetyPass'] = bool(_sdg.get('passed', True))
            results[f'{_v}_SafetyValNDegraded'] = _sdg.get('n_degraded', np.nan)
            results[f'{_v}_SafetyValRescue'] = _sdg.get('degraded_rescue', np.nan)
            results[f'{_v}_SafetyValNomPenaltyRel'] = _sdg.get('nominal_penalty_rel', np.nan)
            results[f'{_v}_SafetyValMAEMult'] = _sdg.get('mae_multiplier', np.nan)
            results[f'{_v}_SafetyReason'] = _sdg.get('reason', '')
            _r21d = getattr(self, '_r21_selector_diag', {}).get(_v, {})
            results[f'{_v}_DynamicSelectorFitted'] = bool(_r21d.get('fitted', False))
            results[f'{_v}_DynamicSelectorTrainN'] = _r21d.get('n_train', np.nan)
            results[f'{_v}_DynamicSelectorTrainPos'] = _r21d.get('n_pos', np.nan)
            results[f'{_v}_DynamicSelectorTrainNeg'] = _r21d.get('n_neg', np.nan)
            results[f'{_v}_DynamicGateThreshold'] = float(
                getattr(self, '_r18_deadband', {}).get(_v, np.nan))
            results[f'{_v}_DynamicSelectorReason'] = _r21d.get('reason', '')
        results['dynamic_selector_enabled'] = bool(
            getattr(self.config, 'R21_DYNAMIC_SELECTOR', False))
        # PATCH-A1: the PTAC arm's own realised bank width, so a reader can
        # compare it against the comparator rows' n_drift_bank_cols directly.
        results['uses_drift_bank'] = bool(len(self._r17_drift_cols) > 0)
        results['n_drift_bank_cols'] = int(len(self._r17_drift_cols))
        # ------------------------------------------------------------ PATCH-D2
        # GATE/PREDICTION CONSISTENCY CHECK.
        #
        # The audit flagged four arms on challenged_89509 that are bit-identical
        # on all three channels while reporting gate_n_corrected > 0, and read
        
        # is correct -- final_prediction = baseline_test_pred + predicted_residuals
        # with the gate zeroing declined COLUMNS beforehand -- and that the
        # identity has a different, legitimate cause: a channel can be gated ON
        # (its calibration-half correction is large enough to pass R9) and still
        # receive an ALL-ZERO correction on the TEST window, because
        #   (a) the R18 deadband post-hoc-zeroes test rows whose p_fault falls
        #       below the calibrated threshold, and
        #   (b) the graph's own deadband, relu(p - d)/(1 - d), returns exactly 0
        #       for every test row the detector scores below d.
        # Both act per ROW, after the per-COLUMN gate decision, so
        # gate_n_corrected counts an INTENT to correct that the deadband can
        # legitimately reduce to nothing.
        #
        # This check therefore measures the thing that actually matters -- did
        # the scored prediction move -- and distinguishes the benign case from a
        # real wiring fault. It compares against the internal anchor prediction
        # (baseline_test_pred), which is the array the correction is added to.
        _tol = float(getattr(self.config, 'PATCH_D2_PARITY_TOL', 1e-12))
        results['parity_tol'] = _tol
        _delta_max = np.abs(final_prediction - baseline_test_pred)
        with np.errstate(invalid='ignore'):
            _moved_any = bool(np.nanmax(_delta_max) > _tol) if _delta_max.size else False
        results['pred_differs_from_anchor'] = _moved_any
        results['max_abs_applied_correction'] = (
            float(np.nanmax(_delta_max)) if _delta_max.size else np.nan)
        # Per-channel: gated ON but numerically inert on every test row.
        _inert = []
        for _j, _v in enumerate(target_vars):
            _cmax = (float(np.nanmax(_delta_max[:, _j]))
                     if _delta_max.size else np.nan)
            results[f'{_v}_MaxAbsCorrection'] = _cmax
            _on = bool(gate_mask[_j])
            _moved = bool(np.isfinite(_cmax) and _cmax > _tol)
            results[f'{_v}_CorrectionInert'] = bool(_on and not _moved)
            if _on and not _moved:
                _inert.append(_v)
        results['n_gated_on_but_inert'] = len(_inert)
        # INVALID must be an ASSEMBLY invariant, not "the prediction did not
        # move". A gated-ON channel whose correction is zero on every test row
        # is the BENIGN deadband case above and is common on this run -- marking
        
        # ship is the one where the correction exists but never reaches the
        # scored array, so the check is the identity the assembly claims:
        #     final_prediction == baseline_test_pred + predicted_residuals
        # plus the directional case where a channel carries a non-zero residual
        # yet its scored prediction is unchanged.
        _resid = np.asarray(predicted_residuals, dtype=float)
        _asm_err = (float(np.nanmax(np.abs(
                        final_prediction - (baseline_test_pred + _resid))))
                    if _resid.size else 0.0)
        results['assembly_max_err'] = _asm_err
        _asm_bad = bool(_asm_err > max(_tol, 1e-9))
        _lost = []
        for _j, _v in enumerate(target_vars):
            _rmax = float(np.nanmax(np.abs(_resid[:, _j]))) if _resid.size else 0.0
            _pmax = float(np.nanmax(_delta_max[:, _j])) if _delta_max.size else 0.0
            results[f'{_v}_MaxAbsResidual'] = _rmax
            if _rmax > _tol and not (_pmax > _tol):
                _lost.append(_v)
        results['n_corrections_lost'] = len(_lost)
        _invalid = bool(_asm_bad or _lost)
        results['row_invalid'] = _invalid
        results['row_invalid_reason'] = (
            (f'assembly identity violated (max |pred - (anchor+resid)| = '
             f'{_asm_err:.3g})' if _asm_bad else '')
            + ('; ' if (_asm_bad and _lost) else '')
            + (f'non-zero residual never reached the scored prediction on: '
               f'{", ".join(_lost)}' if _lost else ''))
        if _invalid:
            print(f"    [PATCH-D2] ROW MARKED INVALID: "
                  f"{results['row_invalid_reason']}")
        if _inert:
            print(f"    [PATCH-D2] {len(_inert)} channel(s) gated ON but "
                  f"numerically inert on the test window (|delta| <= {_tol:g} "
                  f"everywhere): {', '.join(_inert)}. Cause is the row-wise "
                  f"deadband, not the column gate; these channels are at exact "
                  f"anchor parity and must not be read as corrected.")
        for v in target_vars:
            d = gate_diag.get(v, {})
            results[f'{v}_Gate'] = d.get('gate', np.nan)
            results[f'{v}_GateApplied'] = bool(d.get('applied', True))
        results['realised_bind_rate'] = clip_hit_rate
        # The aggregate rate averages over targets and so understates a bound
        # that is doing all its work on one channel. Report per-target too: a
        # 17% aggregate that is 71% on pH and 0% elsewhere is a pH-bound, and
        # the manuscript should say so rather than claim a global 17%.
        if per_target_hit is not None:
            for v, r in zip(target_vars, np.atleast_1d(per_target_hit)):
                results[f'{v}_BindRate'] = float(r)

        # reliability diagnostics can be built without re-running inference.
        self.last_corrections = predicted_residuals.copy()

        # ------------------------------------------------------------------ R16-E
        # Park EVERY PTAC arm's degradation probabilities on config, keyed by
        # model name, so detection_report can score the headline arm's against
        # the fault mask after the suite finishes.
        #
        # flag is assigned in the Stage-2 queue loop, and the headline model is
        # the Stage-1 C-sweep arm that WINS selection -- it runs before its own
        # name exists and is never re-run. So the flag was False for every
        # experiment that had a fault head, `_headline_fault_prob` stayed unset,
        # and detection_report was skipped on every dataset with only the
        # "gating is on but no fault probabilities were recorded" notice to show
        # for it. The detection table is the sole evidence that the gate keys on
        # degradation rather than on noise, so silently not writing it is the
        
        # promoting the winner after selection keeps the original guarantee --
        # the table describes the arm the manuscript reports, not whichever arm
        # happened to run last.
        if getattr(self, 'last_fault_prob', None) is not None:
            if not hasattr(self.config, '_ptac_fault_prob_registry'):
                self.config._ptac_fault_prob_registry = {}
            self.config._ptac_fault_prob_registry[self.model_name] = (
                self.last_fault_prob, test_indices)
            # Direct write kept for the Stage-2 queue path, where is_headline IS
            # set correctly (the repeat-runs block re-instantiates the headline
            # arm by name); promotion below is idempotent with it.
            if getattr(self, 'is_headline', False):
                self.config._headline_fault_prob = self.last_fault_prob
                self.config._headline_test_index = test_indices

        # compute_metrics for EVERY model on identical footing (see the R16-D
        # block there), so this experiment no longer counts its own. The local
        # count is retained only as a cross-check that the two paths agree on
        # the same prediction array; a disagreement means the array scored is
        # not the array reported and the run should be treated as suspect.
        _pred_df_for_viol = pd.DataFrame(
            df_baseline_preds.loc[test_indices].values + predicted_residuals,
            columns=target_vars)
        _viol = count_physical_violations(_pred_df_for_viol, target_vars,
                                          getattr(self.config, 'PHYSICAL_LIMITS', {}))
        if len(_viol):
            _local_n = int(_viol.n_below.sum() + _viol.n_above.sum())
            _central_n = results.get('n_physical_violations', _local_n)
            results['physviol_local_crosscheck'] = _local_n
            if _local_n != _central_n:
                print(f"    [R16-D] WARNING: local violation count {_local_n} != "
                      f"centrally counted {_central_n}. The prediction array "
                      f"scored by compute_metrics differs from "
                      f"baseline+correction; investigate before quoting either.")

        results['clip_k'] = self.clip_k if self.clip_k is not None else np.nan
        results['clip_hit_rate'] = clip_hit_rate
        for v, r in zip(target_vars, per_target_hit):
            results[f'{v}_ClipHit'] = r

        # baseline worse on a target, the "baseline-parity" language is unearned.
        viol = {v: results.get(f'{v}_ParityViol', np.nan) for v in target_vars}
        worst = max((x for x in viol.values() if not pd.isna(x)), default=np.nan)
        if not pd.isna(worst) and worst > 0.5:
            print(f"    [R1] WARNING: parity violated on >50% of test points for "
                  f"at least one target ({viol}). The parity claim does not hold "
                  f"as stated -- report the violation rate in the manuscript.")

        errors_raw = y_true_final - final_prediction
        errors_dict = {name: errors_raw[:, i] for i, name in enumerate(target_vars)}
        results['eval_protocol'] = EVAL_PROTOCOL_ROLLING_H1
        results['target_mode'] = 'delta'
        return results, timings, errors_dict


class MonolithicExperiment(BenchmarkExperiment):
    """Internal experiment utility."""

    def __init__(self, model_name, config, obs_mask=None, fault_mask=None,
                 tuning_grid=None):
        super().__init__(model_name, config)
        self.obs_mask = obs_mask
        self.fault_mask = fault_mask
        
        # A list => search that many configurations on validation, matching the
        # budget M2P-PTAC receives from its C sweep.
        self.tuning_grid = (tuning_grid if tuning_grid is not None
                            else (config.MONOLITHIC_TUNING_GRID
                                  if getattr(config, 'MONOLITHIC_TUNED', False)
                                  else None))
        if config.MONOLITHIC_AS_ABLATION:
            if not model_name.lower().startswith('ablation'):
                self.model_name = f"Ablation: {model_name} (no parity anchor)"
        elif not config.MONOLITHIC_TUNED:
            raise RuntimeError(
                "[R2] MONOLITHIC_AS_ABLATION=False requires MONOLITHIC_TUNED=True. "
                "Reporting an untuned monolithic network as a competitive baseline "
                "is the strawman the reviewer objected to. Either tune it with the "
                "same budget as M2P-PTAC, or leave it in the ablation section.")

    def run(self, df, target_vars):
        start_time_total = time.time()
        y_tab = df[target_vars]
        train_end_idx = int(len(df) * self.config.TRAIN_SPLIT)

        scaler_y = MinMaxScaler().fit(y_tab.iloc[:train_end_idx])
        y_tab_scaled = pd.DataFrame(scaler_y.transform(y_tab), columns=target_vars, index=y_tab.index)

        df_m2p_input = df.copy()
        time_features = ['hour_sin', 'hour_cos']
        df_m2p_input['hour_sin'] = np.sin(2 * np.pi * df.index.hour / 24.0)
        df_m2p_input['hour_cos'] = np.cos(2 * np.pi * df.index.hour / 24.0)

        feature_cols = [c for c in df.columns if c in target_vars]
        scaler_x = MinMaxScaler().fit(df_m2p_input.iloc[:train_end_idx][feature_cols])
        df_scaled_features = pd.DataFrame(
            scaler_x.transform(df_m2p_input[feature_cols]),
            columns=feature_cols, index=df.index
        )
        df_scaled_features[time_features] = df_m2p_input[time_features]

        X_m2p_full, m2p_indices = create_m2p_features(df_scaled_features, target_vars, time_features, self.config)
        common_indices = y_tab.index.intersection(m2p_indices)
        y_m2p_target = y_tab_scaled.loc[common_indices].values

        X_m2p_short_aligned = (
            pd.DataFrame([r.flatten() for r in X_m2p_full['short_term_input']], index=m2p_indices)
            .loc[common_indices].values
            .reshape(len(common_indices), self.config.SHORT_WINDOW_SIZE, -1)
        )
        X_m2p_long_aligned = (
            pd.DataFrame([r.flatten() for r in X_m2p_full['long_term_input']], index=m2p_indices)
            .loc[common_indices].values
            .reshape(len(common_indices), self.config.LONG_WINDOW_SIZE, -1)
        )
        X_short_flat = X_m2p_short_aligned.reshape(X_m2p_short_aligned.shape[0], -1)
        X_long_flat = X_m2p_long_aligned.reshape(X_m2p_long_aligned.shape[0], -1)
        X_unified = np.concatenate([X_short_flat, X_long_flat], axis=1)

        train_end = int(len(common_indices) * self.config.TRAIN_SPLIT)
        val_end = int(len(common_indices) * (self.config.TRAIN_SPLIT + self.config.VAL_SPLIT))

        X_train_m2p = X_unified[:train_end]
        X_val_m2p = X_unified[train_end:val_end]
        X_test_m2p = X_unified[val_end:]
        y_train_m2p = y_m2p_target[:train_end]
        y_val_m2p = y_m2p_target[train_end:val_end]

        # PTAC context block -- on a non-hourly cadence the literal matched no
        # columns and the context input silently became zero-width).
        _mw = int(getattr(self.config, '_steps_per_day', 24))
        if _mw <= 1:
            _mw = max(_roll_windows_of(self.config))
        context_cols = [c for c in df.columns
                        if f'_roll_mean_{_mw}' in c or f'_roll_std_{_mw}' in c]
        if not context_cols:
            _w2 = max(_roll_windows_of(self.config))
            context_cols = [c for c in df.columns
                            if f'_roll_mean_{_w2}' in c or f'_roll_std_{_w2}' in c]
        X_ctx_full = df[context_cols].iloc[self.config.LONG_WINDOW_SIZE:].values
        current_context_dim = len(context_cols)

        tf.keras.backend.clear_session()
        model = build_m2p_attention_network(
            config=self.config,
            target_vars=target_vars,
            num_dynamic_vars=len(target_vars),
            short_window_features=X_m2p_short_aligned.shape[2],
            long_window_features=X_m2p_long_aligned.shape[2],
            context_dim=current_context_dim,
            name_suffix="_Monolithic",
            use_fault_gating=False        # R16-E: comparator, deliberately ungated
        )
        X_train_ctx = X_ctx_full[:train_end]
        X_val_ctx = X_ctx_full[train_end:val_end]
        X_test_ctx = X_ctx_full[val_end:]

        # ------------------------------------------------------------------
        #
        
        # one arbitrary learning rate while M2P-PTAC gets a swept hyperparameter.
        # When self.tuning_grid is set, the monolithic model receives a search
        # over the SAME NUMBER of configurations as the C sweep that M2P-PTAC
        # gets, selected on the VALIDATION split, and the budget is printed so
        # the manuscript can state it. Only then is a comparison of the two
        # architectures a statement about architecture.
        # ------------------------------------------------------------------
        grid = list(self.tuning_grid or [{'learning_rate': self.config.LEARNING_RATE,
                                          'batch_size': self.config.BATCH_SIZE}])
        if len(grid) > 1:
            print(f"    [C-T7] tuning monolithic over {len(grid)} configurations "
                  f"(M2P-PTAC C sweep budget: "
                  f"{len(self.config.LAMBDA_ANALYSIS_VALUES)}), selecting on validation.")
        best = {'val': np.inf, 'model': None, 'cfg': None}
        for gi, g in enumerate(grid):
            if gi > 0:
                tf.keras.backend.clear_session()
                model = build_m2p_attention_network(
                    config=self.config, target_vars=target_vars,
                    num_dynamic_vars=len(target_vars),
                    short_window_features=X_m2p_short_aligned.shape[2],
                    long_window_features=X_m2p_long_aligned.shape[2],
                    context_dim=current_context_dim,
                    name_suffix=f"_Monolithic_t{gi}",
                    use_fault_gating=False)
            optimizer = tf.keras.optimizers.Adam(
                learning_rate=g.get('learning_rate', self.config.LEARNING_RATE),
                clipnorm=1.0)
            # default, so the loss is fully specified in the manuscript.
            model.compile(optimizer=optimizer,
                          loss=tf.keras.losses.Huber(
                              delta=getattr(self.config, 'HUBER_DELTA', 1.0)))
            hist = model.fit(
                x=[X_train_m2p, X_train_ctx],
                y=[y_train_m2p[:, i] for i in range(len(target_vars))],
                validation_data=([X_val_m2p, X_val_ctx], [y_val_m2p[:, i] for i in range(len(target_vars))]),
                epochs=self.config.EPOCHS,
                batch_size=g.get('batch_size', self.config.BATCH_SIZE),
                callbacks=[keras.callbacks.EarlyStopping(monitor='val_loss', patience=self.config.PATIENCE, restore_best_weights=True)],
                verbose=0
            )
            vl = float(np.min(hist.history.get('val_loss', [np.inf])))
            if len(grid) > 1:
                print(f"      cfg {gi + 1}/{len(grid)} {g} -> val_loss {vl:.6f}")
            if vl < best['val']:
                best.update(val=vl, model=model, cfg=g)
        if best['model'] is not None:
            model = best['model']
            if len(grid) > 1:
                print(f"    [C-T7] selected {best['cfg']} (val_loss {best['val']:.6f}). "
                      f"Report this budget in the manuscript alongside M2P-PTAC's.")
        timings = {'Training Time (s)': time.time() - start_time_total,
                   'Tuning Configs': len(grid)}

        start_time_forecast = time.time()
        preds_scaled = np.array(model.predict([X_test_m2p, X_test_ctx], verbose=0)).T.reshape(-1, len(target_vars))  
        timings['Forecast Time (s)'] = time.time() - start_time_forecast

        final_prediction = scaler_y.inverse_transform(preds_scaled)
        y_true_final = y_tab.loc[common_indices[val_end:]].values

        results = {}
        y_train_unscaled = y_tab.loc[common_indices[:train_end]]
        for i, name in enumerate(target_vars):
            y_true_var = y_true_final[:, i]
            y_pred_var = final_prediction[:, i]
            y_train_var = y_train_unscaled[name].values
            results[f'{name}_MAE'] = mean_absolute_error(y_true_var, y_pred_var)
            results[f'{name}_RMSE'] = np.sqrt(mean_squared_error(y_true_var, y_pred_var))
            results[f'{name}_MASE'] = calculate_mase(
                y_true_var, y_pred_var, y_train_var,
                seasonality=_seasonality_of(self.config))   # R16-A

        errors_raw = y_true_final - final_prediction
        errors_dict = {name: errors_raw[:, i] for i, name in enumerate(target_vars)}
        results['eval_protocol'] = EVAL_PROTOCOL_ROLLING_H1
        
        results['target_mode'] = 'level'
        return results, timings, errors_dict


class TabularExperiment(BenchmarkExperiment):
    """Internal experiment utility."""

    def __init__(self, model_name, config, model_class, params,
                 eval_truth_df=None, obs_mask=None, fault_mask=None,
                 target_mode='level', use_drift_bank=None):
        super().__init__(model_name, config)
        self.model_class, self.params = model_class, params
        # on the same clean truth as M2P-PTAC.
        self.eval_truth_df = eval_truth_df
        self.obs_mask = obs_mask
        self.fault_mask = fault_mask
        if target_mode not in ('level', 'delta'):
            raise ValueError(f"target_mode must be 'level' or 'delta', got {target_mode!r}")
        self.target_mode = target_mode
        # ------------------------------------------------------------ PATCH-A1
        # FEATURE PARITY WITH THE INTERNAL ANCHOR (audit F3/F4).
        #
        # PTACExperiment.run() appends the R17 causal drift bank to X_tab
        # BEFORE fitting its internal per-channel anchor, so the anchor the
        # proposed model actually wraps sees X_tab + bank. This class saw
        # X_tab alone, so every 'delta_mae vs differenced anchor' number and
        # every drift-stress gap conflated the neural correction with a
        # feature-set difference. `use_drift_bank` closes that gap.
        #
        # The default is False, and deliberately so. Every arm already carried
        # in the results tables keeps its published name, feature set and
        # numbers -- silently widening the feature set behind an existing name
        # would make the r3 and r4 tables non-comparable under one label, which
        # is the same class of error this patch exists to remove. The
        # feature-matched anchors are ADDED as new, explicitly named arms
        # ('... + drift bank') that pass use_drift_bank=True.
        #
        # That also buys the ablation the audit asked for: the pair
        #   'XGBoost (differenced target)'  vs  '... (differenced target + drift bank)'
        # isolates the DRIFT-BANK contribution with the corrector held out
        # entirely, and the pair
        #   '... (differenced target + drift bank)'  vs  M2P-PTAC
        # then isolates the CORRECTOR with features held fixed. In the r3 run
        # those two effects were summed into one number and reported as the
        # corrector's.
        if use_drift_bank is None:
            use_drift_bank = False
        self.use_drift_bank = bool(use_drift_bank)
        self.n_drift_bank_cols = 0

    def run(self, df, target_vars):
        start_time_total = time.time()
        X_tab, y_tab, lag1_tab = create_tabular_features(
            df, target_vars, config=self.config, return_delta=True)   # R16-A/C
        _raw_train_end, _raw_val_end, _raw_test_start = _raw_split_boundaries(
            self.config, len(df))
        _raw_train_idx = pd.Index(df.index[:_raw_train_end])
        _raw_val_idx = pd.Index(df.index[_raw_train_end:_raw_val_end])
        _raw_test_idx = pd.Index(df.index[_raw_test_start:])
        train_indices = pd.Index([ix for ix in X_tab.index if ix in _raw_train_idx])
        val_indices = pd.Index([ix for ix in X_tab.index if ix in _raw_val_idx])
        test_indices = pd.Index([ix for ix in X_tab.index if ix in _raw_test_idx])
        train_end = len(train_indices)
        val_end = train_end + len(val_indices)
        if not len(train_indices) or not len(val_indices) or not len(test_indices):
            raise RuntimeError(
                f"[R32-CMP] empty comparator block train={len(train_indices)}, "
                f"val={len(val_indices)}, test={len(test_indices)}")
        # PATCH-A1: attach the drift bank BEFORE the split slices are taken,
        # using this frame's own train_end so no future information enters.
        self.n_drift_bank_cols = 0
        if self.use_drift_bank:
            _bank = attach_drift_bank_block(
                df, target_vars, self.config, X_tab.index, train_end,
                tag=f"cmp:{getattr(self.config, '_dataset_name', '?')}:{self.model_name}")
            if _bank.shape[1]:
                X_tab = X_tab.copy()
                for _c in _bank.columns:
                    X_tab[_c] = _bank[_c].values
                self.n_drift_bank_cols = int(_bank.shape[1])
                print(f"    [A1] {self.model_name}: +{self.n_drift_bank_cols} "
                      f"drift-bank columns -> feature parity with the internal "
                      f"anchor ({X_tab.shape[1]} total).")
            else:
                print(f"    [A1] {self.model_name}: drift bank returned no "
                      f"columns; comparator runs on the base feature set. "
                      f"Any delta-vs-anchor verdict from this arm is NOT "
                      f"feature-matched -- check R17_ENABLE/R17_DRIFT_BANK.")
        X_train = X_tab.loc[train_indices]
        X_val = X_tab.loc[val_indices]
        X_test = X_tab.loc[test_indices]
        y_train = y_tab.loc[train_indices]
        y_val = y_tab.loc[val_indices]
        y_test = y_tab.loc[test_indices]

        
        # y_t - y_{t-1}; the level is reconstructed at predict time by adding
        # lag_1 back. lag1_tab comes from create_tabular_features, so it is the
        # same shifted column the features are built from -- no future value is
        # touched. Splits, features, params and seed are identical to 'level'.
        lag1_train = lag1_tab.loc[train_indices]
        lag1_val = lag1_tab.loc[val_indices]
        lag1_test = lag1_tab.loc[test_indices]
        if self.target_mode == 'delta':
            fit_train = y_train - lag1_train[y_train.columns].values
            fit_val = y_val - lag1_val[y_val.columns].values
        else:
            fit_train, fit_val = y_train, y_val

        models = {}
        for i, var in enumerate(target_vars):
            model = self.model_class(**self.params)
            eval_set = [(X_val, fit_val.iloc[:, i])]
            if 'xgb' in str(self.model_class).lower():
                model.set_params(early_stopping_rounds=50)
                model.fit(X_train, fit_train.iloc[:, i], eval_set=eval_set, verbose=False)
            else:
                model.fit(X_train, fit_train.iloc[:, i], eval_set=eval_set, callbacks=[lgb.early_stopping(50, verbose=False)])
            models[var] = model
        timings = {'Training Time (s)': time.time() - start_time_total}

        start_time_forecast = time.time()
        preds = {}
        for var in target_vars:
            p = models[var].predict(X_test)
            if self.target_mode == 'delta':
                p = p + lag1_test[var].values      # reconstruct the level
            preds[var] = p
        if "LightGBM" in self.model_name and "electric conductivity" in target_vars:
            _ds = getattr(self.config, '_dataset_name', 'unknown')
            np.save(os.path.join(self.config.OUTPUT_DIR,
                                 f"y_pred_lgbm_ec_{_ds}.npy"),
                    preds["electric conductivity"])
        num_forecasts = len(X_test)
        timings['Forecast Time (s)'] = (time.time() - start_time_forecast) / num_forecasts

        
        # per-testbed shared frame; y_test only if neither exists.
        _truth = self.eval_truth_df
        if _truth is None:
            _truth = getattr(self.config, '_eval_truth', None)
        if _truth is not None:
            y_true_mat = _truth.loc[test_indices, target_vars].values
        else:
            y_true_mat = y_test[target_vars].values
        y_pred_mat = np.column_stack([preds[v] for v in target_vars])

        obs_test = None
        fault_test = None
        if self.fault_mask is not None:
            fault_test = self.fault_mask.reindex(test_indices).fillna(False)
        if self.obs_mask is not None:
            obs_test = self.obs_mask.reindex(test_indices).fillna(False)

        results = compute_metrics(y_true_mat, y_pred_mat, y_train, target_vars,
                                  obs_mask=obs_test, fault_mask=fault_test,
                                  kind_masks=_slice_kind_masks(
                                      getattr(self.config, '_kind_masks', {}),
                                      test_indices),
                                  persist_pred=_persist_slice(self.config,
                                                              test_indices,
                                                              target_vars),
                                  config=self.config)
        all_errors = {v: y_true_mat[:, i] - y_pred_mat[:, i]
                      for i, v in enumerate(target_vars)}

        results['eval_protocol'] = EVAL_PROTOCOL_ROLLING_H1
        results['target_mode'] = self.target_mode
        # PATCH-A1: record the realised feature set so no reader has to infer
        # from the class which comparator was feature-matched to the anchor.
        results['uses_drift_bank'] = bool(self.use_drift_bank)
        results['n_drift_bank_cols'] = int(self.n_drift_bank_cols)
        results['n_features'] = int(X_tab.shape[1])
        return results, timings, all_errors


