# ============================================================================


EVAL_PROTOCOL_ROLLING_H1 = "rolling-origin h=1 (observed history, no future info)"
EVAL_PROTOCOL_OPEN_LOOP  = "open-loop h=len(test) (no observed feedback)"
EVAL_PROTOCOL_SEASONAL   = "seasonal lag h=24 (observed t-24)"


def rolling_origin_h1(series_full, val_end, fit_once_fn, forecast_1_fn, stride=1,
                      label=""):
    """Internal experiment utility."""
    n_test = len(series_full) - val_end
    train = series_full.iloc[:val_end]
    fitted = fit_once_fn(train)
    if fitted is None:
        return np.full(n_test, float(np.nanmean(train)))
    out = np.empty(n_test, dtype=float)
    out[:] = np.nan
    last_state, last_origin = None, -10**9
    for k in range(n_test):
        origin = val_end + k
        try:
            if origin - last_origin >= stride or last_state is None:
                last_state = series_full.iloc[:origin]
                last_origin = origin
                out[k] = float(forecast_1_fn(fitted, last_state))
            else:
                out[k] = float(forecast_1_fn(fitted, last_state))
        except Exception as e:
            if k == 0:
                print(f"      [C-T11] {label} rolling forecast failed at k=0: {e}")
            out[k] = out[k - 1] if k else float(np.nanmean(train))
    bad = ~np.isfinite(out)
    if bad.any():
        out[bad] = float(np.nanmean(train))
    return out


def assert_single_protocol(df_results, context=""):
    """Internal experiment utility."""
    if 'eval_protocol' not in df_results.columns:
        return True
    protos = sorted(set(df_results['eval_protocol'].dropna().astype(str)))
    if len(protos) > 1:
        print(f"    [C-T11] WARNING: {context} mixes {len(protos)} evaluation "
              f"protocols -- cross-protocol ordering is NOT a model comparison:")
        for p in protos:
            who = list(df_results.index[df_results['eval_protocol'] == p])
            print(f"        {p}: {len(who)} models e.g. {who[:3]}")
        return False
    return True


class ProphetExperiment(BenchmarkExperiment):
    """Internal experiment utility."""
    def run(self, df, target_vars):
        start_time_total = time.time()
        df_prophet = df.copy()
        df_prophet.index = df_prophet.index.tz_localize(None)
        n = len(df_prophet)
        val_end = int(n * (self.config.TRAIN_SPLIT + self.config.VAL_SPLIT))
        test_dates = df_prophet.index[val_end:]
        steps = len(test_dates)
        stride = max(1, int(getattr(self.config, 'PROPHET_REFIT_STRIDE', 24)))

        preds = {}
        for var in target_vars:
            out = np.full(steps, np.nan, dtype=float)
            k = 0
            while k < steps:
                origin = val_end + k
                hist = df_prophet[[var]].iloc[:origin].reset_index()
                hist.columns = ['ds', 'y']
                hist = hist.dropna()
                chunk = min(stride, steps - k)
                try:
                    m = Prophet()
                    m.fit(hist)
                    future = m.make_future_dataframe(
                        periods=chunk, freq=_freq_of(self.config))   # R16-A
                    fc = m.predict(future)
                    out[k:k + chunk] = fc['yhat'].values[-chunk:]
                except Exception as e:
                    if k == 0:
                        print(f"      [C-T11] Prophet failed for {var} at first origin: {e}")
                    fill = float(hist['y'].iloc[-1]) if len(hist) else 0.0
                    out[k:k + chunk] = out[k - 1] if k else fill
                k += chunk
            bad = ~np.isfinite(out)
            if bad.any():
                out[bad] = float(np.nanmean(df_prophet[var].iloc[:val_end]))
            preds[var] = out

        elapsed = time.time() - start_time_total
        timings = {'Training Time (s)': elapsed,
                   'Forecast Time (s)': elapsed / max(1, steps * len(target_vars))}

        results, all_errors = {}, {}
        test_df = df_prophet.iloc[val_end:]
        train_df = df_prophet.iloc[:int(n * self.config.TRAIN_SPLIT)]
        for var in target_vars:
            y_true_var = test_df[var].values
            y_pred_var = preds[var]
            results[f'{var}_MAE'] = mean_absolute_error(y_true_var, y_pred_var)
            results[f'{var}_RMSE'] = np.sqrt(mean_squared_error(y_true_var, y_pred_var))
            results[f'{var}_MASE'] = calculate_mase(y_true_var, y_pred_var,
                                                    train_df[var].values, seasonality=_seasonality_of(self.config))
            all_errors[var] = y_true_var - y_pred_var
        results['eval_protocol'] = (EVAL_PROTOCOL_ROLLING_H1 if stride == 1
                                    else f"rolling-origin h<={stride} (refit every {stride} steps, observed history)")
        
        results['target_mode'] = 'level'
        return results, timings, all_errors


