# --- SOTA Experiment Classes ---
# ============================================================================

class NeuralForecastExperiment(BenchmarkExperiment):
    def __init__(self, model_name, config, model_cls, model_kwargs, seed=None):
        super().__init__(model_name, config)
        self.model_cls = model_cls
        self.model_kwargs = model_kwargs
        
        # random_seed=self.config.SEED -- a constant -- so all five "seeds"
        # trained bit-identical models and the reported sd was exactly 0.0000
        # for every neural comparator. That is a plumbing artefact, not
        # determinism, and it understated comparator variance to zero while the
        # proposed model carried honest variance. Never compare against it.
        self.seed = config.SEED if seed is None else seed

    def _get_pred_col(self, forecast_df):
        exclude = {'unique_id', 'ds', 'y'}
        cols = [c for c in forecast_df.columns if c not in exclude]
        return cols[0] if cols else forecast_df.columns[-1]

    def run(self, df, target_vars):
        if not NEURALFORECAST_AVAILABLE:
            raise ImportError(f"Install neuralforecast to run {self.model_name}")

        start_time_total = time.time()

        # FIX #1: Single, clean interpolation block with correct indentation.
        # The duplicate block and the IndentationError have been removed.
        # The timings dict typo (start_time_tota) is also fixed here.
        
        # experiment scores against. The three-stage fill that used to live here
        # (both-directions before val_end, forward-only after, then ffill)
        # repaired the neuralforecast INPUT but left df_reg -- the array actually
        # passed to mean_absolute_error -- holding NaN, which is what killed the
        # Belgian run. It also gave the neural comparators a different ground
        # truth from the classical ones on the same testbed.
        df_reg = get_eval_truth(df, self.config, list(target_vars),
                                verbose=False)

        n = len(df_reg)
        val_end = int(n * (self.config.TRAIN_SPLIT + self.config.VAL_SPLIT))

        nf_frames = []
        for var in target_vars:
            tmp = df_reg[[var]].reset_index()
            tmp.columns = ['ds', 'y']
            tmp['unique_id'] = var
            nf_frames.append(tmp[['unique_id', 'ds', 'y']])
        nf_df = pd.concat(nf_frames, ignore_index=True)

        # ------------------------------------------------------------------
        # ['y']" on ANY NaN and there is no fallback that survives it -- the
        # rolling loop then degrades to naive on every step and the run dies
        # at the metric stage with "Input contains NaN". The two fills above
        # cannot close this: `asfreq('h')` INSERTS rows for timestamps that
        # were absent from the source file, those rows are invisible to
        # interp_mask_*.csv (which reports 100% measured for VUB), and a
        # forward-only fill leaves any NaN at the START of the test window
        # untouched. Diagnose and repair here rather than in the loop, so the
        # log names the cause instead of printing 2660 fallback lines.
        # ------------------------------------------------------------------
        _bad = nf_df['y'].isna()
        if _bad.any():
            _by_var = nf_df.loc[_bad].groupby('unique_id').size()
            _cut = df_reg.index[val_end]
            _n_test = int((_bad & (nf_df['ds'] >= _cut)).sum())
            print(f"    [C-T13] {self.model_name}: {int(_bad.sum())} NaN in 'y' "
                  f"AFTER both interpolation passes "
                  f"({_n_test} of them inside the test window).")
            print(f"             per target: {_by_var.to_dict()}")
            _first = nf_df.loc[_bad, 'ds'].min()
            _last = nf_df.loc[_bad, 'ds'].max()
            print(f"             span {_first} -> {_last}. Most likely cause: "
                  f"asfreq('h') inserted rows for gaps in the source index; "
                  f"these are NOT recorded in the observation mask.")
            # Repair per series, both directions, then a constant floor. Any
            # point repaired here is imputed and must not be read as measured
            # -- it is excluded from the observed-only metric by obs_mask,
            # which is unchanged by this block.
            nf_df['y'] = (nf_df.groupby('unique_id')['y']
                          .transform(lambda s: s.interpolate(method='linear',
                                                             limit_direction='both')))
            if nf_df['y'].isna().any():
                nf_df['y'] = nf_df.groupby('unique_id')['y'].transform(
                    lambda s: s.fillna(s.median()))
            if nf_df['y'].isna().any():
                nf_df['y'] = nf_df['y'].fillna(0.0)
                print("             WARNING: a target was entirely NaN; "
                      "filled with 0.0. Its metrics are meaningless -- it "
                      "should be in target_exclusions.csv.")
            print(f"             repaired; {int(nf_df['y'].isna().sum())} NaN remain.")

        train_cutoff = df_reg.index[val_end]
        train_df = nf_df[nf_df['ds'] < train_cutoff].copy()
        test_dates = df_reg.index[val_end:]

        series_len = len(train_df[train_df['unique_id'] == target_vars[0]])
        min_hist = max(self.config.LONG_WINDOW_SIZE, 96)
        if series_len <= min_hist:
            min_hist = max(series_len // 2, 24)

        model = self.model_cls(
            h=1,
            input_size=min_hist,
            random_seed=self.seed,   # R9-C: per-run seed, not the constant
            **_NF_QUIET_KWARGS,      
            **self.model_kwargs
        )
        # pandas 3 removed the uppercase offset aliases: 'H' now raises
        # ValueError("Invalid frequency: H"). This one character silenced BOTH
        
        # were claimed as baselines in the manuscript but produced no number.
        nf = NeuralForecast(models=[model], freq=_freq_of(self.config))  # R16-A
        nf.fit(df=train_df)

        preds = {var: [] for var in target_vars}
        history = train_df.copy()
        start_time_forecast = time.time()

        
        # progress bar per origin. This loop is inference-only -- nf.fit() was
        # called once above and is NOT re-called here -- so the rolling-origin
        # h=1 protocol is unchanged; only the logging volume is.
        _n_dates = len(test_dates)
        _t_roll = time.time()
        for _di, date in enumerate(test_dates):
            if _di % 50 == 0:
                _el = time.time() - _t_roll
                _eta = (_el / _di * (_n_dates - _di)) if _di else float('nan')
                print(f"             [{self.model_name}] origin {_di}/{_n_dates} "
                      f"elapsed {_el:.0f}s eta {_eta:.0f}s", flush=True)
            try:
                forecast = nf.predict(df=history, h=1)
                pred_col = self._get_pred_col(forecast)
                for var in target_vars:
                    var_fc = forecast[forecast['unique_id'] == var]
                    if len(var_fc) == 0:
                        preds[var].append(history[history['unique_id'] == var]['y'].iloc[-1])
                    else:
                        preds[var].append(var_fc[pred_col].values[0])
                
                # The rows are built in target_vars order and appended in that
                # same order, so `history` is byte-identical to what the
                # per-variable loop produced -- this is a copy-count change, not
                
                # ~2,600 full-frame copies per deep baseline.
                _new_rows = []
                for var in target_vars:
                    
                    # nf_df was sanitised above -- appending it would re-poison
                    # `history` and every subsequent predict() call would fail.
                    # Fall back to the last known value for this series.
                    _y = df_reg.loc[date, var]
                    if pd.isna(_y):
                        _prev = history.loc[history['unique_id'] == var, 'y']
                        _y = _prev.iloc[-1] if len(_prev) else 0.0
                    _new_rows.append({'unique_id': var, 'ds': date, 'y': _y})
                history = pd.concat([history, pd.DataFrame(_new_rows)],
                                    ignore_index=True)
            except Exception as e:
                print(f"Rolling predict failed at {date} for {self.model_name}: {e}. Using naive fallback.")
                
                # bypassing the C-T13 NaN guard applied in the success branch
                # twenty lines above. A single NaN entering `history` here makes
                # every subsequent nf.predict() raise, so one transient failure
                # silently converted the rest of the series to naive forecasts --
                # and the model still reported a number. Same guard, same result
                # when the value is clean.
                _new_rows = []
                for var in target_vars:
                    _prev = history.loc[history['unique_id'] == var, 'y']
                    preds[var].append(_prev.iloc[-1] if len(_prev) else 0.0)
                    _y = df_reg.loc[date, var]
                    if pd.isna(_y):
                        _y = _prev.iloc[-1] if len(_prev) else 0.0
                    _new_rows.append({'unique_id': var, 'ds': date, 'y': _y})
                history = pd.concat([history, pd.DataFrame(_new_rows)],
                                    ignore_index=True)

        # FIX #1 (continued): Corrected typo start_time_tota → start_time_total
        timings = {
            'Training Time (s)': time.time() - start_time_total,
        }
        num_forecasts = len(test_dates)
        timings['Forecast Time (s)'] = (time.time() - start_time_forecast) / num_forecasts

        results = {}
        errors = {}
        y_test = df_reg.loc[test_dates, target_vars]
        y_train = df_reg.iloc[:int(n * self.config.TRAIN_SPLIT)][target_vars]

        for var in target_vars:
            y_true = y_test[var].values
            y_pred = np.array(preds[var])
            min_len = min(len(y_true), len(y_pred))
            y_true, y_pred = y_true[:min_len], y_pred[:min_len]
            y_train_var = y_train[var].values
            results[f'{var}_MAE'] = mean_absolute_error(y_true, y_pred)
            results[f'{var}_RMSE'] = np.sqrt(mean_squared_error(y_true, y_pred))
            results[f'{var}_MASE'] = calculate_mase(y_true, y_pred, y_train_var, seasonality=_seasonality_of(self.config))
            results[f'{var}_MASE_1'] = calculate_mase_h1(y_true, y_pred, y_train_var)
            errors[var] = y_true - y_pred

        results['eval_protocol'] = EVAL_PROTOCOL_ROLLING_H1
        results['target_mode'] = 'level'
        return results, timings, errors


class NBEATSExperiment(NeuralForecastExperiment):
    def __init__(self, model_name, config, seed=None):   # R9-C
        super().__init__(model_name, config, NBEATS, {
            'max_steps': 1000, 'scaler_type': 'standard', 'dropout_rate': 0.1
        }, seed=seed)


class NHITSExperiment(NeuralForecastExperiment):
    def __init__(self, model_name, config, seed=None):   # R9-C
        super().__init__(model_name, config, NHITS, {
            'max_steps': 1000, 'scaler_type': 'standard',
            'n_pool_kernel_size': [2, 2, 2], 'n_freq_downsample': [4, 2, 1]
        }, seed=seed)


class PatchTSTExperiment(NeuralForecastExperiment):
    def __init__(self, model_name, config, seed=None):   # R9-C
        kwargs = {
            'max_steps': 1000, 'scaler_type': 'standard',
            'patch_len': 24, 'stride': 12, 'revin': True,
            'hidden_size': 128, 'n_heads': 8,
        }
        if _PATCHTST_SUPPORTS_DIM_FF:
            kwargs['dim_feedforward'] = 256
        super().__init__(model_name, config, PatchTST, kwargs, seed=seed)


class SeasonalNaiveExperiment(BenchmarkExperiment):
    def run(self, df, target_vars):
        start_time_total = time.time()
        n = len(df)
        val_end = int(n * (self.config.TRAIN_SPLIT + self.config.VAL_SPLIT))
        test_dates = df.index[val_end:]
        seasonality = 24

        preds = {}
        for var in target_vars:
            shifted = df[var].shift(seasonality)
            preds[var] = shifted.loc[test_dates].values

        start_time_forecast = time.time()
        timings = {
            'Training Time (s)': time.time() - start_time_total,
            'Forecast Time (s)': time.time() - start_time_forecast
        }

        results, errors = {}, {}
        y_test = df.loc[test_dates, target_vars]
        y_train = df.iloc[:int(n * self.config.TRAIN_SPLIT)][target_vars]

        for var in target_vars:
            y_true = y_test[var].values
            y_pred = preds[var]
            if not np.all(~np.isnan(y_pred)):
                y_pred = np.where(np.isnan(y_pred), y_train[var].iloc[-1], y_pred)
            y_train_var = y_train[var].values
            results[f'{var}_MAE'] = mean_absolute_error(y_true, y_pred)
            results[f'{var}_RMSE'] = np.sqrt(mean_squared_error(y_true, y_pred))
            results[f'{var}_MASE'] = calculate_mase(y_true, y_pred, y_train_var, seasonality=_seasonality_of(self.config))
            errors[var] = y_true - y_pred

        results['eval_protocol'] = EVAL_PROTOCOL_SEASONAL
        
        results['target_mode'] = 'level'
        return results, timings, errors


class PersistenceExperiment(BenchmarkExperiment):
    """Internal experiment utility."""

    def run(self, df, target_vars):
        start_time_total = time.time()
        n = len(df)
        val_end = int(n * (self.config.TRAIN_SPLIT + self.config.VAL_SPLIT))
        test_dates = df.index[val_end:]

        preds = {}
        for var in target_vars:
            preds[var] = df[var].shift(1).loc[test_dates].values

        start_time_forecast = time.time()
        timings = {'Training Time (s)': time.time() - start_time_total,
                   'Forecast Time (s)': time.time() - start_time_forecast}

        results, errors = {}, {}
        y_test = df.loc[test_dates, target_vars]
        y_train = df.iloc[:int(n * self.config.TRAIN_SPLIT)][target_vars]
        for var in target_vars:
            y_true = y_test[var].values
            y_pred = preds[var]
            if np.any(np.isnan(y_pred)):
                # only the first test point can be NaN (its t-1 predecessor is
                # the last val point, which exists); guard anyway.
                y_pred = np.where(np.isnan(y_pred), y_train[var].iloc[-1], y_pred)
            yt = y_train[var].values
            results[f'{var}_MAE'] = mean_absolute_error(y_true, y_pred)
            results[f'{var}_RMSE'] = np.sqrt(mean_squared_error(y_true, y_pred))
            results[f'{var}_MASE'] = calculate_mase(y_true, y_pred, yt, seasonality=_seasonality_of(self.config))
            results[f'{var}_MASE_1'] = calculate_mase_h1(y_true, y_pred, yt)
            errors[var] = y_true - y_pred

        results['eval_protocol'] = EVAL_PROTOCOL_ROLLING_H1
        results['target_mode'] = 'level'
        return results, timings, errors


class ThetaExperiment(BenchmarkExperiment):
    """Internal experiment utility."""
    def run(self, df, target_vars):
        start_time_total = time.time()
        n = len(df)
        val_end = int(n * (self.config.TRAIN_SPLIT + self.config.VAL_SPLIT))
        test_dates = df.index[val_end:]
        steps = len(test_dates)
        stride = int(getattr(self.config, 'ROLLING_STRIDE', 1))

        preds = {}
        for var in target_vars:
            # regularising onto a finer grid than the source manufactures the
            # majority of the rows a classical model is then scored on.
            full = df[var].asfreq(_freq_of(self.config)).interpolate(method='linear')
            if len(full.iloc[:val_end].dropna()) < 24 * 2:
                preds[var] = np.full(steps, float(full.iloc[:val_end].mean()))
                continue
            # Theta is cheap to refit (~0.02 s), so each origin gets a genuine
            # refit on observed history only -- no future information used.
            def _fit_once(train_series):
                return True

            def _fc1(_unused, history):
                return ThetaModel(
                history,
                period=_seasonality_of(self.config)   # R16-A: not a fixed 24
            ).fit().forecast(1).iloc[0]

            preds[var] = rolling_origin_h1(full, val_end, _fit_once, _fc1,
                                           stride=stride, label=f"Theta/{var}")

        elapsed = time.time() - start_time_total
        timings = {'Training Time (s)': elapsed,
                   'Forecast Time (s)': elapsed / max(1, steps * len(target_vars))}

        results, errors = {}, {}
        y_test = df.loc[test_dates, target_vars]
        y_train = df.iloc[:int(n * self.config.TRAIN_SPLIT)][target_vars]
        for var in target_vars:
            y_true = y_test[var].values
            y_pred = preds[var]
            results[f'{var}_MAE'] = mean_absolute_error(y_true, y_pred)
            results[f'{var}_RMSE'] = np.sqrt(mean_squared_error(y_true, y_pred))
            results[f'{var}_MASE'] = calculate_mase(y_true, y_pred, y_train[var].values, seasonality=_seasonality_of(self.config))
            errors[var] = y_true - y_pred
        results['eval_protocol'] = EVAL_PROTOCOL_ROLLING_H1
        
        results['target_mode'] = 'level'
        return results, timings, errors


class ExponentialSmoothingExperiment(BenchmarkExperiment):
    """Internal experiment utility."""
    def run(self, df, target_vars):
        start_time_total = time.time()
        n = len(df)
        val_end = int(n * (self.config.TRAIN_SPLIT + self.config.VAL_SPLIT))
        test_dates = df.index[val_end:]
        steps = len(test_dates)
        stride = int(getattr(self.config, 'ROLLING_STRIDE', 1))

        preds = {}
        for var in target_vars:
            # asfreq('h') -- lowercase: 'H' was removed in pandas 3 (see C-T fix)
            # regularising onto a finer grid than the source manufactures the
            # majority of the rows a classical model is then scored on.
            full = df[var].asfreq(_freq_of(self.config)).interpolate(method='linear')
            if len(full.iloc[:val_end].dropna()) < 24 * 2:
                preds[var] = np.full(steps, float(full.iloc[:val_end].mean()))
                continue

            def _fit_once(train_series):
                try:
                    m = ETSModel(train_series, error='add', trend='add',
                                 seasonal='add', seasonal_periods=24,
                                 damped_trend=True)
                    return m.fit(disp=False)
                except Exception as e:
                    print(f"      [C-T11] ETS fit failed for {var}: {e}")
                    return None

            def _fc1(fitted, history):
                
                # history, then step one ahead. No refit, no future info.
                r = ETSModel(history, error='add', trend='add', seasonal='add',
                             seasonal_periods=24, damped_trend=True
                             ).smooth(fitted.params)
                return r.forecast(1).iloc[0]

            preds[var] = rolling_origin_h1(full, val_end, _fit_once, _fc1,
                                           stride=stride, label=f"ETS/{var}")

        elapsed = time.time() - start_time_total
        timings = {'Training Time (s)': elapsed,
                   'Forecast Time (s)': elapsed / max(1, steps * len(target_vars))}

        results, errors = {}, {}
        y_test = df.loc[test_dates, target_vars]
        y_train = df.iloc[:int(n * self.config.TRAIN_SPLIT)][target_vars]
        for var in target_vars:
            y_true = y_test[var].values
            y_pred = preds[var]
            y_train_var = y_train[var].values
            results[f'{var}_MAE'] = mean_absolute_error(y_true, y_pred)
            results[f'{var}_RMSE'] = np.sqrt(mean_squared_error(y_true, y_pred))
            results[f'{var}_MASE'] = calculate_mase(y_true, y_pred, y_train_var, seasonality=_seasonality_of(self.config))
            errors[var] = y_true - y_pred
        results['eval_protocol'] = EVAL_PROTOCOL_ROLLING_H1
        
        results['target_mode'] = 'level'
        return results, timings, errors


class PhysicsGuidedMLPExperiment(BenchmarkExperiment):
    def __init__(self, model_name, config, lambda_physics=0.01):
        super().__init__(model_name, config)
        self.lambda_physics = lambda_physics

    def run(self, df, target_vars):
        start_time_total = time.time()
        y_tab = df[target_vars]
        train_end_idx = int(len(df) * self.config.TRAIN_SPLIT)

        scaler_y = MinMaxScaler().fit(y_tab.iloc[:train_end_idx])
        y_tab_scaled = pd.DataFrame(scaler_y.transform(y_tab), columns=target_vars, index=y_tab.index)

        df_m2p_input = df.copy()
        time_features = ['hour_sin', 'hour_cos']
        df_m2p_input['hour_sin'] = np.sin(2 * np.pi * df.index.hour / 24.0)
        df_m2p_input['hour_cos'] = np.cos(2 * np.pi * df.index.hour / 24.0)

        feature_cols = [c for c in df.columns if c in target_vars]
        scaler_x = MinMaxScaler().fit(df_m2p_input.iloc[:train_end_idx][feature_cols])
        df_scaled_features = pd.DataFrame(
            scaler_x.transform(df_m2p_input[feature_cols]),
            columns=feature_cols, index=df.index
        )
        df_scaled_features[time_features] = df_m2p_input[time_features]

        X_m2p_full, m2p_indices = create_m2p_features(df_scaled_features, target_vars, time_features, self.config)
        common_indices = y_tab.index.intersection(m2p_indices)
        y_m2p_target = y_tab_scaled.loc[common_indices].values

        X_m2p_short_aligned = (
            pd.DataFrame([r.flatten() for r in X_m2p_full['short_term_input']], index=m2p_indices)
            .loc[common_indices].values
            .reshape(len(common_indices), self.config.SHORT_WINDOW_SIZE, -1)
        )
        X_m2p_long_aligned = (
            pd.DataFrame([r.flatten() for r in X_m2p_full['long_term_input']], index=m2p_indices)
            .loc[common_indices].values
            .reshape(len(common_indices), self.config.LONG_WINDOW_SIZE, -1)
        )
        X_short_flat = X_m2p_short_aligned.reshape(X_m2p_short_aligned.shape[0], -1)
        X_long_flat = X_m2p_long_aligned.reshape(X_m2p_long_aligned.shape[0], -1)
        X_unified = np.concatenate([X_short_flat, X_long_flat], axis=1)

        train_end = int(len(common_indices) * self.config.TRAIN_SPLIT)
        val_end = int(len(common_indices) * (self.config.TRAIN_SPLIT + self.config.VAL_SPLIT))

        # FIX #2: build_physics_mlp takes only a single flat input.
        # Removed all X_ctx variables — they are unused by this model.
        X_train_m2p = X_unified[:train_end]
        X_val_m2p = X_unified[train_end:val_end]
        X_test_m2p = X_unified[val_end:]
        y_train_m2p = y_m2p_target[:train_end]
        y_val_m2p = y_m2p_target[train_end:val_end]

        tf.keras.backend.clear_session()
        model = build_physics_mlp(
            input_dim=X_train_m2p.shape[1],
            target_vars=target_vars,
            config=self.config
        )

        def make_physics_loss(var_name):
            base_huber = tf.keras.losses.Huber()
            lambda_p = self.lambda_physics
            def loss_fn(y_true, y_pred):
                huber = base_huber(y_true, y_pred)
                phys = 0.0
                if var_name == 'ph':
                    phys += tf.reduce_mean(
                        tf.maximum(0.0, 6.0 - y_pred) + tf.maximum(0.0, y_pred - 9.0)
                    )
                if var_name == 'electric conductivity':
                    phys += tf.reduce_mean(tf.maximum(0.0, -y_pred))
                return huber + lambda_p * phys
            return loss_fn

        optimizer = tf.keras.optimizers.Adam(learning_rate=self.config.LEARNING_RATE, clipnorm=1.0)
        model.compile(optimizer=optimizer, loss=[make_physics_loss(var) for var in target_vars])

        # FIX #2 (continued): Single input — no context input list wrapping
        model.fit(
            x=X_train_m2p,
            y=[y_train_m2p[:, i] for i in range(len(target_vars))],
            validation_data=(X_val_m2p, [y_val_m2p[:, i] for i in range(len(target_vars))]),
            epochs=self.config.EPOCHS,
            batch_size=self.config.BATCH_SIZE,
            callbacks=[keras.callbacks.EarlyStopping(
                monitor='val_loss', patience=self.config.PATIENCE, restore_best_weights=True
            )],
            verbose=0
        )
        timings = {'Training Time (s)': time.time() - start_time_total}

        start_time_forecast = time.time()
        # FIX #2 (continued): Single input to predict
        preds_scaled = np.array(model.predict(X_test_m2p, verbose=0)).T.reshape(-1, len(target_vars))  
        timings['Forecast Time (s)'] = time.time() - start_time_forecast

        final_prediction = scaler_y.inverse_transform(preds_scaled)
        y_true_final = y_tab.loc[common_indices[val_end:]].values

        results = {}
        y_train_unscaled = y_tab.loc[common_indices[:train_end]]
        errors_raw = y_true_final - final_prediction
        errors_dict = {}

        for i, name in enumerate(target_vars):
            y_true_var = y_true_final[:, i]
            y_pred_var = final_prediction[:, i]
            y_train_var = y_train_unscaled[name].values
            results[f'{name}_MAE'] = mean_absolute_error(y_true_var, y_pred_var)
            results[f'{name}_RMSE'] = np.sqrt(mean_squared_error(y_true_var, y_pred_var))
            results[f'{name}_MASE'] = calculate_mase(y_true_var, y_pred_var, y_train_var, seasonality=_seasonality_of(self.config))
            errors_dict[name] = errors_raw[:, i]

        results['eval_protocol'] = EVAL_PROTOCOL_ROLLING_H1
        
        results['target_mode'] = 'level'
        return results, timings, errors_dict


class GreyBoxXGBExperiment(BenchmarkExperiment):
    def __init__(self, model_name, config, seed=None):
        super().__init__(model_name, config)
        
        # several targets, which makes a fake zero variance the most misleading
        # number in the table.
        self.seed = config.SEED if seed is None else seed

    def run(self, df, target_vars):
        start_time_total = time.time()
        df_aug = df.copy()

        if 'temperature' in df_aug.columns:
            df_aug['do_sat_proxy'] = 14.5 - 0.39 * df_aug['temperature'] + 0.007 * (df_aug['temperature'] - 20)**2

        if 'ph' in df_aug.columns and 'electric conductivity' in df_aug.columns:
            df_aug['ph_cond_interaction'] = df_aug['ph'] * np.log1p(df_aug['electric conductivity'])

        X_tab, y_tab = create_tabular_features(df_aug, target_vars,
                                               config=self.config)   # R16-A/C
        train_end = int(len(y_tab) * self.config.TRAIN_SPLIT)
        val_end = int(len(y_tab) * (self.config.TRAIN_SPLIT + self.config.VAL_SPLIT))
        train_idx = X_tab.index[:train_end]
        val_idx = X_tab.index[train_end:val_end]
        test_idx = X_tab.index[val_end:]

        X_train = X_tab.loc[train_idx]
        X_val = X_tab.loc[val_idx]
        X_test = X_tab.loc[test_idx]
        y_train = y_tab.loc[train_idx]
        y_val = y_tab.loc[val_idx]
        y_test = y_tab.loc[test_idx]

        models = {}
        for i, var in enumerate(target_vars):
            model = xgb.XGBRegressor(
                objective='reg:squarederror', n_estimators=1000,
                learning_rate=0.01, random_state=self.seed,   # R9-C
                n_jobs=-1, early_stopping_rounds=50
            )
            model.fit(X_train, y_train.iloc[:, i], eval_set=[(X_val, y_val.iloc[:, i])], verbose=False)
            models[var] = model

        timings = {'Training Time (s)': time.time() - start_time_total}

        start_time_forecast = time.time()
        preds = {var: models[var].predict(X_test) for var in target_vars}
        timings['Forecast Time (s)'] = time.time() - start_time_forecast

        results = {}
        all_errors = {}
        for var in target_vars:
            y_true_var = y_test[var].values
            y_pred_var = preds[var]
            y_train_var = y_train[var].values
            results[f'{var}_MAE'] = mean_absolute_error(y_true_var, y_pred_var)
            results[f'{var}_RMSE'] = np.sqrt(mean_squared_error(y_true_var, y_pred_var))
            results[f'{var}_MASE'] = calculate_mase(y_true_var, y_pred_var, y_train_var, seasonality=_seasonality_of(self.config))
            all_errors[var] = y_true_var - y_pred_var

        results['eval_protocol'] = EVAL_PROTOCOL_ROLLING_H1
        
        results['target_mode'] = 'level'
        return results, timings, all_errors


# ============================================================================
# --- Analysis & Plotting Functions ---
# ============================================================================

def calculate_rank_biserial(x, y):
    try:
        u_stat, _ = mannwhitneyu(x, y, alternative='two-sided')
        n1, n2 = len(x), len(y)
        return 1 - (2 * u_stat) / (n1 * n2)
    except:
        return 0.0


def bootstrap_ci(data, n_boot=2000, ci=95):
    if len(data) < 2:
        return 0.0, 0.0
    data = np.array(data)
    indices = np.random.randint(0, len(data), (n_boot, len(data)))
    samples = data[indices]
    means = np.mean(samples, axis=1)
    lower = np.percentile(means, (100 - ci) / 2)
    upper = np.percentile(means, 100 - (100 - ci) / 2)
    return lower, upper


def correction_reliability_diagnostics(errors_dict, results_df, target_vars,
                                       dataset_name, config, corrections=None,
                                       selected_arm=None):
    """Internal experiment utility."""
    if corrections is None or not len(corrections):
        print(f"    [C-T2] no correction magnitudes recorded for "
              f"{dataset_name}; skipping reliability diagnostics.")
        return None

    C = np.asarray(corrections, dtype=float)          # (n_points, n_targets)
    rows = []
    fig, axes = plt.subplots(1, 3, figsize=(13.2, 3.6))

    # ---- (i) |error| vs |delta|, binned ------------------------------------
    ax = axes[0]
    
    # |delta|, so the error series and the correction array must come from the
    # SAME arm. The prefix match returned C=0.0001 while `corrections` is the
    # conformal/ablation arm's own array, pairing one arm's errors with
    # another's corrections.
    prop = (selected_arm if (selected_arm is not None
                             and selected_arm in errors_dict)
            else next((k for k in errors_dict if k.startswith('M2P-PTAC')), None))
    if selected_arm is not None and prop != selected_arm:
        print(f"    [C-T2] PATCH-D1: selected arm '{selected_arm}' absent; "
              f"panel (i) falls back to '{prop}'.")
    if prop:
        for j, v in enumerate(target_vars):
            if v not in errors_dict[prop] or j >= C.shape[1]:
                continue
            e = np.abs(np.asarray(errors_dict[prop][v], dtype=float))
            d = np.abs(C[:, j])
            m = min(len(e), len(d))
            e, d = e[:m], d[:m]
            ok = np.isfinite(e) & np.isfinite(d)
            if ok.sum() < 30:
                continue
            e, d = e[ok], d[ok]
            # Deciles of correction magnitude; median error within each.
            qs = np.quantile(d, np.linspace(0, 1, 11))
            qs = np.unique(qs)
            if len(qs) < 3:
                continue
            idx = np.clip(np.digitize(d, qs[1:-1]), 0, len(qs) - 2)
            xs, ys = [], []
            for b in range(len(qs) - 1):
                sel = idx == b
                if sel.sum() < 5:
                    continue
                xs.append(float(np.median(d[sel])))
                ys.append(float(np.median(e[sel])))
                rows.append(dict(dataset=dataset_name, target=v, bin=b,
                                 median_abs_correction=xs[-1],
                                 median_abs_error=ys[-1], n=int(sel.sum())))
            if xs:
                ax.plot(xs, ys, 'o-', ms=3, lw=1.1, label=v[:16])
    ax.set_xlabel(r'$|\Delta|$ (correction magnitude)')
    ax.set_ylabel('median |error|')
    ax.set_title('(i) error vs correction size', loc='left', fontsize=9)
    ax.legend(frameon=False, fontsize=6)

    # ---- (ii) histogram of corrections with both bounds -------------------
    ax = axes[1]
    flat = np.abs(C[np.isfinite(C)]).ravel()
    if len(flat):
        ax.hist(flat, bins=60, color='#4C72B0', alpha=0.75,
                label=r'$|\Delta|$ (all targets)')
        ax.set_yscale('log')
        conf_cols = [c for c in results_df.columns if c.endswith('_ConfBound')]
        if conf_cols:
            cb = pd.to_numeric(results_df[conf_cols].stack(),
                               errors='coerce').dropna()
            if len(cb):
                ax.axvline(cb.median(), color='#C44E52', lw=1.6,
                           label='conformal bound (median)')
        ks = pd.to_numeric(results_df.get('clip_k'), errors='coerce').dropna()
        # k*sigma is per-target; reconstruct the smallest one actually used.
        if len(ks):
            ax.axvline(flat.max() * 1.001, color='#55A868', ls='--', lw=1.2,
                       label='max observed $|\\Delta|$')
    ax.set_xlabel(r'$|\Delta|$'); ax.set_ylabel('count (log)')
    ax.set_title('(ii) correction distribution vs bounds', loc='left', fontsize=9)
    ax.legend(frameon=False, fontsize=6)

    # ---- (iii) empirical bind curve vs k ----------------------------------
    ax = axes[2]
    ks = np.linspace(0.05, 3.0, 40)
    # sigma per target taken from the spread of the corrections themselves AND
    
    sig_corr = np.nanstd(C, axis=0)
    for label, sig, col in [('$k\\cdot\\sigma_{\\Delta}$ (correction scale)',
                             sig_corr, '#C44E52'),
                            ('$k\\cdot\\sigma_{\\mathrm{train}}$ (as submitted)',
                             sig_corr * 0 + np.nan, '#4C72B0')]:
        if not np.all(np.isfinite(sig)):
            continue
        frac = [float(np.nanmean(np.abs(C) > (k * sig))) for k in ks]
        ax.plot(ks, frac, lw=1.5, color=col, label=label)
        for k, f in zip(ks, frac):
            rows.append(dict(dataset=dataset_name, target='__all__',
                             k=float(k), bind_fraction=float(f),
                             scaling=label))
    ax.axhline(config.DEFAULT_CONFORMAL_ALPHA, ls=':', color='#555', lw=1.0,
               label=f'nominal $\\alpha$={config.DEFAULT_CONFORMAL_ALPHA}')
    ax.set_xlabel('$k$'); ax.set_ylabel(r'fraction $|\Delta| > k\sigma$')
    ax.set_title('(iii) empirical bind curve', loc='left', fontsize=9)
    ax.legend(frameon=False, fontsize=6)

    fig.suptitle(f'Correction reliability -- {dataset_name}', fontsize=10,
                 x=0.01, ha='left', fontweight='bold')
    fig.tight_layout()
    out = os.path.join(config.OUTPUT_DIR,
                       f'correction_reliability_{dataset_name}.png')
    fig.savefig(out, dpi=200, bbox_inches='tight')
    plt.close(fig)
    if rows:
        pd.DataFrame(rows).to_csv(os.path.join(
            config.OUTPUT_DIR, f'correction_reliability_{dataset_name}.csv'),
            index=False)
    print(f"    [C-T2] wrote {os.path.basename(out)}")
    return out


def build_pareto_table(config, datasets=('stable', 'challenged_90234',
                                         'challenged_89509', 'belgian_vub')):
    """Internal experiment utility."""
    frames = []
    for ds in datasets:
        mp = os.path.join(config.OUTPUT_DIR, f'final_results_metrics_{ds}.csv')
        tp = os.path.join(config.OUTPUT_DIR, f'final_results_timings_{ds}.csv')
        if not os.path.exists(mp):
            continue
        M = pd.read_csv(mp, index_col=0)
        T = pd.read_csv(tp, index_col=0) if os.path.exists(tp) else pd.DataFrame()
        keep = {}
        for c in ['Primary_Macro_MAE', 'Macro_MAE_obs',
                  'Macro_MAE_obs_ex_degen', 'Macro_MAE',
                  'Macro_MAE_ex_degen', 'Mean_MASE',
                  'electric conductivity_MAE', 'realised_bind_rate',
                  'n_physical_violations']:
            if c in M.columns:
                keep[c] = pd.to_numeric(M[c], errors='coerce')
        D = pd.DataFrame(keep)
        for c in T.columns:
            if pd.api.types.is_numeric_dtype(T[c]) or 'time' in c.lower() or 'param' in c.lower():
                D[c] = pd.to_numeric(T[c], errors='coerce')
        D.insert(0, 'dataset', ds)
        D.index.name = 'model'
        frames.append(D.reset_index())
    if not frames:
        print("    [C-T6] no metrics CSVs found; run the benchmark first.")
        return None
    P = pd.concat(frames, ignore_index=True)
    out_csv = os.path.join(config.OUTPUT_DIR, 'pareto_all_datasets.csv')
    P.to_csv(out_csv, index=False)

    # Cost axis: inference latency is the operational cost for a deployed
    # sensor-network forecaster (it is paid every cycle); training time is paid
    # once. Prefer inference, fall back to training, and label whichever is used
    # so the figure cannot be read as the other.
    # The timings CSV names this column 'Forecast Time (s)'; matching only on
    # 'inference' silently fell through to 'Training Time (s)' and plotted the
    # wrong cost axis with no error.
    time_col = next((c for c in P.columns
                     if any(k in c.lower()
                            for k in ('inference', 'inf_time', 'forecast'))), None)
    cost_kind = 'inference latency (per-cycle cost)'
    if time_col is None:
        time_col = next((c for c in P.columns if 'time' in c.lower()), None)
        cost_kind = 'training time (one-off cost)'
    if time_col is not None:
        print(f"    [C-T6] cost axis = '{time_col}' ({cost_kind}).")
    accuracy_col = next((c for c in ('Primary_Macro_MAE',
                                     'Macro_MAE_obs_ex_degen',
                                     'Macro_MAE_obs', 'Macro_MAE_ex_degen',
                                     'Macro_MAE')
                         if c in P.columns), None)
    if time_col and accuracy_col is not None:
        print(f"    [C-T6] accuracy axis = '{accuracy_col}'.")
        ds_list = [d for d in P.dataset.unique()]
        fig, axes = plt.subplots(1, len(ds_list),
                                 figsize=(3.6 * len(ds_list), 3.6), squeeze=False)
        fig.suptitle(f'C-T6: accuracy vs cost  --  cost = {cost_kind}',
                     fontsize=10, y=0.99)
        for ax, ds in zip(axes[0], ds_list):
            sub = P[(P.dataset == ds)].dropna(subset=[accuracy_col, time_col])
            # A log axis cannot show a zero or negative time. Timing resolution
            # can round a fast model to 0.0; drop those rather than let
            # matplotlib silently discard them, and say how many were dropped.
            n_before = len(sub)
            sub = sub[sub[time_col] > 0]
            if len(sub) < n_before:
                print(f"    [C-T6] {ds}: dropped {n_before - len(sub)} model(s) "
                      f"with non-positive {time_col} (below timing resolution).")
            if not len(sub):
                continue
            ax.scatter(sub[time_col], sub[accuracy_col], s=18,
                       color='#4C72B0')
            # Non-dominated set: nothing both faster and more accurate.
            # Indexed by position, not by attribute: the timing column name is
            # 'Training Time (s)', which itertuples() silently renames to a
            # positional placeholder, so getattr(row, time_col) raised
            # AttributeError and lost the whole figure.
            tvals = sub[time_col].to_numpy()
            mvals = sub[accuracy_col].to_numpy()
            names = sub['model'].to_numpy()
            nd = []
            for a in range(len(sub)):
                dominated = (((tvals <= tvals[a]) & (mvals <= mvals[a]) &
                              ((tvals < tvals[a]) | (mvals < mvals[a])))).any()
                if not dominated:
                    nd.append(names[a])
            f = sub[sub.model.isin(nd)].sort_values(time_col)
            ax.plot(f[time_col], f[accuracy_col], 'o-', color='#C44E52', ms=5,
                    lw=1.3, label='Pareto frontier')
            for tv, mv, nm in zip(f[time_col].to_numpy(),
                                  f[accuracy_col].to_numpy(),
                                  f['model'].to_numpy()):
                ax.annotate(str(nm)[:18], (tv, mv),
                            xytext=(3, 3), textcoords='offset points', fontsize=5.5)
            # Inference times span orders of magnitude (SeasonalNaive is ~1e-6 s,
            # the deep models ~1e0), so a linear axis collapses every model of
            # interest onto x=0. Log axis; the cost kind moves to the suptitle
            # because repeating it under four panels made the labels collide.
            ax.set_xscale('log')
            ax.set_xlabel(time_col)
            ax.set_ylabel(accuracy_col.replace('_', ' '))
            ax.set_title(ds, fontsize=9, loc='left')
            ax.set_yscale('log'); ax.legend(frameon=False, fontsize=6)
        fig.tight_layout()
        fig.savefig(os.path.join(config.OUTPUT_DIR, 'pareto_all_datasets.png'),
                    dpi=200, bbox_inches='tight')
        plt.close(fig)
    print(f"    [C-T6] wrote pareto_all_datasets.csv ({len(P)} rows) + plot.")
    return out_csv


def significance_report(errors_dict, target_vars, proposed='M2P-PTAC',
                        internal_baseline='XGBoost Baseline', n_boot=2000,
                        selected_arm=None, dataset_name=None,
                        abstention=None, baseline_matched=None):
    """Internal experiment utility."""
    dm_rows, nested_rows = [], []
    # ---- PATCH-D1: authoritative arm resolution -------------------------
    if selected_arm is not None and selected_arm in errors_dict:
        prop_key = selected_arm
        _resolution = 'validation-selected arm (explicit)'
    elif selected_arm is not None:
        # Asked for a specific arm and it is absent: refuse rather than
        # silently fall back to a different arm and label it as the selected
        # one. A wrong-arm verdict is worse than a missing verdict.
        print(f"    [sig] PATCH-D1: selected arm '{selected_arm}' is absent "
              f"from errors_dict (keys present: {len(errors_dict)}). Refusing "
              f"to substitute another M2P arm -- no significance CSV written "
              f"for this call.")
        return pd.DataFrame(), pd.DataFrame()
    else:
        prop_key = next((k for k in errors_dict if k.startswith(proposed)), None)
        _resolution = 'first prefix match (NO selected arm supplied)'
        if prop_key is not None:
            print(f"    [sig] PATCH-D1 WARNING: no selected_arm given; fell "
                  f"back to first prefix match '{prop_key}'. This may not be "
                  f"the arm the benchmark reports.")
    if prop_key is None:
        print(f"    [sig] no model matching '{proposed}' -- skipping.")
        return pd.DataFrame(), pd.DataFrame()
    print(f"    [sig] proposed arm under test: '{prop_key}' "
          f"({_resolution}); internal baseline: '{internal_baseline}'.")

    # ---- (1) non-nested comparators -----------------------------------
    for other in errors_dict:
        if other == prop_key:
            continue
        nested = (other == internal_baseline)
        pv, recs = [], []
        for v in target_vars:
            if v not in errors_dict[prop_key] or v not in errors_dict.get(other, {}):
                continue
            a, b = _align_error_pair(errors_dict[prop_key][v],
                                     errors_dict[other][v])
            stat, p, n = dm_test_hln(a, b, h=1, power=1)
            recs.append(dict(comparator=other, target=v, dm_stat=stat, p_raw=p, n=n,
                             mae_proposed=float(np.nanmean(np.abs(a))),
                             mae_comparator=float(np.nanmean(np.abs(b)))))
            pv.append(p)
        if not recs:
            continue
        adj = holm_correct(pv)
        for r, pa in zip(recs, adj):
            r['p_holm'] = float(pa) if np.isfinite(pa) else np.nan
            r['favours'] = ('proposed' if r['mae_proposed'] < r['mae_comparator']
                            else 'comparator')
            r['valid_test'] = not nested
            r['note'] = ('DM INVALID -- nested pair, see nested table'
                         if nested else 'DM valid (non-nested)')
        dm_rows += recs

    # ---- (2) the nested pair, done properly ----------------------------
    if internal_baseline in errors_dict:
        # ---------------------------------------------------------- PATCH-A2
        _abst = dict(abstention or {})
        _per_t = dict(_abst.get('per_target', {}) or {})
        _tol = float(_abst.get('tol', 1e-12))
        _pass_all = bool(_abst.get('passthrough', False))
        for v in target_vars:
            if v not in errors_dict[prop_key] or v not in errors_dict[internal_baseline]:
                continue
            a, b = _align_error_pair(errors_dict[prop_key][v],
                                     errors_dict[internal_baseline][v])
            bs = paired_bootstrap_mae(a, b, n_boot=n_boot, seed=0)
            # PATCH-A2: did the gate actually apply a correction on THIS
            # channel? Absent information, fall back to the arm-level
            # passthrough flag; absent that too, treat as applicable (the
            # pre-patch behaviour) but say so in the record.
            _ti = dict(_per_t.get(v, {}) or {})
            _mx = _ti.get('max_abs_correction', np.nan)
            if np.isfinite(_mx if _mx is not None else np.nan):
                _applied = bool(float(_mx) > _tol)
                _basis = 'per-channel max applied correction'
            elif _abst:
                _applied = not _pass_all
                _basis = 'arm-level passthrough flag'
            else:
                _applied = True
                _basis = 'no gate record supplied (assumed applied)'
            _stat_verdict = ('correction helps' if bs['hi'] < 0 else
                             'correction hurts' if bs['lo'] > 0 else
                             'indistinguishable from baseline')
            if _applied:
                _verdict = _stat_verdict
                _parity_warn = False
            else:
                # Zero correction: with a MATCHED baseline the arrays are
                # identical by construction, so any nonzero delta is a
                # fit/feature discrepancy rather than an effect. Against an
                # unmatched baseline a nonzero delta is expected (target-mode
                
                _verdict = 'not applicable (gate abstained)'
                _parity_warn = bool(baseline_matched
                                    and abs(float(bs['point'])) > 1e-9)
            nested_rows.append(dict(
                target=v, mae_corrected=float(np.nanmean(np.abs(a))),
                mae_baseline=float(np.nanmean(np.abs(b))),
                delta_mae=bs['point'], ci_lo=bs['lo'], ci_hi=bs['hi'],
                n=bs['n'], frac_favouring_corrected=bs.get('frac_favouring_a', np.nan),
                bootstrap_method=bs.get('method', 'unavailable'),
                bootstrap_block_len=bs.get('block_len', np.nan),
                gate_applied_correction=bool(_applied),
                max_abs_applied_correction=(float(_mx) if np.isfinite(
                    _mx if _mx is not None else np.nan) else np.nan),
                abstention_basis=_basis,
                applicable=bool(_applied),
                statistical_verdict=_stat_verdict,
                parity_warning=bool(_parity_warn),
                verdict=_verdict))
        _na = [r for r in nested_rows if not r['applicable']]
        if _na:
            print(f"    [A2] {len(_na)} of {len(nested_rows)} channel(s) had a "
                  f"ZERO applied correction; recorded as 'not applicable (gate "
                  f"abstained)' rather than a corrector verdict: "
                  f"{[r['target'] for r in _na]}")
            _pw = [r['target'] for r in _na if r['parity_warning']]
            if _pw:
                print(f"    [A2] PARITY WARNING: channels {_pw} show a nonzero "
                      f"MAE discrepancy despite a zero applied correction "
                      f"against '{internal_baseline}', which is declared "
                      f"feature- and target-matched. That difference must be "
                      f"zero; a nonzero value means the two arms do not in fact "
                      f"share a feature set (PATCH-A1).")
            elif not baseline_matched:
                print(f"    [A2] (no parity check: '{internal_baseline}' is not "
                      f"declared matched to the corrected arm, so a nonzero "
                      f"discrepancy under a zero correction is expected -- it is "
                      f"the target-mode/feature difference, not the corrector.)")

    dm_df = pd.DataFrame(dm_rows)
    nested_df = pd.DataFrame(nested_rows)
    # ---- PATCH-D1: stamp identity onto BOTH frames ----------------------
    # The caller used to add 'internal_baseline'/'baseline_target_mode' to the
    # nested frame only, and nothing recorded WHICH M2P arm was tested. With
    # 14 M2P arms per testbed a CSV that names only 'M2P-PTAC' is not
    # attributable, which is how the displaced arm went unnoticed.
    _bt_mode = ('delta' if 'differenced' in str(internal_baseline)
                else 'level' if internal_baseline == 'XGBoost Baseline'
                else 'unknown')
    for _df in (dm_df, nested_df):
        if len(_df):
            _df['proposed_model'] = proposed
            _df['selected_arm'] = prop_key
            _df['arm_resolution'] = _resolution
            _df['internal_baseline'] = internal_baseline
            _df['baseline_target_mode'] = _bt_mode
            if dataset_name is not None:
                _df['dataset'] = dataset_name
    if len(nested_df):
        print("\n    [sig] NESTED comparison (corrected vs its own baseline), "
              "paired bootstrap:")
        for r in nested_df.itertuples():
            print(f"      {r.target:24s} dMAE={r.delta_mae:+.4f} "
                  f"[{r.ci_lo:+.4f}, {r.ci_hi:+.4f}]  {r.verdict}")
    if len(dm_df):
        valid = dm_df[dm_df.valid_test]
        sig = valid[(valid.p_holm < 0.05) & (valid.favours == 'proposed')]
        print(f"    [sig] DM on non-nested pairs: {len(sig)}/{len(valid)} "
              f"target-comparator cells significant in favour of the proposed model "
              f"(Holm-adjusted, alpha=0.05).")
    return dm_df, nested_df


def aggregate_over_seeds(per_seed_frames, id_col='model_name'):
    """Internal experiment utility."""
    if not per_seed_frames:
        return pd.DataFrame()
    cat = pd.concat(per_seed_frames, ignore_index=True)
    # 'seed' is the grouping label, not a metric: averaging it produces a
    # meaningless 'seed_mean' column that reads like a result.
    num = [c for c in cat.columns
           if c not in (id_col, 'seed') and pd.api.types.is_numeric_dtype(cat[c])]
    g = cat.groupby(id_col)[num]
    mean, sd, n = g.mean(), g.std(ddof=1), g.size()
    out = mean.copy()
    out.columns = [f"{c}_mean" for c in out.columns]
    for c in num:
        out[f"{c}_sd"] = sd[c]
    out['n_seeds'] = n
    for c in ['Primary_Macro_MAE', 'Macro_MAE_obs',
              'Macro_MAE_obs_ex_degen', 'Macro_MAE',
              'Macro_MAE_ex_degen', 'Mean_MASE']:
        if c in mean.columns:
            out[f'{c}_report'] = [f"{m:.4f} +/- {s:.4f}"
                                  for m, s in zip(mean[c], sd[c].fillna(0))]
    return out.reset_index()

def perform_statistical_tests(results_df, errors_dict,
                              baseline_name='XGBoost Baseline',
                              obs_mask=None):
    print("Performing rigorous statistical analysis (Holm-Bonferroni + "
          "Bootstrapping; source-retained cells when available)...")
    if baseline_name not in errors_dict:
        return results_df

    # This broad table is an end-to-end pipeline comparison. It is not the
    # neural-corrector attribution, which is reported separately against the
    # feature-matched differenced anchor.
    results_df['end_to_end_statistical_comparator'] = baseline_name
    results_df['corrector_attribution_anchor'] = CORRECTOR_ATTRIBUTION_ANCHOR

    baseline_errors_by_var = errors_dict[baseline_name]
    target_vars = sorted(baseline_errors_by_var.keys())

    for var in target_vars:
        base_err = baseline_errors_by_var[var]
        use_observed = obs_mask is not None and var in obs_mask.columns

        def _aligned_pair(left, right):
            if isinstance(left, pd.Series) and isinstance(right, pd.Series):
                pair = pd.concat([left.rename('left'), right.rename('right')],
                                 axis=1, join='inner').dropna()
                if use_observed:
                    keep = (obs_mask[var].reindex(pair.index)
                            .fillna(False).astype(bool).values)
                    pair = pair.iloc[keep]
                return (np.abs(pair['left'].values.astype(float)),
                        np.abs(pair['right'].values.astype(float)))
            left = np.asarray(left, dtype=float)
            right = np.asarray(right, dtype=float)
            n = min(len(left), len(right))
            if use_observed:
                n = min(n, len(obs_mask))
            left, right = left[-n:], right[-n:]
            keep = np.isfinite(left) & np.isfinite(right)
            if use_observed:
                om = obs_mask[var].fillna(False).values.astype(bool)[-n:]
                keep &= om
            return left[keep], right[keep]

        def _scored_error(err):
            if isinstance(err, pd.Series):
                s = err.dropna()
                if use_observed:
                    keep = (obs_mask[var].reindex(s.index)
                            .fillna(False).astype(bool).values)
                    s = s.iloc[keep]
                return np.abs(s.values.astype(float))
            err = np.asarray(err, dtype=float)
            n = min(len(err), len(obs_mask)) if use_observed else len(err)
            err = err[-n:]
            keep = np.isfinite(err)
            if use_observed:
                keep &= obs_mask[var].fillna(False).values.astype(bool)[-n:]
            return err[keep]

        p_values_raw = []
        model_indices_to_test = []

        for model_name in results_df.index:
            if model_name == baseline_name or model_name not in errors_dict:
                continue
            if var in errors_dict[model_name]:
                model_err = errors_dict[model_name][var]
                base_pair, model_pair = _aligned_pair(base_err, model_err)
                try:
                    if len(base_pair) < 10:
                        continue
                    _, p = wilcoxon(base_pair, model_pair,
                                    alternative='greater')
                    p_values_raw.append(p)
                    model_indices_to_test.append(model_name)
                except (ValueError, FloatingPointError):
                    pass

        if p_values_raw:
            try:
                _, p_adj, _, _ = multipletests(p_values_raw, alpha=0.05, method='holm')
            except:
                p_adj = p_values_raw
        else:
            p_adj = []

        p_map = dict(zip(model_indices_to_test, p_adj)) if p_values_raw else {}

        for model_name in results_df.index:
            if model_name not in errors_dict or var not in errors_dict[model_name]:
                continue

            curr_err = _scored_error(np.abs(np.asarray(
                errors_dict[model_name][var], dtype=float)))
            if len(curr_err) == 0:
                continue
            lower, upper = bootstrap_ci(curr_err)
            metric_col = (f'{var}_MAE_obs' if use_observed
                          and f'{var}_MAE_obs' in results_df.columns
                          else f'{var}_MAE')
            mae_val = pd.to_numeric(results_df.loc[model_name, metric_col],
                                    errors='coerce')
            suffix = '_obs' if metric_col.endswith('_MAE_obs') else ''
            results_df.loc[model_name, f'{var}_MAE{suffix}_CI'] = (
                f"{mae_val:.3f} [{lower:.3f}-{upper:.3f}]")

            if model_name == baseline_name:
                stat_value = "Ref"
            elif model_name in p_map:
                p_val = p_map[model_name]
                base_pair, curr_pair = _aligned_pair(base_err, np.abs(
                    np.asarray(errors_dict[model_name][var], dtype=float)))
                r_rb = calculate_rank_biserial(base_pair, curr_pair)
                if abs(r_rb) < 0.1:   eff_lbl = "Negl"
                elif abs(r_rb) < 0.3: eff_lbl = "Sm"
                elif abs(r_rb) < 0.5: eff_lbl = "Md"
                else:                  eff_lbl = "Lg"
                p_str = "<0.001" if p_val < 0.001 else f"{p_val:.3f}"
                stat_value = f"{p_str} ({eff_lbl})"
            else:
                continue
            stat_col = f'{var}_Stats_obs' if use_observed else f'{var}_Stats'
            results_df.loc[model_name, stat_col] = stat_value
            # Keep the historical column as a pointer to the primary test while
            # making its scope explicit in the CSV.
            results_df.loc[model_name, f'{var}_Stats'] = stat_value

    results_df = results_df.drop(columns=['p-value (vs XGBoost)'], errors='ignore')
    results_df['statistical_scope'] = (
        'source-retained only' if obs_mask is not None else 'all points')
    return results_df


def generate_plots(results_df, timings_df, dataset_name, config,
                   target_vars=None):
    plt.style.use('seaborn-v0_8-whitegrid')
    for metric in ['MAE', 'RMSE', 'MASE']:
        if target_vars is not None:
            if metric == 'MAE':
                observed_cols = [f'{v}_MAE_obs' for v in target_vars
                                 if f'{v}_MAE_obs' in results_df.columns]
                metric_cols = (observed_cols if observed_cols else
                               [f'{v}_MAE' for v in target_vars
                                if f'{v}_MAE' in results_df.columns])
            else:
                metric_cols = [f'{v}_{metric}' for v in target_vars
                               if f'{v}_{metric}' in results_df.columns]
        else:
            metric_cols = [c for c in results_df.columns
                           if re.fullmatch(rf'.+_{metric}', str(c))]
        if not metric_cols:
            continue
        df_metric = results_df[metric_cols].copy()
        df_metric.columns = [
            (c[:-len('_MAE_obs')] if c.endswith('_MAE_obs')
             else c[:-len(f'_{metric}')])
            for c in df_metric.columns]
        fig, ax = plt.subplots(figsize=(14, 8))
        df_metric.plot(kind='bar', ax=ax, colormap='viridis')
        scope = (' (source-retained only)'
                 if metric == 'MAE'
                 and any(c.endswith('_MAE_obs') for c in metric_cols) else '')
        ax.set_title(f'{metric} Comparison{scope} on '
                     f'{dataset_name.title()} Dataset', fontsize=16,
                     fontweight='bold')
        ax.set_ylabel(f'{metric} (lower is better)', fontsize=12)
        ax.set_xlabel('')
        ax.tick_params(axis='x', rotation=45, labelsize=11)
        ax.grid(axis='y', linestyle='--', alpha=0.7)
        plt.tight_layout()
        plt.savefig(os.path.join(config.OUTPUT_DIR, f'metrics_{metric.lower()}_comparison_{dataset_name}.png'))
        plt.close()

    fig, axes = plt.subplots(1, 2, figsize=(16, 6))
    timings_df['Training Time (s)'].plot(kind='bar', ax=axes[0], color='skyblue')
    axes[0].set_title('Model Training Time', fontsize=14, fontweight='bold')
    axes[0].set_ylabel('Time (seconds, log scale)', fontsize=12)
    axes[0].tick_params(axis='x', rotation=45, labelsize=11)
    axes[0].set_yscale('log')
    timings_df['Forecast Time (s)'].plot(kind='bar', ax=axes[1], color='salmon')
    axes[1].set_title('Forecast Inference Time', fontsize=14, fontweight='bold')
    axes[1].set_ylabel('Time (seconds, log scale)', fontsize=12)
    axes[1].tick_params(axis='x', rotation=45, labelsize=11)
    axes[1].set_yscale('log')
    fig.suptitle(f'Performance Profiling on {dataset_name.title()} Dataset', fontsize=18, fontweight='bold')
    plt.tight_layout(rect=[0, 0, 1, 0.96])
    plt.savefig(os.path.join(config.OUTPUT_DIR, f'timings_comparison_{dataset_name}.png'))
    plt.close()


def drop_invalid_rows(df, where, keep=()):
    """Internal experiment utility."""
    if df is None or not len(df) or 'row_invalid' not in df.columns:
        return df
    bad = df.index[df['row_invalid'].fillna(False).astype(bool)]
    if not len(bad):
        return df
    protected = [b for b in bad if b in set(keep)]
    if protected:
        print(f"    [PATCH-D2] *** SELECTED HEADLINE ARM IS INVALID *** "
              f"{protected} in '{where}'. This is not an excludable ablation "
              f"row -- the headline result itself is affected and must be "
              f"rebuilt before the manuscript quotes it.")
    droppable = [b for b in bad if b not in set(keep)]
    if droppable:
        print(f"    [PATCH-D2] excluding {len(droppable)} INVALID row(s) from "
              f"'{where}': {droppable}")
    return df.drop(index=droppable)


def generate_sensitivity_plot(results_df, dataset_name, config,
                              selected_arm=None):
    # PATCH-D2: the C-sensitivity curve is a manuscript figure, so an INVALID
    # arm must not contribute a point to it.
    results_df = drop_invalid_rows(results_df, f'C-sensitivity plot '
                                              f'({dataset_name})',
                                   keep=(selected_arm,) if selected_arm else ())
    lambda_results = results_df.loc[results_df.index.str.contains('M2P-PTAC')].copy()
    if lambda_results.empty:
        return
    primary_col = next((c for c in ('Primary_Macro_MAE',
                                    'Macro_MAE_obs_ex_degen',
                                    'Macro_MAE_obs',
                                    'Macro_MAE_ex_degen', 'Macro_MAE')
                        if c in lambda_results.columns), None)
    mae_cols = [c for c in lambda_results.columns
                if c.endswith('_MAE') and not c.startswith('Macro_')]
    if primary_col is None and not mae_cols:
        return

    def extract_c(name):
        match = re.search(r'C=([0-9\.]+)', name)
        return float(match.group(1)) if match else 0.005

    lambda_results['C'] = lambda_results.index.map(extract_c)
    lambda_results['Average_MAE'] = (
        pd.to_numeric(lambda_results[primary_col], errors='coerce')
        if primary_col is not None
        else lambda_results[mae_cols].apply(
            pd.to_numeric, errors='coerce').mean(axis=1))
    lambda_results = lambda_results.sort_values('C')

    plt.style.use('seaborn-v0_8-whitegrid')
    fig, ax = plt.subplots(figsize=(10, 6))
    ax.plot(lambda_results['C'], lambda_results['Average_MAE'], marker='o', linestyle='-', color='darkblue')
    ax.set_xscale('log')
    ax.set_xlabel('Base Regularization Hyperparameter (C)', fontsize=12)
    ax.set_ylabel('Primary Mean Absolute Error (MAE)', fontsize=12)
    ax.set_title(f'Hyperparameter C Sensitivity on {dataset_name.title()} Dataset', fontsize=16, fontweight='bold')
    ax.grid(True, which="both", ls="--")
    plt.tight_layout()
    plt.savefig(os.path.join(config.OUTPUT_DIR, f'sensitivity_analysis_{dataset_name}.png'))
    plt.close()


def ManualTimeSeriesSplit(data, n_splits):
    n_samples = len(data)
    k_fold_size = n_samples // (n_splits + 1)
    if k_fold_size == 0:
        raise ValueError("Cannot create folds with zero size.")
    indices = np.arange(n_samples)
    for i in range(n_splits):
        mid = (i + 1) * k_fold_size
        end = min((i + 2) * k_fold_size, n_samples)
        # Expanding-origin folds: every validation block is predicted using all
        # information available strictly before it.  The former disjoint train
        # blocks discarded earlier history and did not reproduce deployment.
        yield indices[:mid], indices[mid:end]


def oof_anchor_residuals(X_train, y_diff_train, lag1_train, n_blocks=5,
                         inner_eval_frac=0.10, xgb_kwargs=None, verbose=True):
    """Internal experiment utility."""
    import numpy as _np
    n = len(X_train)
    K = max(int(n_blocks), 2)
    bs = n // K
    resid = _np.full(n, _np.nan, dtype=float)
    if bs < 2:
        if verbose:
            print(f"    [OOF] only {n} train rows for {K} blocks -- OOF skipped.")
        return resid, _np.zeros(n, dtype=bool)
    kw = dict(xgb_kwargs or {})
    kw.pop('early_stopping_rounds', None)
    yv = _np.asarray(y_diff_train, dtype=float)
    lv = _np.asarray(lag1_train, dtype=float)
    for k in range(1, K):
        f_end = k * bs
        p_end = n if k == K - 1 else (k + 1) * bs
        if p_end <= f_end:
            continue
        n_in = max(int(f_end * (1.0 - inner_eval_frac)), 1)
        if n_in >= f_end:
            n_in = f_end - 1
        fit_sl, ev_sl = slice(0, n_in), slice(n_in, f_end)
        m = xgb.XGBRegressor(early_stopping_rounds=50, **kw)
        if ev_sl.stop - ev_sl.start >= 5:
            m.fit(X_train.iloc[fit_sl], yv[fit_sl],
                  eval_set=[(X_train.iloc[ev_sl], yv[ev_sl])], verbose=False)
        else:
            m = xgb.XGBRegressor(**kw)
            m.fit(X_train.iloc[0:f_end], yv[0:f_end], verbose=False)
        pd_ = m.predict(X_train.iloc[f_end:p_end])
        resid[f_end:p_end] = (yv[f_end:p_end] + lv[f_end:p_end]) - (pd_ + lv[f_end:p_end])
    covered = ~_np.isnan(resid)
    if verbose:
        print(f"    [OOF] {K} expanding folds, block={bs}: "
              f"{int(covered.sum())}/{n} train rows have an out-of-fold residual "
              f"({int((~covered).sum())} warm-up rows excluded from corrector training).")
    return resid, covered


def tune_m2p_hyperparameters(df, target_vars, config):
    print("\n" + "#"*80 + "\n### STARTING RIGOROUS HYPERPARAMETER TUNING FOR M2P-PTAC ###\n" + "#"*80)
    from itertools import product
    param_grid = {
        'BILSTM_UNITS': [64, 80, 96, 112, 128],
        'CONV_FILTERS': [64, 80, 96, 112, 128],
        'ATTENTION_HEADS': [2, 4, 8],
        'HEAD_DENSE_UNITS': [64, 128, 256],
        'DROPOUT_RATE': [0.2, 0.3, 0.4, 0.5],
    }
    all_param_combinations = [dict(zip(param_grid.keys(), v)) for v in product(*param_grid.values())]
    param_list = random.sample(all_param_combinations, min(config.N_ITER_SEARCH, len(all_param_combinations)))
    print(f"Testing {len(param_list)} random hyperparameter combinations...")

    train_val_end_idx = int(len(df) * (config.TRAIN_SPLIT + config.VAL_SPLIT))
    df_train_val = df.iloc[:train_val_end_idx]
    X_tab, y_tab, lag1_tab = create_tabular_features(
        df_train_val, target_vars, config=config, return_delta=True)   # R16-A/C

    # Out-of-fold anchor residuals only.  Fitting one XGBoost model on all of
    # train+validation and scoring it in-sample leaked each row's target into
    # the neural target used by the architecture search.
    df_residuals = pd.DataFrame(index=y_tab.index, columns=target_vars,
                                dtype=float)
    for var in target_vars:
        y_diff = y_tab[var] - lag1_tab[var]
        _res, _covered = oof_anchor_residuals(
            X_tab, y_diff.values, lag1_tab[var].values, n_blocks=6,
            xgb_kwargs=dict(objective='reg:squarederror', n_estimators=100,
                            random_state=42), verbose=False)
        df_residuals[var] = _res

    df_m2p_input = df_train_val.copy()
    time_features = ['hour_sin', 'hour_cos']
    df_m2p_input['hour_sin'] = np.sin(2 * np.pi * df_m2p_input.index.hour / 24.0)
    df_m2p_input['hour_cos'] = np.cos(2 * np.pi * df_m2p_input.index.hour / 24.0)

    X_m2p_full, m2p_indices = create_m2p_features(df_m2p_input, target_vars, time_features, config)
    common_indices = X_tab.index.intersection(m2p_indices)
    _covered_all = np.isfinite(df_residuals.loc[common_indices].values).all(axis=1)
    common_indices = common_indices[_covered_all]
    if len(common_indices) < 30:
        raise RuntimeError(
            f'Only {len(common_indices)} fully out-of-fold corrector rows remain '
            'for architecture tuning; refusing an in-sample fallback.')
    y_full = df_residuals.loc[common_indices].values

    X_m2p_short = (
        pd.DataFrame([r.flatten() for r in X_m2p_full['short_term_input']], index=m2p_indices)
        .loc[common_indices].values
        .reshape(len(common_indices), config.SHORT_WINDOW_SIZE, -1)
    )
    X_m2p_long = (
        pd.DataFrame([r.flatten() for r in X_m2p_full['long_term_input']], index=m2p_indices)
        .loc[common_indices].values
        .reshape(len(common_indices), config.LONG_WINDOW_SIZE, -1)
    )
    X_for_tuner = np.concatenate([
        X_m2p_short.reshape(X_m2p_short.shape[0], -1),
        X_m2p_long.reshape(X_m2p_long.shape[0], -1)
    ], axis=1)

    # over the same input space the benchmark's corrector receives.
    _tw = int(getattr(config, '_steps_per_day', 24))
    if _tw <= 1:
        _tw = max(_roll_windows_of(config))
    context_cols = [c for c in X_tab.columns
                    if f'_roll_mean_{_tw}' in c or f'_roll_std_{_tw}' in c]
    if not context_cols:
        _tw2 = max(_roll_windows_of(config))
        context_cols = [c for c in X_tab.columns
                        if f'_roll_mean_{_tw2}' in c or f'_roll_std_{_tw2}' in c]
    context_cols = context_cols + [c for c in X_tab.columns
                                   if str(c).endswith(_HEALTH_NAME_SUFFIXES)]
    X_context_full = X_tab.loc[common_indices][context_cols].values
    current_context_dim = len(context_cols)

    best_score = float('inf')
    best_params = None

    for i, params in enumerate(param_list):
        print(f"\n--- Testing Combo {i+1}/{len(param_list)}: {params} ---")
        fold_scores = []
        temp_config = copy.deepcopy(config)
        for key, value in params.items():
            setattr(temp_config, key, value)

        for train_idx, val_idx in ManualTimeSeriesSplit(y_full, n_splits=5):
            X_train_seq, X_val_seq = X_for_tuner[train_idx], X_for_tuner[val_idx]
            X_train_ctx, X_val_ctx = X_context_full[train_idx], X_context_full[val_idx]
            y_train, y_val = y_full[train_idx], y_full[val_idx]

            # Fold-local preprocessing.  Validation rows never set a centring,
            # scale, or target-weight parameter.
            _ss = StandardScaler().fit(X_train_seq)
            X_train_seq = _ss.transform(X_train_seq)
            X_val_seq = _ss.transform(X_val_seq)
            if X_train_ctx.shape[1]:
                _cs = StandardScaler().fit(X_train_ctx)
                X_train_ctx = _cs.transform(X_train_ctx)
                X_val_ctx = _cs.transform(X_val_ctx)
            _ys = StandardScaler().fit(y_train)
            y_train_s = _ys.transform(y_train)
            y_val_s = _ys.transform(y_val)

            tf.keras.backend.clear_session()
            model = build_m2p_attention_network(
                config=temp_config, target_vars=target_vars,
                num_dynamic_vars=len(target_vars),
                short_window_features=X_m2p_short.shape[2],
                long_window_features=X_m2p_long.shape[2],
                context_dim=current_context_dim, unified_encoder=False,
                # backbone and the L1 coefficient against CV MAE; the detection
                # heads are supervised by the fault mask, which this tuner is
                # not given, so they are excluded from the searched space rather
                # than trained against absent labels.
                use_fault_gating=False
            )
            model.compile(optimizer='adam', loss='huber')
            model.fit(
                x=[X_train_seq, X_train_ctx],
                y=[y_train_s[:, j] for j in range(len(target_vars))],
                validation_data=([X_val_seq, X_val_ctx],
                                 [y_val_s[:, j] for j in range(len(target_vars))]),
                epochs=100, batch_size=config.BATCH_SIZE, verbose=0,
                shuffle=False,
                callbacks=[keras.callbacks.EarlyStopping(
                    monitor='val_loss', patience=10, restore_best_weights=True)]
            )
            
            # tuning log -- 25 combos x 5 folds = 125 bare predict() calls, each
            # printing "1/3 ... 3/3 ... 70ms/step" while fit() above is silent.
            _po = model.predict([X_val_seq, X_val_ctx], verbose=0)
            preds = np.stack([np.asarray(q).reshape(-1) for q in _po], axis=1)
            # Equal target weight on standardised residuals; conductivity can
            # no longer dominate the architecture choice through its units.
            fold_scores.append(float(np.mean([
                mean_absolute_error(y_val_s[:, j], preds[:, j])
                for j in range(len(target_vars))])))

        avg_score = np.mean(fold_scores)
        print(f"    -> Average equal-target standardised OOF MAE: {avg_score:.4f}")
        if avg_score < best_score:
            best_score = avg_score
            best_params = params
            print(f"    -> New best score found!")

    print("\n" + "="*80)
    print(f"Best Score (equal-target standardised OOF MAE): {best_score:.4f}")
    print("Best Parameters Found:", best_params)
    os.makedirs(config.OUTPUT_DIR, exist_ok=True)
    import json
    json_path = os.path.join(config.OUTPUT_DIR, 'best_hyperparameters.json')
    with open(json_path, 'w') as f:
        json.dump(best_params, f, indent=4)
    print(f"Best hyperparameters saved to {json_path}")
    return best_params


# ============================================================================
# --- Main Orchestrator ---
# ============================================================================

def _mk_seed_comparator(name, config, obs_mask, fault_mask, seed):
    """Internal experiment utility."""
    n = str(name)
    # n_estimators is only set on config by TEST_MODE; on a full run the
    # attribute does not exist, so getattr with the production default is what
    # keeps the seed sweep from dying with AttributeError on the cluster.
    n_est = int(getattr(config, 'n_estimators', 1000))
    if n == "XGBoost Baseline":
        return TabularExperiment(n, config, xgb.XGBRegressor,
                                 {'objective': 'reg:squarederror',
                                  'n_estimators': n_est,
                                  'learning_rate': 0.01, 'random_state': seed},
                                 obs_mask=obs_mask, fault_mask=fault_mask)
    if n == "LightGBM Baseline":
        return TabularExperiment(n, config, lgb.LGBMRegressor,
                                 {'objective': 'regression_l1',
                                  'n_estimators': n_est,
                                  'learning_rate': 0.01, 'random_state': seed,
                                  'verbose': -1},
                                 obs_mask=obs_mask, fault_mask=fault_mask)
    # F6: the two DIFFERENCED-target trees had no recipe, so every seed-stability
    # table reported "no rebuild recipe for comparator 'XGBoost (differenced
    # target)'" (76 occurrences in the last log) and fell back to M2P dispersion
    # alone. That is the one comparator the central claim needs: the paper's
    # improvement must be measured against the differenced anchor, not the level
    # model, so its cross-seed dispersion is required for any CI on the headline
    # delta. Recipes mirror the main-loop constructors at lines ~8034/8038
    # exactly, with random_state carrying the per-run seed instead of 42.
    if n == "XGBoost (differenced target)":
        return TabularExperiment(n, config, xgb.XGBRegressor,
                                 {'objective': 'reg:squarederror',
                                  'n_estimators': n_est,
                                  'learning_rate': 0.01, 'random_state': seed},
                                 obs_mask=obs_mask, fault_mask=fault_mask,
                                 target_mode='delta')
    if n == "LightGBM (differenced target)":
        return TabularExperiment(n, config, lgb.LGBMRegressor,
                                 {'objective': 'regression_l1',
                                  'n_estimators': n_est,
                                  'learning_rate': 0.01, 'random_state': seed,
                                  'verbose': -1},
                                 obs_mask=obs_mask, fault_mask=fault_mask,
                                 target_mode='delta')
    # PATCH-A1: recipes for the feature-matched anchors, so the seed-stability
    # table can compute cross-seed dispersion on the arm the attribution test
    # actually uses. Without these the F6 fallback ("no rebuild recipe") would
    # reappear on exactly the comparator the central claim depends on.
    if n == "XGBoost (differenced target + drift bank)":
        return TabularExperiment(n, config, xgb.XGBRegressor,
                                 {'objective': 'reg:squarederror',
                                  'n_estimators': n_est,
                                  'learning_rate': 0.01, 'random_state': seed},
                                 obs_mask=obs_mask, fault_mask=fault_mask,
                                 target_mode='delta', use_drift_bank=True)
    if n == "LightGBM (differenced target + drift bank)":
        return TabularExperiment(n, config, lgb.LGBMRegressor,
                                 {'objective': 'regression_l1',
                                  'n_estimators': n_est,
                                  'learning_rate': 0.01, 'random_state': seed,
                                  'verbose': -1},
                                 obs_mask=obs_mask, fault_mask=fault_mask,
                                 target_mode='delta', use_drift_bank=True)
    if n == "Grey-Box XGBoost":
        return GreyBoxXGBExperiment(n, config, seed=seed)          # R9-C
    if n == "Physics-Guided MLP":
        # Keras weight init is stochastic; set_all_seeds(seed) is called by the
        # sweep before each rebuild, which is what randomises this one.
        return PhysicsGuidedMLPExperiment(n, config, lambda_physics=0.01)
    if n == "SeasonalNaive (24h)":
        # Deterministic by construction: sd across seeds is exactly 0, which is
        # the correct answer for it, not a failure.
        return SeasonalNaiveExperiment(n, config)
    if n == "Theta Method":
        return ThetaExperiment(n, config)
    if n == "ETS (Holt-Winters)":
        return ExponentialSmoothingExperiment(n, config)
    if n == "Prophet Specialist":
        return ProphetExperiment(n, config)
    if n == "N-HiTS" and NEURALFORECAST_AVAILABLE:
        return NHITSExperiment(n, config, seed=seed)               # R9-C
    if n == "PatchTST" and NEURALFORECAST_AVAILABLE:
        return PatchTSTExperiment(n, config, seed=seed)            # R9-C
    print(f"    [C-T10] no rebuild recipe for comparator '{n}'; "
          f"reporting M2P-PTAC dispersion alone. Add a recipe to "
          f"_mk_seed_comparator to compare against it across seeds.")
    return None


def backfill_uniform_metrics(results_df, all_errors, config, target_vars,
                             dataset_name, obs_mask=None):
    """Internal experiment utility."""
    et = getattr(config, '_eval_truth', None)
    ref = getattr(config, '_persist_truth', None)
    if et is None or ref is None or not all_errors:
        return results_df
    limits = getattr(config, 'PHYSICAL_LIMITS', {})
    cols = [v for v in target_vars if v in et.columns and v in ref.columns]
    if not cols:
        return results_df

    n_back, n_viol_back = 0, 0
    for mname, errs in all_errors.items():
        if mname not in results_df.index or not isinstance(errs, dict):
            continue
        did_persist, viol_total, viol_seen = False, 0, False
        for v in cols:
            if v not in errs:
                continue
            e = np.asarray(errs[v], dtype=float).reshape(-1)
            if len(e) < 10 or len(e) > len(et):
                continue
            tail = slice(len(et) - len(e), len(et))
            yt = et[v].values[tail].astype(float)
            pv = ref[v].values[tail].astype(float)
            yp = yt - e                       # exact reconstruction
            ok = np.isfinite(yt) & np.isfinite(yp) & np.isfinite(pv)
            if obs_mask is not None and v in obs_mask.columns:
                om = obs_mask[v].reindex(et.index).fillna(False).values[tail]
                ok &= om.astype(bool)
            if ok.sum() < 10:
                continue

            pc = f'{v}_RelMAE_persist'
            _already = (pc in results_df.columns
                        and not pd.isna(results_df.at[mname, pc]))
            if not _already:
                mp = float(np.mean(np.abs(yt[ok] - pv[ok])))
                mm = float(np.mean(np.abs(yt[ok] - yp[ok])))
                if mp > 1e-12:
                    results_df.loc[mname, f'{v}_MAE_persist'] = mp
                    results_df.loc[mname, pc] = mm / mp
                    results_df.loc[mname, f'{v}_Beats_persist'] = bool(mm < mp)
                    results_df.loc[mname, f'{v}_N_persist'] = int(ok.sum())
                    results_df.loc[
                        mname, f'{v}_persist_metric_observed_only'] = bool(
                            obs_mask is not None)
                    did_persist = True

            lo, hi = limits.get(v, (-np.inf, np.inf))
            fin = np.isfinite(yp)
            nv = int(((yp[fin] < lo) | (yp[fin] > hi)).sum())
            viol_total += nv
            viol_seen = True
            results_df.loc[mname, f'{v}_PhysViol'] = (
                float(nv) / max(int(fin.sum()), 1))

        if viol_seen and not bool(results_df.get('physviol_counted',
                                                 pd.Series(dtype=object)
                                                 ).get(mname, False)):
            results_df.loc[mname, 'n_physical_violations'] = viol_total
            results_df.loc[mname, 'n_physical_violations_post_guard'] = 0
            n_viol_back += 1
        n_back += int(did_persist)

    # Aggregates over whatever is now present, so the headline row and the
    # comparators are summarised by the same rule.
    rel = [f'{v}_RelMAE_persist' for v in cols
           if f'{v}_RelMAE_persist' in results_df.columns]
    beat = [f'{v}_Beats_persist' for v in cols
            if f'{v}_Beats_persist' in results_df.columns]
    if rel:
        results_df['Mean_RelMAE_persist'] = results_df[rel].astype(float).mean(axis=1)
    if beat:
        results_df['Beats_persist_frac'] = results_df[beat].apply(
            lambda r: np.nanmean([1.0 if x is True else 0.0 if x is False else np.nan
                                  for x in r]), axis=1)

    # cannot mistake a testbed scored on a manufactured grid for a valid one.
    results_df['cadence'] = str(_freq_of(config))
    results_df['cadence_valid'] = bool(getattr(config, '_cadence_valid', True))
    _cd = getattr(config, '_cadence_diag', {}) or {}
    if np.isfinite(_cd.get('cadence_interp_frac', np.nan)):
        results_df['cadence_interp_frac'] = float(_cd['cadence_interp_frac'])

    print(f"    [R16-B/D] backfilled persistence columns for {n_back} models and "
          f"violation counts for {n_viol_back}, reconstructing predictions from "
          f"residuals + shared eval truth.")
    if rel:
        _mr = results_df['Mean_RelMAE_persist'].astype(float)
        _n_beat = int((_mr < 1.0).sum())
        print(f"    [R16-B] {_n_beat}/{len(_mr.dropna())} models beat test-window "
              f"persistence on the mean ratio. This is the column to quote; the "
              f"in-sample *_MASE columns are retained beside it for continuity "
              f"with the submitted table, not as the headline.")
    return results_df


def detection_report(results_df, config, target_vars, dataset_name,
                     fault_prob=None, fault_mask=None, test_index=None):
    """Internal experiment utility."""
    if fault_prob is None or fault_mask is None or test_index is None:
        return None
    rows = []
    thr = float(getattr(config, 'DETECTION_THRESHOLD', 0.5))
    fm = fault_mask.reindex(test_index).fillna(False)

    def _calibration_metrics(y, p, n_bins=10):
        y = np.asarray(y, dtype=float); p = np.asarray(p, dtype=float)
        ok = np.isfinite(y) & np.isfinite(p)
        y, p = y[ok], np.clip(p[ok], 0.0, 1.0)
        if len(y) == 0:
            return np.nan, np.nan, []
        brier = float(np.mean((p - y) ** 2))
        bins = np.linspace(0.0, 1.0, int(n_bins) + 1)
        ece = 0.0; br = []
        for bi in range(len(bins) - 1):
            lo, hi = bins[bi], bins[bi + 1]
            mask = ((p >= lo) & (p < hi)) if bi < len(bins) - 2 else ((p >= lo) & (p <= hi))
            if not mask.any():
                continue
            conf = float(np.mean(p[mask])); freq = float(np.mean(y[mask])); n = int(mask.sum())
            ece += (n / len(y)) * abs(conf - freq)
            br.append(dict(bin_lo=lo, bin_hi=hi, n=n, mean_probability=conf,
                           observed_frequency=freq))
        return brier, float(ece), br
    for i, v in enumerate(target_vars):
        if v not in fm.columns or i >= np.asarray(fault_prob).shape[1]:
            continue
        y = fm[v].values.astype(bool)
        p = np.asarray(fault_prob)[:, i].astype(float)
        ok = np.isfinite(p)
        y, p = y[ok], p[ok]
        _brier, _ece, _relbins = _calibration_metrics(y.astype(float), p, n_bins=10)
        # Reliability bins are useful even when AUC is undefined (e.g. all-clean
        # window): they reveal whether a nominal 'probability' is overconfident.
        if _relbins:
            _rb = pd.DataFrame(_relbins)
            _rb.insert(0, 'target', v)
            _rb.to_csv(os.path.join(config.OUTPUT_DIR,
                       f'detection_reliability_{dataset_name}_{_safe_filename(v)}.csv'),
                       index=False)
        if len(y) < 20 or y.sum() == 0 or y.all():
            rows.append(dict(target=v, n=len(y), prevalence=float(y.mean())
                             if len(y) else np.nan, auc=np.nan,
                             precision=np.nan, recall=np.nan,
                             brier=_brier, ece=_ece,
                             auc_null_p95=np.nan, auc_perm_p=np.nan,
                             median_lead_steps=np.nan,
                             note='no positive or no negative class in the '
                                  'scored window -- detection is undefined here, '
                                  'not zero'))
            continue
        # Rank-based AUC (Mann-Whitney), tie-corrected.
        r = pd.Series(p).rank().values
        n1, n0 = int(y.sum()), int((~y).sum())
        auc = float((r[y].sum() - n1 * (n1 + 1) / 2.0) / (n1 * n0))
        pred = p >= thr
        tp = int((pred & y).sum())
        prec = float(tp / pred.sum()) if pred.sum() else np.nan
        rec = float(tp / n1)
        # Lead time: for each fault onset, how many steps earlier did p cross.
        onsets = np.flatnonzero(y.astype(int) - np.r_[0, y.astype(int)[:-1]] > 0)
        leads = []
        for o in onsets:
            w = pred[max(0, o - 48):o]
            if w.any():
                leads.append(int(len(w) - np.flatnonzero(w)[0]))
        # ---------------------------------------------------------- R16-E
        # A PERMUTATION NULL, not a fixed AUC threshold. Measured on this suite:
        # four independent targets scored against uniform-random probabilities
        # produced a maximum AUC of 0.617, which a fixed "AUC > 0.60 means signal"
        # rule reads as detection. The null distribution of the SAME statistic
        # under label shuffling is what makes the number interpretable, and the
        # p-value is reported per target so the reader can apply their own
        # multiplicity correction over the target count.
        _rs = np.random.default_rng(20240617)
        n_perm = int(getattr(config, 'DETECTION_N_PERM', 2000))
        null = np.empty(n_perm)
        for b in range(n_perm):
            yb = _rs.permutation(y)
            null[b] = ((r[yb].sum() - n1 * (n1 + 1) / 2.0) / (n1 * n0))
        p_perm = float((1.0 + np.sum(null >= auc)) / (n_perm + 1.0))
        _note = ''
        if not leads:
            _note = ('threshold never crossed before an onset -- the head '
                     'flags faults concurrently, not in advance')
        rows.append(dict(target=v, n=len(y), prevalence=float(y.mean()),
                         auc=auc, auc_null_p95=float(np.quantile(null, 0.95)),
                         auc_perm_p=p_perm,
                         precision=prec, recall=rec,
                         brier=_brier, ece=_ece,
                         median_lead_steps=float(np.median(leads)) if leads else np.nan,
                         note=_note))
    if not rows:
        return None
    dt = pd.DataFrame(rows)
    path = os.path.join(config.OUTPUT_DIR, f'detection_metrics_{dataset_name}.csv')
    dt.to_csv(path, index=False)
    print("\n--- R16-E: DEGRADATION DETECTION (the gated corrector's premise) ---")
    print(dt.to_string(index=False))
    _a = dt.auc.dropna()
    _n_tested = int(dt.auc_perm_p.notna().sum())
    _alpha = 0.05 / max(_n_tested, 1)          # Bonferroni over the targets tested
    _sig = dt[dt.auc_perm_p.notna() & (dt.auc_perm_p < _alpha)]
    if _n_tested == 0:
        print("    [R16-E] No target had both classes present in the scored "
              "window. Detection is UNDEFINED here, which is not the same as "
              "zero -- do not report a detection result for this testbed.")
    elif len(_sig) == 0:
        print(f"    [R16-E] NEGATIVE RESULT. No target's AUC exceeds its own "
              f"permutation null at alpha={_alpha:.4f} "
              f"(0.05 Bonferroni-corrected over {_n_tested} targets); best AUC "
              f"{_a.max():.3f} against a null 95th percentile of "
              f"{dt.auc_null_p95.max():.3f}. On these stations the degradation "
              f"signature is not learnable from the available features, so the "
              f"gated corrector contributes the exact-parity guarantee and NOT "
              f"an accuracy gain. Report it that way: a null detection result "
              f"with a proved safety property is a defensible contribution, and "
              f"claiming accuracy the table does not support is not.")
    else:
        print(f"    [R16-E] {len(_sig)}/{_n_tested} targets beat their "
              f"permutation null at alpha={_alpha:.4f}: "
              f"{', '.join(_sig.target)} (best AUC {_a.max():.3f}). The "
              f"correction is concentrated on flagged points, so the accuracy "
              f"claim rests on this table -- quote it beside the MAE.")
    return dt


def _r34_bool_series(x):
    """Parse a CSV boolean column without treating non-empty strings as True."""
    if getattr(x, 'dtype', None) == bool:
        return x.astype(bool)
    return x.astype(str).str.strip().str.lower().isin({'1', 'true', 't', 'yes', 'y'})


def _r34_file_sha256(path):
    import hashlib
    h = hashlib.sha256()
    with open(path, 'rb') as fh:
        for chunk in iter(lambda: fh.read(1024 * 1024), b''):
            h.update(chunk)
    return h.hexdigest()


def _r34_load_offline_qualification(config, artifact_path, acceptance_path):
    """Load frozen R32-v2 evidence and reconstruct its ORIGINAL acceptance rule.

    Job 50056584 predates the later R33 JSON schema: it does not contain
    ``system_confirmation_passed`` or per-target evidence dictionaries.  This
    loader therefore validates the fields that R32-v2 actually wrote and
    reproduces the exact R32-v2 confirmation predicate.  No new threshold is
    introduced.  Because that job retrained the procedure at each intensity,
    the resulting Q_j is explicitly labelled procedure-level qualification,
    not fixed-weight-model qualification.
    """
    artifact_path = os.path.abspath(str(artifact_path))
    acceptance_path = os.path.abspath(str(acceptance_path))
    if not os.path.isfile(artifact_path):
        raise RuntimeError(f"[R34] qualification artifact not found: {artifact_path}")
    if not os.path.isfile(acceptance_path):
        raise RuntimeError(f"[R34] rescue acceptance file not found: {acceptance_path}")

    with open(artifact_path, 'r') as fh:
        r32 = json.load(fh)
    acc = pd.read_csv(acceptance_path)

    required_json = {
        'status', 'post_result_tuning_allowed', 'C', 'gate_mapping',
        'min_degraded_units_positive', 'min_nominal_units_positive',
        'max_abs_null_rescue', 'sudden_mean_rescue',
        'sudden_ci_positive_rate', 'safety_pass_rate_positive_cells',
        'accepted_sudden_curves', 'n_sudden_curves'
    }
    missing_json = sorted(required_json - set(r32))
    if missing_json:
        raise RuntimeError(
            '[R34] supplied artifact is not the expected R32-v2 schema; '
            f'missing keys: {missing_json}')

    if bool(r32.get('post_result_tuning_allowed', True)):
        raise RuntimeError('[R34] qualification artifact allows post-result tuning; refusing use.')
    if not np.isclose(float(r32.get('C')), 1e-4, rtol=0.0, atol=1e-12):
        raise RuntimeError(f"[R34] R32 C mismatch: expected 0.0001, got {r32.get('C')}")

    expected_mapping = {
        'temperature': 'train-innovation hard switch alpha=1.0',
        'ph': 'train-innovation hard switch alpha=1.0',
        'electric conductivity': 'R30 causal health-state procedure p>=0.50',
        'dissolved oxygen': 'train-innovation hard switch alpha=1.0',
    }
    if dict(r32.get('gate_mapping', {})) != expected_mapping:
        raise RuntimeError(
            '[R34] R32 gate mapping does not match the frozen R31 release: '
            f"{r32.get('gate_mapping')}")

    # Reproduce EXACTLY the R32-v2 confirmation predicate from the source that
    # generated job 50056584.  This is provenance reconstruction, not a new rule.
    reconstructed_confirmed = bool(
        int(r32.get('min_degraded_units_positive', 0)) >= 5
        and int(r32.get('min_nominal_units_positive', 0)) >= 5
        and float(r32.get('max_abs_null_rescue', np.inf)) <= 0.02
        and float(r32.get('sudden_mean_rescue', -np.inf)) > 0.20
        and float(r32.get('sudden_ci_positive_rate', 0.0)) >= 0.90
        and float(r32.get('safety_pass_rate_positive_cells', 0.0)) >= 0.90
        and int(r32.get('accepted_sudden_curves', 0)) == 4
    )
    expected_status = 'FROZEN_FIXED_BOUNDARY_HYBRID_CONFIRMED'
    if str(r32.get('status')) != expected_status or not reconstructed_confirmed:
        raise RuntimeError(
            '[R34] R32-v2 controlled qualification did not satisfy its original '
            f"criterion: status={r32.get('status')}, reconstructed={reconstructed_confirmed}")

    required_acc = {'target', 'drift_type', 'accepted'}
    if not required_acc.issubset(acc.columns):
        raise RuntimeError(
            f"[R34] acceptance CSV missing columns: {sorted(required_acc-set(acc.columns))}")
    sudden = acc[acc['drift_type'].astype(str).eq('sudden_shift')].copy()
    sudden['_accepted_bool'] = _r34_bool_series(sudden['accepted'])

    core = list(expected_mapping)
    qmap = {}
    audit_rows = []
    for target in core:
        row = sudden[sudden['target'].astype(str).eq(target)]
        if len(row) != 1:
            raise RuntimeError(
                f"[R34] expected exactly one sudden_shift acceptance row for '{target}', got {len(row)}")
        accepted = bool(row['_accepted_bool'].iloc[0])
        q = bool(reconstructed_confirmed and accepted)
        qmap[target] = q
        audit_rows.append(dict(
            target=target,
            r32_v2_reconstructed_confirmed=reconstructed_confirmed,
            sudden_curve_accepted=accepted,
            offline_qualified=q,
            qualification_scope='procedure_level_r32_v2',
            fixed_weight_replay_proven=False,
            min_degraded_units_positive=int(r32['min_degraded_units_positive']),
            min_nominal_units_positive=int(r32['min_nominal_units_positive']),
            sudden_mean_rescue=float(r32['sudden_mean_rescue']),
            sudden_ci_positive_rate=float(r32['sudden_ci_positive_rate']),
            safety_pass_rate_positive_cells=float(r32['safety_pass_rate_positive_cells']),
        ))

    if not all(qmap.values()):
        raise RuntimeError(
            f"[R34] not all four R32-v2 sudden-shift curves were accepted: {qmap}")

    provenance = {
        'qualification_artifact': artifact_path,
        'qualification_artifact_sha256': _r34_file_sha256(artifact_path),
        'acceptance_csv': acceptance_path,
        'acceptance_csv_sha256': _r34_file_sha256(acceptance_path),
        'running_script': os.path.abspath(__file__),
        'running_script_sha256': _r34_file_sha256(os.path.abspath(__file__)),
        'R32_status': str(r32.get('status')),
        'R32_C': float(r32['C']),
        'R32_post_result_tuning_allowed': bool(r32['post_result_tuning_allowed']),
        'R32_confirmation_draw_seeds': list(r32.get('confirmation_draw_seeds', [])),
        'R32_reconstructed_original_confirmation': bool(reconstructed_confirmed),
        'qualification_scope': 'procedure_level_r32_v2',
        'fixed_weight_replay_proven': False,
        'offline_qualification_by_target': qmap,
    }
    return qmap, provenance, pd.DataFrame(audit_rows)

def _r34d_feature_preflight(dataset_name, df, target_vars, config, station_hint=None):
    """CPU-only audit of the exact challenged feature matrix before model fitting."""
    _cfg = copy.deepcopy(config)
    ensure_cadence(df, _cfg, dataset_name, verbose=False)
    _excl = load_target_exclusions(_cfg, station_hint=station_hint)
    _cfg._r34_dqa_excluded_channels = tuple(_excl.keys()) if _excl else tuple()
    _tv = [v for v in target_vars if v in df.columns and v not in _excl]
    if not _tv:
        raise RuntimeError(f'[R34D-PREFLIGHT] no forecastable targets remain for {dataset_name}')
    _drop = [c for c in _cfg._r34_dqa_excluded_channels if c in df.columns and c not in _tv]
    _dm = df.drop(columns=_drop, errors='ignore').copy()

    # Build the EXACT feature matrix used by the comparator/PTAC context.
    _X, _Y, _L = create_tabular_features(_dm, _tv, config=_cfg, return_delta=True)
    _tr, _va, _te = _raw_split_boundaries(_cfg, len(_dm))
    _blocks = {
        'train': pd.Index(_dm.index[:_tr]),
        'val': pd.Index(_dm.index[_tr:_va]),
        'test': pd.Index(_dm.index[_te:]),
    }
    _vis = {k: int(_X.index.isin(v).sum()) for k, v in _blocks.items()}

    # Label visibility is audited separately so an empty block can never be
    # misdiagnosed as a feature problem again.
    _label_vis = {}
    for _k, _idx in _blocks.items():
        _yy = _dm.loc[_idx, _tv].apply(pd.to_numeric, errors='coerce')
        _label_vis[_k] = {
            'rows': int(len(_yy)),
            'all_targets_finite': int(np.isfinite(_yy.values).all(axis=1).sum()),
            'per_target_finite': {v: int(np.isfinite(_yy[v].values).sum()) for v in _tv},
        }

    print(f"[R34D-PREFLIGHT] {dataset_name}: targets={_tv}; dropped_features={_drop}")
    print(f"[R34D-PREFLIGHT] {dataset_name}: feature-visible={_vis}")
    print(f"[R34D-PREFLIGHT] {dataset_name}: label-visible={_label_vis}")
    if min(_vis.values()) <= 0:
        raise RuntimeError(
            f'[R34D-PREFLIGHT] empty fixed raw-time feature block for {dataset_name}: {_vis}. '
            'Chronology is unchanged; inspect the printed label visibility before proceeding.')
    return dict(dataset=dataset_name, targets=_tv, dropped_features=_drop,
                feature_visibility=_vis, label_visibility=_label_vis)


def _r35_binary_association(fault, action):
    """Exact 2x2 DQA/action association with conservative zero-cell handling."""
    f = np.asarray(fault, dtype=bool)
    a = np.asarray(action, dtype=bool)
    if f.shape != a.shape:
        raise ValueError(f'[R35] fault/action shape mismatch {f.shape} vs {a.shape}')
    n11 = int(np.sum(f & a))
    n10 = int(np.sum(f & ~a))
    n01 = int(np.sum(~f & a))
    n00 = int(np.sum(~f & ~a))
    nf = n11 + n10
    nh = n01 + n00
    p_f = float(n11 / nf) if nf else np.nan
    p_h = float(n01 / nh) if nh else np.nan
    if np.isfinite(p_h) and p_h > 0:
        enrich = float(p_f / p_h) if np.isfinite(p_f) else np.nan
    elif np.isfinite(p_f) and p_f > 0:
        enrich = np.inf
    else:
        enrich = np.nan
    rd = float(p_f - p_h) if np.isfinite(p_f) and np.isfinite(p_h) else np.nan
    try:
        or_fisher, p_two = scipy_stats.fisher_exact(
            [[n11, n10], [n01, n00]], alternative='two-sided')
        or_fisher = float(or_fisher)
        p_two = float(p_two)
    except Exception:
        or_fisher, p_two = np.nan, np.nan

    # Haldane-Anscombe OR + approximate 95% CI, reported in addition to exact
    # Fisher p so zero cells do not make the effect-size interval unusable.
    aa, bb, cc, dd = [x + 0.5 for x in (n11, n10, n01, n00)]
    or_ha = float((aa * dd) / (bb * cc))
    se = float(np.sqrt(1.0/aa + 1.0/bb + 1.0/cc + 1.0/dd))
    z = 1.959963984540054
    lo = float(np.exp(np.log(or_ha) - z * se))
    hi = float(np.exp(np.log(or_ha) + z * se))
    precision_like = float(n11 / (n11 + n01)) if (n11 + n01) else np.nan
    return dict(
        n11_fault_action=n11,
        n10_fault_noaction=n10,
        n01_healthy_action=n01,
        n00_healthy_noaction=n00,
        n_fault=nf,
        n_healthy=nh,
        p_action_given_fault=p_f,
        p_action_given_healthy=p_h,
        action_enrichment_ratio=enrich,
        action_risk_difference=rd,
        fisher_odds_ratio=or_fisher,
        fisher_p_two_sided=p_two,
        odds_ratio_ha=or_ha,
        odds_ratio_ha_ci95_low=lo,
        odds_ratio_ha_ci95_high=hi,
        p_dqa_fault_given_action=precision_like,
    )


def _r35_episode_stats(fault, action):
    """Episode coverage on the exact unshifted audit rows; no best-lag search."""
    f = np.asarray(fault, dtype=bool)
    a = np.asarray(action, dtype=bool)
    starts = np.flatnonzero(f & np.r_[True, ~f[:-1]])
    ends = np.flatnonzero(f & np.r_[~f[1:], True])
    covered = 0
    delays = []
    lengths = []
    for st, en in zip(starts, ends):
        lengths.append(int(en - st + 1))
        hit = np.flatnonzero(a[st:en+1])
        if hit.size:
            covered += 1
            delays.append(int(hit[0]))
    n_ep = int(len(starts))
    return dict(
        n_fault_episodes=n_ep,
        n_fault_episodes_with_action=int(covered),
        fault_episode_action_coverage=(float(covered / n_ep) if n_ep else np.nan),
        median_fault_episode_length_rows=(float(np.median(lengths)) if lengths else np.nan),
        median_first_action_delay_rows=(float(np.median(delays)) if delays else np.nan),
    )


def _r35_export_dqa_action_audit(dataset_name, exp, target_vars, config,
                                 obs_mask, fault_mask, kind_masks,
                                 authorization_summary, action_tol=1e-12):
    """Timestamp-level DQA x PTAC intervention audit for frozen R34D replay.

    Primary association statistics use SOURCE-RETAINED test rows only. DQA is
    an abnormal-regime indicator, not a clean-value oracle; therefore this
    audit validates selectivity/abstention behavior and never claims physical
    correction accuracy. EC is additionally marked non-independent because its
    health gate is causally fitted from DQA fault labels.
    """
    outdir = config.OUTPUT_DIR
    idx = pd.Index(getattr(exp, 'last_test_indices', pd.Index([])))
    if len(idx) == 0:
        raise RuntimeError(f'[R35] {dataset_name}: PTAC did not retain test indices')
    corr = np.asarray(getattr(exp, 'last_corrections', None), dtype=float)
    anchor = np.asarray(getattr(exp, 'last_anchor_prediction', None), dtype=float)
    final = np.asarray(getattr(exp, 'last_final_prediction', None), dtype=float)
    recorded = np.asarray(getattr(exp, 'last_recorded_test', None), dtype=float)
    nt = len(target_vars)
    expected = (len(idx), nt)
    for nm, arr in [('correction', corr), ('anchor', anchor), ('final', final), ('recorded', recorded)]:
        if arr.shape != expected:
            raise RuntimeError(f'[R35] {dataset_name}: {nm} shape {arr.shape} != {expected}')

    if obs_mask is None or fault_mask is None:
        raise RuntimeError(f'[R35] {dataset_name}: DQA observation/fault masks are mandatory')
    obs = obs_mask.reindex(index=idx, columns=target_vars).fillna(False).astype(bool)
    fault = fault_mask.reindex(index=idx, columns=target_vars).fillna(False).astype(bool)
    kinds = {str(k): m.reindex(index=idx, columns=target_vars).fillna(False).astype(bool)
             for k, m in (kind_masks or {}).items() if m is not None}

    pre_masks = getattr(exp, '_r31_test_gate_mask_by_target', {}) or {}
    tol = float(action_tol)
    summary_rows = []
    episode_rows = []
    auth_by_target = {}
    if isinstance(authorization_summary, pd.DataFrame) and 'target' in authorization_summary.columns:
        auth_by_target = {str(r['target']): r for _, r in authorization_summary.iterrows()}

    for j, target in enumerate(target_vars):
        tname = str(target)
        safe = re.sub(r'[^0-9A-Za-z._-]+', '_', tname).strip('_') or f'target{j}'
        pre = np.asarray(pre_masks.get(tname, np.zeros(len(idx), dtype=bool)), dtype=bool)
        if pre.shape != (len(idx),):
            raise RuntimeError(f'[R35] {dataset_name}/{tname}: pre-safety mask shape {pre.shape}')
        applied = np.abs(corr[:, j]) > tol
        src = obs[tname].values.astype(bool)
        any_fault = fault[tname].values.astype(bool)

        # Timeline table: keep every exact test timestamp, but distinguish the
        # source-retained rows used by the primary association statistics.
        T = pd.DataFrame({
            'timestamp': pd.to_datetime(idx),
            'dataset': dataset_name,
            'target': tname,
            'source_retained': src,
            'dqa_fault_any': any_fault,
            'r31_pre_safety_action': pre,
            'final_applied_action': applied,
            'applied_correction': corr[:, j],
            'abs_applied_correction': np.abs(corr[:, j]),
            'anchor_prediction': anchor[:, j],
            'm2p_prediction': final[:, j],
            # The raw/cleaned series is only treated as recorded telemetry when
            # provenance says the source value was retained.
            'recorded_sensor_value': np.where(src, recorded[:, j], np.nan),
        })
        for kind, km in kinds.items():
            T[f'dqa_{kind}'] = km[tname].values.astype(bool)
        # These are telemetry-consistency errors, NOT physical-truth errors.
        T['anchor_abs_error_to_recorded'] = np.where(
            src, np.abs(anchor[:, j] - recorded[:, j]), np.nan)
        T['m2p_abs_error_to_recorded'] = np.where(
            src, np.abs(final[:, j] - recorded[:, j]), np.nan)
        T['m2p_minus_anchor_abs_error_to_recorded'] = (
            T['m2p_abs_error_to_recorded'] - T['anchor_abs_error_to_recorded'])

        ar = auth_by_target.get(tname, {})
        for col in ('offline_qualified', 'local_nominal_safe',
                    'local_degraded_supported', 'final_authorized', 'r31_gate_kind'):
            T[col] = ar.get(col, np.nan) if hasattr(ar, 'get') else np.nan
        T['r34d_checkpoint_path'] = str(getattr(exp, '_r35_checkpoint_path', '') or '')
        T['r34d_checkpoint_sha256'] = str(getattr(exp, '_r35_checkpoint_sha256', '') or '')

        timeline_path = os.path.join(
            outdir, f'r35_timestamp_audit_{dataset_name}__{safe}.csv')
        T.to_csv(timeline_path, index=False)

        # Primary = exact source-retained rows. Supplementary = all model-visible
        # rows, useful for diagnosing reconstructed/sentinel-heavy periods.
        scopes = [
            ('source_retained_primary', src),
            ('all_test_supplementary', np.ones(len(idx), dtype=bool)),
        ]
        fault_sets = [('any', any_fault)] + [
            (kind, km[tname].values.astype(bool)) for kind, km in kinds.items()
        ]
        for scope_name, sm in scopes:
            for fault_kind, fm in fault_sets:
                use = np.asarray(sm, dtype=bool)
                f_use = np.asarray(fm, dtype=bool)[use]
                for stage_name, action_full in (
                        ('r31_pre_safety', pre), ('final_applied', applied)):
                    a_use = np.asarray(action_full, dtype=bool)[use]
                    assoc = _r35_binary_association(f_use, a_use)
                    eps = _r35_episode_stats(f_use, a_use)
                    # Correction magnitude is meaningful as intervention size,
                    # not as truth recovery, on archival field telemetry.
                    abs_c = np.abs(corr[:, j])[use]
                    c_fault = abs_c[f_use]
                    c_health = abs_c[~f_use]
                    independent = not (tname == 'electric conductivity')
                    role = (
                        'external_consistency_check_gate_not_fit_on_DQA_labels'
                        if independent else
                        'deployment_consistency_only_EC_gate_fit_on_DQA_labels')
                    if stage_name == 'final_applied':
                        role += ';final_authorization_also_uses_DQA_safety_telemetry'
                    row = dict(
                        dataset=dataset_name,
                        target=tname,
                        scope=scope_name,
                        fault_kind=fault_kind,
                        gate_stage=stage_name,
                        n_rows=int(use.sum()),
                        n_actions=int(a_use.sum()),
                        dqa_association_role=role,
                        offline_qualified=ar.get('offline_qualified', np.nan) if hasattr(ar, 'get') else np.nan,
                        local_nominal_safe=ar.get('local_nominal_safe', np.nan) if hasattr(ar, 'get') else np.nan,
                        final_authorized=ar.get('final_authorized', np.nan) if hasattr(ar, 'get') else np.nan,
                        median_abs_correction_on_fault=(float(np.median(c_fault)) if len(c_fault) else np.nan),
                        median_abs_correction_on_healthy=(float(np.median(c_health)) if len(c_health) else np.nan),
                        max_abs_correction_on_fault=(float(np.max(c_fault)) if len(c_fault) else np.nan),
                        max_abs_correction_on_healthy=(float(np.max(c_health)) if len(c_health) else np.nan),
                        **assoc,
                        **eps,
                    )
                    summary_rows.append(row)
                    episode_rows.append(dict(dataset=dataset_name, target=tname,
                                             scope=scope_name, fault_kind=fault_kind,
                                             gate_stage=stage_name, **eps))

        # Timeline visualization: exact timestamp tracks, no lag optimization.
        try:
            x = pd.to_datetime(idx)
            fig, ax = plt.subplots(figsize=(13, 3.6))
            ax.step(x, any_fault.astype(int), where='post', label='DQA fault (any)')
            ax.step(x, pre.astype(int) * 0.70, where='post', label='R31 pre-safety action')
            ax.step(x, applied.astype(int) * 0.40, where='post', label='Final applied action')
            ax.set_ylim(-0.08, 1.12)
            ax.set_yticks([0.0, 0.4, 0.7, 1.0])
            ax.set_yticklabels(['0', 'final', 'R31', 'DQA'])
            ax.set_title(f'{dataset_name} / {tname}: exact DQA-action timeline')
            ax.set_xlabel('timestamp')
            ax.legend(loc='upper right', ncol=3, fontsize=8)
            fig.tight_layout()
            fig.savefig(os.path.join(outdir,
                                     f'r35_decision_timeline_{dataset_name}__{safe}.png'),
                        dpi=180, bbox_inches='tight')
            plt.close(fig)

            fig, ax = plt.subplots(figsize=(13, 4.2))
            ax.plot(x, np.where(src, recorded[:, j], np.nan), label='recorded source telemetry')
            ax.plot(x, anchor[:, j], label='matched anchor')
            ax.plot(x, final[:, j], label='M2P-PTAC')
            hit = np.flatnonzero(applied)
            if len(hit):
                ax.scatter(x[hit], final[hit, j], s=18, label='final intervention')
            ax.set_title(f'{dataset_name} / {tname}: predictions and applied interventions')
            ax.set_xlabel('timestamp')
            ax.set_ylabel(tname)
            ax.legend(loc='best', fontsize=8)
            fig.tight_layout()
            fig.savefig(os.path.join(outdir,
                                     f'r35_prediction_timeline_{dataset_name}__{safe}.png'),
                        dpi=180, bbox_inches='tight')
            plt.close(fig)
        except Exception as e:
            print(f'[R35] timeline plot skipped for {dataset_name}/{tname}: {e}')

    S = pd.DataFrame(summary_rows)
    E = pd.DataFrame(episode_rows)
    sp = os.path.join(outdir, f'r35_dqa_action_summary_{dataset_name}.csv')
    ep = os.path.join(outdir, f'r35_dqa_episode_summary_{dataset_name}.csv')
    S.to_csv(sp, index=False)
    E.to_csv(ep, index=False)

    # Compact primary table for console/manuscript triage: source-retained,
    # aggregate DQA mask, exact zero-lag association only.
    primary = S[(S['scope'] == 'source_retained_primary') &
                (S['fault_kind'] == 'any')].copy()
    keep = ['dataset','target','gate_stage','n_rows','n_fault','n_healthy','n_actions',
            'p_action_given_fault','p_action_given_healthy','action_enrichment_ratio',
            'fisher_odds_ratio','fisher_p_two_sided','fault_episode_action_coverage',
            'dqa_association_role']
    print('\n[R35] PRIMARY EXACT-TIMESTAMP DQA x ACTION AUDIT')
    print(primary[keep].round(6).to_string(index=False))
    print('[R35] Interpretation boundary: DQA locates abnormal regimes; it does not provide clean physical truth.')
    return S


# ============================================================================
# ============================================================================
R36_FEATURES = (
    'diff1', 'abs_diff1',
    'robust_dev_6', 'robust_dev_24',
    'slope_6', 'slope_24',
    'sd_ratio_6_24', 'flat_frac_6', 'run_length_flat',
    'hour_sin', 'hour_cos',
)
R36_THRESHOLD = 0.50
R36_MIN_FAULT_ROWS = 5
R36_MIN_FAULT_EPISODES = 2
R36_MIN_HEALTHY_ROWS = 20
R36_MIN_SENSITIVITY = 0.60
R36_MIN_SPECIFICITY = 0.80
R36_MIN_BALANCED_ACCURACY = 0.70
R36_MIN_EPISODE_COVERAGE = 0.50
R36_MAX_FISHER_P = 0.05
R36_MIN_FINAL_ACTION_ON_CORRECTABLE = 0.50
R36_MAX_FINAL_ACTION_ON_HEALTHY = 0.20


def _r36_rolling_slope(x):
    a = np.asarray(x, dtype=float)
    good = np.isfinite(a)
    if good.sum() < 2:
        return np.nan
    yy = a[good]
    xx = np.arange(len(a), dtype=float)[good]
    xx = xx - xx.mean()
    den = float(np.dot(xx, xx))
    return float(np.dot(xx, yy - yy.mean()) / den) if den > 0 else 0.0


def _r36_causal_features(series):
    """Causal pH-only detector features; current and past telemetry only."""
    y = pd.to_numeric(series, errors='coerce').astype(float)
    d1 = y.diff()
    med6 = y.rolling(6, min_periods=3).median()
    med24 = y.rolling(24, min_periods=6).median()
    mad6 = (y - med6).abs().rolling(6, min_periods=3).median()
    mad24 = (y - med24).abs().rolling(24, min_periods=6).median()
    # Fixed physical-unit epsilon: never estimate a scale from the full
    # holdout series, because that would let future test telemetry influence
    # earlier feature values. pH resolution well below 1e-6 is immaterial here.
    eps = 1e-6
    sd6 = y.rolling(6, min_periods=3).std(ddof=0)
    sd24 = y.rolling(24, min_periods=6).std(ddof=0)
    flat = d1.abs().le(eps).astype(float)
    flat_frac = flat.rolling(6, min_periods=3).mean()
    # Causal consecutive near-flat run length.
    rl = np.zeros(len(y), dtype=float)
    run = 0
    for i, v in enumerate(flat.fillna(False).astype(bool).values):
        run = run + 1 if v else 0
        rl[i] = run
    idx = y.index
    F = pd.DataFrame(index=idx)
    F['diff1'] = d1
    F['abs_diff1'] = d1.abs()
    F['robust_dev_6'] = (y - med6).abs() / (1.4826 * mad6 + eps)
    F['robust_dev_24'] = (y - med24).abs() / (1.4826 * mad24 + eps)
    F['slope_6'] = y.rolling(6, min_periods=3).apply(_r36_rolling_slope, raw=True)
    F['slope_24'] = y.rolling(24, min_periods=6).apply(_r36_rolling_slope, raw=True)
    F['sd_ratio_6_24'] = sd6 / (sd24 + eps)
    F['flat_frac_6'] = flat_frac
    F['run_length_flat'] = rl
    F['hour_sin'] = np.sin(2 * np.pi * idx.hour / 24.0)
    F['hour_cos'] = np.cos(2 * np.pi * idx.hour / 24.0)
    F = F.replace([np.inf, -np.inf], np.nan)
    return F[list(R36_FEATURES)]


def _r36_correctable_mask(kind_masks, target, index):
    """Predeclared correctable state: excursion OR drift; severe faults abstain."""
    idx = pd.Index(index)
    pos = pd.Series(False, index=idx)
    for k in ('excursion', 'drift'):
        m = (kind_masks or {}).get(k)
        if m is not None and target in m.columns:
            pos |= m.reindex(idx)[target].fillna(False).astype(bool)
    severe = pd.Series(False, index=idx)
    for k in ('stuck', 'zero', 'sentinel'):
        m = (kind_masks or {}).get(k)
        if m is not None and target in m.columns:
            severe |= m.reindex(idx)[target].fillna(False).astype(bool)
    # Severe state wins if masks overlap.
    return (pos & ~severe).astype(bool), severe.astype(bool)


def _r36_dev_frame(file_path, config, target='ph', use_fraction=0.85):
    df = load_water_quality_data(file_path, config)
    if df is None or target not in df.columns:
        raise RuntimeError(f'[R36] development target {target!r} absent: {file_path}')
    om = load_observation_mask(file_path, config)
    km = load_fault_kind_masks(file_path, config)
    ncut = int(np.floor(len(df) * float(use_fraction)))
    idx = pd.Index(df.index[:ncut])
    F = _r36_causal_features(df[target]).reindex(idx)
    y, severe = _r36_correctable_mask(km, target, idx)
    obs = (om.reindex(idx)[target].fillna(False).astype(bool)
           if om is not None and target in om.columns
           else pd.Series(True, index=idx))
    good = obs & F.notna().all(axis=1)
    X = F.loc[good].copy()
    yy = y.loc[good].astype(int)
    meta = dict(file_path=str(file_path), n_raw=int(len(df)), n_used=int(len(X)),
                n_positive=int(yy.sum()), n_negative=int((1-yy).sum()),
                n_severe=int(severe.loc[good].sum()), cutoff_fraction=float(use_fraction),
                first_timestamp=str(X.index.min()) if len(X) else None,
                last_timestamp=str(X.index.max()) if len(X) else None)
    return X, yy, meta


def _r36_fit_detector(config, output_dir):
    """Fit exactly one predeclared detector on development stations only."""
    dev = [
        ('stable_190226', config.FILE_PATH_STABLE),
        ('challenged_190234', config.FILE_PATH_CHALLENGED),
        ('challenged_189509', config.FILE_PATH_CHALLENGED_2),
    ]
    Xs, ys, meta = [], [], []
    for name, path in dev:
        X, y, m = _r36_dev_frame(path, config, target='ph', use_fraction=0.85)
        m['dataset'] = name
        Xs.append(X.reset_index(drop=True)); ys.append(y.reset_index(drop=True)); meta.append(m)
    X = pd.concat(Xs, ignore_index=True)
    y = pd.concat(ys, ignore_index=True).astype(int)
    if int(y.sum()) < 20 or int((1-y).sum()) < 20:
        raise RuntimeError(f'[R36] development detector labels underpowered: pos={int(y.sum())}, neg={int((1-y).sum())}')
    scaler = StandardScaler().fit(X[list(R36_FEATURES)].values)
    model = LogisticRegression(
        C=1.0, penalty='l2', solver='liblinear', class_weight='balanced',
        random_state=42, max_iter=1000)
    model.fit(scaler.transform(X[list(R36_FEATURES)].values), y.values)
    coef = pd.DataFrame({'feature': list(R36_FEATURES), 'coefficient': model.coef_.ravel()})
    coef.to_csv(os.path.join(output_dir, 'r36_detector_coefficients.csv'), index=False)
    with open(os.path.join(output_dir, 'r36_detector_training_manifest.json'), 'w') as fh:
        json.dump({'development_datasets': meta, 'n_rows': int(len(X)),
                   'n_positive': int(y.sum()), 'n_negative': int((1-y).sum()),
                   'features': list(R36_FEATURES), 'threshold': R36_THRESHOLD,
                   'model': 'LogisticRegression(C=1.0,l2,liblinear,class_weight=balanced,random_state=42)'},
                  fh, indent=2)
    return scaler, model


def _r36_episode_stats_simple(mask, action):
    return _r35_episode_stats(np.asarray(mask, bool), np.asarray(action, bool))


def _r36_export_holdout_audit(dataset_name, exp, config, obs_mask, kind_masks):
    if not bool(getattr(config, 'R36_DQA_DISTILLED_GATE', False)):
        return None
    target = 'ph'
    idx = pd.Index(getattr(exp, 'last_test_indices', []))
    if len(idx) == 0:
        raise RuntimeError('[R36] missing exact test indices from PTAC experiment')
    probs = (getattr(config, 'R36_EXTERNAL_GATE_PROB_SERIES_BY_TARGET', {}) or {}).get(target)
    gates = (getattr(config, 'R36_EXTERNAL_GATE_SERIES_BY_TARGET', {}) or {}).get(target)
    if probs is None or gates is None:
        raise RuntimeError('[R36] missing sealed detector probabilities/gates')
    truth, severe = _r36_correctable_mask(kind_masks, target, idx)
    obs = (obs_mask.reindex(idx)[target].fillna(False).astype(bool)
           if obs_mask is not None and target in obs_mask.columns
           else pd.Series(True, index=idx))
    valid = obs & probs.reindex(idx).notna()
    t = truth.reindex(idx)[valid].astype(bool).values
    sev = severe.reindex(idx)[valid].astype(bool).values
    g = gates.reindex(idx)[valid].fillna(False).astype(bool).values
    p = probs.reindex(idx)[valid].astype(float).values
    corr = np.asarray(getattr(exp, 'last_corrections', np.empty((0,1))), dtype=float)
    if corr.ndim != 2 or corr.shape[0] != len(idx):
        raise RuntimeError('[R36] correction/test-index cardinality mismatch')
    tol = 1e-12
    final_all = np.abs(corr[:,0]) > tol
    final = final_all[np.asarray(valid.values, dtype=bool)]

    assoc = _r35_binary_association(t, g)
    eps = _r36_episode_stats_simple(t, g)
    tp = int(np.sum(t & g)); fn = int(np.sum(t & ~g)); fp = int(np.sum(~t & g)); tn = int(np.sum(~t & ~g))
    sensitivity = tp / (tp+fn) if tp+fn else np.nan
    specificity = tn / (tn+fp) if tn+fp else np.nan
    precision = tp / (tp+fp) if tp+fp else np.nan
    f1 = 2*precision*sensitivity/(precision+sensitivity) if np.isfinite(precision) and np.isfinite(sensitivity) and precision+sensitivity else np.nan
    bal = 0.5*(sensitivity+specificity) if np.isfinite(sensitivity) and np.isfinite(specificity) else np.nan
    npos=int(t.sum()); nneg=int((~t).sum())
    evidence = bool(npos >= R36_MIN_FAULT_ROWS and eps['n_fault_episodes'] >= R36_MIN_FAULT_EPISODES and nneg >= R36_MIN_HEALTHY_ROWS)
    fisher_ok = bool(np.isfinite(assoc['fisher_p_two_sided']) and assoc['fisher_p_two_sided'] <= R36_MAX_FISHER_P and (not np.isfinite(assoc['fisher_odds_ratio']) or assoc['fisher_odds_ratio'] > 1.0))
    detection_pass = bool(evidence and sensitivity >= R36_MIN_SENSITIVITY and specificity >= R36_MIN_SPECIFICITY and bal >= R36_MIN_BALANCED_ACCURACY and eps['fault_episode_action_coverage'] >= R36_MIN_EPISODE_COVERAGE and fisher_ok)

    p_final_fault = float(final[t].mean()) if t.any() else np.nan
    p_final_healthy = float(final[~t].mean()) if (~t).any() else np.nan
    local_safe = bool(getattr(exp, '_r19_safety_diag', {}).get(target, {}).get('local_nominal_safe', False))
    final_auth = bool(getattr(exp, '_r19_safety_diag', {}).get(target, {}).get('passed', False))
    routing_pass = bool(detection_pass and final_auth and np.isfinite(p_final_fault) and p_final_fault >= R36_MIN_FINAL_ACTION_ON_CORRECTABLE and np.isfinite(p_final_healthy) and p_final_healthy <= R36_MAX_FINAL_ACTION_ON_HEALTHY)

    rows = pd.DataFrame({
        'timestamp': idx[valid.values], 'source_retained': True,
        'dqa_correctable_excursion_or_drift': t,
        'dqa_severe_stuck_zero_sentinel': sev,
        'detector_probability': p, 'detector_gate': g, 'final_applied_action': final,
        'applied_correction': corr[np.asarray(valid.values, dtype=bool),0],
    })
    rows.to_csv(os.path.join(config.OUTPUT_DIR, 'r36_holdout_timestamp_audit.csv'), index=False)

    summary = dict(
        protocol='R36_SEALED_DQA_DISTILLED_HOLDOUT_V1', dataset=dataset_name, target=target,
        holdout_station='861513064189988', threshold=R36_THRESHOLD,
        n_source_retained_test_rows=int(len(t)), n_correctable=int(npos), n_healthy=int(nneg),
        n_severe=int(sev.sum()), n_fault_episodes=int(eps['n_fault_episodes']),
        n_fault_episodes_with_detection=int(eps['n_fault_episodes_with_action']),
        fault_episode_detection_coverage=float(eps['fault_episode_action_coverage']),
        sensitivity=float(sensitivity) if np.isfinite(sensitivity) else None,
        specificity=float(specificity) if np.isfinite(specificity) else None,
        precision=float(precision) if np.isfinite(precision) else None,
        f1=float(f1) if np.isfinite(f1) else None,
        balanced_accuracy=float(bal) if np.isfinite(bal) else None,
        detector_action_rate=float(g.mean()) if len(g) else None,
        action_enrichment_ratio=float(assoc['action_enrichment_ratio']) if np.isfinite(assoc['action_enrichment_ratio']) else None,
        fisher_odds_ratio=float(assoc['fisher_odds_ratio']) if np.isfinite(assoc['fisher_odds_ratio']) else None,
        fisher_p_two_sided=float(assoc['fisher_p_two_sided']) if np.isfinite(assoc['fisher_p_two_sided']) else None,
        evidence_sufficient=evidence, local_nominal_safe=local_safe, final_authorized=final_auth,
        final_action_given_correctable=float(p_final_fault) if np.isfinite(p_final_fault) else None,
        final_action_given_healthy=float(p_final_healthy) if np.isfinite(p_final_healthy) else None,
        detection_confirmation_passed=detection_pass,
        routing_confirmation_passed=routing_pass,
        acceptance=dict(min_fault_rows=R36_MIN_FAULT_ROWS, min_fault_episodes=R36_MIN_FAULT_EPISODES,
                        min_healthy_rows=R36_MIN_HEALTHY_ROWS, min_sensitivity=R36_MIN_SENSITIVITY,
                        min_specificity=R36_MIN_SPECIFICITY, min_balanced_accuracy=R36_MIN_BALANCED_ACCURACY,
                        min_episode_coverage=R36_MIN_EPISODE_COVERAGE, max_fisher_p=R36_MAX_FISHER_P,
                        min_final_action_on_correctable=R36_MIN_FINAL_ACTION_ON_CORRECTABLE,
                        max_final_action_on_healthy=R36_MAX_FINAL_ACTION_ON_HEALTHY),
        interpretation_limit='DQA validates real-field fault recognition/routing timing, not numerical physical correction truth.'
    )
    with open(os.path.join(config.OUTPUT_DIR, 'r36_holdout_confirmation.json'), 'w') as fh:
        json.dump(summary, fh, indent=2)
    pd.DataFrame([summary | {k: v for k,v in assoc.items() if np.isscalar(v)}]).to_csv(
        os.path.join(config.OUTPUT_DIR, 'r36_holdout_confirmation.csv'), index=False)

    # Timeline, read-only.
    try:
        fig, ax = plt.subplots(figsize=(12, 4))
        x = rows['timestamp']
        ax.step(x, rows['dqa_correctable_excursion_or_drift'].astype(int)*1.0, where='post', label='DQA correctable')
        ax.step(x, rows['detector_gate'].astype(int)*0.68, where='post', label='R36 detector')
        ax.step(x, rows['final_applied_action'].astype(int)*0.36, where='post', label='Final PTAC action')
        ax.set_ylim(-0.05, 1.1); ax.set_yticks([0,0.36,0.68,1.0]); ax.set_yticklabels(['0','final','detector','DQA'])
        ax.set_title('R36 sealed holdout: DQA-correctable vs automatic detector vs final intervention')
        ax.legend(loc='upper right'); fig.autofmt_xdate(); fig.tight_layout()
        fig.savefig(os.path.join(config.OUTPUT_DIR, 'r36_holdout_timeline.png'), dpi=200)
        plt.close(fig)
    except Exception as e:
        print(f'[R36] timeline write skipped: {e}')
    print('\n[R36] SEALED HOLDOUT CONFIRMATION')
    print(json.dumps(summary, indent=2))
    return summary


def _run_r34_challenged_eval(dataset_name, df, target_vars, config,
                              obs_mask=None, fault_mask=None, kind_masks=None):
    """Run only frozen PTAC and its feature-matched differenced XGB anchor."""
    print("\n" + "=" * 96)
    print(f"R34 CHALLENGED-FIELD AUTHORIZATION EVALUATION -- {dataset_name}")
    print("=" * 96)
    print("Q_offline : frozen R32 fixed-boundary qualification artifact")
    print("S_local   : unchanged local nominal R19 UCB interlock")
    print("G_t       : unchanged R31 pointwise hybrid gate")
    print("C         : 0.0001 fixed; no sweep")
    print("SPLIT     : raw chronological 70/15/15; NO adaptive fallback")
    print("REFERENCE : archival sensor record only; no physical-correction truth claim")
    print("=" * 96)

    # R34D -- DQA exclusion must apply to the FEATURE SET as well as scoring.
    # create_tabular_features() automatically treats every non-target, non-battery
    # water-quality column as exogenous.  Therefore a channel excluded by DQA
    # (e.g. degenerate dissolved oxygen on challenged_89509) would otherwise
    # re-enter as a predictor and its missing/invalid history could delete an
    # entire raw-time validation block when the feature frame is dropna()'d.
    # We remove only channels explicitly excluded by the station's authoritative
    # DQA manifest.  All remaining legitimate cross-channel predictors are kept.
    _dqa_excluded = tuple(getattr(config, '_r34_dqa_excluded_channels', tuple()) or tuple())
    _drop_from_features = [c for c in _dqa_excluded if c in df.columns and c not in target_vars]
    if _drop_from_features:
        print(f"[R34D] removing DQA-excluded channel(s) from model features: {_drop_from_features}")
    df_model = df.drop(columns=_drop_from_features, errors='ignore').copy()

    # Audit model-visible rows BEFORE fitting without changing raw chronology.
    _xp, _yp, _lp = create_tabular_features(
        df_model, target_vars, config=config, return_delta=True)
    _tr, _va, _te = _raw_split_boundaries(config, len(df_model))
    _rtr = pd.Index(df_model.index[:_tr])
    _rva = pd.Index(df_model.index[_tr:_va])
    _rte = pd.Index(df_model.index[_te:])
    _vis = dict(
        train=int(sum(ix in _rtr for ix in _xp.index)),
        val=int(sum(ix in _rva for ix in _xp.index)),
        test=int(sum(ix in _rte for ix in _xp.index)),
    )
    print(f"[R34D] comparator feature visibility after DQA feature isolation: {_vis}")
    if min(_vis.values()) <= 0:
        raise RuntimeError(
            '[R34D] fixed raw-time block remains empty after removing only DQA-'
            f'excluded feature channels: {_vis}. Chronology will not be changed.')

    c_anchor = copy.deepcopy(config)
    c_ptac = copy.deepcopy(config)
    anchor = TabularExperiment(
        CORRECTOR_ATTRIBUTION_ANCHOR, c_anchor, xgb.XGBRegressor,
        {'objective': 'reg:squarederror', 'n_estimators': 1000,
         'learning_rate': 0.01, 'random_state': 42},
        obs_mask=obs_mask, fault_mask=fault_mask,
        target_mode='delta', use_drift_bank=True)
    ar, at, ae = anchor.run(df_model.copy(), target_vars)

    model_name = 'M2P-PTAC (R34 frozen C=0.0001)'
    exp = PTACExperiment(
        model_name, c_ptac, base_lambda=1e-4,
        conformal_alpha=None, obs_mask=obs_mask, fault_mask=fault_mask)
    exp.is_headline = True
    mr, mt, me = exp.run(df_model.copy(), target_vars)

    rows = []
    for name, res in ((CORRECTOR_ATTRIBUTION_ANCHOR, ar), (model_name, mr)):
        rr = dict(res)
        rr['model_name'] = name
        rows.append(rr)
    metrics = pd.DataFrame(rows).set_index('model_name')
    metrics_path = os.path.join(config.OUTPUT_DIR, f'r34_metrics_{dataset_name}.csv')
    metrics.to_csv(metrics_path)

    per_target_attribution(
        metrics, target_vars, config, dataset_name, model_name,
        baseline_name=CORRECTOR_ATTRIBUTION_ANCHOR, degenerate=())

    diag = getattr(exp, '_r19_safety_diag', {}) or {}
    qmap = getattr(config, 'R34_OFFLINE_QUALIFICATION_BY_TARGET', {}) or {}
    corr = np.asarray(getattr(exp, 'last_corrections', np.empty((0, len(target_vars)))), dtype=float)
    tol = float(mr.get('parity_tol', 1e-12) or 1e-12)
    summary = []
    for j, target in enumerate(target_vars):
        d = diag.get(target, {})
        pre_action = float(getattr(exp, '_r31_test_action_rate', {}).get(target, np.nan))
        val_action = float(getattr(exp, '_r31_val_action_rate', {}).get(target, np.nan))
        final_action = (float(np.mean(np.abs(corr[:, j]) > tol))
                        if corr.ndim == 2 and corr.shape[0] and j < corr.shape[1]
                        else np.nan)
        obs_col = f'{target}_MAE_obs'
        mae_col = (obs_col if obs_col in metrics.columns
                   and pd.notna(metrics.loc[CORRECTOR_ATTRIBUTION_ANCHOR, obs_col])
                   and pd.notna(metrics.loc[model_name, obs_col])
                   else f'{target}_MAE')
        b = float(metrics.loc[CORRECTOR_ATTRIBUTION_ANCHOR, mae_col])
        m = float(metrics.loc[model_name, mae_col])
        def gv(rowname, suffix):
            col = f'{target}_{suffix}'
            return (float(metrics.loc[rowname, col])
                    if col in metrics.columns and pd.notna(metrics.loc[rowname, col])
                    else np.nan)
        summary.append(dict(
            dataset=dataset_name, target=target,
            offline_qualified=bool(qmap.get(target, False)),
            local_nominal_safe=bool(d.get('local_nominal_safe', False)),
            local_degraded_supported=bool(d.get('local_degraded_supported', False)),
            final_authorized=bool(d.get('passed', False)),
            r31_gate_kind=str(getattr(exp, '_r31_gate_kind', {}).get(target, '')),
            r31_val_action_rate_pre_safety=val_action,
            r31_test_action_rate_pre_safety=pre_action,
            final_test_action_rate=final_action,
            n_degraded=int(d.get('n_degraded', 0)),
            n_degraded_units=int(d.get('n_degraded_units', 0)),
            n_nominal=int(d.get('n_nominal', 0)),
            n_nominal_units=int(d.get('n_nominal_units', 0)),
            degraded_rescue=float(d.get('degraded_rescue', np.nan)),
            degraded_rescue_lcb=float(d.get('degraded_rescue_lcb', np.nan)),
            nominal_penalty_ucb_rel=float(d.get('nominal_penalty_ucb_rel', np.nan)),
            mae_multiplier_ucb=float(d.get('mae_multiplier_ucb', np.nan)),
            metric_scope=('source-retained only' if mae_col == obs_col else 'all points'),
            anchor_mae=b, m2p_mae=m, abs_gain=b-m,
            pct_improvement=(100.0 * (b-m) / b if b else np.nan),
            anchor_mae_fault=gv(CORRECTOR_ATTRIBUTION_ANCHOR, 'MAE_fault'),
            m2p_mae_fault=gv(model_name, 'MAE_fault'),
            anchor_mae_healthy=gv(CORRECTOR_ATTRIBUTION_ANCHOR, 'MAE_healthy'),
            m2p_mae_healthy=gv(model_name, 'MAE_healthy'),
            max_abs_correction=float(mr.get(f'{target}_MaxAbsCorrection', np.nan)),
            reason=str(d.get('reason', '')),
        ))
    out = pd.DataFrame(summary)
    out_path = os.path.join(config.OUTPUT_DIR, f'r34_authorization_summary_{dataset_name}.csv')
    out.to_csv(out_path, index=False)
    print("\n[R34] authorization + attribution summary")
    print(out.round(6).to_string(index=False))

    # fitted models, gates, safety decisions and reported metrics.
    _r35_export_dqa_action_audit(
        dataset_name, exp, target_vars, config,
        obs_mask=obs_mask, fault_mask=fault_mask, kind_masks=kind_masks,
        authorization_summary=out, action_tol=tol)
    if bool(getattr(config, 'R36_DQA_DISTILLED_GATE', False)):
        _r36_export_holdout_audit(dataset_name, exp, config, obs_mask, kind_masks)
    return out


def run_full_benchmark_suite(dataset_name, df, target_vars, config,
                             is_public_data=False, obs_mask=None, fault_mask=None,
                             station_hint=None, kind_masks=None):
    if df is None:
        return None  # Return None so caller can detect failure

    _ensure_variant_output_dir(config)

    # ---------------------------------------------------------------- R16-A
    # CADENCE FIRST. Every downstream frequency-dependent quantity -- the
    # regularisation grid, the seasonal MASE period, the lag and rolling-window
    # sets, the encoder window sizes, NeuralForecast's and Prophet's freq -- is
    # derived here from THIS dataset's sampling interval and attached to config.
    
    # different model on a manufactured grid while appearing in the same table.
    ensure_cadence(df, config, dataset_name, verbose=True)

    # Validate the handoff before filtering it.  This catches a stale mask whose
    # index/columns no longer describe the cleaned file instead of letting a
    # later reindex silently convert the mismatch to False.
    validate_dqa_handoff(df, target_vars, obs_mask, fault_mask, kind_masks,
                         config, dataset_name)

    # Honour the authoritative DQA exclusion list BEFORE the generic window
    # gate.  Otherwise a measured stuck channel is mislabeled as a forward-fill
    # plateau and its audited exclusion reason disappears from the run record.
    excl = load_target_exclusions(config, station_hint=station_hint)
    # R34D: retain the complete DQA exclusion map on config.  In the challenged-
    # only authorization branch, excluded sensor channels must not silently
    # re-enter create_tabular_features() as exogenous predictors after they have
    # been removed from target_vars.  That previously allowed degenerate DO on
    # challenged_89509 to wipe the entire raw validation block via global dropna.
    if bool(getattr(config, 'R34_CHALLENGED_ONLY', False)):
        config._r34_dqa_excluded_channels = tuple(excl.keys()) if excl else tuple()
    if excl:
        dropped = [v for v in target_vars if v in excl]
        if dropped:
            print(f"\n[DQA] Dropping {len(dropped)} target(s) excluded by the data "
                  f"quality assessment for '{dataset_name}':")
            for v in dropped:
                print(f"       - {v}: {excl[v]}")
            print("       The channels remain documented in the DQA outputs, "
                  "but are not forecast-scored or included in model-level "
                  "fault strata. State the exclusion in the manuscript.")
            target_vars = [v for v in target_vars if v not in excl]
        if not target_vars:
            print(f"[DQA] Every target for '{dataset_name}' was excluded. "
                  f"Skipping this dataset.")
            return None

    # Secondary safeguard for targets not already excluded by DQA.  It cannot
    # replace the DQA verdict and therefore runs second.
    target_vars = assert_test_window_usable(df, target_vars, config,
                                            dataset_name, obs_mask=obs_mask)

    # travel on it rather than as a new kwarg on twenty-odd constructors. Set
    # here and read in compute_metrics' callers; absent means per-kind metrics
    # are simply not reported.
    config._kind_masks = kind_masks or {}

    
    # to every experiment that accepts it. Previously each family regularised
    # the frame its own way -- the neural comparators scored against an
    # asfreq('h') frame with inserted rows, the classical ones against the raw
    # index -- so "the same testbed" meant two different ground truths, and on
    # the Belgian data one of them still held NaN at metric time.
    eval_truth = get_eval_truth(df, config, list(target_vars))
    config._eval_truth = eval_truth

    # A testbed above CADENCE_MAX_INTERP_FRAC is stamped cadence_valid=False on
    # every result row -- reportable as a diagnostic, barred from a headline
    # aggregate -- rather than being silently scored or silently dropped.
    _cad_valid, _cad_diag = assert_cadence_integrity(
        df, eval_truth, config, list(target_vars), dataset_name,
        obs_mask=obs_mask)
    config._cadence_valid = bool(_cad_valid)
    config._cadence_diag = _cad_diag

    # handed to every model's compute_metrics call. This is the denominator the
    # MASE columns should have had: measured on the window that was scored.
    config._persist_truth = build_persistence_reference(
        eval_truth, list(target_vars), config)

    if bool(getattr(config, 'R34_CHALLENGED_ONLY', False)):
        return _run_r34_challenged_eval(
            dataset_name, df, target_vars, config,
            obs_mask=obs_mask, fault_mask=fault_mask, kind_masks=kind_masks)

    print("\n" + "#"*80 + f"\n### DEFINITIVE BENCHMARK SUITE ON {dataset_name.upper()} DATASET ###\n" + "#"*80)
    print("[FINAL-R19] release definition: ordinary/nominal benchmark keeps the "
          "audited deployed anchor; controlled degradation uses explicit T2 "
          "corrector supervision (clean - deployed-anchor) with the anchor "
          "never clean-retargeted. Validation safety veto is "
          f"{'ON' if getattr(config, 'R19_SAFETY_VETO', False) else 'OFF'}.")
    print("[RR-FINAL] XGBoost anchor and submitted BiLSTM/CNN/GRU/MHA "
          "architecture preserved; graph deadband floor=0, with a "
          "calibration-block probability threshold and an independent "
          "confidence-bound safety veto; 5-seed stress/ablation protocol "
          "enabled.")
    os.makedirs(config.OUTPUT_DIR, exist_ok=True)

    
    # OPT-IN RESUME.
    #
    # main() runs this suite over four testbeds sequentially. When the job is
    # killed on testbed 3, resubmitting re-runs testbeds 1 and 2 from scratch --
    # hours of GPU time to reproduce CSVs that are already on disk. With
    # M2P_RESUME=1 a testbed whose final metrics CSV already exists is skipped.
    #
    # Default is OFF: silently reusing a stale CSV from an older revision of this
    # file is exactly the kind of provenance error the C-T13 banner above exists
    # to catch. Opt in only when resuming a run of THIS file.
    _final_m = os.path.join(config.OUTPUT_DIR,
                            f'final_results_metrics_{dataset_name}.csv')
    if os.environ.get('M2P_RESUME', '0') == '1' and os.path.exists(_final_m):
        print(f"[R14-E] M2P_RESUME=1 and {os.path.basename(_final_m)} exists "
              f"({os.path.getsize(_final_m)} bytes, mtime "
              f"{time.strftime('%Y-%m-%d %H:%M', time.localtime(os.path.getmtime(_final_m)))}). "
              f"Skipping '{dataset_name}'.")
        print(f"[R14-E] Delete that file to force a re-run of this testbed.")
        return None

    all_results, all_timings, all_errors = [], [], {}

    # --- STAGE 1: SENSITIVITY ANALYSIS ---
    print("\n>>> STAGE 1: Optimizing Hyperparameter C for the Proposed Model...")
    sensitivity_track = []

    for val in config.LAMBDA_ANALYSIS_VALUES:
        name = f"M2P-PTAC (C={val})"
        print(f"Testing {name}...")
        # variants survive only as the negative control in the Stage-2 sweep.
        exp = PTACExperiment(name, config, base_lambda=val,
                             conformal_alpha=config.DEFAULT_CONFORMAL_ALPHA,
                             obs_mask=obs_mask, fault_mask=fault_mask)
        results, timings, errors = exp.run(df.copy(), target_vars)
        # Select on the disjoint C-selection block, never on test.  Missing
        # validation evidence is a release failure, not permission to tune on
        # the reported test interval.
        sel = results.get('_val_MAE_for_selection', np.nan)
        if pd.isna(sel):
            raise RuntimeError(
                f"[SELECT] '{name}' produced no finite validation-only "
                "selection score. Refusing to use test MAE to choose C.")
        _obs_test = [results.get(f'{v}_MAE_obs', np.nan) for v in target_vars]
        _obs_test = [x for x in _obs_test if pd.notna(x)]
        test_mae = (float(np.mean(_obs_test)) if _obs_test else
                    float(np.mean([results[f'{v}_MAE'] for v in target_vars])))
        test_mae_all = float(np.mean(
            [results[f'{v}_MAE'] for v in target_vars]))
        sensitivity_track.append({'lambda': val, 'mae': sel,
                                  'test_mae': test_mae,
                                  'test_mae_all': test_mae_all,
                                  'results': results, 'timings': timings, 'errors': errors})
        results['model_name'] = name
        timings['model_name'] = name
        all_results.append(pd.DataFrame(results, index=[0]))
        all_timings.append(pd.DataFrame(timings, index=[0]))
        all_errors[name] = _timestamp_error_dict(errors, eval_truth.index)

    best_entry = min(sensitivity_track, key=lambda x: x['mae'])
    global_optimal_c = best_entry['lambda']
    ptac_headline_name = f"M2P-PTAC (C={global_optimal_c})"

    # ---------------------------------------------------------------- R16-H
    # Promote the selected arm's degradation probabilities to the headline
    # slot detection_report reads. The headline model is a Stage-1 arm, so
    # this is the first point in the run where its name is known; without
    # this promotion the detection table is never written (see the R16-H
    # note in PTACExperiment.run). Set M2P_NO_DETECTION_PROMOTE=1 to restore
    # the r16 behaviour and confirm the table's absence was this and nothing
    # else.
    _reg = getattr(config, '_ptac_fault_prob_registry', {})
    if os.environ.get('M2P_NO_DETECTION_PROMOTE', '0') != '1' \
            and ptac_headline_name in _reg:
        config._headline_fault_prob, config._headline_test_index = \
            _reg[ptac_headline_name]
        _pm = float(np.nanmean(config._headline_fault_prob))
        print(f"    [R16-H] detection probabilities promoted from the selected "
              f"arm '{ptac_headline_name}'; mean p_fault over its test window "
              f"{_pm:.4f}. A mean near zero means the detector sees a healthy "
              f"station and the model is deliberately reproducing the anchor.")
    elif getattr(config, 'USE_FAULT_GATING', False):
        print(f"    [R16-H] WARNING: no recorded probabilities for the selected "
              f"arm '{ptac_headline_name}' (registry holds {sorted(_reg)}). The "
              f"detection table will be skipped -- do not claim detection "
              f"performance for this testbed.")

    print(f"\n[!] Global Optimal C selected on VALIDATION: {global_optimal_c} "
          f"(equal-target MAE ratio vs matched differenced XGBoost anchor: "
          f"{best_entry['mae']:.5f}; its source-retained "
          f"test MAE: {best_entry.get('test_mae', float('nan')):.5f}; "
          f"all-point test MAE: "
          f"{best_entry.get('test_mae_all', float('nan')):.5f})")
    # If these two are ever bit-identical across every testbed, the selection is
    

    # --- STAGE 2: CONTROLLED ABLATIONS & EXTERNAL BASELINES ---
    print(">>> STAGE 2: Running Controlled Ablations and External Baselines...")

    ablation_exps = [
        PTACExperiment("M2P-Ablation (Unified Enc.)", config, base_lambda=global_optimal_c,
                       unified_encoder=True, conformal_alpha=config.DEFAULT_CONFORMAL_ALPHA,
                       obs_mask=obs_mask, fault_mask=fault_mask),
        PTACExperiment("M2P-Ablation (No Attention)", config, base_lambda=global_optimal_c,
                       use_attention=False, conformal_alpha=config.DEFAULT_CONFORMAL_ALPHA,
                       obs_mask=obs_mask, fault_mask=fault_mask),
        PTACExperiment("M2P-Ablation (No CNN)", config, base_lambda=global_optimal_c,
                       use_cnn=False, conformal_alpha=config.DEFAULT_CONFORMAL_ALPHA,
                       obs_mask=obs_mask, fault_mask=fault_mask),
    ]

    # ----------------------------------------------------------------------
    # an adjective into a mechanism. Reports MAE at k in {1,2,3} plus the
    # unbounded control, alongside how often each bound actually binds.
    # If clipping barely changes MAE, that IS the result: the bound is free.
    # ----------------------------------------------------------------------
    for k in config.CLIP_K_SWEEP:
        ablation_exps.append(
            PTACExperiment(f"M2P-PTAC (clip k={k})", config, base_lambda=global_optimal_c,
                           clip_k=k, obs_mask=obs_mask, fault_mask=fault_mask))
    ablation_exps.append(
        PTACExperiment("M2P-PTAC (unbounded, as submitted)", config,
                       base_lambda=global_optimal_c, clip_k=None, obs_mask=obs_mask, fault_mask=fault_mask))

    # ----------------------------------------------------------------------
    # rows above are retained deliberately as the negative control: they should
    
    # these rows bind at approximately their nominal alpha. The contrast between
    # the two families IS the ablation that justifies calling the model bounded.
    # ----------------------------------------------------------------------
    for a in config.CONFORMAL_ALPHA_SWEEP:
        ablation_exps.append(
            PTACExperiment(f"M2P-PTAC (conformal a={a})", config,
                           base_lambda=global_optimal_c, conformal_alpha=a,
                           obs_mask=obs_mask, fault_mask=fault_mask))

    # ----------------------------------------------------------------------
    # deliberately retained in this ordinary benchmark arm, so this is NOT a
    # fully unprotected control. The fully unprotected/bounded/final safety
    # decomposition is Study B. This naming avoids over-interpreting nominal
    # passthrough rows as a complete gating ablation.
    # ----------------------------------------------------------------------
    if getattr(config, 'RUN_GATED_ABLATION', False):
        ablation_exps.append(
            PTACExperiment("M2P-PTAC (R9 gate disabled; R19 retained)", config,
                           base_lambda=global_optimal_c,
                           conformal_alpha=config.DEFAULT_CONFORMAL_ALPHA,
                           gate_threshold=None,
                           obs_mask=obs_mask, fault_mask=fault_mask))

    external_exps = [
        MonolithicExperiment("M2P-Monolithic", config, obs_mask=obs_mask, fault_mask=fault_mask),
        # so the untuned/tuned gap is measured rather than asserted. If the gap
        
        # measuring the tuning budget, not the architecture -- and that is the
        # honest finding to report.
        MonolithicExperiment("M2P-Monolithic (tuned, C-T7)", config,
                             obs_mask=obs_mask, fault_mask=fault_mask,
                             tuning_grid=config.MONOLITHIC_TUNING_GRID),
        TabularExperiment("XGBoost Baseline", config, xgb.XGBRegressor,
                          {'objective': 'reg:squarederror', 'n_estimators': 1000, 'learning_rate': 0.01, 'random_state': 42},
                          obs_mask=obs_mask, fault_mask=fault_mask),
        TabularExperiment("LightGBM Baseline", config, lgb.LGBMRegressor,
                          {'objective': 'regression_l1', 'n_estimators': 1000, 'learning_rate': 0.01, 'random_state': 42, 'verbose': -1},
                          obs_mask=obs_mask, fault_mask=fault_mask),
        
        # Differenced-anchor variants. ADDED, not substituted: the two rows
        
        # table stays reproducible. These two are identical in every respect
        # except the learning target (increment instead of level), which is
        # what makes the pair a controlled comparison. See TabularExperiment's
        # docstring for the measured per-channel effect and its scope.
        TabularExperiment("XGBoost (differenced target)", config, xgb.XGBRegressor,
                          {'objective': 'reg:squarederror', 'n_estimators': 1000, 'learning_rate': 0.01, 'random_state': 42},
                          obs_mask=obs_mask, fault_mask=fault_mask,
                          target_mode='delta'),
        TabularExperiment("LightGBM (differenced target)", config, lgb.LGBMRegressor,
                          {'objective': 'regression_l1', 'n_estimators': 1000, 'learning_rate': 0.01, 'random_state': 42, 'verbose': -1},
                          obs_mask=obs_mask, fault_mask=fault_mask,
                          target_mode='delta'),
        # ----------------------------------------------------------- PATCH-A1
        # FEATURE-MATCHED DIFFERENCED ANCHORS. Identical to the two rows above
        # in target, params and seed, plus the R17 causal drift bank -- i.e.
        # exactly the feature set PTACExperiment.run() fits its INTERNAL
        # anchor on. The first of these is the correct internal_baseline for
        # the nested attribution test; the four rows together decompose the
        TabularExperiment("XGBoost (differenced target + drift bank)", config, xgb.XGBRegressor,
                          {'objective': 'reg:squarederror', 'n_estimators': 1000, 'learning_rate': 0.01, 'random_state': 42},
                          obs_mask=obs_mask, fault_mask=fault_mask,
                          target_mode='delta', use_drift_bank=True),
        TabularExperiment("LightGBM (differenced target + drift bank)", config, lgb.LGBMRegressor,
                          {'objective': 'regression_l1', 'n_estimators': 1000, 'learning_rate': 0.01, 'random_state': 42, 'verbose': -1},
                          obs_mask=obs_mask, fault_mask=fault_mask,
                          target_mode='delta', use_drift_bank=True),
    ]
    if not is_public_data:
        external_exps.append(ProphetExperiment("Prophet Specialist", config))

    sota_exps = []
    if NEURALFORECAST_AVAILABLE:
        import neuralforecast as _nf_mod
        print(f"[INFO] neuralforecast version: {_nf_mod.__version__}")
        sota_exps.append(NHITSExperiment("N-HiTS", config))
        sota_exps.append(PatchTSTExperiment("PatchTST", config))

    sota_exps += [
        SeasonalNaiveExperiment("SeasonalNaive (24h)", config),
        ThetaExperiment("Theta Method", config),
        ExponentialSmoothingExperiment("ETS (Holt-Winters)", config),
        PhysicsGuidedMLPExperiment("Physics-Guided MLP", config, lambda_physics=0.01),
        GreyBoxXGBExperiment("Grey-Box XGBoost", config),
    ]

    
    # INCREMENTAL CHECKPOINTING.
    #
    # The final `results_df.to_csv` sits AFTER this whole loop, which runs the
    
    # comparators, so do not rely on a hardcoded count; the progress line prints
    
    # [19/24 on stable]: experiment 19 of 24 on testbed 1 of 4, so the eighteen
    # experiments that had already completed -- several of them hours of GPU
    # time -- were discarded with nothing on disk to show for them. One
    # `to_csv` per experiment costs milliseconds against runs measured in hours.
    #
    # `_partial_` files are written after EVERY experiment and are deliberately
    # NOT deleted on success: they double as the record of which experiment was
    # in flight if the job dies again. The authoritative
    # final_results_metrics_<ds>.csv is still written by the original code path
    # below, unchanged, so nothing downstream needs to know these exist.
    _partial_m = os.path.join(config.OUTPUT_DIR,
                              f'_partial_metrics_{dataset_name}.csv')
    _partial_t = os.path.join(config.OUTPUT_DIR,
                              f'_partial_timings_{dataset_name}.csv')

    _queue = ablation_exps + external_exps + sota_exps
    for _qi, exp in enumerate(_queue, start=1):
        # flush=True on the progress line: without it a SLURM kill leaves the
        # buffered name unwritten and the log's last experiment looks completed.
        print(f"\n--- Running Experiment: {exp.model_name} "
              f"[{_qi}/{len(_queue)} on {dataset_name}] ---", flush=True)
        # degradation probabilities the detection table is built from.
        exp.is_headline = (getattr(exp, 'model_name', None) == ptac_headline_name)
        _t_exp = time.time()
        try:
            results, timings, errors = exp.run(df.copy(), target_vars)
            results['model_name'] = exp.model_name
            timings['model_name'] = exp.model_name
            all_results.append(pd.DataFrame(results, index=[0]))
            all_timings.append(pd.DataFrame(timings, index=[0]))
            all_errors[exp.model_name] = _timestamp_error_dict(
                errors, eval_truth.index)
            print(f"--- Finished: {exp.model_name} "
                  f"({time.time() - _t_exp:.1f}s) ---", flush=True)
            try:
                pd.concat(all_results, ignore_index=True).to_csv(_partial_m,
                                                                index=False)
                pd.concat(all_timings, ignore_index=True).to_csv(_partial_t,
                                                                index=False)
            except Exception as _pe:
                print(f"    [R14-B] partial checkpoint failed: {_pe}", flush=True)
        except Exception as e:
            
            # KeyError prints the bare key and for a shape mismatch prints a
            # tuple -- neither locates the failure. The traceback is what makes
            # a 20-experiment overnight run debuggable from the log alone.
            import traceback as _tb
            print(f"!!! Experiment {exp.model_name} FAILED: "
                  f"{type(e).__name__}: {e}", flush=True)
            _tb.print_exc()

    if not all_results:
        # Every experiment failed. Concat would raise "No objects to concatenate"
        # and mask the real cause, which is already above in the log.
        print(f"\n!!! [R14-B] Every experiment failed on '{dataset_name}'. "
              f"No metrics to write. See the tracebacks above.", flush=True)
        return None

    results_df = pd.concat(all_results, ignore_index=True).set_index('model_name')
    timings_df = pd.concat(all_timings, ignore_index=True).set_index('model_name')
    results_df = perform_statistical_tests(
        results_df, all_errors, baseline_name='XGBoost Baseline',
        obs_mask=obs_mask)

    # ======================================================================
    # REVISION REPORTING BLOCK
    # ======================================================================
    # Sec 2.5 -- no target may be silently dropped from the table.
    assert_target_completeness(results_df, target_vars, dataset_name)

    # Sec 2.4 -- identify constant-series targets before they enter any mean.
    degenerate = flag_degenerate_targets(results_df, target_vars, config)

    # ---------------------------------------------------------------- R16-B/D
    # Uniform denominator and uniform safety accounting for every model, before
    # any aggregate is formed -- otherwise the aggregates summarise a table whose
    # columns are populated for some rows and NaN for others.
    results_df = backfill_uniform_metrics(
        results_df, all_errors, config, list(target_vars), dataset_name,
        obs_mask=obs_mask)

    # Sec 2.2 -- scale-free aggregates next to the unit-mixed Macro-MAE.
    if config.REPORT_SCALE_FREE_AGGREGATES:
        results_df = add_aggregate_columns(results_df, target_vars, config, degenerate)

    
    
    # uninterpretable -- and warns on the three that make it over-readable.
    results_df = assert_run_integrity(
        results_df, target_vars, dataset_name, config,
        anchor_name=CORRECTOR_ATTRIBUTION_ANCHOR)

    # ==================================================================== PATCH
    # FINAL SANITY BLOCK. Reports; does not modify any metric. Every statement
    # here is checked against the table that is about to be written, so a
    # failure is visible in the log next to the numbers it concerns.
    # ---------------------------------------------------------------- PATCH-D4
    # PERSIST all_errors. The brief requires the significance CSVs to be
    # regenerable "from the EXISTING STORED ERROR ARRAYS ... without
    # retraining". On the current run that is impossible: all_errors lives only
    # in memory inside this function, and the only per-point arrays on disk are
    # the single-channel EC files (which PATCH-D3 shows are not even
    # arm-attributable). Writing the per-point absolute errors here makes the
    # requirement satisfiable for every future run: significance_report() can
    # then be re-called on the stored dict with a different selected_arm and no
    # model is ever refitted. This adds persistence only -- no metric, fit,
    # split, seed, or test definition is touched.
    try:
        _err_path = os.path.join(config.OUTPUT_DIR,
                                 f'per_point_errors_{dataset_name}.npz')
        _payload, _manifest = {}, []
        for _mn, _ed in all_errors.items():
            if not isinstance(_ed, dict):
                continue
            for _v, _arr in _ed.items():
                _a = np.asarray(_arr, dtype=float).ravel()
                _key = f"{_mn}||{_v}"
                _payload[_key] = _a
                _time_key = None
                if isinstance(_arr, pd.Series):
                    _time_key = _key + '||timestamp_ns'
                    _idx = pd.to_datetime(_arr.index)
                    _payload[_time_key] = _idx.asi8.astype('int64')
                _manifest.append({'dataset': dataset_name, 'model_name': _mn,
                                  'target': _v, 'n': int(_a.size),
                                  'MAE': float(np.nanmean(np.abs(_a)))
                                  if _a.size else np.nan, 'key': _key,
                                  'timestamp_key': _time_key,
                                  'alignment': ('timestamp_inner_join'
                                                if _time_key else
                                                'common_tail_fallback')})
        if _payload:
            np.savez_compressed(_err_path, **_payload)
            pd.DataFrame(_manifest).to_csv(
                os.path.join(config.OUTPUT_DIR,
                             f'per_point_errors_manifest_{dataset_name}.csv'),
                index=False)
            print(f"    [PATCH-D4] wrote per-point errors for "
                  f"{len({r['model_name'] for r in _manifest})} model(s) x "
                  f"{len({r['target'] for r in _manifest})} target(s) -> "
                  f"{os.path.basename(_err_path)}. significance_report() can be "
                  f"re-run from this file for ANY arm without refitting.")
    except Exception as _e:
        print(f"    [PATCH-D4] could not persist per-point errors: {_e}")

    print(f"\n--- [PATCH] FINAL SANITY CHECKS ({dataset_name}) ---")
    # (1) the arm the significance analysis will test == the benchmark-selected
    #     arm. Both come from ptac_headline_name now; assert they agree with the
    #     validation argmin that produced it.
    _sel_ok = ptac_headline_name in results_df.index
    print(f"  [1] selected arm '{ptac_headline_name}' present in results table: "
          f"{_sel_ok}; it is the arm passed to significance_report().")
    if not _sel_ok:
        print("      WARNING: selected arm missing from the table -- the "
              "significance call will refuse rather than substitute.")
    # (2) nested baseline identity.
    print(f"  [2] nested delta-anchor baseline: 'XGBoost (differenced target)' "
          f"present: {'XGBoost (differenced target)' in all_errors}")
    # (3)+(4) gate/prediction consistency and INVALID rows.
    if 'row_invalid' in results_df.columns:
        _inv = results_df.index[
            results_df['row_invalid'].fillna(False).astype(bool)].tolist()
        _in_cols = [c for c in results_df.columns if c.endswith('_CorrectionInert')]
        _n_inert = (int(pd.to_numeric(results_df.get('n_gated_on_but_inert'),
                                      errors='coerce').fillna(0).sum())
                    if 'n_gated_on_but_inert' in results_df.columns else 0)
        print(f"  [3] gated-ON-but-numerically-inert channel-slots across all "
              f"rows: {_n_inert} (row-wise deadband; exact anchor parity, NOT "
              f"a wiring fault -- see PATCH-D2 note in run()).")
        print(f"  [4] rows marked INVALID: {len(_inv)}"
              + (f" -> {_inv}" if _inv else ""))
        # (5) the selected headline row must not be INVALID.
        _sel_invalid = ptac_headline_name in _inv
        print(f"  [5] selected headline arm INVALID: {_sel_invalid}"
              + ("  *** the headline result itself is affected ***"
                 if _sel_invalid else "  (headline result stands)"))
    else:
        print("  [3-5] consistency columns absent -- no PTAC arm produced a "
              "gate diagnostic on this testbed.")
    # (6)-(8) unchanged invariants, restated so the log carries them.
    print(f"  [6] cross-protocol ranking: not introduced by this patch "
          f"(eval_protocol partition unchanged; see R15-G above).")
    print(f"  [7] test-set tuning: not introduced -- arm selection remains the "
          f"validation argmin (_val_MAE_for_selection).")
    print(f"  [8] leakage: not introduced -- no new fit, transform, or "
          f"threshold reads test data in this patch.")
    print(f"  [9] environment manifest/provenance: untouched.")

    results_df.to_csv(os.path.join(config.OUTPUT_DIR, f'final_results_metrics_{dataset_name}.csv'))
    timings_df.to_csv(os.path.join(config.OUTPUT_DIR, f'final_results_timings_{dataset_name}.csv'))

    # ------------------------------------------------------------------ R16-E
    # Does the degradation head detect degradation? The gated corrector's
    # accuracy claim depends entirely on this table, so it is written on every
    # run, including the runs where the answer is no.
    try:
        _hp = getattr(config, '_headline_fault_prob', None)
        _hi = getattr(config, '_headline_test_index', None)
        if _hp is not None and fault_mask is not None and _hi is not None:
            detection_report(results_df, config, list(target_vars), dataset_name,
                             fault_prob=_hp, fault_mask=fault_mask,
                             test_index=_hi)
        elif getattr(config, 'USE_FAULT_GATING', False):
            print("\n[R16-E] gating is on but no fault probabilities were "
                  "recorded from the headline run (no fault mask for this "
                  "testbed, or the headline experiment failed). No detection "
                  "table written -- do not claim detection performance here.")
    except Exception as _de:
        print(f"[R16-E] detection report failed: {type(_de).__name__}: {_de}")


    # ======================================================================
    
    # ======================================================================
    # (a) Significance protocol -- DM on non-nested pairs, paired bootstrap on
    #     the nested pair. See significance_report() for why they differ.
    # ---------------------------------------------------------------- PATCH-A2
    # Build the GATE RECORD for the reported arm, read straight off the metrics
    # frame the run just assembled: per-channel <var>_MaxAbsCorrection (written
    # by PATCH-D2) plus the arm-level Anchor_passthrough flag. This is what lets
    # significance_report() mark abstained channels non-applicable instead of
    # emitting a corrector verdict on a correction of exactly zero.
    #
    # PATCH-A5b: promote the SELECTED arm's checkpoint to the names the asset
    # loader reads, and delete the per-arm candidates. Until this runs, those
    
    # figure was drawn from a model the manuscript does not report.
    try:
        _sel_stem = os.path.join(
            config.OUTPUT_DIR,
            f"model_ptac_{dataset_name}__{_safe_filename(ptac_headline_name)}")
        _sel_bundle = os.path.join(
            config.OUTPUT_DIR,
            f"prediction_bundle_{dataset_name}__"
            f"{_safe_filename(ptac_headline_name)}.npz")
        _reported_bundle = os.path.join(
            config.OUTPUT_DIR,
            f"prediction_bundle_{dataset_name}__REPORTED.npz")
        if os.path.exists(_sel_bundle):
            shutil.copyfile(_sel_bundle, _reported_bundle)
            print(f"    [PREDICTION-BUNDLE] promoted reported arm -> "
                  f"{os.path.basename(_reported_bundle)}")
        else:
            _register_release_failure(
                config, 'MISSING_REPORTED_PREDICTION_BUNDLE',
                f"No prediction bundle for selected arm '{ptac_headline_name}' "
                f"on dataset '{dataset_name}'.")
        if any(os.path.exists(_sel_stem + _ext)
               for _ext in ('.keras', '.h5')):
            # Write a name NO later arm can clobber. The generic and
            # per-dataset stems are still refreshed for backward
            # compatibility, but arms that run after this point (the
            # fault-weight sweep, the drift-stress arms) overwrite them
            # again -- in the r5 smoke run the end-of-run model_ptac.h5
            # held 'M2P-PTAC (fw=1)'. The REPORTED stem is written once,
            # here, and the asset loader reads it first.
            for _ext in ('.h5', '.keras', '.manifest.json'):
                if not os.path.exists(_sel_stem + _ext):
                    continue
                for _dst in (os.path.join(
                                 config.OUTPUT_DIR,
                                 f"model_ptac_{dataset_name}__REPORTED" + _ext),
                             os.path.join(config.OUTPUT_DIR,
                                          f"model_ptac_{dataset_name}" + _ext),
                             os.path.join(config.OUTPUT_DIR,
                                          "model_ptac" + _ext)):
                    shutil.copyfile(_sel_stem + _ext, _dst)
            print(f"    [A5] promoted the checkpoint of the REPORTED arm "
                  f"'{ptac_headline_name}' to model_ptac[_{dataset_name}].*; "
                  f"the attention figure now uses the reported model.")
            # Prune the non-selected candidates: ~16MB each, and leaving them
            # invites a later reader to load one by name.
            for _f in os.listdir(config.OUTPUT_DIR):
                if (_f.startswith(f"model_ptac_{dataset_name}__")
                        and not _f.startswith(os.path.basename(_sel_stem))
                        and not _f.startswith(
                            f"model_ptac_{dataset_name}__REPORTED")):
                    try:
                        os.remove(os.path.join(config.OUTPUT_DIR, _f))
                    except OSError:
                        pass
        else:
            print(f"    [A5] WARNING: no per-arm checkpoint for the reported "
                  f"arm '{ptac_headline_name}'; the asset loader will read "
                  f"whichever PTAC arm wrote last. Treat any attention figure "
                  f"from this run as unattributed.")
            _register_release_failure(
                config, 'MISSING_REPORTED_CHECKPOINT',
                f"No per-arm checkpoint for '{ptac_headline_name}' on "
                f"'{dataset_name}'.")
    except Exception as _pe:
        print(f"    [A5] checkpoint promotion failed "
              f"({type(_pe).__name__}: {_pe}).")
        _register_release_failure(
            config, 'CHECKPOINT_PROMOTION_FAILED',
            f"{dataset_name}: {type(_pe).__name__}: {_pe}")

    # PATCH-A1: publish the realised drift-bank layout per arm, so the parity
    # claim is auditable from a file rather than from reading the class
    # hierarchy. It comes before the significance block because the PARITY
    # WARNING raised there is only interpretable next to it.
    try:
        _par = parity_report(config, dataset=dataset_name)
        if len(_par):
            _par.insert(0, 'dataset', dataset_name)
            _par.to_csv(os.path.join(config.OUTPUT_DIR,
                                     f'drift_bank_parity_{dataset_name}.csv'),
                        index=False)
    except Exception as _pe:
        print(f"    [A1] parity report failed ({type(_pe).__name__}: {_pe}).")

    _abstention = None
    try:
        if ptac_headline_name in results_df.index:
            _row = results_df.loc[ptac_headline_name]
            if isinstance(_row, pd.DataFrame):      # duplicate index guard
                _row = _row.iloc[0]
            _pt = {}
            for _v in target_vars:
                _c = f'{_v}_MaxAbsCorrection'
                # <var>_CorrectionInert is True only for channels the gate
                # turned ON whose correction the deadband then reduced to zero
                # on every test row; it is False both for a declined channel
                # and for one that actually moved. The decisive quantity is
                # therefore the applied magnitude, which is unambiguous.
                _pt[_v] = dict(
                    gated_on_but_inert=bool(_row.get(f'{_v}_CorrectionInert', False)),
                    max_abs_correction=(float(_row[_c])
                                        if _c in _row.index
                                        and pd.notna(_row[_c]) else np.nan))
            _abstention = dict(
                passthrough=bool(_row.get('Anchor_passthrough', False)),
                per_target=_pt,
                tol=float(_row.get('parity_tol', 1e-12) or 1e-12))
            _nz = [v for v, d in _pt.items()
                   if np.isfinite(d['max_abs_correction'])
                   and d['max_abs_correction'] > _abstention['tol']]
            print(f"    [A2] gate record for '{ptac_headline_name}': "
                  f"passthrough={_abstention['passthrough']}, "
                  f"{len(_nz)}/{len(target_vars)} channel(s) with a nonzero "
                  f"applied correction {_nz}")
        else:
            print(f"    [A2] '{ptac_headline_name}' absent from results_df; "
                  f"significance tests run WITHOUT a gate record, so abstained "
                  f"channels cannot be distinguished from corrected ones.")
    except Exception as _ae:
        print(f"    [A2] WARNING: could not build the gate record "
              f"({type(_ae).__name__}: {_ae}); abstention handling disabled "
              f"for this dataset.")
        _abstention = None
    try:
        # PATCH-D1: ptac_headline_name is the validation argmin resolved at the
        # end of the Stage-1 C sweep; it is the arm every headline table reports.
        dm_df, nested_df = significance_report(
            all_errors, target_vars, proposed='M2P-PTAC',
            internal_baseline='XGBoost Baseline', n_boot=config.N_BOOTSTRAP,
            selected_arm=ptac_headline_name, dataset_name=dataset_name,
            abstention=_abstention,
            # 'XGBoost Baseline' is the LEVEL-target model: not matched in
            # target mode, so no parity claim is made from this call.
            baseline_matched=False)
        if len(dm_df):
            dm_df.to_csv(os.path.join(config.OUTPUT_DIR,
                         f'significance_dm_{dataset_name}.csv'), index=False)
        if len(nested_df):
            nested_df['internal_baseline'] = 'XGBoost Baseline'
            nested_df['baseline_target_mode'] = 'level'
            nested_df.to_csv(os.path.join(config.OUTPUT_DIR,
                             f'significance_nested_{dataset_name}.csv'), index=False)

        # F8: ATTRIBUTION FIX. The nested bootstrap above uses the LEVEL-target
        # tree as its internal baseline, so a favourable verdict measures the
        # Delta-target reformulation AND the neural corrector jointly. The
        # corrector's own contribution is the comparison against the DIFFERENCED
        # anchor -- the model M2P actually wraps and corrects. Both are now
        # written; the differenced one is the attributable result and the file
        # carries the baseline identity so neither can be quoted as the other.
        # ------------------------------------------------------------ PATCH-A1
        # The attributable baseline is the FEATURE-MATCHED differenced anchor:
        # PTACExperiment fits its internal anchor on X_tab + drift bank, so
        # only an external anchor fitted on the same matrix isolates the
        # corrector. 'XGBoost (differenced target)' -- the r3 choice -- differs
        # from the internal anchor in BOTH the correction and the feature set,
        # which is what produced adverse verdicts on channels whose applied
        # correction was exactly zero. Prefer the matched arm; fall back to the
        # unmatched one only if it is missing, and label the file accordingly.
        _anchor_matched = CORRECTOR_ATTRIBUTION_ANCHOR
        if _anchor_matched in all_errors:
            _anchor_nm, _matched = _anchor_matched, True
        else:
            _anchor_nm, _matched = None, False
            _register_release_failure(
                config, 'MISSING_MATCHED_ATTRIBUTION_ANCHOR',
                f"'{_anchor_matched}' is absent for '{dataset_name}'; the "
                "neural corrector's attributable effect cannot be released.")
        if _anchor_nm in all_errors:
            _dm2, _nested2 = significance_report(
                all_errors, target_vars, proposed='M2P-PTAC',
                internal_baseline=_anchor_nm, n_boot=config.N_BOOTSTRAP,
                selected_arm=ptac_headline_name, dataset_name=dataset_name,
                abstention=_abstention,
                # Matched only when the feature-matched anchor was available;
                # the fallback arm lacks the drift bank, so a discrepancy there
                
                baseline_matched=bool(_matched))
            if len(_nested2):
                _nested2['internal_baseline'] = _anchor_nm
                _nested2['baseline_target_mode'] = 'delta'
                _nested2['baseline_feature_matched'] = bool(_matched)
                _nested2.to_csv(os.path.join(
                    config.OUTPUT_DIR,
                    f'significance_nested_vs_delta_anchor_{dataset_name}.csv'),
                    index=False)
                print("\n    [F8] NESTED TEST vs DIFFERENCED ANCHOR "
                      f"({_anchor_nm}) -- this is the corrector's attributable "
                      "effect; the 'XGBoost Baseline' version above also "
                      "contains the Delta-target reformulation.")
                _cols = [c for c in ('target', 'delta_mae', 'ci_lo', 'ci_hi',
                                     'frac_favouring_corrected',
                                     'max_abs_applied_correction',
                                     'applicable', 'verdict', 'parity_warning')
                         if c in _nested2.columns]
                print(_nested2[_cols].round(4).to_string(index=False))
        elif _anchor_nm is not None:
            print(f"    [F8] '{_anchor_nm}' absent from all_errors; the "
                  "corrector's attributable effect could NOT be computed on "
                  f"{dataset_name}. Do not quote the nested verdict as the "
                  "corrector's effect.")
    except Exception as e:
        print(f"    [sig] significance report failed: {e}")
        _register_release_failure(
            config, 'SIGNIFICANCE_REPORT_FAILED',
            f"{dataset_name}: {type(e).__name__}: {e}")

    # (b) R8 bound comparison: k-sigma rows (negative control) against
    #     conformal rows. The realised bind rate is the whole point.
    # PATCH-D2: ablation_bound_family_<dataset>.csv is manuscript-facing, so
    # INVALID rows are excluded here while remaining in the authoritative
    # metrics CSV with their diagnostic columns intact.
    bound_rows = drop_invalid_rows(
        results_df.loc[results_df.index.str.contains(
            'clip k=|unbounded|conformal a=', regex=True)],
        f'bound-family ablation ({dataset_name})',
        keep=(ptac_headline_name,))
    if len(bound_rows):
        cols = ([c for c in ['bound_family', 'conformal_alpha', 'clip_k',
                             'realised_bind_rate', 'clip_hit_rate', 'Macro_MAE',
                             'n_physical_violations'] if c in bound_rows.columns]
                + [c for c in bound_rows.columns if c.endswith('_ConfBound')]
                + [c for c in bound_rows.columns if c.endswith('_MAE')])
        bt = bound_rows[cols]
        bt.to_csv(os.path.join(config.OUTPUT_DIR,
                  f'ablation_bound_family_{dataset_name}.csv'))
        print("\n--- R8: BOUND FAMILY COMPARISON ---")
        print("(k-sigma rows are the negative control: Round 7 measured their "
              "bind rate at 0.000 on every target of every testbed.)")
        print(bt.to_string())

        # ------------------------------------------------------------ PATCH-F14
        # ATTAINABILITY AUDIT FOR THE CONFORMAL ARMS.
        #
        # conformal_correction_bound() already refuses correctly per channel:
        # it leaves the bound at +inf when alpha is not attainable at the
        # calibration size (level_raw > 1 requires n >= ceil(1/alpha)-1) or when
        # n < min_n. What was missing is any AGGREGATION of those refusals, so
        # the bound-family table showed a fully unbounded arm as an ordinary row
        # with bind rate 0.0000 -- visually identical to a bound that was
        # calibrated and simply never engaged. Those are opposite findings: the
        # first is "we could not calibrate at this alpha", the second is "the
        # correction never got large enough to clip".
        #
        # On the last run every testbed had at least one unattainable alpha
        # (n=47/40/38 calibration points vs the 99 that alpha=0.01 needs), and
        # on challenged_89509 the calibration split fell to n=22, below min_n,
        # so EVERY conformal arm there is unbounded on every channel.
        #
        # This writes the per-arm attainability record and refuses to let an
        # uncalibrated row be read as a bound that never binds. Diagnostic only
        # -- no bound, alpha, calibration split or metric is changed.
        try:
            _cb_cols = [c for c in bound_rows.columns if c.endswith('_ConfBound')]
            if _cb_cols:
                _att = []
                for _nm in bound_rows.index:
                    if 'conformal a=' not in str(_nm):
                        continue
                    _nch = len(_cb_cols)
                    _unb = [c.replace('_ConfBound', '') for c in _cb_cols
                            if not np.isfinite(pd.to_numeric(
                                bound_rows.loc[_nm, c], errors='coerce'))]
                    _alpha = pd.to_numeric(
                        bound_rows.loc[_nm].get('conformal_alpha'),
                        errors='coerce')
                    _need = (int(np.ceil(1.0 / _alpha)) - 1
                             if np.isfinite(_alpha) and _alpha > 0 else np.nan)
                    _att.append(dict(
                        dataset=dataset_name, model_name=_nm, alpha=_alpha,
                        n_cal_required_for_alpha=_need,
                        n_channels=_nch, n_channels_unbounded=len(_unb),
                        channels_unbounded='; '.join(_unb),
                        fully_unbounded=bool(len(_unb) == _nch),
                        realised_bind_rate=pd.to_numeric(
                            bound_rows.loc[_nm].get('realised_bind_rate'),
                            errors='coerce'),
                        interpretation=(
                            'UNCALIBRATED at this alpha -- bind rate 0 is NOT '
                            'evidence about the corrector' if len(_unb) == _nch
                            else 'partially uncalibrated -- per-channel bounds '
                                 'differ in status' if _unb
                            else 'calibrated on every channel')))
                if _att:
                    _A = pd.DataFrame(_att)
                    _A.to_csv(os.path.join(
                        config.OUTPUT_DIR,
                        f'conformal_attainability_{dataset_name}.csv'),
                        index=False)
                    print("\n    [F14] CONFORMAL ATTAINABILITY "
                          f"({dataset_name}):")
                    print(_A[['model_name', 'alpha',
                              'n_cal_required_for_alpha',
                              'n_channels_unbounded', 'n_channels',
                              'realised_bind_rate']].to_string(index=False))
                    _dead = _A[_A.fully_unbounded]
                    if len(_dead):
                        print(f"    [F14] {len(_dead)} of {len(_A)} conformal "
                              "arm(s) are UNBOUNDED ON EVERY CHANNEL. Their "
                              "bind rate of 0.0000 records a failure to "
                              "calibrate, not a bound that never engaged. Do "
                              "NOT present these rows as evidence for or "
                              "against a bounded-correction claim, and do not "
                              "read a bind-rate-vs-alpha trend through them:")
                        for _, _r in _dead.iterrows():
                            print(f"        {_r.model_name}: alpha="
                                  f"{_r.alpha} needs n >= "
                                  f"{_r.n_cal_required_for_alpha} calibration "
                                  "points, or n < min_n on this testbed")
                    if bool(_A.fully_unbounded.all()):
                        print("    [F14] EVERY conformal arm on "
                              f"'{dataset_name}' is uncalibrated. This testbed "
                              "supports NO conformal bound claim at any alpha.")
        except Exception as _fe:
            print(f"    [F14] attainability audit failed: {_fe}")

    # (c) C-T8: bootstrap CIs on the MAE cost of each bound level, so the
    #     ablation reports uncertainty rather than a point difference that may
    #     be smaller than seed noise.
    try:
        boot_rows = []
        for mname in bound_rows.index:
            if mname not in all_errors:
                continue
            for v in target_vars:
                if v not in all_errors[mname]:
                    continue
                e = np.abs(np.asarray(all_errors[mname][v], dtype=float))
                e = e[np.isfinite(e)]
                if len(e) < 10:
                    continue
                rng = np.random.default_rng(0)
                bs = rng.integers(0, len(e), size=(config.N_BOOTSTRAP, len(e)))
                means = e[bs].mean(axis=1)
                lo, hi = np.percentile(means, [2.5, 97.5])
                boot_rows.append(dict(model=mname, target=v, mae=float(e.mean()),
                                      ci_lo=float(lo), ci_hi=float(hi),
                                      ci_width=float(hi - lo), n=len(e)))
        if boot_rows:
            pd.DataFrame(boot_rows).to_csv(os.path.join(
                config.OUTPUT_DIR, f'clip_k_bootstrap_{dataset_name}.csv'), index=False)
            print(f"    [C-T8] wrote {len(boot_rows)} bootstrap CI rows.")
    except Exception as e:
        print(f"    [C-T8] bootstrap failed: {e}")

    # (d) C-T3: physical-violation counts per model. A prediction outside the
    #     physically possible range is a deployment hazard independent of MAE,
    #     and it is the evidence an inference-time guard is warranted.
    viol_cols = [c for c in results_df.columns if c.endswith('_PhysViol')]
    if 'n_physical_violations' in results_df.columns or viol_cols:
        vt = results_df[[c for c in ['n_physical_violations'] + viol_cols
                         if c in results_df.columns]]
        vt.to_csv(os.path.join(config.OUTPUT_DIR,
                  f'physical_violations_{dataset_name}.csv'))
        tot = pd.to_numeric(results_df.get('n_physical_violations'),
                            errors='coerce').fillna(0)
        if tot.sum() > 0:
            print("\n--- C-T3: PHYSICALLY IMPOSSIBLE PREDICTIONS ---")
            print(tot[tot > 0].to_string())
        else:
            print("\n[C-T3] No physically impossible predictions from any model. "
                  "The safety guard is not load-bearing on these testbeds -- "
                  "report that rather than implying it prevents failures.")

    # (e) C-T2: correction reliability diagnostics, built from the headline
    #     model's own recorded corrections.
    try:
        # PATCH-D1: track WHICH arm supplied the correction array, so panel (i)
        # can pair those corrections with that same arm's error series instead
        # of with the first-swept arm's.
        _corr, _corr_arm = None, None
        for _e in ablation_exps:
            if getattr(_e, 'last_corrections', None) is not None and \
                    'conformal' in getattr(_e, 'model_name', ''):
                _corr = _e.last_corrections
                _corr_arm = getattr(_e, 'model_name', None)
                break
        if _corr is None:
            for _e in ablation_exps:
                if getattr(_e, 'last_corrections', None) is not None:
                    _corr = _e.last_corrections
                    _corr_arm = getattr(_e, 'model_name', None)
                    break
        correction_reliability_diagnostics(all_errors, results_df, target_vars,
                                           dataset_name, config, corrections=_corr,
                                           selected_arm=_corr_arm)
    except Exception as e:
        print(f"    [C-T2] reliability diagnostics failed: {e}")

    # (f2) C1: DEPLOYMENT COST. Runs before the seed sweep so a sweep failure
    #      cannot cost us the cost table.
    if getattr(config, 'RUN_DEPLOYMENT_PROFILE', False):
        try:
            profile_deployment_cost(
                [e for e in (ablation_exps + external_exps)
                 if getattr(e, '_last_keras_model', None) is not None],
                config, dataset_name)
        except Exception as e:
            print(f"    [C1] deployment profile failed: {e}")

    # (g) C-T10: MULTI-SEED STABILITY. This is the task that decides whether any
    #     ordering above is a measurement or a coin flip. aggregate_over_seeds()
    
    #     number in that run was a single seed, so the 0.09-0.64 Macro-MAE
    #     spread among M2P-PTAC's own variants could not be separated from the
    #     margin against the best comparator. Re-run only the selected-C model
    
    #     grid times 5 seeds does not fit the cluster budget, and the dispersion
    #     of the headline pair is what the claim actually rests on.
    try:
        seeds = list(getattr(config, 'SEEDS', [42]))
        if len(seeds) > 1:
            print(f"\n--- [C-T10] MULTI-SEED STABILITY over seeds {seeds} ---")
            
            _macro = next((c for c in ('Primary_Macro_MAE',
                                       'Macro_MAE_obs_ex_degen',
                                       'Macro_MAE_obs',
                                       'Macro_MAE_ex_degen', 'Macro_MAE')
                           if c in results_df.columns), 'Macro_MAE')
            _ext = [m for m in results_df.index
                    if not str(m).startswith(('M2P-', 'Ablation:'))]
            best_ext = (results_df.loc[_ext, _macro].idxmin() if _ext else None)
            # single comparator's sd was a plumbing artefact AND that several
            # OTHER comparators beat the proposed model, so dispersion is needed
            # for all of them before any ordering can be stated.
            _n_cmp = int(getattr(config, 'SEED_COMPARATORS_N', 1))
            _cmp_names = (results_df.loc[_ext, _macro].nsmallest(_n_cmp).index.tolist()
                          if _ext else [])
            # F7: the comparator set was chosen purely by Macro_MAE rank, so the
            # differenced-target anchor was included only when it happened to
            # rank in the top SEED_COMPARATORS_N. It is the reference the paper's
            # headline delta is measured against (crediting the level model to
            # the corrector conflates the Delta-target reformulation with the
            # neural layer), so its dispersion must be available on EVERY
            # testbed, not incidentally. Force it in, without growing the sweep:
            # it displaces the weakest auto-selected comparator.
            # PATCH-A1: force in the FEATURE-MATCHED anchor -- it is now the
            # reference the attribution test uses, so it is the one whose
            # cross-seed dispersion the headline CI needs. Both anchors are
            # requested (the pair is the feature-effect ablation), and the trim
            # that makes room only ever discards AUTO-SELECTED names, never a
            # forced one -- trimming the tail blindly would have dropped the
            # anchor appended on the previous iteration.
            _forced = [_a for _a in ('XGBoost (differenced target + drift bank)',
                                     'XGBoost (differenced target)')
                       if _ext and _a in results_df.index]
            if _forced:
                _auto = [c for c in _cmp_names if c not in _forced]
                _room = max(0, max(1, _n_cmp) - len(_forced))
                _cmp_names = _forced + _auto[:_room]
                print(f"    [F7] forced {_forced} into the seed sweep "
                      f"(headline-delta reference and its feature-effect "
                      f"partner); comparator set is now {_cmp_names}.")
            print(f"    Repeating '{ptac_headline_name}' and {len(_cmp_names)} "
                  f"comparator(s) {_cmp_names} across {len(seeds)} seeds.")
            per_seed = []
            for s in seeds:
                set_all_seeds(s)
                rows_s = []
                _pt = PTACExperiment(ptac_headline_name, config,
                                     base_lambda=global_optimal_c,
                                     conformal_alpha=config.DEFAULT_CONFORMAL_ALPHA,
                                     obs_mask=obs_mask, fault_mask=fault_mask)
                _cmps = [_mk_seed_comparator(_nm, config, obs_mask, fault_mask, s)
                         for _nm in _cmp_names]
                for _e in [_pt] + _cmps:
                    if _e is None:
                        continue
                    try:
                        r_s, _t_s, _e_s = _e.run(df.copy(), target_vars)
                        r_s['model_name'] = getattr(_e, 'model_name', str(_e))
                        r_s['seed'] = s
                        rows_s.append(pd.DataFrame(r_s, index=[0]))
                    except Exception as _ex:
                        print(f"    [C-T10] seed {s} / {getattr(_e,'model_name','?')} "
                              f"failed: {_ex}")
                if rows_s:
                    per_seed.append(pd.concat(rows_s, ignore_index=True))
            if per_seed:
                agg = aggregate_over_seeds(per_seed, id_col='model_name')
                agg.to_csv(os.path.join(config.OUTPUT_DIR,
                           f'seed_stability_{dataset_name}.csv'), index=False)
                _rep = [c for c in agg.columns if c.endswith('_report')] or \
                       [c for c in agg.columns if c.endswith('_mean')]
                print(agg[['model_name', 'n_seeds'] + _rep].to_string(index=False))
                # The decisive comparison: is the gap larger than the noise?
                _mc = f'{_macro}_mean'
                _sc = f'{_macro}_sd'
                if _mc in agg.columns and len(agg) >= 2:
                    _a = agg.set_index('model_name')
                    if ptac_headline_name in _a.index and best_ext in _a.index:
                        _gap = _a.loc[best_ext, _mc] - _a.loc[ptac_headline_name, _mc]
                        _noise = float(np.nanmax([_a.loc[ptac_headline_name, _sc],
                                                  _a.loc[best_ext, _sc]]))
                        print(f"\n    [C-T10] {_macro}: gap to best comparator "
                              f"= {_gap:+.4f}; largest seed sd = {_noise:.4f}.")
                        if not np.isfinite(_gap) or not np.isfinite(_noise):
                            print("    [C-T10] Cannot compare: non-finite gap or sd.")
                        elif _noise == 0.0:
                            
                            # result. SeasonalNaive/Theta/ETS are deterministic by
                            # construction, so 0 is correct for them. For anything
                            # with a Keras or tree RNG it means the reseed did not
                            # reach the model and the sweep measured one draw three
                            # times -- do NOT report that as stability.
                            print("    [C-T10] Seed sd is EXACTLY 0 for both models. "
                                  "If either is a neural or tree model this means "
                                  "the reseed never reached it -- the sweep "
                                  "re-measured one draw and carries no dispersion "
                                  "information. Only deterministic baselines "
                                  "(SeasonalNaive, Theta, ETS) may legitimately "
                                  "report 0. Verify before quoting.")
                        elif abs(_gap) < _noise:
                            print("    [C-T10] VERDICT: the gap is SMALLER than "
                                  "run-to-run noise. No ordering between the "
                                  "proposed model and this comparator may be "
                                  "claimed on this testbed; report mean +/- sd "
                                  "and say the two are indistinguishable.")
                        else:
                            print("    [C-T10] VERDICT: the gap exceeds seed noise "
                                  f"({abs(_gap)/max(_noise,1e-12):.1f}x sd). The "
                                  "ordering survives repetition; still report "
                                  "mean +/- sd, never the single best run.")
        else:
            print(f"\n[C-T10] SEEDS={seeds}: single-seed run. Every number in this "
                  "report is one draw and carries no dispersion estimate -- "
                  "set SEEDS to >=3 before quoting any ordering in the "
                  "manuscript.")
    except Exception as e:
        print(f"    [C-T10] multi-seed stability failed: {e}")

    # (f) C-T1: re-evaluate on contiguous fully-observed windows only. Tests the
    #     'sparse-window overfitting' hypothesis for the public dataset instead
    #     of assuming it.
    if obs_mask is not None:
        try:
            keep = contiguous_observed_windows(obs_mask, target_vars,
                                               config.CONTIGUOUS_MIN_LEN)
            print(f"\n--- [C-T1] CONTIGUOUS FULLY-OBSERVED WINDOWS "
                  f"(min length {config.CONTIGUOUS_MIN_LEN}) ---")
            # The mask spans train+val+test, but only the test tail is scored.
            # Reporting coverage over the whole series describes a set that was
            # never restricted: on challenged_90234 the series-level figure was
            # 73.6% while every scored point was in fact inside a window, so the
            # 'restricted' MAE came out bit-identical to the all-points MAE and
            # looked like a bug. Report coverage over the EVALUATION WINDOW.
            n_eval = max((len(np.asarray(e, dtype=float))
                          for errs in all_errors.values() for e in errs.values()),
                         default=0)
            if n_eval and len(keep) >= n_eval:
                keep_eval = keep.iloc[-n_eval:]
            else:
                keep_eval = keep
                if n_eval:
                    print(f"    [C-T1] WARNING: observation mask ({len(keep)} rows) is "
                          f"shorter than the evaluation window ({n_eval}); cannot "
                          f"align. Skipping -- an unaligned restriction would "
                          f"silently score the wrong points.")
                    keep_eval = None
            n_keep = int(keep_eval.sum()) if keep_eval is not None else 0
            print(f"    Evaluation window: {n_keep} of {len(keep_eval)} scored "
                  f"timestamps ({100 * n_keep / max(len(keep_eval), 1):.1f}%) lie "
                  f"in a fully-observed window "
                  f"[series-wide: {int(keep.sum())}/{len(keep)}].")
            if keep_eval is not None and n_keep == len(keep_eval):
                print("    [C-T1] Every scored point is already fully observed, so "
                      "the restricted MAE equals the all-points MAE by "
                      "construction. For this testbed the headline number owes "
                      "nothing to imputation.")
            if keep_eval is not None and n_keep >= 50:
                rows = []
                sub_full = keep_eval.values
                for mname, errs in all_errors.items():
                    rec = {'model_name': mname}
                    for v in target_vars:
                        if v not in errs:
                            continue
                        e = pd.Series(np.asarray(errs[v], dtype=float))
                        if len(e) == len(sub_full):
                            sub = sub_full
                        elif len(sub_full) > len(e):
                            sub = sub_full[-len(e):]
                        else:
                            continue
                        rec[f'{v}_MAE_contig'] = float(np.nanmean(np.abs(e[sub])))
                    rows.append(rec)
                ct = pd.DataFrame(rows).set_index('model_name')
                ct['Macro_MAE_contig'] = ct.mean(axis=1, numeric_only=True)
                ct.to_csv(os.path.join(config.OUTPUT_DIR,
                          f'contiguous_window_{dataset_name}.csv'))
                print("    [C-T1] Macro-MAE restricted to fully-observed "
                      "contiguous windows (compare against the all-points "
                      "Macro_MAE; a large gap means the headline number is "
                      "partly a statement about imputation):")
                print(ct[['Macro_MAE_contig']].sort_values('Macro_MAE_contig').to_string())
            elif keep_eval is not None:
                print("    [C-T1] Too few contiguous points to re-evaluate. This is "
                      "itself the finding for this dataset: there is no "
                      "densely-observed stretch to score on.")
        except Exception as e:
            print(f"    [C-T1] failed: {e}")

    # Runs before the final summary so the healthy-cell ranking is printed
    # alongside the all-points one it is meant to check.
    try:
        stratify_all_models_by_fault(
            all_errors, fault_mask, target_vars, config, dataset_name,
            results_df=results_df, obs_mask=obs_mask)
    except Exception as e:
        print(f"    [C-T12] all-model stratification failed: {e}")

    # Gated on RUN_FAULT_WEIGHT_SWEEP because it refits PTAC once per weight.
    # Only runs where there is something to measure -- a testbed with no
    # faulted TEST points cannot show rescue or its absence, so the sweep is
    # skipped there rather than burning several fits to print NaN.
    if getattr(config, 'RUN_FAULT_WEIGHT_SWEEP', False) and fault_mask is not None:
        _has_fault_cols = [c for c in results_df.columns
                           if c.endswith('_MAE_fault')] if results_df is not None else []
        if _has_fault_cols:
            try:
                sweep_fault_train_weight(
                    df, target_vars, config, dataset_name,
                    obs_mask=obs_mask, fault_mask=fault_mask,
                    base_lambda=getattr(config, 'OPTIMAL_LAMBDA', None))
            except Exception as e:
                print(f"    [C-T15] fault-weight sweep failed: {e}")
        else:
            print(f"    [C-T15] '{dataset_name}' has no target with >=10 "
                  f"source-retained DQA-flagged TEST points; sweep skipped "
                  f"(no defensible fault-truth sample here).")

    print("\n" + "="*80 + f"\n--- {dataset_name.upper()} FINAL SUMMARY ---\n" + "="*80)
    # cross-protocol ordering as a model comparison.
    assert_single_protocol(results_df, context=f"{dataset_name} FINAL SUMMARY")
    if 'eval_protocol' in results_df.columns:
        print("\n[C-T11] evaluation protocol by model:")
        for p, grp in results_df.groupby(results_df['eval_protocol'].astype(str)):
            print(f"    {p}")
            print(f"        {len(grp)} models: {list(grp.index)[:6]}"
                  + (" ..." if len(grp) > 6 else ""))
    # Source-retained metrics are the primary release table. All-point metrics
    # are printed separately as a reconstruction-sensitivity analysis.
    with pd.option_context('display.max_columns', None, 'display.width', 250):
        _primary_cols = [c for c in results_df.columns
                         if (c.endswith('_MAE_obs')
                             or c in ('Macro_MAE_obs',
                                      'Macro_MAE_obs_ex_degen',
                                      'Primary_Macro_MAE',
                                      'Primary_MAE_scope'))]
        print("\n[PRIMARY] source-retained forecasting metrics:")
        print(results_df[_primary_cols])
        _all_cols = [c for c in results_df.columns
                     if c.endswith('_MAE') and not c.endswith('_MAE_obs')]
        _all_cols += [c for c in ('Macro_MAE', 'Macro_MAE_ex_degen')
                      if c in results_df.columns]
        print("\n[SENSITIVITY] all-point metrics (include reconstructed truth):")
        print(results_df[list(dict.fromkeys(_all_cols))])

    # Sec 2.1 -- per-target attribution: the primary result table.
    headline = next((m for m in results_df.index
                     if m.startswith(f"M2P-PTAC (C={global_optimal_c}")), None)
    if headline is None:
        headline = next((m for m in results_df.index if 'M2P-PTAC' in m), None)
    if headline:
        per_target_attribution(
            results_df, target_vars, config, dataset_name, headline,
            baseline_name=CORRECTOR_ATTRIBUTION_ANCHOR,
            degenerate=degenerate)

    clip_rows = results_df.loc[results_df.index.str.contains('clip k=|unbounded', regex=True)]
    if len(clip_rows):
        _clip_primary = [c for c in clip_rows.columns
                         if c.endswith('_MAE_obs')]
        if not _clip_primary:
            _clip_primary = [c for c in clip_rows.columns
                             if c.endswith('_MAE')]
        cols = (_clip_primary
                + [c for c in clip_rows.columns if c.endswith('_ClipHit')]
                + [c for c in ['Primary_Macro_MAE', 'Macro_MAE',
                               'clip_hit_rate'] if c in clip_rows.columns])
        clip_tbl = clip_rows[cols].apply(pd.to_numeric, errors='coerce')
        clip_tbl.to_csv(os.path.join(config.OUTPUT_DIR, f'ablation_clip_k_{dataset_name}.csv'))

    # validation-side statistic, the decision, and the realised test outcome, so
    # a reader can check the rule rather than take it on trust.
    try:
        _grows = []
        for _m in results_df.index:
            for _v in target_vars:
                _g = results_df.loc[_m].get(f'{_v}_Gate', np.nan)
                if pd.isna(_g):
                    continue
                _grows.append(dict(
                    model_name=_m, target=_v, gate=_g,
                    threshold=results_df.loc[_m].get('gate_threshold', np.nan),
                    applied=results_df.loc[_m].get(f'{_v}_GateApplied', np.nan),
                    test_MAE_obs=results_df.loc[_m].get(
                        f'{_v}_MAE_obs', np.nan),
                    test_MAE_all=results_df.loc[_m].get(
                        f'{_v}_MAE', np.nan),
                    test_ParityViol=results_df.loc[_m].get(f'{_v}_ParityViol', np.nan)))
        if _grows:
            pd.DataFrame(_grows).to_csv(os.path.join(
                config.OUTPUT_DIR, f'gate_decisions_{dataset_name}.csv'), index=False)
            print(f"    [R9-A] wrote gate_decisions_{dataset_name}.csv")
    except Exception as e:
        print(f"    [R9-A] gate table failed: {e}")
        print("\n" + "="*78)
        print(f"[R1] HARD PARITY BOUND ABLATION -- {dataset_name}")
        print("     MAE cost of enforcing delta in [-k*sigma, +k*sigma], and how")
        print("     often the bound actually binds.")
        print("="*78)
        print(clip_tbl.round(4).to_string())

    obs_cols = [c for c in results_df.columns if c.endswith('_MAE_obs')]
    if obs_cols:
        pairs = []
        for c in obs_cols:
            v = c[:-len('_MAE_obs')]
            if f'{v}_MAE' in results_df.columns:
                pairs += [f'{v}_MAE', c, f'{v}_N_obs', f'{v}_N_total']
        pairs = [c for c in pairs if c in results_df.columns]
        obs_tbl = results_df[pairs].apply(pd.to_numeric, errors='coerce')
        obs_tbl.to_csv(os.path.join(config.OUTPUT_DIR, f'imputation_decomposition_{dataset_name}.csv'))
        print("\n" + "="*78)
        print(f"[R3] IMPUTATION DECOMPOSITION -- {dataset_name}")
        print("     '_MAE_obs' is the primary source-retained metric; '_MAE' is the")
        print("     all-point sensitivity including reconstructed targets. A gain")
        print("     present only in '_MAE' is an interpolation artifact.")
        print("="*78)
        print(obs_tbl.round(4).to_string())
    elif config.REPORT_OBSERVED_ONLY:
        print(f"\n[R3] No observation mask for '{dataset_name}'. Observed-only "
              f"metrics were NOT computed -- re-run data_quality_assessment.py "
              f"to emit interp_mask_*.csv, then re-run this benchmark.")

    # ======================================================================
    # NATURAL DEGRADATION STRATIFICATION
    #
    # The paper's claim is that the corrector rescues DEGRADED sensors. Every
    
    # the cleaner had removed the natural degradation before any model saw it.
    # With fault-preserving cleaning, DQA signatures remain available. The
    # defensible comparison is error on source-retained points carrying a
    # stuck/frozen, drift, or excursion signature versus source-retained healthy
    # points from the same sensor, window, and model.
    #
    
    # most falsifiable. If MAE_fault does not improve over the baseline, the
    # rescue claim is not supported and the paper should say so.
    # ======================================================================
    fault_cols = [c for c in results_df.columns if c.endswith('_MAE_fault')]
    if fault_cols:
        rows = []
        for c in fault_cols:
            v = c[:-len('_MAE_fault')]
            for mdl in results_df.index:
                mf = pd.to_numeric(results_df.loc[mdl, c], errors='coerce')
                mh = pd.to_numeric(results_df.loc[mdl, f'{v}_MAE_healthy'],
                                   errors='coerce') if f'{v}_MAE_healthy' in results_df.columns else np.nan
                nf = pd.to_numeric(results_df.loc[mdl, f'{v}_N_fault'],
                                   errors='coerce') if f'{v}_N_fault' in results_df.columns else np.nan
                nf_dqa = pd.to_numeric(
                    results_df.loc[mdl, f'{v}_N_fault_dqa'], errors='coerce') \
                    if f'{v}_N_fault_dqa' in results_df.columns else np.nan
                nf_rec = pd.to_numeric(
                    results_df.loc[mdl, f'{v}_N_fault_reconstructed'],
                    errors='coerce') \
                    if f'{v}_N_fault_reconstructed' in results_df.columns else np.nan
                rows.append(dict(model=mdl, target=v, MAE_fault=mf,
                                 MAE_healthy=mh, N_fault=nf,
                                 N_fault_dqa=nf_dqa,
                                 N_fault_reconstructed=nf_rec,
                                 fault_penalty=(mf - mh) if pd.notna(mf) and pd.notna(mh) else np.nan))
        ftbl = pd.DataFrame(rows)
        ftbl.to_csv(os.path.join(config.OUTPUT_DIR,
                                 f'fault_stratified_{dataset_name}.csv'), index=False)
        print("\n" + "="*78)
        print(f"NATURAL DEGRADATION STRATIFICATION -- {dataset_name}")
        print("     MAE on source-retained DQA-flagged readings vs source-retained")
        print("     healthy readings; reconstructed fault cells are counts only.")
        print("     'fault_penalty' = MAE_fault - MAE_healthy; lower is a model")
        print("     that holds up when the sensor misbehaves.")
        print("="*78)
        print(ftbl.round(4).to_string(index=False))

        # ------------------------------------------------------------ R16-K
        # ATTRIBUTE THE RESCUE, DO NOT JUST DECLARE IT.
        #
        # This block used to compare M2P-PTAC against 'XGBoost Baseline' only --
        # the LEVEL-target tree -- and print a single percentage. On the r16
        # detection run that produced "[RESCUE] dissolved oxygen: 1.474 ->
        # 0.405 (+72.6%)", which reads as the neural corrector rescuing a
        # degraded sensor. It is not. The differenced-target XGBoost scores
        # 0.405 on the same faulted points: bit-identical to the proposal,
        # because the gate declined and the correction was zero. The entire
        # "+72.6%" is the increment reformulation of the ANCHOR, and the
        # differenced-target LightGBM (0.370) beats the proposal outright.
        #
        # A rescue claim therefore has to be made against a same-target-mode
        # anchor, and the level-anchor gap has to be labelled as what it is --
        # the reformulation's contribution, which belongs to the base stage and
        # not to the corrector. Both numbers are printed, always, so the
        # decomposition cannot be dropped when the table is copied into a paper.
        _lvl = 'XGBoost Baseline'
        # PATCH-A1: the rescue decomposition needs the FEATURE-MATCHED
        # differenced anchor for the same reason the nested test does -- the
        # unmatched arm differs from what PTAC corrects in both the correction
        # and the drift bank, so a "RESCUE" against it is not the corrector's
        # contribution even though the line says so. An unmatched fallback
        # cannot identify the neural contribution, so it is never substituted.
        _dif = CORRECTOR_ATTRIBUTION_ANCHOR
        if _dif not in results_df.index:
            _register_release_failure(
                config, 'MISSING_MATCHED_FAULT_ATTRIBUTION_ANCHOR',
                f"'{_dif}' is absent from the fault-attribution table for "
                f"'{dataset_name}'.")
        
        # faulted-point comparison the manuscript quotes, so it must describe
        # the selected arm and not the first-swept one.
        m2p = (ptac_headline_name
               if ptac_headline_name in results_df.index
               else next((m for m in results_df.index
                          if m.startswith('M2P-PTAC')), None))
        if m2p is not None and m2p != ptac_headline_name:
            print(f"    [fault] PATCH-D1: selected arm '{ptac_headline_name}' "
                  f"absent from results_df; using '{m2p}'.")
        if m2p is not None:
            _tm = results_df['target_mode'] if 'target_mode' in results_df.columns else None
            # Best same-mode competitor that is NOT the proposal or one of its
            # own arms: if something outside the M2P family wins on faulted
            # points, the claim is dead regardless of the anchor gap.
            _peers = [m for m in results_df.index
                      if not str(m).startswith(('M2P-', 'Ablation: M2P'))
                      and (_tm is None or str(_tm.get(m, '')) == 'delta')]
            for v in sorted({c[:-len('_MAE_fault')] for c in fault_cols}):
                _g = lambda m: (pd.to_numeric(results_df.loc[m, f'{v}_MAE_fault'],
                                              errors='coerce')
                                if m in results_df.index else np.nan)
                p, bl, bd = _g(m2p), _g(_lvl), _g(_dif)
                if pd.isna(p):
                    continue
                print(f"  --- {v} (on {int(pd.to_numeric(results_df.loc[m2p, f'{v}_N_fault'], errors='coerce') or 0)} faulted points) ---")
                if pd.notna(bd):
                    verdict = "RESCUE" if p < bd else "NO RESCUE"
                    print(f"      [{verdict}] vs SAME-TARGET-MODE anchor "
                          f"{_dif}: {bd:.4f} -> {p:.4f} "
                          f"({100*(bd-p)/bd:+.1f}%). THIS is the corrector's "
                          f"contribution.")
                    if abs(p - bd) <= 1e-12 * max(1.0, abs(bd)):
                        print(f"      The two are bit-identical: the corrector "
                              f"contributed NOTHING on this target's faulted "
                              f"points. Any rescue percentage quoted against the "
                              f"level anchor belongs to the increment "
                              f"reformulation of the base stage.")
                else:
                    print(f"      [UNDECIDABLE] '{_dif}' has no MAE_fault here, "
                          f"so the corrector's contribution cannot be separated "
                          f"from the reformulation's. Do not quote a rescue.")
                if pd.notna(bl):
                    print(f"      [context] vs LEVEL anchor {_lvl}: {bl:.4f} -> "
                          f"{p:.4f} ({100*(bl-p)/bl:+.1f}%). This gap is mostly "
                          f"the DELTA REFORMULATION, not the corrector -- it is "
                          f"not a neural-architecture result and must not be "
                          f"reported as one.")
                _bp = [(m, _g(m)) for m in _peers if pd.notna(_g(m))]
                if _bp:
                    _bm, _bv = min(_bp, key=lambda kv: kv[1])
                    if _bv < p:
                        print(f"      !! '{_bm}' is BETTER on these faulted "
                              f"points ({_bv:.4f} vs {p:.4f}). The rescue claim "
                              f"does not survive a same-target-mode competitor.")
                if pd.notna(bd) and p >= bd:
                    print(f"      The corrector does NOT improve on source-retained "
                          f"DQA-flagged readings for '{v}'. This is the paper's core "
                          f"claim; a macro-average gain elsewhere does not "
                          f"substitute for it.")
    elif config.REPORT_FAULT_STRATIFIED:
        # ---------------------------------------------------------- R16-I
        # Say WHICH of the two causes applies. The r16 message asserted "no
        
        # columns are also absent when a mask WAS supplied and simply carries
        # fewer than FAULT_METRIC_MIN_N faulted rows inside the evaluation
        # window -- a property of the chronological split, not of the cleaning.
        # Sending the reader to re-clean data that is already fault-preserving
        # wastes the diagnosis and hides the real constraint, which is that the
        # test window has to CONTAIN degradation for the rescue claim to be
        # measurable at all.
        _nf_cols = [c for c in results_df.columns if c.endswith('_N_fault')]
        _nf_max = 0
        if _nf_cols:
            _nf_max = int(pd.to_numeric(
                results_df[_nf_cols].stack(), errors='coerce').max(skipna=True) or 0)
        if fault_mask is None:
            print(f"\n[Fault/R16-I] No fault mask for '{dataset_name}'. "
                  f"Degraded-vs-healthy metrics were NOT computed. Re-run "
                  f"data_quality_assessment.py with fault_handling='preserve' "
                  f"so natural degradation survives cleaning.")
        else:
            _tot = int(fault_mask.fillna(False).values.sum())
            print(f"\n[Fault/R16-I] A fault mask WAS supplied for "
                  f"'{dataset_name}' ({_tot} flagged readings in the full "
                  f"series), but the evaluation window contains at most "
                  f"{_nf_max} source-retained flagged reading(s) per target -- "
                  f"below the "
                  f"{int(getattr(config, 'FAULT_METRIC_MIN_N', getattr(Config, 'FAULT_METRIC_MIN_N', 10)))}-row floor "
                  f"for a per-target MAE. Degraded-vs-healthy metrics were NOT "
                  f"computed. This is the chronological split, NOT the cleaning: "
                  f"do not re-run the cleaner, and do not report a rescue claim "
                  f"for this testbed. Either the split must place a degradation "
                  f"episode inside the test window, or the claim must be made on "
                  f"a station whose degradation occurs late in the record.")

    generate_plots(results_df, timings_df, dataset_name, config,
                   target_vars=target_vars)
    generate_sensitivity_plot(results_df, dataset_name, config,
                              selected_arm=ptac_headline_name)
    # F5: this was gated on `"90234" in dataset_name`, so the robustness figure
    # was attempted for exactly ONE of four testbeds and the other three were
    # never even tried -- no skip message, no figure, nothing in the log to say
    # why. The function already refuses to draw from another testbed's arrays
    # and already reports its own reason for skipping (R16-G), so calling it
    # unconditionally is safe and makes the absence auditable.
    generate_paradox_proof_plot(config, dataset_name, global_optimal_c)

    # Return optimal_c so caller can use it without relying on a global
    return global_optimal_c


