def sweep_fault_train_weight(df, target_vars, config, dataset_name,
                             obs_mask=None, fault_mask=None,
                             base_lambda=None, weights=None):
    """Internal experiment utility."""
    if fault_mask is None:
        print("    [C-T15] no fault mask; weight sweep skipped.")
        return None
    ensure_cadence(df, config, dataset_name)      # R16-A

    weights = list(weights if weights is not None
                   else getattr(config, 'FAULT_WEIGHT_SWEEP', (1.0, 3.0, 5.0)))
    if base_lambda is None:
        base_lambda = getattr(config, 'OPTIMAL_LAMBDA', 0.001)

    print("\n" + "=" * 78)
    print(f"C-T15 FAULT-AWARE TRAINING SWEEP -- {dataset_name}")
    print("     weight=1.0 is the submitted model (fault labels unused in the")
    print("     objective). Later rows change ONLY the training weights.")
    print("=" * 78)

    rows = []
    for w in weights:
        cfg = copy.deepcopy(config)
        cfg.FAULT_TRAIN_WEIGHT = float(w)
        try:
            exp = PTACExperiment(f"M2P-PTAC (fw={w:g})", cfg,
                                 base_lambda=base_lambda,
                                 conformal_alpha=getattr(
                                     cfg, 'DEFAULT_CONFORMAL_ALPHA', None),
                                 obs_mask=obs_mask, fault_mask=fault_mask)
            res, _, _ = exp.run(df, target_vars)
        except Exception as exc:                      # noqa: BLE001
            print(f"    [C-T15] weight {w:g} failed: {type(exc).__name__}: {exc}")
            continue
        if res is None:
            continue
        for v in target_vars:
            mf = res.get(f'{v}_MAE_fault', np.nan)
            rows.append(dict(dataset=dataset_name, weight=float(w), target=v,
                             MAE_fault=mf,
                             MAE_healthy=res.get(f'{v}_MAE_healthy', np.nan),
                             MAE=res.get(f'{v}_MAE', np.nan),
                             N_fault=res.get(f'{v}_N_fault', np.nan),
                             fault_truth_unique=res.get(
                                 f'{v}_fault_truth_unique', np.nan),
                             fault_truth_degenerate=res.get(
                                 f'{v}_fault_truth_degenerate', np.nan)))

    if not rows:
        print("    [C-T15] sweep produced no rows.")
        return None

    swp = pd.DataFrame(rows)
    out = os.path.join(config.OUTPUT_DIR,
                       f'fault_weight_sweep_{dataset_name}.csv')
    swp.to_csv(out, index=False)
    print(swp.round(4).to_string(index=False))

    
    for v in sorted(swp['target'].unique()):
        sub = swp[swp['target'] == v].dropna(subset=['MAE_fault'])
        if sub.empty:
            continue
        base_row = sub[sub['weight'] == 1.0]
        if base_row.empty:
            continue
        b = float(base_row['MAE_fault'].iloc[0])
        best = sub.loc[sub['MAE_fault'].idxmin()]
        degen = bool(base_row['fault_truth_degenerate'].iloc[0]) \
            if pd.notna(base_row['fault_truth_degenerate'].iloc[0]) else False
        tag = ' [DEGENERATE TRUTH -- not interpretable]' if degen else ''
        if float(best['MAE_fault']) < b:
            print(f"  [C-T15] {v}: weight {best['weight']:g} improves "
                  f"MAE_fault {b:.4f} -> {float(best['MAE_fault']):.4f} "
                  f"({100 * (b - float(best['MAE_fault'])) / b:+.1f}%){tag}")
        else:
            print(f"  [C-T15] {v}: no weight beats the submitted model "
                  f"(best {float(best['MAE_fault']):.4f} vs {b:.4f}). "
                  f"Fault-aware training does not rescue this target.{tag}")
    print(f"  -> {os.path.basename(out)}")
    return swp


def stratify_all_models_by_fault(all_errors, fault_mask, target_vars, config,
                                 dataset_name, results_df=None, obs_mask=None):
    """Internal experiment utility."""
    if fault_mask is None:
        print("    [C-T12] no fault mask supplied; all-model stratification skipped.")
        return None
    if obs_mask is None and bool(getattr(config, 'REQUIRE_DQA_HANDOFF', True)):
        raise ValueError(
            "[C-T12] source-retention mask is required for fault metrics")

    rows = []
    for mname, errs in all_errors.items():
        for v in target_vars:
            if v not in errs or v not in fault_mask.columns:
                continue
            e = np.asarray(errs[v], dtype=float)
            fm_full = fault_mask[v].fillna(False).astype(bool).values
            om_full = (obs_mask[v].fillna(False).astype(bool).values
                       if obs_mask is not None and v in obs_mask.columns
                       else np.ones(len(fm_full), dtype=bool))
            if len(fm_full) >= len(e) and len(om_full) >= len(e):
                fm = fm_full[-len(e):]          # same tail rule as C-T1
                om = om_full[-len(e):]
            else:
                rows.append(dict(model=mname, target=v, MAE_fault=np.nan,
                                 MAE_healthy=np.nan, N_fault=np.nan,
                                 N_healthy=np.nan, fault_penalty=np.nan,
                                 n_scored=len(e),
                                 note='mask shorter than residual array; not aligned',
                                 N_fault_dqa=np.nan,
                                 N_fault_reconstructed=np.nan))
                continue
            ae = np.abs(e)
            fsel = fm & om
            hsel = (~fm) & om
            reconstructed = fm & ~om
            nf, nh = int(fsel.sum()), int(hsel.sum())
            mf = float(np.nanmean(ae[fsel])) if nf else np.nan
            mh = float(np.nanmean(ae[hsel])) if nh else np.nan
            rows.append(dict(model=mname, target=v, MAE_fault=mf, MAE_healthy=mh,
                             N_fault=nf, N_healthy=nh,
                             N_fault_dqa=int(fm.sum()),
                             N_fault_reconstructed=int(reconstructed.sum()),
                             fault_penalty=(mf - mh) if (nf and nh) else np.nan,
                             n_scored=len(e),
                             note='source-retained cells only'))

    tbl = pd.DataFrame(rows)
    if tbl.empty:
        print("    [C-T12] nothing to stratify.")
        return None

    out = os.path.join(config.OUTPUT_DIR,
                       f'fault_stratified_ALL_{dataset_name}.csv')
    tbl.to_csv(out, index=False)

    print("\n" + "=" * 78)
    print(f"C-T12 -- FAULT/HEALTHY STRATIFICATION, ALL MODELS -- {dataset_name}")
    print("     Both strata are restricted to source-retained values. DQA-")
    print("     flagged cells whose targets were reconstructed are counted but")
    print("     never scored against the interpolator.")
    print("=" * 78)
    print(f"    stratified {tbl.model.nunique()} models "
          f"({int(tbl.MAE_healthy.notna().sum())} model/target cells with a "
          f"healthy-cell MAE).")

    # The load-bearing output: does the all-points ranking survive on clean
    # cells? Reported per target, all models, best-first.
    for v in target_vars:
        s = tbl[(tbl.target == v) & tbl.MAE_healthy.notna()]
        if s.empty:
            continue
        nf = int(s.N_fault.max())
        if nf == 0:
            print(f"\n  [{v}] no faulted cells in the evaluation window -- "
                  f"healthy-cell MAE equals all-points MAE by construction.")
            continue
        s = s.sort_values('MAE_healthy')
        print(f"\n  [{v}] {nf} faulted / {int(s.N_healthy.max())} healthy cells "
              f"scored. Ranking on HEALTHY cells only:")
        for _, r in s.head(8).iterrows():
            print(f"        {r.model:46s} healthy {r.MAE_healthy:9.4f}   "
                  f"faulted {r.MAE_fault:9.4f}")

        if results_df is not None and f'{v}_MAE' in results_df.columns:
            allpts = pd.to_numeric(results_df[f'{v}_MAE'], errors='coerce')
            rank_all = list(allpts.sort_values().index)
            rank_hea = list(s.set_index('model').MAE_healthy.sort_values().index)
            common = [m for m in rank_all if m in rank_hea]
            if len(common) >= 3:
                a = [common.index(m) for m in common]
                b = [rank_hea.index(m) for m in common]
                tau_num = sum(np.sign(a[i] - a[j]) * np.sign(b[i] - b[j])
                              for i in range(len(a)) for j in range(i + 1, len(a)))
                tau = tau_num / (len(a) * (len(a) - 1) / 2)
                print(f"        rank correlation all-points vs healthy-only: "
                      f"tau={tau:+.3f}  "
                      f"(top model all-points '{rank_all[0]}' -> "
                      f"healthy-only '{rank_hea[0]}')")
                if rank_all[0] != rank_hea[0]:
                    print("        [C-T12] THE HEADLINE ORDERING CHANGES when the "
                          "corrupted cells are removed. The all-points table is "
                          "not a statement about forecasting skill.")

    # The two families do not score the same window: comparators score
    # len(df)-val_end points while the tabular path loses LONG_WINDOW_SIZE rows
    # to lag construction. On challenged_89509 that is 95 vs 84, and every one
    # of the 11 extra points is faulted -- so the comparators are scored on a
    # window carrying MORE corruption, not less. Ranking them against each
    # other on their own windows is therefore not a like-for-like comparison.
    # Emit the matched-window ranking as well: every model restricted to the
    # shortest common tail.
    lens = {len(np.asarray(e, dtype=float))
            for errs in all_errors.values() for e in errs.values()}
    if len(lens) > 1:
        n_common = min(lens)
        print(f"\n    [C-T12] WINDOW MISMATCH: models score "
              f"{sorted(lens)} points. Re-ranking all models on the common "
              f"tail of {n_common} points.")
        mrows = []
        for mname, errs in all_errors.items():
            for v in target_vars:
                if v not in errs or v not in fault_mask.columns:
                    continue
                e = np.asarray(errs[v], dtype=float)[-n_common:]
                fm = fault_mask[v].astype(bool).values[-n_common:]
                ae = np.abs(e)
                mrows.append(dict(model=mname, target=v,
                                  MAE_healthy_matched=float(np.nanmean(ae[~fm])) if (~fm).any() else np.nan,
                                  MAE_fault_matched=float(np.nanmean(ae[fm])) if fm.any() else np.nan,
                                  MAE_all_matched=float(np.nanmean(ae)),
                                  N_fault_matched=int(fm.sum()),
                                  N_healthy_matched=int((~fm).sum())))
        mt = pd.DataFrame(mrows)
        mt.to_csv(os.path.join(config.OUTPUT_DIR,
                  f'fault_stratified_MATCHED_{dataset_name}.csv'), index=False)
        for v in target_vars:
            s = mt[(mt.target == v) & mt.MAE_healthy_matched.notna()].sort_values('MAE_healthy_matched')
            if s.empty:
                continue
            print(f"\n    [{v}] matched window, HEALTHY cells only "
                  f"({int(s.N_healthy_matched.max())} cells):")
            for _, r in s.head(6).iterrows():
                print(f"        {r.model:46s} {r.MAE_healthy_matched:9.4f}")
    return tbl


def load_and_pivot_raw_data(file_path):
    try:
        df = pd.read_csv(file_path, comment='#')
        df = df[['_time', '_field', '_value']]
        df_pivot = df.pivot(index='_time', columns='_field', values='_value')
        df_pivot.index = pd.to_datetime(df_pivot.index, format='ISO8601')
        if 'disolved oxygen' in df_pivot.columns:
            df_pivot = df_pivot.rename(columns={'disolved oxygen': 'dissolved oxygen'})
        if df_pivot.index.year.max() > pd.Timestamp.now().year:
            df_pivot.index = df_pivot.index - pd.DateOffset(years=2)
        return df_pivot
    except FileNotFoundError:
        print(f"\nERROR: Could not find the RAW data file at {file_path}")
        return None


def generate_case_study_plot(config):
    """Plot the exact validation-selected stable predictions, without refitting."""
    print("\n" + "#" * 80
          + "\n### GENERATING CASE STUDY FROM REPORTED PREDICTION BUNDLE ###\n"
          + "#" * 80)
    bundle_path = os.path.join(
        config.OUTPUT_DIR, 'prediction_bundle_stable__REPORTED.npz')
    if not os.path.exists(bundle_path):
        raise FileNotFoundError(
            f"Missing {bundle_path}. The case-study figure is released only "
            "from the exact validation-selected benchmark predictions.")

    with np.load(bundle_path, allow_pickle=False) as z:
        required = {'timestamp_ns', 'target_names', 'y_true', 'anchor',
                    'correction', 'final', 'source_retained'}
        missing = required.difference(z.files)
        if missing:
            raise ValueError(f"Prediction bundle misses keys: {sorted(missing)}")
        times = pd.to_datetime(z['timestamp_ns'].astype('int64'))
        targets = [str(x) for x in z['target_names'].tolist()]
        y_true = np.asarray(z['y_true'], dtype=float)
        anchor = np.asarray(z['anchor'], dtype=float)
        correction = np.asarray(z['correction'], dtype=float)
        final = np.asarray(z['final'], dtype=float)
        retained = np.asarray(z['source_retained'], dtype=bool)

    if not (y_true.shape == anchor.shape == correction.shape == final.shape
            == retained.shape):
        raise ValueError(
            "Prediction bundle arrays have inconsistent shapes: "
            f"truth={y_true.shape}, anchor={anchor.shape}, "
            f"correction={correction.shape}, final={final.shape}, "
            f"retained={retained.shape}.")
    if y_true.ndim != 2 or y_true.shape[0] == 0 or len(times) != y_true.shape[0]:
        raise ValueError('Prediction bundle contains no plottable test rows.')
    if y_true.shape[1] != len(targets):
        raise ValueError('Target-name count does not match prediction width.')

    preferred = ('dissolved oxygen', 'electric conductivity', 'ph', 'temperature')
    target = next((v for v in preferred if v in targets), targets[0])
    j = targets.index(target)
    keep = (np.isfinite(y_true[:, j]) & np.isfinite(anchor[:, j])
            & np.isfinite(final[:, j]) & retained[:, j])
    if not keep.any():
        raise ValueError(f"No source-retained finite rows for case target '{target}'.")

    plt.style.use('seaborn-v0_8-whitegrid')
    fig, ax = plt.subplots(figsize=(15, 7))
    ax.plot(times[keep], y_true[keep, j], label='Source-retained truth',
            color='#1f77b4', linewidth=2.3, zorder=4)
    ax.plot(times[keep], anchor[keep, j],
            label='Matched differenced XGBoost anchor', color='#ff7f0e',
            linestyle='--', linewidth=1.9, zorder=3)
    ax.plot(times[keep], final[keep, j],
            label='Validation-selected M2P-PTAC', color='#2ca02c',
            linewidth=1.8, marker='o', markersize=2.5, alpha=0.85, zorder=5)
    ax.set_title(f"Reported stable-test forecast: {target.title()}",
                 fontsize=16, fontweight='bold')
    ax.set_xlabel('Timestamp')
    ax.set_ylabel(target.title())
    ax.legend(loc='best', frameon=True)
    ax.grid(True, linestyle='--', alpha=0.5)
    fig.autofmt_xdate()
    fig.tight_layout()
    plot_filename = os.path.join(config.OUTPUT_DIR,
                                 'case_study_plot_final.png')
    fig.savefig(plot_filename, dpi=200, bbox_inches='tight')
    plt.close(fig)
    print(f"Final case study plot saved from exact reported arrays: "
          f"{plot_filename}")
    return plot_filename


def _r22_select_controlled_stress_c(df_stable, target_vars, config, injector,
                                      obs_mask=None, fault_mask=None):
    """Select one C from disjoint controlled-T2 validation, never test rescue."""
    candidates = [float(x) for x in getattr(
        config, 'LAMBDA_ANALYSIS_VALUES', [getattr(config, 'OPTIMAL_LAMBDA', 0.001)])]
    tune_seeds = [int(x) for x in getattr(
        config, 'R22_STRESS_C_SELECTION_SEEDS', [101, 202, 303])]
    n_hist = int(getattr(config, 'R22_STRESS_HISTORY_EPISODES', 14))
    fixed_hist = dict(getattr(config, 'R18_FIXED_HISTORY_INTENSITY', {}) or {})
    drift_types = ('gradual_bias', 'sudden_shift')

    # Build each fixed history curriculum once. Test intensity is exactly zero;
    # only validation metrics are harvested below. The null-test rows are never
    # read by the selector and therefore cannot tune C.
    prepared = {}
    for dt in drift_types:
        h0 = float(fixed_hist.get(dt, 0.15 if dt == 'gradual_bias' else 2.0))
        d0, clean0 = injector.apply_drift(
            df_stable, dt, 0.0, target_vars,
            history_episodes=n_hist,
            history_seed=int(getattr(config, 'SEED', 42)) + 977,
            history_intensity=h0)
        syn = getattr(injector, 'last_drift_mask', None)
        if syn is None:
            syn = pd.DataFrame(False, index=d0.index, columns=target_vars)
        syn = syn.reindex(index=d0.index, columns=target_vars).fillna(False).astype(bool)
        auth = syn.copy()
        if fault_mask is not None:
            nat = (fault_mask.reindex(index=d0.index, columns=target_vars)
                   .fillna(False).astype(bool))
            auth = auth | nat
        prepared[dt] = (d0, clean0, syn, auth)

    rows = []
    print("\n[R22] CONTROLLED-T2 C SELECTION -- validation only; test rescue ignored")
    print(f"[R22] candidates={candidates}; tuning seeds={tune_seeds}; "
          f"drift families={list(drift_types)}")
    for cval in candidates:
        for dt in drift_types:
            d0, clean0, syn, auth = prepared[dt]
            for sd in tune_seeds:
                set_all_seeds(sd)
                exp = PTACExperiment(
                    f"R22-CSEL-{dt}-C{cval:g}-seed{sd}", config,
                    base_lambda=cval,
                    conformal_alpha=config.DEFAULT_CONFORMAL_ALPHA,
                    eval_truth_df=clean0, obs_mask=obs_mask,
                    fault_mask=auth, rescue_mask=syn, authorization_mask=syn,
                    train_truth_df=None, corrector_target_df=clean0,
                    seed=sd)
                res, _, _ = exp.run(d0.copy(), target_vars)
                score = float(res.get('_val_MAE_for_selection', np.nan))
                rows.append(dict(C=cval, drift_type=dt, tuning_seed=sd,
                                 val_equal_target_ratio=score,
                                 selection_scope=res.get('_val_selection_scope', ''),
                                 test_metrics_used=False))
                print(f"    [R22-CSEL] C={cval:g} {dt} seed={sd}: "
                      f"val ratio={score:.6f}")

    tab = pd.DataFrame(rows)
    path = os.path.join(config.OUTPUT_DIR, 'r22_stress_c_selection.csv')
    tab.to_csv(path, index=False)
    agg = (tab.groupby('C')['val_equal_target_ratio']
              .agg(['mean', 'std', 'count']).reset_index())
    if agg['mean'].notna().sum() == 0:
        raise RuntimeError("[R22] no finite controlled-validation C score.")

    finite = agg[np.isfinite(agg['mean'])].copy().sort_values(['mean', 'C'])
    tol = float(getattr(config, 'R22_STRESS_C_TIE_TOL', 1e-8))
    best_mean = float(finite['mean'].iloc[0])
    tied = finite[np.abs(finite['mean'] - best_mean) <= tol]
    if len(tied) > 1:
        default_c = float(getattr(config, 'OPTIMAL_LAMBDA', 0.001))
        vals = tied['C'].astype(float).values
        if np.any(np.isclose(vals, default_c, rtol=0.0, atol=tol)):
            chosen = default_c
            policy = 'exact validation tie -> prespecified OPTIMAL_LAMBDA'
        else:
            chosen = float(tied.iloc[len(tied)//2]['C'])
            policy = 'exact validation tie -> median tied candidate'
    else:
        chosen = float(finite['C'].iloc[0])
        policy = 'minimum mean controlled-validation ratio'

    agg['selected'] = np.isclose(agg['C'].astype(float), chosen, rtol=0.0, atol=tol)
    agg['selection_policy'] = policy
    agg.to_csv(os.path.join(config.OUTPUT_DIR,
                            'r22_stress_c_selection_summary.csv'), index=False)
    print(f"[R22] selected ONE stress-test C={chosen:g} by {policy}; "
          "the same C is frozen for both drift families, every intensity, and "
          f"all reported rescue seeds. Audit: {path}")
    return chosen


def run_drift_stress_test(df_stable, target_vars, config, optimal_c, obs_mask=None,
                          fault_mask=None):
    """Evaluate the pipeline under controlled sensor-degradation stress."""
    print("\n" + "#" * 80 + "\n### RUNNING SYNTHETIC DRIFT STRESS TEST (CORRECTED) ###\n" + "#" * 80)
    # frame, and Config's window/lag fields still carry the last testbed's
    # cadence. Reset them from this frame before fitting anything.
    ensure_cadence(df_stable, config, 'drift_stress_stable')

    # benchmarks keep their frozen 40/30/30 validation roles. The stress test
    # receives more independent controlled evidence without weakening any
    _r22_active = bool(getattr(config, 'R22_STRESS_PROTOCOL', False))
    _r22_old_cal = float(getattr(config, 'VALIDATION_CAL_FRACTION', 0.40))
    _r22_old_safe = float(getattr(config, 'VALIDATION_SAFETY_FRACTION', 0.30))
    _r22_old_flag = bool(getattr(config, '_r22_stress_active', False))
    if _r22_active:
        config._r22_stress_active = True
        config.VALIDATION_CAL_FRACTION = float(getattr(
            config, 'R22_STRESS_VALIDATION_CAL_FRACTION', 0.35))
        config.VALIDATION_SAFETY_FRACTION = float(getattr(
            config, 'R22_STRESS_VALIDATION_SAFETY_FRACTION', 0.35))
        print(f"[R22] controlled stress roles: calibration="
              f"{config.VALIDATION_CAL_FRACTION:.2f}, safety="
              f"{config.VALIDATION_SAFETY_FRACTION:.2f}, C-selection="
              f"{1.0-config.VALIDATION_CAL_FRACTION-config.VALIDATION_SAFETY_FRACTION:.2f}")

    injector = SyntheticDriftInjector(config)

    zero = [0.0] if config.DRIFT_INCLUDE_ZERO_CONTROL else []
    drift_scenarios = [
        # ROLLBACK REGRESSION: decisive grid only. The historical full curve
        # already exists; this run isolates whether the old mechanism survives
        # the repaired protocol without spending another 17-cell sweep.
        ('sudden_shift', zero + [1.0, 2.0, 4.0]),
    ]
    if bool(getattr(config, 'TOURNAMENT_ACTIVE', False)):
        drift_scenarios = [
            ('gradual_bias', list(getattr(config, 'TOURNAMENT_GRADUAL_LEVELS', (0.0, 0.10, 0.25)))),
            ('sudden_shift', list(getattr(config, 'TOURNAMENT_SUDDEN_LEVELS', (0.0, 2.0, 4.0)))),
        ]
        print('[TOURNAMENT] development stress grid: ' +
              '; '.join(f'{n}={lv}' for n, lv in drift_scenarios))

    if bool(getattr(config, 'R25_MECHANISM_DIAGNOSTIC', False)) and bool(
            getattr(config, 'R25_MECHANISM_QUICK', True)):
        drift_scenarios = [
            ('gradual_bias', list(getattr(config, 'R25_MECHANISM_GRADUAL_LEVELS',
                                           (0.0, 0.10, 0.20, 0.25)))),
            ('sudden_shift', list(getattr(config, 'R25_MECHANISM_SUDDEN_LEVELS',
                                          (0.0, 1.0, 2.0, 4.0)))),
        ]
        print('[R25-MECH] QUICK diagnostic stress grid enabled: ' +
              '; '.join(f'{n}={lv}' for n, lv in drift_scenarios))

    if bool(getattr(config, 'R27_COMPONENT_AUDIT', False)):
        drift_scenarios = [('gradual_bias', [0.0, 0.10])]
        print('[R27A] COMPONENT AUDIT ONLY: gradual_bias=[0.0, 0.10], seed=[42]. '
              'This run diagnoses validation-state mismatch magnitude; it is NOT a release curve.')

    stress_results = []
    # F9: independent seeds for the rescue sweep. The release configuration
    # uses five; smoke mode explicitly reduces this to one.
    _rescue_seeds = list(getattr(config, 'R17_RESCUE_SEEDS', None)
                         or [int(getattr(config, 'SEED', 42))])
    if bool(getattr(config, 'TOURNAMENT_ACTIVE', False)):
        _rescue_seeds = list(getattr(config, 'TOURNAMENT_SEEDS', (101, 202, 303)))
    if bool(getattr(config, 'R25_MECHANISM_DIAGNOSTIC', False)) and bool(
            getattr(config, 'R25_MECHANISM_QUICK', True)):
        _rescue_seeds = list(getattr(config, 'R25_MECHANISM_SEEDS', [42, 43, 44]))
    if bool(getattr(config, 'R27_COMPONENT_AUDIT', False)):
        _rescue_seeds = [42]
    print(f"[F9] rescue sweep seeds: {_rescue_seeds} "
          f"({len(_rescue_seeds)} draw(s) per drift/intensity cell)")
    # answer different questions -- MAE(I) asks whether injected degradation
    # degrades (a harness check), R(I) asks whether the corrector repairs it
    # (the scientific claim) -- and the second cannot be read off the first.
    rescue_rows = []
    replay_audit_rows = []
    mechanism_rows = []
    policy_rows = []
    # (drift family, seed), never by test intensity.  Validation fingerprints
    # make the fixed-pretest premise executable rather than assumed.
    if bool(getattr(config, 'R27_FIXED_MODEL_REPLAY', False)):
        config._r27_weight_cache = {}
        config._r27_validation_reference = {}
        config._r27_policy_reference = {}
        config._r27_audit_rows = []
        config._r27_component_reference = {}
        config._r27_component_rows = []
        print('[R27] FIXED-MODEL replay ENABLED: one neural fit per drift-family/seed; '
              'all test intensities reuse exact cached Keras weights.')
    _history_fingerprints = {}
    _fixed_history = dict(getattr(config, 'R18_FIXED_HISTORY_INTENSITY', {}) or {})

    _r25_fixed_c = str(getattr(config, 'R25_MECHANISM_FIXED_C', '') or '').strip()
    if bool(getattr(config, 'R25_MECHANISM_DIAGNOSTIC', False)) and _r25_fixed_c:
        try:
            optimal_c = float(_r25_fixed_c)
        except ValueError as _e:
            raise ValueError(f"PTAC_DIAG_C must be numeric, got {_r25_fixed_c!r}") from _e
        print(f"[R25-MECH] using externally frozen controlled-stress C={optimal_c:g}; "
              "NO C selection is performed in this diagnostic run.")
    elif (_r22_active and bool(getattr(config, 'R22_STRESS_SELECT_C', True))):
        _inherited_c = float(optimal_c)
        optimal_c = _r22_select_controlled_stress_c(
            df_stable, target_vars, config, injector,
            obs_mask=obs_mask, fault_mask=fault_mask)
        print(f"[R22] replaced inherited field/stable C={_inherited_c:g} with "
              f"controlled-validation C={optimal_c:g} for Stage 2.2 only.")

    for drift_name, levels in drift_scenarios:
        for level in levels:
            tag = "I=0 CONTROL" if level == 0 else f"Level {level}"
            print(f"--> Drift: {drift_name} @ {tag}")
            _hist = int(getattr(
                config, 'R22_STRESS_HISTORY_EPISODES',
                getattr(config, 'R18_HISTORY_EPISODES', 0)) if _r22_active
                else getattr(config, 'R18_HISTORY_EPISODES', 0) or 0)
            _hist_intensity = float(_fixed_history.get(
                drift_name, next((x for x in levels if x > 0), 0.0)))
            df_drifted, df_clean = injector.apply_drift(
                df_stable, drift_name, level, target_vars,
                history_episodes=_hist,
                history_seed=int(getattr(config, 'SEED', 42)) + 977,
                history_intensity=_hist_intensity)

            # The training/validation curriculum must be byte-identical across
            # intensity arms.  Previously it scaled with the TEST intensity and
            # I=0 had no historical faults, so the x-axis changed both training
            # data and test degradation at once.
            import hashlib as _hashlib
            _, _tv_end, _ = _raw_split_boundaries(config, len(df_drifted))
            _hv = pd.util.hash_pandas_object(
                df_drifted.loc[:, target_vars].iloc[:_tv_end],
                index=True).values.tobytes()
            _h = _hashlib.sha256(_hv).hexdigest()
            if drift_name in _history_fingerprints:
                if _history_fingerprints[drift_name] != _h:
                    raise RuntimeError(
                        f"[R18] training/validation history changed across "
                        f"'{drift_name}' intensity arms. The stress curve is "
                        "confounded and cannot be released.")
            else:
                _history_fingerprints[drift_name] = _h
                print(f"    [R18] fixed historical curriculum for {drift_name}: "
                      f"I_history={_hist_intensity:g}, sha256={_h[:12]}")

            truth = df_clean if config.DRIFT_EVAL_AGAINST_CLEAN_TRUTH else None

            # Keep two estimands separate. Natural DQA faults remain available
            # for training and fault-stratified metrics; controlled rescue is
            # evaluated only on rows injected by this arm.
            _synthetic_mask = getattr(injector, 'last_drift_mask', None)
            if _synthetic_mask is None:
                _synthetic_mask = pd.DataFrame(
                    False, index=df_drifted.index, columns=target_vars)
            _synthetic_mask = (_synthetic_mask.reindex(
                index=df_drifted.index, columns=target_vars)
                .fillna(False).astype(bool))
            _train_fault_mask = _synthetic_mask.copy()
            if (fault_mask is not None and not bool(getattr(
                    config, 'NATIVE_SYNTHETIC_LABELS_ONLY', False))):
                _natural = (fault_mask.reindex(index=df_drifted.index,
                                               columns=target_vars)
                            .fillna(False).astype(bool))
                _train_fault_mask = _train_fault_mask | _natural
            elif bool(getattr(config, 'NATIVE_SYNTHETIC_LABELS_ONLY', False)):
                print("    [NATIVE] controlled training labels = synthetic T2 "
                      "mask ONLY; natural DQA flags are not used as "
                      "counterfactual correction truth.")

            # ==================================================================
            # F9: MULTI-SEED DISPERSION ON THE RESCUE SWEEP.
            #
            
            # cell, so every headline rescue number -- including the +55.6% EC
            # figure and all three acceptance verdicts -- rested on a single
            # draw with no uncertainty attached. The two audited drift types are
            # injected deterministically (apply_drift uses no RNG for
            # gradual_bias/sudden_shift), so the injection is identical across
            # seeds and the only variance is model initialisation and the gate.
            # That is exactly the variance that matters: the gate has already
            # been observed to flip its decision across seeds on real data, so a
            # single-seed acceptance verdict is not reproducible evidence.
            #
            # Injection stays OUTSIDE this loop (it is seed-independent, and
            # re-running it would waste time and risk a different draw).
            # Cost: len(R17_RESCUE_SEEDS) x the previous sweep. At the measured
            
            # the full 5, to keep this addition tightly scoped.
            # ==================================================================
            for _seed in _rescue_seeds:
                if len(_rescue_seeds) > 1:
                    set_all_seeds(int(_seed))
                    print(f"    [F9] seed {_seed}")
                config._active_rescue_seed = int(_seed)
                # FINAL R19/T2 release path.  The forecasting anchor keeps
                # the observed/degraded target convention; clean truth is supplied
                # ONLY to the neural corrector target.  This removes the R18
                # anchor-absorption confound and makes B -> C attributable.
                _use_t2 = bool(getattr(config, 'R19_T2_DRIFT_RESCUE', True))
                if bool(getattr(config, 'R27_FIXED_MODEL_REPLAY', False)):
                    config._r27_replay_key = f'{drift_name}|seed={int(_seed)}'
                    config._r27_replay_level = float(level)
                exp_ptac = PTACExperiment(
                    f"M2P_{drift_name}_{level}", config,
                    base_lambda=optimal_c,
                    conformal_alpha=getattr(
                        config, 'STRESS_CONFORMAL_ALPHA',
                        config.DEFAULT_CONFORMAL_ALPHA),
                    eval_truth_df=truth, obs_mask=obs_mask,
                    fault_mask=_train_fault_mask,
                    rescue_mask=_synthetic_mask,
                    authorization_mask=_synthetic_mask,
                    train_truth_df=None,
                    corrector_target_df=(df_clean if _use_t2 else None))
                res_ptac, _, _ = exp_ptac.run(df_drifted, target_vars)
                if bool(getattr(config, 'R27_FIXED_MODEL_REPLAY', False)):
                    _cache27 = getattr(config, '_r27_weight_cache', {})
                    _key27 = getattr(config, '_r27_replay_key', None)
                    _weights27 = _cache27.get(_key27, []) if isinstance(_cache27, dict) else []
                    _sha27 = ''
                    if _weights27:
                        _hw27 = _hashlib.sha256()
                        for _w27 in _weights27:
                            _a27 = np.ascontiguousarray(np.asarray(_w27))
                            _hw27.update(str(_a27.shape).encode('ascii'))
                            _hw27.update(str(_a27.dtype).encode('ascii'))
                            _hw27.update(_a27.tobytes())
                        _sha27 = _hw27.hexdigest()
                    replay_audit_rows.append(dict(
                        drift_type=str(drift_name), intensity=float(level),
                        seed=int(_seed), replay_key=str(_key27),
                        weights_reused=bool(getattr(
                            exp_ptac, '_r27_weights_reused', False)),
                        weight_sha256=_sha27,
                        history_sha256=str(_history_fingerprints.get(
                            drift_name, ''))))

                # ------------------------------------------------------ R25
                # Mechanism decomposition on the SAME fitted model/test rows.
                # A = anchor only
                # B = anchor + bounded neural correction before p_fault
                # C = anchor + graph p_fault-gated correction before R20/R19/R21
                # D = full deployed correction after all policy gates
                if bool(getattr(config, 'R25_MECHANISM_DIAGNOSTIC', False)):
                    _arr25 = getattr(exp_ptac, '_r19_arrays', {}) or {}
                    _raw25 = getattr(exp_ptac, '_r25_test_corr_bounded', None)
                    _raw25s = getattr(exp_ptac, '_r25_test_corr_bounded_scaled', None)
                    _tau25 = getattr(exp_ptac, '_r25_tau_scaled', None)
                    if _arr25 and _raw25 is not None:
                        _idx25 = pd.DatetimeIndex(_arr25['test_index'])
                        _base25 = np.asarray(_arr25['test_base'], dtype=float)
                        _truth25 = np.asarray(_arr25['test_true'], dtype=float)
                        _gate25 = np.asarray(_arr25.get('test_corr_raw'), dtype=float)
                        _full25 = np.asarray(_arr25['test_corr'], dtype=float)
                        _prob25 = _arr25.get('test_prob')
                        _prob25 = (np.asarray(_prob25, dtype=float)
                                   if _prob25 is not None else None)
                        _dm25 = (_synthetic_mask.reindex(index=_idx25,
                                                         columns=target_vars)
                                 .fillna(False).values.astype(bool))
                        for _j25, _v25 in enumerate(target_vars):
                            _y25 = _truth25[:, _j25]
                            _b25 = _base25[:, _j25]
                            _d25 = _dm25[:, _j25]
                            _fin25 = np.isfinite(_y25) & np.isfinite(_b25)
                            _deg25 = _fin25 & _d25
                            _nom25 = _fin25 & ~_d25
                            _cstar25 = _y25 - _b25
                            _base_deg_mae25 = (float(np.mean(np.abs(_cstar25[_deg25])))
                                               if _deg25.any() else np.nan)
                            _base_nom_mae25 = (float(np.mean(np.abs(_cstar25[_nom25])))
                                               if _nom25.any() else np.nan)
                            _paths25 = {
                                'A_anchor': np.zeros(len(_b25), dtype=float),
                                'B_raw_bounded': np.asarray(_raw25[:, _j25], dtype=float),
                                'C_pfault_gated': np.asarray(_gate25[:, _j25], dtype=float),
                                'D_full_policy': np.asarray(_full25[:, _j25], dtype=float),
                            }
                            # detector telemetry once per path row for easy joins
                            _auc25 = np.nan
                            _pdeg25 = np.nan
                            _pnom25 = np.nan
                            if _prob25 is not None:
                                _pp25 = _prob25[:, _j25]
                                if _deg25.any():
                                    _pdeg25 = float(np.nanmean(_pp25[_deg25]))
                                if _nom25.any():
                                    _pnom25 = float(np.nanmean(_pp25[_nom25]))
                                if float(level) > 0 and _deg25.any() and _nom25.any():
                                    try:
                                        from sklearn.metrics import roc_auc_score as _auc_fn25
                                        _sel25 = _fin25 & np.isfinite(_pp25)
                                        if np.unique(_d25[_sel25]).size == 2:
                                            _auc25 = float(_auc_fn25(_d25[_sel25].astype(int),
                                                                    _pp25[_sel25]))
                                    except Exception:
                                        pass
                            _sat25 = np.nan
                            if (_raw25s is not None and _tau25 is not None
                                    and _j25 < len(_tau25)
                                    and np.isfinite(_tau25[_j25])
                                    and _tau25[_j25] > 0):
                                _sat25 = float(np.mean(
                                    np.abs(_raw25s[:, _j25]) >= 0.95 * _tau25[_j25]))
                            for _path25, _corr25 in _paths25.items():
                                _pred25 = _b25 + _corr25
                                _err25 = np.abs(_y25 - _pred25)
                                _deg_mae25 = (float(np.mean(_err25[_deg25]))
                                              if _deg25.any() else np.nan)
                                _rescue25 = (1.0 - _deg_mae25 / max(_base_deg_mae25, 1e-12)
                                             if np.isfinite(_deg_mae25)
                                             and np.isfinite(_base_deg_mae25)
                                             and _base_deg_mae25 > 1e-12 else np.nan)
                                _nom_mae25 = (float(np.mean(_err25[_nom25]))
                                              if _nom25.any() else np.nan)
                                _nom_rel25 = ((_nom_mae25 - _base_nom_mae25)
                                              / max(_base_nom_mae25, 1e-12)
                                              if np.isfinite(_nom_mae25)
                                              and np.isfinite(_base_nom_mae25) else np.nan)
                                _act25 = _fin25 & (np.abs(_corr25) > 1e-12)
                                _help25 = (float(np.mean(
                                    _err25[_deg25] < np.abs(_cstar25[_deg25])))
                                           if _deg25.any() else np.nan)
                                _harm_nom25 = (float(np.mean(
                                    _err25[_nom25] > np.abs(_cstar25[_nom25])))
                                               if _nom25.any() else np.nan)
                                _corrcoef25 = np.nan
                                _sign25 = np.nan
                                _ccsel25 = _deg25 & np.isfinite(_corr25) & np.isfinite(_cstar25)
                                if _ccsel25.sum() >= 3:
                                    _x25 = _corr25[_ccsel25]
                                    _z25 = _cstar25[_ccsel25]
                                    if np.std(_x25) > 1e-12 and np.std(_z25) > 1e-12:
                                        _corrcoef25 = float(np.corrcoef(_x25, _z25)[0, 1])
                                    _nz25 = np.abs(_z25) > 1e-9
                                    if _nz25.any():
                                        _sign25 = float(np.mean(
                                            np.sign(_x25[_nz25]) == np.sign(_z25[_nz25])))
                                mechanism_rows.append(dict(
                                    drift_type=drift_name, intensity=float(level),
                                    seed=int(_seed), target=_v25, pathway=_path25,
                                    n_degraded=int(_deg25.sum()), n_nominal=int(_nom25.sum()),
                                    degraded_mae=_deg_mae25, rescue=_rescue25,
                                    nominal_mae=_nom_mae25, nominal_penalty_rel=_nom_rel25,
                                    acted_fraction=float(np.mean(_act25)) if _fin25.any() else np.nan,
                                    degraded_helpful_rate=_help25,
                                    nominal_harmful_rate=_harm_nom25,
                                    corr_with_true_correction=_corrcoef25,
                                    correction_sign_accuracy=_sign25,
                                    p_fault_auc=_auc25, p_fault_mean_degraded=_pdeg25,
                                    p_fault_mean_nominal=_pnom25,
                                    tanh_near_bound_fraction=_sat25))

                # ------------------------------------------------------ R26
                # POST-HOC POLICY LOCALIZATION / MINIMAL POLICY CANDIDATE.
                # All four candidates reuse this SAME fitted graph.  Their
                # thresholds are selected on CAL only, authorization is on the
                # disjoint SAFETY block only, and test is scored only afterwards.
                if bool(getattr(config, 'R26_POLICY_LOCALIZATION', False)):
                    _pv26 = getattr(exp_ptac, '_r26_policy_val', None)
                    _ar26 = getattr(exp_ptac, '_r19_arrays', {}) or {}
                    if _pv26 is None or not _ar26:
                        raise RuntimeError('[R26] policy replay arrays unavailable')
                    _nb26 = int(_pv26['n_cal'])
                    _ns26 = int(_pv26['n_safe'])
                    _cal26 = slice(0, _nb26)
                    _safe26 = slice(_nb26, _nb26 + _ns26)
                    _vb26 = np.asarray(_pv26['base'], dtype=float)
                    _vy26 = np.asarray(_pv26['truth'], dtype=float)
                    _vd26 = np.asarray(_pv26['degraded'], dtype=bool)
                    _vo26 = np.asarray(_pv26['observed'], dtype=bool)
                    _vc26 = np.asarray(_pv26['corr_graph'], dtype=float)
                    _vp26 = np.asarray(_pv26['p_fault'], dtype=float)
                    _vr26 = np.asarray(_pv26['r21_score'], dtype=float)
                    _gm26 = np.asarray(_pv26['gate_mask'], dtype=bool)

                    _tb26 = np.asarray(_ar26['test_base'], dtype=float)
                    _ty26 = np.asarray(_ar26['test_true'], dtype=float)
                    _tc26 = np.asarray(_ar26['test_corr_raw'], dtype=float).copy()
                    _bd26 = _ar26.get('bound', None)
                    if _bd26 is not None:
                        _bb26 = np.asarray(_bd26, dtype=float).reshape(1, -1)
                        _tc26 = np.clip(_tc26, -_bb26, _bb26)
                    if not _gm26.all():
                        _tc26[:, ~_gm26] = 0.0
                    _tp26 = np.asarray(_ar26['test_prob'], dtype=float)
                    _tr26 = np.asarray(_ar26['test_selector_score'], dtype=float)
                    _tidx26 = pd.DatetimeIndex(_ar26['test_index'])
                    _td26 = (_synthetic_mask.reindex(index=_tidx26, columns=target_vars)
                              .fillna(False).values.astype(bool))
                    _full26 = np.asarray(_ar26['test_corr'], dtype=float)
                    _postsel26 = np.asarray(
                        getattr(exp_ptac, '_r26_test_corr_post_selector'), dtype=float)

                    # -------------------------------------------------- R27A
                    # Component-wise validation replay audit.
                    #
                    # too strict for GPU inference: a 1-ulp float difference
                    # changes the SHA even when the policy state is numerically
                    # identical. Here masks must remain EXACT, while floats are
                    # compared with explicit atol/rtol and their actual
                    # differences are written BEFORE any abort.
                    if bool(getattr(config, 'R27_FIXED_MODEL_REPLAY', False)):
                        _vk27 = (str(drift_name), int(_seed))
                        _lvl27 = float(level)
                        _vidx27 = pd.DatetimeIndex(val_indices)
                        _components27 = {
                            'validation_index_ns': np.asarray(
                                _vidx27.view('int64'), dtype=np.int64),
                            'base': np.asarray(_vb26, dtype=float),
                            'truth': np.asarray(_vy26, dtype=float),
                            'degraded_mask': np.asarray(_vd26, dtype=bool),
                            'observed_mask': np.asarray(_vo26, dtype=bool),
                            'corr_graph': np.asarray(_vc26, dtype=float),
                            'p_fault': np.asarray(_vp26, dtype=float),
                            'r21_score': np.asarray(_vr26, dtype=float),
                            'gate_mask': np.asarray(_gm26, dtype=bool),
                        }
                        _refs27 = getattr(config, '_r27_component_reference', {})
                        _rows27 = getattr(config, '_r27_component_rows', [])
                        _is_ref27 = _vk27 not in _refs27
                        if _is_ref27:
                            _refs27[_vk27] = {
                                k: np.array(v, copy=True) for k, v in _components27.items()
                            }
                            print(f'    [R27A] validation component reference {_vk27} '
                                  f'at I={_lvl27:g}')
                        else:
                            _bad27 = []
                            for _nm27, _cur27 in _components27.items():
                                _ref27 = np.asarray(_refs27[_vk27][_nm27])
                                _shape_ok27 = (_ref27.shape == _cur27.shape)
                                if (_ref27.dtype == bool or _cur27.dtype == bool
                                        or np.issubdtype(_ref27.dtype, np.integer)
                                        or np.issubdtype(_cur27.dtype, np.integer)):
                                    _exact27 = bool(_shape_ok27 and
                                                    np.array_equal(_ref27, _cur27))
                                    _maxabs27 = 0.0 if _exact27 else float('inf')
                                    _meanabs27 = 0.0 if _exact27 else float('inf')
                                    _pass27 = _exact27
                                    _nchanged27 = (0 if _exact27 else
                                                   int(np.size(_cur27)) if _shape_ok27
                                                   else -1)
                                else:
                                    if _shape_ok27:
                                        _rf27 = np.asarray(_ref27, dtype=float)
                                        _cf27 = np.asarray(_cur27, dtype=float)
                                        _finite27 = np.isfinite(_rf27) & np.isfinite(_cf27)
                                        _nanpat27 = np.array_equal(
                                            np.isnan(_rf27), np.isnan(_cf27))
                                        if _finite27.any():
                                            _dif27 = np.abs(_cf27[_finite27] - _rf27[_finite27])
                                            _maxabs27 = float(np.max(_dif27))
                                            _meanabs27 = float(np.mean(_dif27))
                                            _nchanged27 = int(np.sum(_dif27 > 1e-12))
                                        else:
                                            _maxabs27 = 0.0
                                            _meanabs27 = 0.0
                                            _nchanged27 = 0
                                        _pass27 = bool(
                                            _nanpat27 and np.allclose(
                                                _rf27, _cf27,
                                                rtol=1e-6, atol=1e-8,
                                                equal_nan=True))
                                    else:
                                        _maxabs27 = float('inf')
                                        _meanabs27 = float('inf')
                                        _nchanged27 = -1
                                        _pass27 = False
                                _rows27.append(dict(
                                    drift_type=str(drift_name), seed=int(_seed),
                                    reference_intensity=float(
                                        list(drift_scenarios[
                                            [x[0] for x in drift_scenarios].index(drift_name)
                                        ][1])[0]),
                                    replay_intensity=_lvl27,
                                    component=_nm27,
                                    shape_reference=str(_ref27.shape),
                                    shape_replay=str(_cur27.shape),
                                    max_abs_diff=_maxabs27,
                                    mean_abs_diff=_meanabs27,
                                    n_changed_gt_1e12=_nchanged27,
                                    pass_tolerance=bool(_pass27)))
                                if not _pass27:
                                    _bad27.append((_nm27, _maxabs27))
                            config._r27_component_rows = _rows27
                            _auditp27 = os.path.join(
                                config.OUTPUT_DIR,
                                'r27b_validation_component_audit.csv')
                            pd.DataFrame(_rows27).to_csv(_auditp27, index=False)
                            print(f'    [R27A] component audit written immediately -> {_auditp27}')
                            if _bad27:
                                _msg27 = ', '.join(
                                    f'{n}:max|d|={d:.6g}' for n, d in _bad27)
                                raise RuntimeError(
                                    '[R27A] MATERIAL validation-state change across '
                                    f'test intensity for {_vk27}: {_msg27}. '
                                    'See r27b_validation_component_audit.csv.')
                            else:
                                print(f'    [R27A] validation state NUMERICALLY MATCHES '
                                      f'{_vk27} at I={_lvl27:g} '
                                      '(rtol=1e-6, atol=1e-8). The prior SHA mismatch '
                                      'was floating-point noise, not a material confound.')

                    _candidates26 = [
                        ('raw_pfault_CB_R20', 'p_fault', 'cb'),
                        ('R21_CB_R20', 'r21', 'cb'),
                        ('raw_pfault_POINT_R20', 'p_fault', 'point'),
                        ('R21_POINT_R20', 'r21', 'point'),
                    ]
                    for _j26, _v26 in enumerate(target_vars):
                        _score_map_v26 = {
                            'p_fault': (_vp26[:, _j26], _tp26[:, _j26]),
                            'r21': (_vr26[:, _j26], _tr26[:, _j26]),
                        }
                        _btest26 = _tb26[:, _j26]
                        _ytest26 = _ty26[:, _j26]
                        _dtest26 = _td26[:, _j26]
                        _fint26 = np.isfinite(_btest26) & np.isfinite(_ytest26)
                        _degtest26 = _fint26 & _dtest26
                        _nomtest26 = _fint26 & ~_dtest26
                        _pretest26 = np.abs(_ytest26 - _btest26)
                        _base_deg26 = (float(np.mean(_pretest26[_degtest26]))
                                       if _degtest26.any() else np.nan)
                        _base_nom26 = (float(np.mean(_pretest26[_nomtest26]))
                                       if _nomtest26.any() else np.nan)

                        for _nm26, _scorekind26, _mode26 in _candidates26:
                            _vscore26, _tscore26 = _score_map_v26[_scorekind26]
                            _calfun26 = (calibrate_utility_gate_threshold
                                         if _mode26 == 'cb'
                                         else calibrate_point_utility_gate_threshold)
                            _diag26 = _calfun26(
                                _vscore26[_cal26], _vc26[_cal26, _j26],
                                _vb26[_cal26, _j26], _vy26[_cal26, _j26],
                                _vd26[_cal26, _j26], config,
                                observed=_vo26[_cal26, _j26])
                            _thr26 = float(_diag26.get('threshold', 1.000001))

                            # Independent R19 safety replay using the frozen
                            # threshold.  Same evidence function and limits as
                            # the production safety veto.
                            _csafe26 = np.where(
                                _vscore26[_safe26] >= _thr26,
                                _vc26[_safe26, _j26], 0.0)
                            _bsafe26 = _vb26[_safe26, _j26]
                            _ysafe26 = _vy26[_safe26, _j26]
                            _dsafe26 = _vd26[_safe26, _j26]
                            _osafe26 = _vo26[_safe26, _j26]
                            _pre_safe26 = np.abs(_ysafe26 - _bsafe26)
                            _post_safe26 = np.abs(_ysafe26 - (_bsafe26 + _csafe26))
                            _valid_safe26 = (_osafe26 & np.isfinite(_pre_safe26)
                                             & np.isfinite(_post_safe26))
                            _sev26 = _safety_evidence(
                                np.where(_valid_safe26, _pre_safe26, np.nan),
                                np.where(_valid_safe26, _post_safe26, np.nan),
                                _dsafe26 & _valid_safe26, config)
                            _safe_ok26, _safe_reasons26 = _r26_safety_pass(_sev26, config)

                            # identical across test intensities for a fixed
                            # (family, seed, target).
                            if (bool(getattr(config, 'R27_FIXED_MODEL_REPLAY', False))
                                    and _nm26 == 'R21_POINT_R20'):
                                _pk27 = (str(drift_name), int(_seed), str(_v26))
                                _pref27 = getattr(config, '_r27_policy_reference', {})
                                _state27 = dict(
                                    threshold=float(_thr26),
                                    cal_feasible=bool(_diag26.get('feasible', False)),
                                    safety_pass=bool(_safe_ok26),
                                    safety_rescue_lcb=float(_sev26.get('rescue_lcb', np.nan)),
                                    safety_nominal_ucb_rel=float(_sev26.get('nominal_penalty_ucb_rel', np.nan)),
                                    safety_multiplier_ucb=float(_sev26.get('mae_multiplier_ucb', np.nan)))
                                if _pk27 not in _pref27:
                                    _pref27[_pk27] = _state27
                                else:
                                    _old27 = _pref27[_pk27]
                                    _ok27 = (
                                        abs(float(_old27['threshold']) - float(_state27['threshold'])) <= 1e-10
                                        and bool(_old27['cal_feasible']) == bool(_state27['cal_feasible'])
                                        and bool(_old27['safety_pass']) == bool(_state27['safety_pass']))
                                    if not _ok27:
                                        raise RuntimeError(
                                            f'[R27] POLICY STATE CHANGED with test intensity for {_pk27}: '
                                            f'ref={_old27}, now={_state27}. Aborting.')
                                getattr(config, '_r27_audit_rows', []).append(dict(
                                    drift_type=drift_name, intensity=float(level), seed=int(_seed),
                                    target=_v26, validation_hash=_vh27 if '_vh27' in locals() else '',
                                    weights_reused=bool(getattr(exp_ptac, '_r27_weights_reused', False)),
                                    threshold=float(_thr26),
                                    cal_feasible=bool(_diag26.get('feasible', False)),
                                    safety_pass=bool(_safe_ok26),
                                    safety_rescue_lcb=float(_sev26.get('rescue_lcb', np.nan)),
                                    safety_nominal_ucb_rel=float(_sev26.get('nominal_penalty_ucb_rel', np.nan)),
                                    safety_multiplier_ucb=float(_sev26.get('mae_multiplier_ucb', np.nan))))

                            # Test is never used above.  Record both the frozen
                            # pre-safety policy and the actually authorized
                            # deployment result.  The former is diagnostic only.
                            _ctest_pre26 = np.where(
                                _tscore26 >= _thr26, _tc26[:, _j26], 0.0)
                            _ctest_final26 = (_ctest_pre26 if _safe_ok26
                                               else np.zeros_like(_ctest_pre26))

                            def _metrics26(_corr):
                                _err = np.abs(_ytest26 - (_btest26 + _corr))
                                _dmae = (float(np.mean(_err[_degtest26]))
                                         if _degtest26.any() else np.nan)
                                _res = (1.0 - _dmae / max(_base_deg26, 1e-12)
                                        if np.isfinite(_dmae) and np.isfinite(_base_deg26)
                                        and _base_deg26 > 1e-12 else np.nan)
                                _nmae = (float(np.mean(_err[_nomtest26]))
                                         if _nomtest26.any() else np.nan)
                                _nrel = ((_nmae - _base_nom26) / max(_base_nom26, 1e-12)
                                         if np.isfinite(_nmae) and np.isfinite(_base_nom26)
                                         else np.nan)
                                return _res, _nrel, float(np.mean(np.abs(_corr) > 1e-12))

                            _rpre26, _npre26, _apre26 = _metrics26(_ctest_pre26)
                            _rfin26, _nfin26, _afin26 = _metrics26(_ctest_final26)
                            policy_rows.append(dict(
                                drift_type=drift_name, intensity=float(level), seed=int(_seed),
                                target=_v26, candidate=_nm26, score=_scorekind26,
                                threshold_mode=_mode26, threshold=_thr26,
                                cal_feasible=bool(_diag26.get('feasible', False)),
                                cal_rescue_rel=float(_diag26.get('degraded_rescue_rel', np.nan)),
                                cal_rescue_lcb_rel=float(_diag26.get('degraded_rescue_lcb_rel', np.nan)),
                                cal_nominal_penalty_rel=float(_diag26.get('nominal_penalty_rel', np.nan)),
                                cal_nominal_ucb_rel=float(_diag26.get('nominal_penalty_ucb_rel', np.nan)),
                                safety_pass=bool(_safe_ok26),
                                safety_reasons='|'.join(_safe_reasons26),
                                safety_rescue=float(_sev26.get('rescue', np.nan)),
                                safety_rescue_lcb=float(_sev26.get('rescue_lcb', np.nan)),
                                safety_nominal_ucb_rel=float(_sev26.get('nominal_penalty_ucb_rel', np.nan)),
                                safety_multiplier_ucb=float(_sev26.get('mae_multiplier_ucb', np.nan)),
                                test_rescue_pre_safety=_rpre26,
                                test_nominal_penalty_pre_safety=_npre26,
                                test_action_pre_safety=_apre26,
                                test_rescue_authorized=_rfin26,
                                test_nominal_penalty_authorized=_nfin26,
                                test_action_authorized=_afin26))

                        # Audit: R21 + current CB-R20 + R19 replay must reproduce
                        # the script's own full-policy correction exactly.
                        _cur_rows26 = [x for x in policy_rows
                                       if x['drift_type'] == drift_name
                                       and x['intensity'] == float(level)
                                       and x['seed'] == int(_seed)
                                       and x['target'] == _v26
                                       and x['candidate'] == 'R21_CB_R20']
                        # Direct correction equality is checked separately below
                        # using the internally captured pre-R19 selector output.
                        _max_pre26 = float(np.max(np.abs(
                            _postsel26[:, _j26] - np.where(
                                _tr26[:, _j26] >= float(_pv26['internal_threshold'][_j26]),
                                _tc26[:, _j26], 0.0))))
                        if _max_pre26 > 1e-8:
                            raise AssertionError(
                                f'[R26] internal R21/R20 replay mismatch for {_v26}: '
                                f'{_max_pre26:.3g}')

                # internally, or the drift curve measures a hyperparameter gap and
                # not the correction. PTACExperiment.run() fits its internal
                # baseline with n_estimators=1000, learning_rate=0.01,
                
                # {'n_estimators': 500} at XGBoost's DEFAULT learning_rate (0.3),
                # which is a materially weaker model: on the stable testbed it is
                # ~13% worse on electric conductivity -- the variable the drift
                # figure plots -- before any drift is injected at all. Every point
                # on the published drift curve therefore carried that gap as a
                # constant offset in PTAC's favour. Matching the configuration is
                # the only way the curve can be read as evidence about correction.
                #
                # ------------------------------------------------------ PATCH-A3
                # FEATURE PARITY IN THE DRIFT CURVE (audit F4). Matching the
                # hyperparameters (C-T14, above) was necessary but not
                # sufficient: PTACExperiment.run() also appends the R17 causal
                # drift bank before fitting its internal anchor, and this
                # comparator did not. The r3 curve reported 20.7% / 27.0% MAE
                # reductions at gradual intensities 0.05 / 0.10 where the run's
                # OWN rescue metric was exactly 0.000 -- the corrector provably
                # changed nothing on the drifted rows, so the entire gap was the
                # feature set. use_drift_bank=True closes it, and the unmatched
                # arm is kept alongside so the decomposition is visible in the
                # saved CSV rather than argued in prose.
                #
                # SEED SEMANTICS. random_state stays 42 deliberately. The
                # internal anchor inside PTACExperiment is constructed with
                # random_state=42 regardless of the sweep seed, so varying it
                # here would re-open the C-T14 gap the comment above closes.
                # Consequence: the tree arms are DETERMINISTIC across
                # _rescue_seeds and their MAE_sd is 0.0 by construction, while
                # M2P-PTAC's dispersion comes from the neural initialisation.
                # That asymmetry is real and is now recorded per row
                # ('deterministic_across_seeds') so a reader cannot mistake the
                # zero for a single-draw comparator.
                _cmp_specs = [
                    ('XGBoost (drift bank)', True,
                     xgb.XGBRegressor, {'objective': 'reg:squarederror',
                                        'n_estimators': 1000,
                                        'learning_rate': 0.01,
                                        'random_state': 42, 'n_jobs': -1}),
                    ('XGBoost', False,
                     xgb.XGBRegressor, {'objective': 'reg:squarederror',
                                        'n_estimators': 1000,
                                        'learning_rate': 0.01,
                                        'random_state': 42, 'n_jobs': -1}),
                ]
                
                # M2P-PTAC on all four testbeds. It must appear on the drift
                # curve too, or the curve is silent about the one baseline that
                # actually threatens the claim.
                if bool(getattr(config, 'DRIFT_STRESS_INCLUDE_LGBM', True)):
                    _cmp_specs.append(
                        ('LightGBM (drift bank)', True,
                         lgb.LGBMRegressor, {'objective': 'regression_l1',
                                             'n_estimators': 1000,
                                             'learning_rate': 0.01,
                                             'random_state': 42,
                                             'verbose': -1}))
                _res_cmp = {}
                for _nm, _bank_on, _cls, _prm in _cmp_specs:
                    _exp = TabularExperiment(
                        f"{_nm}_{drift_name}_{level}", config, _cls, _prm,
                        eval_truth_df=truth, obs_mask=obs_mask,
                        target_mode='delta', use_drift_bank=_bank_on)
                    _res_cmp[_nm] = _exp.run(df_drifted, target_vars)[0]
                res_xgb = _res_cmp['XGBoost (drift bank)']   # the fair comparator

                var_to_plot = 'electric conductivity'
                if f'{var_to_plot}_MAE' not in res_ptac:
                    var_to_plot = target_vars[0]
                stress_results.append({'Type': drift_name, 'Level': level, 'seed': int(_seed),
                                       'Model': 'M2P-PTAC', 'MAE': res_ptac[f'{var_to_plot}_MAE'],
                                       'uses_drift_bank': True,
                                       'deterministic_across_seeds': False})
                for _nm, _bank_on, _c, _p in _cmp_specs:
                    stress_results.append(
                        {'Type': drift_name, 'Level': level, 'seed': int(_seed),
                         'Model': _nm, 'MAE': _res_cmp[_nm][f'{var_to_plot}_MAE'],
                         'uses_drift_bank': bool(_bank_on),
                         'deterministic_across_seeds': True})

                _rr = getattr(exp_ptac, '_r17_rescue', None)
                if _rr is not None and len(_rr):
                    for _row in _rr.itertuples():
                        rescue_rows.append(dict(
                            seed=int(_seed),
                            drift_type=drift_name, intensity=float(level),
                            target=_row.target, n_drift_rows=int(_row.n_drift_rows),
                            max_abs_correction=float(_row.max_abs_correction),
                            rescue=float(_row.rescue_ratio),
                            # quoted without the anchor's own contribution.
                            anchor_drift_removal=float(
                                getattr(_row, 'anchor_drift_removal', float('nan'))),
                            anchor_residual_fraction=float(
                                getattr(_row, 'anchor_residual_fraction', float('nan'))),
                            total_drift_removal=float(
                                getattr(_row, 'total_drift_removal', float('nan'))),
                            # boundary too. They were computed per target but
                            # dropped here, so the saved curve carried removal
                            # fractions with no way to tell which were measurable.
                            drift_snr=float(
                                getattr(_row, 'drift_snr', float('nan'))),
                            removal_identifiable=bool(
                                getattr(_row, 'removal_identifiable', False)),
                            safety_pass=bool(np.asarray(getattr(exp_ptac, '_r19_safety_mask',
                                                               np.zeros(len(target_vars), dtype=bool)))[
                                target_vars.index(_row.target)]),
                            safety_n_degraded_units=int((getattr(exp_ptac, '_r19_safety_diag', {})
                                .get(_row.target, {}) or {}).get('n_degraded_units', 0)),
                            safety_n_nominal_units=int((getattr(exp_ptac, '_r19_safety_diag', {})
                                .get(_row.target, {}) or {}).get('n_nominal_units', 0)),
                            safety_rescue_lcb=float((getattr(exp_ptac, '_r19_safety_diag', {})
                                .get(_row.target, {}) or {}).get('degraded_rescue_lcb', np.nan)),
                            safety_nominal_ucb_rel=float((getattr(exp_ptac, '_r19_safety_diag', {})
                                .get(_row.target, {}) or {}).get('nominal_penalty_ucb_rel', np.nan)),
                            safety_multiplier_ucb=float((getattr(exp_ptac, '_r19_safety_diag', {})
                                .get(_row.target, {}) or {}).get('mae_multiplier_ucb', np.nan))))

    if bool(getattr(config, 'R27_FIXED_MODEL_REPLAY', False)):
        _ra27 = pd.DataFrame(replay_audit_rows)
        _rap27 = os.path.join(config.OUTPUT_DIR,
                              'r27_fixed_weight_replay_audit.csv')
        _ra27.to_csv(_rap27, index=False)
        _bad27 = []
        for (_dt27, _sd27), _g27 in _ra27.groupby(
                ['drift_type', 'seed'], sort=False):
            _g27 = _g27.sort_values('intensity', kind='stable')
            _reuse27 = _g27['weights_reused'].astype(bool).values
            _sha27 = _g27['weight_sha256'].astype(str)
            _hist27 = _g27['history_sha256'].astype(str)
            _ok_reuse27 = bool(
                len(_reuse27) >= 2 and not _reuse27[0]
                and _reuse27[1:].all())
            _ok_sha27 = bool(_sha27.ne('').all() and _sha27.nunique() == 1)
            _ok_hist27 = bool(_hist27.ne('').all() and _hist27.nunique() == 1)
            if not (_ok_reuse27 and _ok_sha27 and _ok_hist27):
                _bad27.append(
                    f"{_dt27}/seed={_sd27}: reuse={_reuse27.tolist()}, "
                    f"weight_hashes={int(_sha27.nunique())}, "
                    f"history_hashes={int(_hist27.nunique())}")
        print(f"[R27] exact weight replay audit -> {_rap27}")
        if _bad27:
            raise RuntimeError(
                '[R27] fixed-model replay audit failed: ' + ' | '.join(_bad27))
        print('[R27] PASS: one fit per drift-family/seed; every later intensity '
              'reused one identical weight hash and one identical pre-test '
              'history hash.')

    if mechanism_rows:
        _mr25 = pd.DataFrame(mechanism_rows)
        _mr25.to_csv(os.path.join(config.OUTPUT_DIR,
                                  'r25_mechanism_pathways_per_seed.csv'), index=False)
        _grp25 = ['drift_type', 'intensity', 'target', 'pathway']
        _num25 = [c for c in _mr25.columns if c not in _grp25 + ['seed']
                  and pd.api.types.is_numeric_dtype(_mr25[c])]
        _ms25 = (_mr25.groupby(_grp25)[_num25]
                 .agg(['mean', 'std', 'count']))
        _ms25.columns = ['_'.join(c).strip('_') for c in _ms25.columns]
        _ms25 = _ms25.reset_index()
        _ms25.to_csv(os.path.join(config.OUTPUT_DIR,
                                  'r25_mechanism_pathways_summary.csv'), index=False)

        # Failure-localization table: compare the three intervention stages.
        _loc25 = []
        for (_dt25, _ii25, _tg25), _g25 in _ms25.groupby(
                ['drift_type', 'intensity', 'target']):
            if float(_ii25) <= 0:
                continue
            _rmap25 = dict(zip(_g25['pathway'], _g25['rescue_mean']))
            _b25 = float(_rmap25.get('B_raw_bounded', np.nan))
            _c25 = float(_rmap25.get('C_pfault_gated', np.nan))
            _d25 = float(_rmap25.get('D_full_policy', np.nan))
            if np.isfinite(_b25) and _b25 > 0.10 and (not np.isfinite(_c25) or _c25 < 0.5*_b25):
                _where25 = 'fault_detector_or_pointwise_gate'
            elif np.isfinite(_c25) and _c25 > 0.10 and (not np.isfinite(_d25) or _d25 < 0.5*_c25):
                _where25 = 'posthoc_selector_or_safety_policy'
            elif np.isfinite(_b25) and _b25 <= 0.05:
                _where25 = 'neural_corrector_learning'
            else:
                _where25 = 'mixed_or_regime_specific'
            _loc25.append(dict(drift_type=_dt25, intensity=float(_ii25),
                               target=_tg25, raw_rescue=_b25,
                               pfault_gated_rescue=_c25, full_policy_rescue=_d25,
                               likely_bottleneck=_where25))
        _ld25 = pd.DataFrame(_loc25)
        _ld25.to_csv(os.path.join(config.OUTPUT_DIR,
                                  'r25_mechanism_failure_localization.csv'), index=False)
        print('\n[R25-MECH] MECHANISM PATHWAY SUMMARY')
        _show25 = _ms25[[_c for _c in ['drift_type','intensity','target','pathway',
                                       'rescue_mean','rescue_std',
                                       'corr_with_true_correction_mean',
                                       'correction_sign_accuracy_mean',
                                       'p_fault_auc_mean'] if _c in _ms25.columns]]
        print(_show25.round(4).to_string(index=False))
        if len(_ld25):
            print('\n[R25-MECH] FAILURE LOCALIZATION')
            print(_ld25.round(4).to_string(index=False))

    if policy_rows:
        _pr26 = pd.DataFrame(policy_rows)
        _pr26.to_csv(os.path.join(config.OUTPUT_DIR,
                                  'r26_policy_candidates_per_seed.csv'), index=False)
        _keys26 = ['drift_type','intensity','target','candidate','score','threshold_mode']
        _num26 = [c for c in _pr26.columns if c not in _keys26 + ['seed','safety_reasons']
                  and pd.api.types.is_numeric_dtype(_pr26[c])]
        _ps26 = (_pr26.groupby(_keys26)[_num26].agg(['mean','std','count']))
        _ps26.columns = ['_'.join(c).strip('_') for c in _ps26.columns]
        _ps26 = _ps26.reset_index()
        _ps26.to_csv(os.path.join(config.OUTPUT_DIR,
                                  'r26_policy_candidates_summary.csv'), index=False)

        # Validation-side authorization census. This is the decision table to
        # inspect FIRST; test performance must not be used to rewrite thresholds.
        _ver26 = (_pr26.groupby(['candidate','drift_type','target'])
                  .agg(n_fits=('seed','size'),
                       cal_feasible_rate=('cal_feasible','mean'),
                       safety_pass_rate=('safety_pass','mean'),
                       mean_test_rescue_authorized=('test_rescue_authorized','mean'),
                       mean_test_nominal_penalty_authorized=('test_nominal_penalty_authorized','mean'))
                  .reset_index())
        _ver26.to_csv(os.path.join(config.OUTPUT_DIR,
                                   'r26_policy_authorization_census.csv'), index=False)
        print('\n[R26] POLICY AUTHORIZATION CENSUS')
        print(_ver26.round(4).to_string(index=False))
        print('[R26] IMPORTANT: this is a development/localization run. If a new '
              'candidate is retained, lock it before a fresh final stress study.')

        if bool(getattr(config, 'R27_FIXED_MODEL_REPLAY', False)):
            _audit27 = pd.DataFrame(getattr(config, '_r27_audit_rows', []))
            _audit27.to_csv(os.path.join(config.OUTPUT_DIR,
                                         'r27_fixed_replay_audit.csv'), index=False)
            _r27 = _pr26[_pr26['candidate'] == 'R21_POINT_R20'].copy()
            _keep27 = [c for c in [
                'drift_type','intensity','seed','target','threshold','cal_feasible',
                'safety_pass','safety_reasons','safety_rescue_lcb',
                'safety_nominal_ucb_rel','safety_multiplier_ucb',
                'test_rescue_pre_safety','test_nominal_penalty_pre_safety',
                'test_action_pre_safety','test_rescue_authorized',
                'test_nominal_penalty_authorized','test_action_authorized']
                if c in _r27.columns]
            _r27[_keep27].to_csv(os.path.join(
                config.OUTPUT_DIR, 'r27_r21_point_per_seed.csv'), index=False)
            _sum27 = (_r27.groupby(['drift_type','intensity','target'])
                      .agg(n_seeds=('seed','nunique'),
                           cal_feasible_rate=('cal_feasible','mean'),
                           safety_pass_rate=('safety_pass','mean'),
                           threshold_mean=('threshold','mean'),
                           threshold_sd=('threshold','std'),
                           pre_safety_rescue_mean=('test_rescue_pre_safety','mean'),
                           authorized_rescue_mean=('test_rescue_authorized','mean'),
                           action_rate_mean=('test_action_authorized','mean'))
                      .reset_index())
            _sum27.to_csv(os.path.join(config.OUTPUT_DIR,
                                       'r27_fixed_model_curve_summary.csv'), index=False)
            print('\n[R27] FIXED-MODEL CURVE SUMMARY (R21 + POINT-R20 + unchanged R19)')
            print(_sum27.round(4).to_string(index=False))
            if len(_audit27):
                _badw27 = _audit27.groupby(['drift_type','seed'])['weights_reused'].sum()
                print('[R27] replay audit written: r27_fixed_replay_audit.csv; '
                      'expected 3 reused intensity arms per family/seed after one reference fit.')

    # -------------------------------------------------------------- R27B
    # Persist the component invariance audit even after a successful full run.
    if bool(getattr(config, 'R27_FIXED_MODEL_REPLAY', False)):
        _cr27b = pd.DataFrame(getattr(config, '_r27_component_rows', []) or [])
        if len(_cr27b):
            _cr27b.to_csv(os.path.join(
                config.OUTPUT_DIR, 'r27b_validation_component_audit.csv'),
                index=False)
            _bad27b = _cr27b[~_cr27b['pass_tolerance'].astype(bool)]
            print(f"[R27B] validation-component invariance: "
                  f"{len(_cr27b)-len(_bad27b)}/{len(_cr27b)} comparisons PASS")
            if len(_bad27b):
                raise RuntimeError(
                    "[R27B] material pre-test state differences remain after "
                    "raw-time split repair; refusing release.")

    _df_stress_raw = pd.DataFrame(stress_results)
    df_stress = _df_stress_raw.copy()
    # F12: F9 added a seed dimension, so there are now len(R17_RESCUE_SEEDS)
    # rows per (Type, Level, Model). Everything downstream -- the monotonicity
    # gate and the MAE curves -- assumes ONE row per cell and would raise
    # "Index contains duplicate entries, cannot reshape" at the pivot. Keep the
    # per-seed rows as the raw record, and collapse to the seed mean (with sd)
    # for the gate and the figures so their semantics are unchanged.
    df_stress.to_csv(os.path.join(config.OUTPUT_DIR,
                                  'drift_stress_results_per_seed.csv'), index=False)
    if 'seed' in df_stress.columns and df_stress['seed'].nunique() > 1:
        _keys = [c for c in ('Type', 'Level', 'Model') if c in df_stress.columns]
        # PATCH-A3: the parity FLAGS are constant within a (Type, Level, Model)
        # cell and boolean. pandas treats bool as numeric, so leaving them in
        # _num would average them into 0.0/1.0 floats plus a meaningless _sd
        # column. Carry them through the _first frame instead.
        _flags = [c for c in ('uses_drift_bank', 'deterministic_across_seeds')
                  if c in df_stress.columns]
        _num = [c for c in df_stress.columns
                if c not in _keys + ['seed'] + _flags
                and pd.api.types.is_numeric_dtype(df_stress[c])]
        _sd = (df_stress.groupby(_keys)[_num].std()
                        .rename(columns={c: c + '_sd' for c in _num}))
        _mn = df_stress.groupby(_keys)[_num].mean()
        _first = (df_stress.drop_duplicates(_keys).set_index(_keys)
                           .drop(columns=[c for c in _num + ['seed']
                                          if c in df_stress.columns]))
        df_stress = (_mn.join(_sd).join(_first, how='left')
                        .reset_index())
        _ns = pd.DataFrame(stress_results).groupby(_keys)['seed'].nunique()
        df_stress = df_stress.merge(_ns.rename('n_seeds').reset_index(),
                                    on=_keys, how='left')
        print(f"    [F12] drift_stress_results collapsed over "
              f"{int(pd.DataFrame(stress_results)['seed'].nunique())} seeds "
              f"(mean + _sd columns, n_seeds per cell); per-seed rows kept in "
              f"drift_stress_results_per_seed.csv")
    df_stress.to_csv(os.path.join(config.OUTPUT_DIR, 'drift_stress_results.csv'), index=False)

    # ----------------------------------------------------------------------
    # Sanity gate: degradation must degrade.
    # ----------------------------------------------------------------------
    print("\n[R4] Stress-harness check -- the MATCHED DIFFERENCED-TARGET XGBoost + drift-bank anchor must worsen with intensity; corrected-model monotonicity is descriptive only:")
    harness_ok = True
    _r4_release_refs = {'XGBoost (drift bank)'}  # stress-table alias of CORRECTOR_ATTRIBUTION_ANCHOR
    for (dtype, mdl), grp in df_stress.groupby(['Type', 'Model']):
        grp = grp.sort_values('Level')
        base = grp[grp['Level'] == 0]['MAE']
        base_str = f"{base.iloc[0]:.3f}" if len(base) else "n/a"
        deltas = np.diff(grp['MAE'].values)
        ok = bool((deltas >= -1e-9).all())
        # Paired inference across the SAME seeds at adjacent intensities.  The
        # former pooled, independent-cell SE discarded the pairing and labelled
        # it "paired"; that can both hide and invent inversions.
        _hard, _soft = [], []
        _raw_grp = _df_stress_raw[
            (_df_stress_raw['Type'] == dtype)
            & (_df_stress_raw['Model'] == mdl)]
        _raw_piv = _raw_grp.pivot_table(
            index='seed', columns='Level', values='MAE', aggfunc='first')
        _levels = grp['Level'].values
        for _i in range(len(_levels) - 1):
            _l0, _l1 = _levels[_i], _levels[_i + 1]
            if _l0 not in _raw_piv.columns or _l1 not in _raw_piv.columns:
                continue
            _pair = _raw_piv[[_l0, _l1]].dropna()
            _diff = (_pair[_l1] - _pair[_l0]).values
            _mean_d, _lo_d, _hi_d = _student_t_mean_ci(_diff, confidence=0.95)
            if not np.isfinite(_mean_d) or _mean_d >= -1e-9:
                continue
            _rec = ((_l0, _l1), _mean_d, _lo_d, _hi_d, int(len(_diff)))
            if len(_diff) < 2 or not np.isfinite(_hi_d) or _hi_d < 0:
                _hard.append(_rec)
            else:
                _soft.append(_rec)
        ok = not _hard
        _release_critical = str(mdl) in _r4_release_refs
        if _release_critical:
            harness_ok &= ok
        if _hard and _release_critical:
            _verdict = 'NON-MONOTONE MATCHED ANCHOR (HARNESS FAIL)'
        elif _hard:
            _verdict = 'NON-MONOTONE CORRECTED/OTHER (descriptive; not harness fail)'
        elif _soft:
            _verdict = 'MONOTONE within seed noise'
        else:
            _verdict = 'MONOTONE UP (ok)'
        print(f"  {dtype:14s} {mdl:10s} I=0 MAE={base_str:>9s}  "
              f"trend={_verdict}  "
              f"values={np.round(grp['MAE'].values, 3).tolist()}")
        for _lv, _d, _lo, _hi, _n in _soft:
            print(f"      [F13] I={_lv[0]}->{_lv[1]}: paired dMAE={_d:+.4f}, "
                  f"95% t-CI [{_lo:+.4f}, {_hi:+.4f}], n={_n} -- interval "
                  "crosses zero; report as inconclusive, not inverted.")
        for _lv, _d, _lo, _hi, _n in _hard:
            print(f"      [F13] I={_lv[0]}->{_lv[1]}: paired dMAE={_d:+.4f}, "
                  f"95% t-CI [{_lo:+.4f}, {_hi:+.4f}], n={_n} -- "
                  "statistically supported decrease (or underpowered n<2).")
    if not harness_ok:
        print("[R4] WARNING: the matched DIFFERENCED-TARGET XGBoost + drift-bank anchor "
              "has a statistically supported MAE decrease as injected intensity rises. "
              "The stress harness is not releasable.")
        _register_release_failure(
            config, 'DRIFT_MONOTONICITY_FAILED',
            'Matched differenced-target XGBoost + drift-bank anchor has a supported '
            'MAE decrease across adjacent drift intensities.')

    # Crossover detection -- an operating limit, to be stated rather than hidden.
    # PATCH-A3: run against EVERY comparator present, not just the unmatched
    
    for dtype, grp in df_stress.groupby('Type'):
        piv = grp.pivot(index='Level', columns='Model', values='MAE').sort_index()
        if 'M2P-PTAC' not in piv.columns:
            continue
        for _cmp in [c for c in piv.columns if c != 'M2P-PTAC']:
            ahead = piv['M2P-PTAC'] < piv[_cmp]
            if ahead.any() and (~ahead).any():
                first_loss = piv.index[~ahead][0]
                print(f"[R4] CROSSOVER on '{dtype}' vs '{_cmp}': M2P-PTAC loses "
                      f"its advantage at level {first_loss}. Report this as a "
                      f"stated operating limit in the manuscript.")
            elif not ahead.any():
                print(f"[R4] '{_cmp}' is AHEAD OF M2P-PTAC at every intensity "
                      f"on '{dtype}'. This is a negative result for the "
                      f"correction on this scenario and must be reported.")

    # ------------------------------------------------------------------ PATCH-A3
    # DRIFT-GAIN DECOMPOSITION. The audit's F4: the r3 curve attributed the
    # whole M2P-vs-comparator gap to the correction while the rescue metric
    # read 0.000 at the two lowest intensities. With both a banked and an
    # unbanked comparator on the curve the gap now splits into a FEATURE term
    # and a CORRECTOR term, per intensity, and the split is written to disk
    # next to the rescue curve so the two can be read together.
    try:
        _piv = df_stress.pivot_table(index=['Type', 'Level'], columns='Model',
                                     values='MAE')
        if {'M2P-PTAC', 'XGBoost', 'XGBoost (drift bank)'}.issubset(_piv.columns):
            _dec = pd.DataFrame({
                'mae_ptac': _piv['M2P-PTAC'],
                'mae_anchor_banked': _piv['XGBoost (drift bank)'],
                'mae_anchor_plain': _piv['XGBoost'],
            })
            _dec['feature_effect'] = _dec['mae_anchor_plain'] - _dec['mae_anchor_banked']
            _dec['corrector_effect'] = _dec['mae_anchor_banked'] - _dec['mae_ptac']
            _dec['total_gap_vs_plain'] = _dec['mae_anchor_plain'] - _dec['mae_ptac']
            with np.errstate(invalid='ignore', divide='ignore'):
                _dec['corrector_share_of_gap'] = (
                    _dec['corrector_effect'] / _dec['total_gap_vs_plain'].replace(0, np.nan))
            _dec = _dec.reset_index()
            _dec.to_csv(os.path.join(config.OUTPUT_DIR,
                                     'drift_gain_decomposition.csv'), index=False)
            print("\n[A3] DRIFT-GAIN DECOMPOSITION (positive = MAE reduction):")
            print(_dec.round(4).to_string(index=False))
            print("     feature_effect  = drift bank alone, corrector held out")
            print("     corrector_effect = correction alone, features held fixed")
            print("     The r3 headline quoted total_gap_vs_plain as the "
                  "corrector's effect.")
        else:
            print("    [A3] decomposition skipped: need M2P-PTAC plus both the "
                  "banked and unbanked XGBoost arms on the curve.")
    except Exception as _de:
        print(f"    [A3] WARNING: decomposition failed "
              f"({type(_de).__name__}: {_de}); the per-seed CSV is unaffected.")

    # ----------------------------------------------------------------------
    # Plots -- now including the I=0 control point on the axis.
    # ----------------------------------------------------------------------
    for dtype, fname, xlabel, marker in [
        ('gradual_bias', 'drift_stress_gradual_ec.png',
         'Drift Magnitude (Slope Intensity); I=0 is the undrifted control', 'o'),
        ('sudden_shift', 'drift_stress_sudden_ec.png',
         'Drift Intensity (Sigma Shift); 0 is the undrifted control', 's'),
    ]:
        sub = df_stress[df_stress['Type'] == dtype]
        if sub.empty:
            continue
        fig, ax = plt.subplots(figsize=(10, 6))
        sns.lineplot(data=sub, x='Level', y='MAE', hue='Model', marker=marker, ax=ax)
        # PATCH-F13: the monotonicity verdict is now judged against seed
        # dispersion, so the figure must show it. Without these bars the
        # terminal step of the gradual_bias curve reads as a real dip.
        if 'MAE_sd' in sub.columns:
            for _mdl, _g in sub.groupby('Model'):
                _g = _g.sort_values('Level')
                _s = pd.to_numeric(_g['MAE_sd'], errors='coerce')
                _n = (pd.to_numeric(_g['n_seeds'], errors='coerce')
                      if 'n_seeds' in _g.columns else pd.Series(1, index=_g.index))
                _err = (_s / np.sqrt(_n.clip(lower=1))).fillna(0.0).values
                if np.any(_err > 0):
                    ax.errorbar(_g['Level'].values, _g['MAE'].values, yerr=_err,
                                fmt='none', ecolor='0.35', elinewidth=1.0,
                                capsize=3, zorder=1)
            ax.plot([], [], ' ', label='error bars: ±1 SE over seeds')
            ax.legend()
        if config.DRIFT_INCLUDE_ZERO_CONTROL:
            ax.axvline(0, color='0.4', ls=':', lw=1.2)
            ax.text(0, ax.get_ylim()[1], ' undrifted control', va='top',
                    fontsize=9, color='0.3')
        ax.set_title(f'Impact of {"Gradual Sensor Drift" if dtype == "gradual_bias" else "Sudden Sensor Shift"} on EC MAE\n'
                     f'(evaluated against clean ground truth)',
                     fontsize=13, fontweight='bold')
        ax.set_xlabel(xlabel, fontsize=11)
        ax.set_ylabel('MAE (Electric Conductivity)', fontsize=12)
        ax.grid(True, linestyle='--', alpha=0.7)
        fig.tight_layout()
        fig.savefig(os.path.join(config.OUTPUT_DIR, fname), dpi=200)
        plt.close(fig)

    # ----------------------------------------------------------------------
    #
    #   (a) monotone   R(I) non-decreasing in I
    #   (b) positive   R(I) > 0 for I >= 1 (drift at or above the noise floor)
    #   (c) null       |R(0)| <= R17_NULL_TOL
    #
    # (c) IS THE PRIMARY GATE.  In the controlled experiment behind this
    # design, R(0) measured -14.4%: with no drift injected the corrector
    # still fired and made the forecast WORSE on the rows it targeted, which
    # is the synthetic reproduction of the -24.19% cell observed on ch89509
    # electric conductivity.  Because 6 of 16 channel-slots have no
    # test-window faults at all, false alarms outnumber true episodes on this
    # data and a negative R(0) is a net loss, not a rounding error.
    #
    # A run that fails (c) is NOT reported as a rescue result.  The gate is
    # enforced here rather than left to the reader.
    # ----------------------------------------------------------------------
    if rescue_rows:
        df_resc = pd.DataFrame(rescue_rows)
        df_resc.to_csv(os.path.join(config.OUTPUT_DIR,
                                    'r17_rescue_curve.csv'), index=False)

        # ==================================================================
        # F10: DISPERSION AND VERDICT STABILITY ACROSS SEEDS.
        #
        # The acceptance block below averages over seeds (its groupby collapses
        # them), which is the right point estimate but hides the quantity a
        
        # the ACCEPT/REJECT decision survive re-seeding? A verdict that flips
        # across seeds is not a finding. Both tables are written before any
        # averaging so the raw draws remain auditable.
        # ==================================================================
        _nseed = int(df_resc['seed'].nunique()) if 'seed' in df_resc.columns else 1
        if _nseed > 1:
            _agg = {'rescue': ['mean', 'std', 'min', 'max', 'count']}
            for _c in ('anchor_drift_removal', 'total_drift_removal', 'drift_snr'):
                if _c in df_resc.columns:
                    _agg[_c] = ['mean', 'std']
            _disp = (df_resc.groupby(['drift_type', 'target', 'intensity'])
                            .agg(_agg))
            _disp.columns = ['_'.join(c).strip('_') for c in _disp.columns]
            _disp = _disp.reset_index()
            # Small-sample Student-t CI computed from the actual seed draws.
            # With 3--5 seeds, a fixed 1.96 normal multiplier is anti-conservative.
            _ci_rows = []
            for _keys, _gci in df_resc.groupby(
                    ['drift_type', 'target', 'intensity']):
                _mn, _lo, _hi = _student_t_mean_ci(
                    _gci['rescue'].values, confidence=0.95)
                _ci_rows.append(dict(
                    drift_type=_keys[0], target=_keys[1], intensity=_keys[2],
                    rescue_ci_lo=_lo, rescue_ci_hi=_hi))
            _disp = _disp.merge(pd.DataFrame(_ci_rows),
                                on=['drift_type', 'target', 'intensity'],
                                how='left')
            _disp['rescue_ci_excludes_zero'] = (
                (_disp['rescue_ci_lo'] > 0) | (_disp['rescue_ci_hi'] < 0))
            _disp.to_csv(os.path.join(config.OUTPUT_DIR,
                                      'r17_rescue_dispersion.csv'), index=False)
            print(f"\n[F10] RESCUE DISPERSION across {_nseed} seeds "
                  "(mean +/- sd, 95% CI on the mean):")
            for _r in _disp[_disp['intensity'] > 0].itertuples():
                print(f"  {_r.drift_type:14s} {_r.target:22s} I={_r.intensity:<5g} "
                      f"R={100 * _r.rescue_mean:+7.2f}% +/- {100 * _r.rescue_std:5.2f} "
                      f"[{100 * _r.rescue_ci_lo:+7.2f}, {100 * _r.rescue_ci_hi:+7.2f}] "
                      f"{'CI excludes 0' if _r.rescue_ci_excludes_zero else 'CI SPANS 0 -- not distinguishable from no rescue'}")

            # Per-seed verdicts: does the acceptance decision reproduce?
            _tol0 = float(getattr(config, 'R17_NULL_TOL', 0.02))
            _stab = []
            for (_dt, _tg, _sd), _g in df_resc.groupby(['drift_type', 'target', 'seed']):
                _cc0 = ['rescue', 'max_abs_correction']
                for _e0 in ('anchor_drift_removal', 'total_drift_removal', 'drift_snr'):
                    if _e0 in _g.columns:
                        _cc0.append(_e0)
                _cv = (_g.groupby('intensity', as_index=False)[_cc0]
                         .mean().sort_values('intensity'))
                _v0 = evaluate_rescue_acceptance(_cv, null_tol=_tol0)
                _stab.append(dict(drift_type=_dt, target=_tg, seed=int(_sd),
                                  **{k: _v0.get(k) for k in
                                     ('monotone', 'positive', 'null_ok',
                                      'null_rescue', 'accepted', 'note')
                                     if k in _v0}))
            if _stab:
                _st = pd.DataFrame(_stab)
                _st.to_csv(os.path.join(config.OUTPUT_DIR,
                                        'r17_rescue_verdict_stability.csv'),
                           index=False)
                if 'accepted' in _st.columns:
                    print("\n[F10] VERDICT STABILITY (per-seed acceptance decision):")
                    for (_dt, _tg), _g in _st.groupby(['drift_type', 'target']):
                        _acc = _g['accepted'].astype(bool)
                        _flag = ('STABLE' if _acc.nunique() == 1
                                 else 'FLIPS ACROSS SEEDS -- NOT REPRODUCIBLE')
                        print(f"  {_dt:14s} {_tg:22s} "
                              f"accept={_acc.sum()}/{len(_acc)} seeds  {_flag}")
        else:
            print("\n[F10] rescue sweep ran at a SINGLE seed: no dispersion, no "
                  "CI, and verdict reproducibility is untested. Set "
                  "Config.R17_RESCUE_SEEDS to >=3 seeds before quoting any "
                  "rescue number or acceptance verdict in the manuscript.")
        _tol = float(getattr(config, 'R17_NULL_TOL', 0.02))
        print("\n[R17] PROOF-OF-RESCUE ACCEPTANCE  "
              "(R = 1 - MAE_corrected/MAE_anchor on drift rows)")
        verdicts = []
        for (dt, tgt), grp in df_resc.groupby(['drift_type', 'target']):
            _cc = ['rescue', 'max_abs_correction']
            for _extra in ('anchor_drift_removal', 'total_drift_removal',
                           'drift_snr'):
                if _extra in grp.columns:
                    _cc.append(_extra)
            curve = (grp.groupby('intensity', as_index=False)[_cc]
                        .mean().sort_values('intensity'))
            v = evaluate_rescue_acceptance(curve, null_tol=_tol)
            v.update(drift_type=dt, target=tgt)
            verdicts.append(v)
            _pts = ", ".join(
                f"I={r.intensity:g}:{100.0 * r.rescue:+.1f}%"
                if np.isfinite(r.rescue) else f"I={r.intensity:g}:n/a"
                for r in curve.itertuples())
            # REJECT where the anchor already removed ~96% of the drift is a
            # different scientific statement from a REJECT where the anchor
            # left most of the drift on the table, and the verdict alone does
            # not distinguish them. This annotates; it does NOT relax any
            # criterion -- the three tests and every verdict are unchanged.
            _hr = ''
            if 'drift_snr' in curve.columns:
                _s = curve['drift_snr'].dropna()
                if len(_s) and float(_s.max()) < 1.0:
                    _hr = ("  | removal NOT identifiable: injected drift peaks "
                           f"at {float(_s.max()):.2f}x the model's own error "
                           "floor, so the removal denominator is below the "
                           "noise floor (R itself is unaffected)")
            if not _hr and 'anchor_drift_removal' in curve.columns:
                _a = curve['anchor_drift_removal'].dropna()
                if len(_a):
                    _hr = (f"  | anchor already removed "
                           f"{100.0 * _a.mean():.0f}% (headroom "
                           f"{100.0 * (1.0 - _a.mean()):.0f}%)")
                    if 'total_drift_removal' in curve.columns:
                        _t = curve['total_drift_removal'].dropna()
                        if len(_t):
                            _hr += f", end-to-end {100.0 * _t.max():.0f}%"
            print(f"  {dt:14s} {str(tgt)[:22]:22s} "
                  f"{'ACCEPT' if v['accepted'] else 'REJECT':6s}  "
                  f"[mono={v['monotone']} pos={v['positive']} "
                  f"null={v['null_ok']}]  {_pts}{_hr}")
        df_v = pd.DataFrame(verdicts)
        df_v.to_csv(os.path.join(config.OUTPUT_DIR,
                                 'r17_rescue_acceptance.csv'), index=False)
        _fail_null = df_v[df_v.null_ok == False]
        if len(_fail_null):
            print("\n[R17] NULL CONTROL FAILED on "
                  f"{len(_fail_null)} of {len(df_v)} curves. The corrector "
                  "acts when there is no drift to correct. Report R(0) "
                  "alongside every rescue number; a rescue figure that "
                  "starts at I>0 conceals exactly this.")
            for r in _fail_null.itertuples():
                print(f"      {r.drift_type} / {r.target}: "
                      f"R(0) = {100.0 * r.null_rescue:+.2f}%")
        if bool(df_v.accepted.fillna(False).any()):
            print("[R17] At least one curve satisfies positive-rescue + null-safety criteria; rescue monotonicity is descriptive.")
        else:
            print("[R17] NO curve satisfies positive-rescue + null-safety criteria. The rescue "
                  "claim is NOT supported by this run and must not be made.")

        # Rescue curve figure -- R(I) with the null control on the axis and a
        # zero line, so criterion (c) is visible rather than tabulated.
        for dt, grp in df_resc.groupby('drift_type'):
            piv = (grp.groupby(['intensity', 'target'])['rescue']
                      .mean().unstack().sort_index() * 100.0)
            if piv.empty:
                continue
            fig, ax = plt.subplots(figsize=(8, 5))
            for c in piv.columns:
                ax.plot(piv.index, piv[c], marker='o', label=str(c))
            ax.axhline(0, color='0.35', lw=1.0)
            ax.axvline(0, color='0.6', ls=':', lw=1.1)
            ax.set_xlabel('Injected drift intensity I '
                          '(I=0 is the null control)')
            ax.set_ylabel('Rescue R(I)  [%]')
            ax.set_title(f'Proof of rescue -- {dt}\n'
                         'R>0 repairs drift; R<0 at I=0 means the corrector '
                         'harms when nothing is wrong')
            ax.legend(fontsize=8)
            ax.grid(True, ls='--', alpha=0.6)
            fig.tight_layout()
            fig.savefig(os.path.join(config.OUTPUT_DIR,
                                     f'r17_rescue_curve_{dt}.png'), dpi=200)
            plt.close(fig)
    else:
        print("\n[R17] No rescue rows collected (R17_ENABLE off, or no "
              "drift-labelled test rows in any arm).")

    print(f"Drift stress test complete. 2 plots + drift_stress_results.csv saved in {config.OUTPUT_DIR}")

    if _r22_active:
        config.VALIDATION_CAL_FRACTION = _r22_old_cal
        config.VALIDATION_SAFETY_FRACTION = _r22_old_safe
        config._r22_stress_active = _r22_old_flag
        print(f"[R22] restored ordinary validation roles to calibration="
              f"{_r22_old_cal:.2f}, safety={_r22_old_safe:.2f}.")

    # p_fault selector control can reuse EXACTLY the same regularisation.
    return float(optimal_c)


