# =============================================================================
def _inject_fixed_history_curriculum(df_clean, target_vars, config, seed,
                                     sudden_only=False, active_targets=None,
                                     exclude_magnitude=None):
    """Internal experiment utility."""
    d = df_clean.copy()
    m = pd.DataFrame(False, index=df_clean.index, columns=df_clean.columns)
    n = len(d)
    tr_end = int(n * float(config.TRAIN_SPLIT))
    va_end = int(n * float(config.TRAIN_SPLIT + config.VAL_SPLIT))
    rng = np.random.default_rng(int(seed) + 17041)
    _long = int(getattr(config, 'LONG_WINDOW_SIZE', 72))
    mags = list(getattr(config, 'STUDY_A_HISTORY_MAGNITUDES',
                        (0.5, 1.0, 1.5, 2.0, 2.5, 3.0)))
    if exclude_magnitude is not None:
        _orig_mags = list(mags)
        mags = [x for x in mags if not np.isclose(float(x), float(exclude_magnitude),
                                                   rtol=0.0, atol=1e-12)]
        if not mags:
            mags = _orig_mags
    durs = list(getattr(config, 'STUDY_A_HISTORY_DURATIONS', (8, 12, 18, 24)))
    n_ep = int(getattr(config, 'STUDY_A_HISTORY_EPISODES', 8))

    # Guaranteed, substantial representation in both TRAIN and
    # VALIDATION. The earlier 8-episode design put only two episodes in
    
    n_va = max(4, int(round(0.35 * n_ep)))
    n_tr = max(4, n_ep - n_va)
    maxdur = max(durs)
    tr_lo, tr_hi = min(tr_end - 2, _long + 8), max(_long + 9, tr_end - maxdur - 2)
    va_lo, va_hi = tr_end + 2, max(tr_end + 3, va_end - maxdur - 2)
    starts = []
    if tr_hi > tr_lo:
        starts += list(np.linspace(tr_lo, tr_hi, n_tr, dtype=int))
    if va_hi > va_lo:
        starts += list(np.linspace(va_lo, va_hi, n_va, dtype=int))

    _active = set(active_targets if active_targets is not None else target_vars)
    for j, v in enumerate(target_vars):
        if v not in d.columns or v not in _active:
            continue
        sig = d[v].astype(float).values.copy()
        clean = df_clean[v].astype(float).values
        ref = clean[:tr_end]
        scale = max(float(np.nanstd(ref)), 1e-6)
        meanabs = max(float(np.nanmean(np.abs(ref))), 1e-6)
        for k, st in enumerate(starts):
            dur = int(durs[(k + j) % len(durs)])
            en = min(st + dur, va_end)
            if en - st < 2:
                continue
            mag = float(mags[(k + 2 * j) % len(mags)])
            sgn = -1.0 if ((k + j) % 2) else 1.0
            if sudden_only or (k % 3 != 1):
                sig[st:en] += sgn * mag * scale
            else:
                # Mild gradual examples diversify the safety-study curriculum.
                sig[st:en] += np.linspace(0.0, sgn * 0.15 * mag * meanabs,
                                          en - st)
            m.iloc[st:en, m.columns.get_loc(v)] = True
        d[v] = sig
    return d, m


def _make_study_a_dataset(df, target_vars, config, intensity, sign, seed,
                          active_target):
    clean = df.copy()
    degraded, mask = _inject_fixed_history_curriculum(
        clean, target_vars, config, seed, sudden_only=True,
        active_targets=[active_target], exclude_magnitude=float(intensity))
    n = len(degraded)
    va_end = int(n * float(config.TRAIN_SPLIT + config.VAL_SPLIT))
    test_len = n - va_end
    onset = va_end + max(2, test_len // 2)
    for v in target_vars:
        if v != active_target or v not in degraded.columns:
            continue
        ref = clean[v].astype(float).values[:int(n * float(config.TRAIN_SPLIT))]
        scale = max(float(np.nanstd(ref)), 1e-6)
        arr = degraded[v].astype(float).values.copy()
        arr[onset:] += float(sign) * float(intensity) * scale
        degraded[v] = arr
        mask.iloc[onset:, mask.columns.get_loc(v)] = True
    return degraded, clean, mask, clean.index[onset]


def _summarise_study_a_rows(rows, config, out_dir):
    raw = pd.DataFrame(rows)
    raw.to_csv(os.path.join(out_dir, 'study_a_sudden_rescue_per_seed.csv'), index=False)
    if raw.empty:
        return raw, pd.DataFrame(), {'green': False, 'reason': 'no rows'}
    keys = ['sign', 'intensity', 'target']
    agg = raw.groupby(keys).agg(
        n_seeds=('seed', 'nunique'),
        anchor_mae=('anchor_mae_post1', 'mean'),
        corrected_mae=('corrected_mae_post1', 'mean'),
        xgb_diff_anchor_mae=('xgb_diff_anchor_mae_post1', 'mean'),
        nn_delta_mae=('nn_delta_mae_post1', 'mean'),
        abs_gain_vs_xgb_diff=('abs_gain_vs_xgb_diff_post1', 'mean'),
        pct_gain_vs_xgb_diff=('pct_gain_vs_xgb_diff_post1', 'mean'),
        lightgbm_mae=('lightgbm_mae_post1', 'mean'),
        rescue_mean=('rescue_post1', 'mean'),
        rescue_sd=('rescue_post1', 'std'),
        positive_seeds=('rescue_post1', lambda x: int(np.sum(np.asarray(x) > 0))),
        nominal_penalty_rel_mean=('nominal_penalty_rel', 'mean'),
        detection_delay_mean=('detection_delay_steps', 'mean'),
        post_detection_rescue_mean=('post_detection_rescue', 'mean'),
        max_mae_amplification=('mae_amplification_post1', 'max'),
    ).reset_index()
    ci = (raw.groupby(keys)['rescue_post1']
          .apply(lambda x: pd.Series(
              _student_t_mean_ci(x),
              index=['rescue_t_mean', 'rescue_ci_lo', 'rescue_ci_hi']))
          .unstack()
          .reset_index())
    agg = agg.merge(ci, on=keys, how='left', validate='one_to_one')
    # The groupby mean and CI-helper mean must be identical; keep one public
    # estimate and fail if reporting ever becomes internally inconsistent.
    if not np.allclose(agg['rescue_mean'], agg['rescue_t_mean'],
                       equal_nan=True, rtol=0.0, atol=1e-12):
        raise AssertionError('[STUDY-A] mean/CI sample mismatch')
    agg.drop(columns=['rescue_t_mean'], inplace=True)
    agg['ci_method'] = 'two-sided Student-t, df=n_seeds-1'
    agg['ci_excludes_zero_positive'] = agg['rescue_ci_lo'] > 0
    agg['m2p_improvement_vs_lightgbm'] = (
        1.0 - agg['corrected_mae'] / agg['lightgbm_mae'].replace(0, np.nan))
    agg.to_csv(os.path.join(out_dir, 'study_a_sudden_rescue_summary.csv'), index=False)

    min_i = float(getattr(config, 'STUDY_A_GREEN_MIN_INTENSITY', 2.0))
    max_nom = float(getattr(config, 'STUDY_A_MAX_NOMINAL_PENALTY_REL', 0.02))
    min_frac = float(getattr(config, 'STUDY_A_MIN_POSITIVE_SEED_FRACTION', 0.80))
    min_post = float(getattr(config, 'STUDY_A_MIN_POST_DETECTION_RESCUE', 0.20))
    max_amp = float(getattr(config, 'STUDY_A_MAX_MAE_AMPLIFICATION', 2.0))
    hi = agg[agg['intensity'] >= min_i].copy()
    if hi.empty:
        verdict = {'green': False, 'reason': 'no high-intensity cells'}
    else:
        need_pos = np.ceil(min_frac * hi['n_seeds']).astype(int)
        good = ((hi['positive_seeds'] >= need_pos)
                & hi['ci_excludes_zero_positive']
                & (hi['post_detection_rescue_mean'] >= min_post)
                & (hi['nominal_penalty_rel_mean'] <= max_nom)
                & (hi['max_mae_amplification'] <= max_amp))
        agg.loc[hi.index, 'green_cell'] = good.values
        verdict = dict(
            green=bool(good.all()),
            n_cells=int(len(hi)), n_green_cells=int(good.sum()),
            criterion=(f'intensity>={min_i}, >=ceil({min_frac:.2f}*seeds) positive, '
                       f'95% CI>0, post-detection rescue>={min_post:.2f}, '
                       f'nominal penalty<={max_nom:.3f}, amplification<={max_amp:g}x'))
    agg.to_csv(os.path.join(out_dir, 'study_a_sudden_rescue_summary.csv'), index=False)
    with open(os.path.join(out_dir, 'study_a_verdict.json'), 'w') as fh:
        json.dump(verdict, fh, indent=1)
    return raw, agg, verdict


def run_study_a_sudden_rescue(df_stable, target_vars, master_config, optimal_c,
                              obs_mask=None):
    """Run Study A using the shared M2P-PTAC implementation."""
    if not bool(getattr(master_config, 'RUN_STUDY_A_SUDDEN_RESCUE', True)):
        return None
    print('\n' + '#' * 80)
    print('### STUDY A: CAUSAL SUDDEN-SHIFT RESCUE (ISOLATED) ###')
    print('#' * 80)
    base_out = master_config.OUTPUT_DIR
    out_dir = os.path.join(base_out, 'additional_studies', 'study_A_sudden_rescue')
    os.makedirs(out_dir, exist_ok=True)
    rows = []
    _study_targets = [v for v in getattr(master_config, 'STUDY_A_TARGETS', target_vars)
                      if v in target_vars]
    print(f"[STUDY-A] single-sensor targets: {_study_targets}")
    print("[STUDY-A] leave-one-intensity-out curriculum: the TEST magnitude is removed from historical train/validation episodes for each cell.")
    for seed in list(getattr(master_config, 'STUDY_A_SEEDS', [42, 43, 44, 45, 46])):
        for active_target in _study_targets:
            for sign in list(getattr(master_config, 'STUDY_A_SIGNS', (-1.0, 1.0))):
                for intensity in list(getattr(master_config, 'STUDY_A_INTENSITIES', (1.0, 2.0, 3.0))):
                    c = copy.deepcopy(master_config)
                    c.OUTPUT_DIR = out_dir
                    c._dataset_name = 'study_A_sudden_rescue'
                    c.STUDY_A_ENABLE_JUMP_CONTEXT = True
                    c.R18_TRAIN_TRUTH = False
                    c.R19_T2_DRIFT_RESCUE = True
                    c.R20_UTILITY_GATE = True
                    c.GATE_THRESHOLD = None
                    c.R19_SAFETY_VETO = True
                    c.R19_SAFETY_MAX_NOMINAL_PENALTY_REL = float(
                        getattr(c, 'STUDY_A_MAX_NOMINAL_PENALTY_REL', 0.02))
                    ensure_cadence(df_stable, c, 'study_A_sudden_rescue')
                    set_all_seeds(int(seed))
                    d, clean, mask, onset_ts = _make_study_a_dataset(
                        df_stable, target_vars, c, intensity, sign, seed,
                        active_target)
                    exp = PTACExperiment(
                        f'StudyA_M2P_{_safe_filename(active_target)}_s{int(sign):+d}_I{float(intensity):g}_seed{seed}',
                        c, base_lambda=optimal_c,
                        conformal_alpha=c.DEFAULT_CONFORMAL_ALPHA,
                        eval_truth_df=clean, obs_mask=obs_mask,
                        fault_mask=mask, train_truth_df=None,
                        corrector_target_df=clean, seed=int(seed))
                    exp.run(d, target_vars)
                    
                    # frame.  It receives the ordinary matched drift bank but not
                    # the Study-A jump context, which is intentionally a neural
                    # corrector-only deployment signal.
                    _lgb_exp = TabularExperiment(
                        f'StudyA_LGBM_{_safe_filename(active_target)}_s{int(sign):+d}_I{float(intensity):g}_seed{seed}',
                        c, lgb.LGBMRegressor,
                        {'objective': 'regression_l1', 'n_estimators': 1000,
                         'learning_rate': 0.01, 'random_state': 42, 'verbose': -1},
                        eval_truth_df=clean, obs_mask=obs_mask,
                        target_mode='delta', use_drift_bank=True)
                    _lgb_res, _, _lgb_err = _lgb_exp.run(d, target_vars)
                    arr = getattr(exp, '_r19_arrays', {})
                    if not arr or 'test_index' not in arr:
                        print('    [STUDY-A] missing replay arrays; cell skipped.')
                        continue
                    idx = pd.DatetimeIndex(arr['test_index'])
                    base = np.asarray(arr['test_base'], dtype=float)
                    corr = np.asarray(arr['test_corr'], dtype=float)
                    true = np.asarray(arr['test_true'], dtype=float)
                    pred = base + corr
                    tg = list(arr['targets'])
                    onset_pos = int(np.searchsorted(idx.values, np.datetime64(onset_ts)))
                    onset_pos = min(max(onset_pos, 0), len(idx) - 1)
                    post1 = np.arange(len(idx)) >= min(onset_pos + 1, len(idx))
                    nominal = np.arange(len(idx)) < onset_pos
                    for j, v in enumerate(tg):
                        if v != active_target:
                            continue
                        if post1.sum() < int(getattr(c, 'STUDY_A_MIN_POST_POINTS', 8)):
                            continue
                        eb = np.abs(true[:, j] - base[:, j])
                        ec = np.abs(true[:, j] - pred[:, j])
                        mb = float(np.mean(eb[post1])); mc = float(np.mean(ec[post1]))
                        delta_true = true[:, j] - base[:, j]
                        nn_delta_mae = float(np.mean(
                            np.abs(delta_true[post1] - corr[post1, j])))
                        if not np.isclose(nn_delta_mae, mc, rtol=0.0, atol=1e-12):
                            raise AssertionError(
                                '[STUDY-A] neural-delta MAE does not equal final '
                                'forecast MAE; anchor/correction alignment failed')
                        rescue = (1.0 - mc / mb) if mb > 1e-12 else np.nan
                        # First actual neural intervention after onset is the causal
                        # detection proxy; onset itself cannot use its own residual.
                        acted = np.where((np.arange(len(idx)) >= onset_pos)
                                         & (np.abs(corr[:, j]) > 1e-12))[0]
                        det = int(acted[0]) if acted.size else -1
                        delay = float(det - onset_pos) if det >= 0 else np.nan
                        pd_mask = (np.arange(len(idx)) >= det + 1) if det >= 0 else np.zeros(len(idx), bool)
                        pd_rescue = np.nan
                        if pd_mask.sum() >= int(getattr(c, 'STUDY_A_MIN_POST_POINTS', 8)):
                            b2 = float(np.mean(eb[pd_mask])); c2 = float(np.mean(ec[pd_mask]))
                            pd_rescue = (1.0 - c2 / b2) if b2 > 1e-12 else np.nan
                        nom_b = float(np.mean(eb[nominal])) if nominal.any() else np.nan
                        nom_c = float(np.mean(ec[nominal])) if nominal.any() else np.nan
                        nom_rel = ((nom_c - nom_b) / max(nom_b, 1e-12)
                                   if np.isfinite(nom_b) and np.isfinite(nom_c) else np.nan)
                        _le = np.asarray(_lgb_err.get(v, []), dtype=float).ravel()
                        _lgb_mae = (float(np.mean(np.abs(_le[post1])))
                                     if _le.size == len(idx) and post1.any() else np.nan)
                        rows.append(dict(
                            seed=int(seed), sign=float(sign), intensity=float(intensity),
                            target=v, onset_timestamp=str(onset_ts),
                            anchor_mae_post1=mb, corrected_mae_post1=mc,
                            comparison_anchor=CORRECTOR_ATTRIBUTION_ANCHOR,
                            xgb_diff_anchor_mae_post1=mb,
                            nn_delta_mae_post1=nn_delta_mae,
                            m2p_final_mae_post1=mc,
                            abs_gain_vs_xgb_diff_post1=mb - mc,
                            pct_gain_vs_xgb_diff_post1=(
                                100.0 * (mb - mc) / mb if mb > 1e-12 else np.nan),
                            lightgbm_mae_post1=_lgb_mae,
                            rescue_post1=rescue,
                            mae_amplification_post1=(mc / max(mb, 1e-12)),
                            nominal_penalty_rel=nom_rel,
                            detection_delay_steps=delay,
                            post_detection_rescue=pd_rescue,
                            max_abs_correction=float(np.max(np.abs(corr[:, j]))),
                            safety_pass=bool(getattr(exp, '_r19_safety_mask',
                                                     np.zeros(len(tg), bool))[j])))
    raw, agg, verdict = _summarise_study_a_rows(rows, master_config, out_dir)
    print(f"[STUDY-A] VERDICT: {'GREEN' if verdict.get('green') else 'RED/PARTIAL'} -- {verdict}")
    print(f"[STUDY-A] outputs: {out_dir}")
    return raw, agg, verdict


