# =============================================================================
def _make_study_b_dataset(df, target_vars, config, scenario, seed):
    clean = df.copy()
    degraded, mask = _inject_fixed_history_curriculum(
        clean, target_vars, config, seed, sudden_only=False)
    n = len(degraded)
    tr_end = int(n * float(config.TRAIN_SPLIT))
    va_end = int(n * float(config.TRAIN_SPLIT + config.VAL_SPLIT))
    test_len = n - va_end
    onset = va_end + max(2, test_len // 3)
    rng = np.random.default_rng(int(seed) + 30113)

    def _stress_one(v):
        arr = degraded[v].astype(float).values.copy()
        ref = clean[v].astype(float).values[:tr_end]
        scale = max(float(np.nanstd(ref)), 1e-6)
        meanabs = max(float(np.nanmean(np.abs(ref))), 1e-6)
        hi = float(np.nanpercentile(ref, 99))
        lo = float(np.nanpercentile(ref, 1))
        m = re.match(r'extreme_step_(pos|neg)_(\d+)sigma$', scenario)
        if m:
            sgn = 1.0 if m.group(1) == 'pos' else -1.0
            arr[onset:] += sgn * float(m.group(2)) * scale
        elif scenario.startswith('spike_burst_') and scenario.endswith('sigma'):
            mag = float(re.search(r'(\d+)sigma$', scenario).group(1))
            ids = np.arange(onset, n)
            hit = rng.random(len(ids)) < 0.20
            signs = rng.choice([-1.0, 1.0], size=len(ids))
            arr[ids[hit]] += signs[hit] * mag * scale
        elif scenario == 'stuck_high':
            arr[onset:] = hi
        elif scenario == 'stuck_low':
            arr[onset:] = lo
        elif scenario.startswith('missing_burst_'):
            dur = int(scenario.rsplit('_', 1)[-1])
            en = min(n, onset + dur)
            arr[onset:en] = np.nan
            arr = pd.Series(arr).ffill().bfill().values
        elif scenario == 'compound_step4_missing12':
            arr[onset:] += 4.0 * scale
            en = min(n, onset + 12)
            arr[onset:en] = np.nan
            arr = pd.Series(arr).ffill().bfill().values
        elif scenario == 'compound_step6_spikes':
            arr[onset:] += 6.0 * scale
            ids = np.arange(onset, n)
            hit = rng.random(len(ids)) < 0.15
            signs = rng.choice([-1.0, 1.0], size=len(ids))
            arr[ids[hit]] += signs[hit] * 4.0 * scale
        elif scenario == 'gradual_then_step4':
            ids = np.arange(onset, n)
            split = onset + max(2, len(ids) // 2)
            arr[onset:split] += np.linspace(0.0, 0.20 * meanabs,
                                             max(split - onset, 1))
            arr[split:] += 0.20 * meanabs + 4.0 * scale
        else:
            raise ValueError(f'unknown Study-B scenario: {scenario}')
        return arr

    for v in target_vars:
        if v not in degraded.columns:
            continue
        degraded[v] = _stress_one(v)
        mask.iloc[onset:, mask.columns.get_loc(v)] = True
    return degraded, clean, mask, clean.index[onset]

def _physical_violation_count(arr, targets, limits):
    dfp = pd.DataFrame(np.asarray(arr, dtype=float), columns=targets)
    v = count_physical_violations(dfp, targets, limits)
    return int(v.n_below.sum() + v.n_above.sum()) if len(v) else 0


def _summarise_study_b_rows(raw, config, out_dir):
    """Summarise safety arms without weakening the prevention criterion."""
    raw = pd.DataFrame(raw).copy()
    if raw.empty:
        return pd.DataFrame(), {'green': False, 'reason': 'no rows'}

    def _strict_bool(s, label):
        if pd.api.types.is_bool_dtype(s):
            return s.astype(bool).to_numpy()
        mapped = s.astype(str).str.strip().str.lower().map(
            {'true': True, 'false': False, '1': True, '0': False})
        if mapped.isna().any():
            bad = sorted(s[mapped.isna()].astype(str).unique().tolist())
            raise ValueError(f'[STUDY-B] invalid {label} values: {bad[:5]}')
        return mapped.astype(bool).to_numpy()

    raw['catastrophic'] = _strict_bool(raw['catastrophic'], 'catastrophic')

    summary = raw.groupby(['scenario', 'arm']).agg(
        n_cells=('catastrophic', 'size'),
        catastrophic_events=('catastrophic', 'sum'),
        catastrophic_rate=('catastrophic', 'mean'),
        mean_mae_amplification_pre_guard=('mae_amplification_pre_guard', 'mean'),
        worst_mae_amplification_pre_guard=('mae_amplification_pre_guard', 'max'),
        mean_mae_amplification=('mae_amplification', 'mean'),
        worst_mae_amplification=('mae_amplification', 'max'),
        physical_violations_pre_guard=('physical_violations_pre_guard', 'sum'),
        physical_violations_final=('physical_violations_final', 'sum'),
    ).reset_index()
    summary.to_csv(os.path.join(out_dir, 'study_b_safety_stress_summary.csv'),
                   index=False)

    keys = ['seed', 'scenario', 'target']
    unp = (raw.loc[raw.arm == 'C_unprotected', keys + ['catastrophic']]
           .rename(columns={'catastrophic': 'unprotected_catastrophic'}))
    fin = (raw.loc[raw.arm == 'C_final',
                   keys + ['catastrophic', 'physical_violations_final']]
           .rename(columns={'catastrophic': 'final_catastrophic'}))
    paired = unp.merge(fin, on=keys, how='inner', validate='one_to_one')
    if len(paired) != len(unp) or len(paired) != len(fin):
        raise AssertionError(
            '[STUDY-B] unprotected/final cells are not exactly paired')

    u = _strict_bool(paired['unprotected_catastrophic'], 'unprotected event')
    f = _strict_bool(paired['final_catastrophic'], 'final event')
    effect = _paired_binary_effect(u, f)
    effect['absolute_rate_reduction_percentage_points'] = (
        100.0 * effect['absolute_rate_reduction'])
    effect['relative_rate_reduction_percent'] = (
        100.0 * effect['relative_rate_reduction']
        if np.isfinite(effect['relative_rate_reduction']) else np.nan)
    effect['comparison'] = 'C_unprotected vs C_final (paired cells)'
    effect['uncertainty'] = (
        'paired row bootstrap 95% CI; exact McNemar test on discordant pairs')
    pd.DataFrame([effect]).to_csv(
        os.path.join(out_dir, 'study_b_overall_risk_reduction.csv'), index=False)

    n_unp = int(np.sum(u))
    n_fin = int(np.sum(f))
    fin_phys = int(pd.to_numeric(
        paired['physical_violations_final'], errors='raise').sum())
    cat_thr = float(getattr(config, 'STUDY_B_CATASTROPHIC_MAE_RATIO', 2.0))
    verdict = dict(
        green=bool(n_unp > 0 and n_fin == 0 and fin_phys == 0),
        catastrophic_threshold=cat_thr,
        unprotected_catastrophic_events=n_unp,
        final_catastrophic_events=n_fin,
        final_physical_violations=fin_phys,
        **effect,
        interpretation=(
            'prevention demonstrated' if n_unp > 0 and n_fin == 0 and fin_phys == 0
            else ('risk reduced, but zero-event prevention not demonstrated'
                  if n_fin < n_unp else 'no catastrophic-risk reduction')),
        criterion=('GREEN only if the prespecified unprotected control actually '
                   'exhibits >=1 catastrophic event and the final stack exhibits '
                   'none; effect sizes are reported separately and do not alter '
                   'this prevention criterion.'))
    with open(os.path.join(out_dir, 'study_b_verdict.json'), 'w') as fh:
        json.dump(verdict, fh, indent=1)
    return summary, verdict


def run_study_b_safety_stress(df_stable, target_vars, master_config, optimal_c,
                              obs_mask=None):
    """Run Study B using the shared M2P-PTAC implementation."""
    if not bool(getattr(master_config, 'RUN_STUDY_B_SAFETY_STRESS', True)):
        return None
    print('\n' + '#' * 80)
    print('### STUDY B: PRESPECIFIED OOD SAFETY STRESS (ISOLATED) ###')
    print('#' * 80)
    out_dir = os.path.join(master_config.OUTPUT_DIR, 'additional_studies',
                           'study_B_safety_stress')
    os.makedirs(out_dir, exist_ok=True)
    rows = []
    scenarios = list(getattr(master_config, 'STUDY_B_SCENARIOS', ()))
    seeds = list(getattr(master_config, 'STUDY_B_SEEDS', [42, 43, 44, 45, 46]))
    cat_thr = float(getattr(master_config, 'STUDY_B_CATASTROPHIC_MAE_RATIO', 2.0))

    for seed in seeds:
        for scen in scenarios:
            base_cfg = copy.deepcopy(master_config)
            base_cfg.OUTPUT_DIR = out_dir
            base_cfg._dataset_name = 'study_B_safety_stress'
            ensure_cadence(df_stable, base_cfg, 'study_B_safety_stress')
            d, clean, mask, onset_ts = _make_study_b_dataset(
                df_stable, target_vars, base_cfg, scen, seed)

            arm_specs = [
                ('C_unprotected', dict(STUDY_B_DISABLE_TANH_BOUND=True,
                                       USE_FAULT_GATING=False,
                                       R19_SAFETY_VETO=False,
                                       GATE_THRESHOLD=None,
                                       LAMBDA_PARITY=0.0)),
                ('C_bounded_only', dict(STUDY_B_DISABLE_TANH_BOUND=False,
                                        USE_FAULT_GATING=False,
                                        R19_SAFETY_VETO=False,
                                        GATE_THRESHOLD=None,
                                        LAMBDA_PARITY=0.0)),
                ('C_gated_no_veto', dict(STUDY_B_DISABLE_TANH_BOUND=False,
                                         USE_FAULT_GATING=True,
                                         R20_UTILITY_GATE=True,
                                         R19_SAFETY_VETO=False,
                                         GATE_THRESHOLD=None,
                                         LAMBDA_PARITY=0.0)),
                ('C_final', dict(STUDY_B_DISABLE_TANH_BOUND=False,
                                 USE_FAULT_GATING=True,
                                 R20_UTILITY_GATE=True,
                                 GATE_THRESHOLD=None,
                                 R19_SAFETY_VETO=True)),
            ]
            _anchor_written = False
            _anchor_ref = None
            for arm, changes in arm_specs:
                c = copy.deepcopy(base_cfg)
                for k, val in changes.items():
                    setattr(c, k, val)
                set_all_seeds(int(seed))
                exp = PTACExperiment(
                    f'StudyB_{arm}_{scen}_seed{seed}', c,
                    base_lambda=optimal_c, conformal_alpha=None,
                    eval_truth_df=clean, obs_mask=obs_mask,
                    fault_mask=mask, train_truth_df=None,
                    corrector_target_df=clean, seed=int(seed),
                    gate_threshold=(None if arm != 'C_final' else 'inherit'))
                exp.run(d, target_vars)
                arr = getattr(exp, '_r19_arrays', {})
                if not arr or 'test_index' not in arr:
                    continue
                idx = pd.DatetimeIndex(arr['test_index'])
                base = np.asarray(arr['test_base'], dtype=float)
                if _anchor_ref is None:
                    _anchor_ref = base.copy()
                else:
                    _ad = float(np.max(np.abs(base - _anchor_ref)))
                    assert _ad < 1e-12, (
                        f'[STUDY-B] anchor moved across safety arms (max |d|={_ad}). '
                        'The safety comparison would not be attributable.')
                corr = np.asarray(arr['test_corr'], dtype=float)
                true = np.asarray(arr['test_true'], dtype=float)
                tg = list(arr['targets'])
                raw_pred = base + corr
                # The ordinary harness only reports what a physical guard WOULD
                # do. Study B explicitly evaluates the full final safety stack,
                # so the final arm applies the same prespecified limits here.
                if arm == 'C_final':
                    pred = apply_physical_guard(
                        pd.DataFrame(raw_pred, columns=tg), tg,
                        getattr(c, 'PHYSICAL_LIMITS', {})).values
                else:
                    pred = raw_pred
                onset_pos = int(np.searchsorted(idx.values, np.datetime64(onset_ts)))
                footprint = np.arange(len(idx)) >= onset_pos
                for j, v in enumerate(tg):
                    eb = np.abs(true[:, j] - base[:, j])
                    eraw = np.abs(true[:, j] - raw_pred[:, j])
                    ec = np.abs(true[:, j] - pred[:, j])
                    mb = float(np.mean(eb[footprint]))
                    mc_raw = float(np.mean(eraw[footprint]))
                    mc = float(np.mean(ec[footprint]))
                    amp_raw = mc_raw / max(mb, 1e-12)
                    amp = mc / max(mb, 1e-12)
                    if not _anchor_written:
                        rows.append(dict(
                            seed=int(seed), scenario=scen, arm='B_anchor', target=v,
                            onset_timestamp=str(onset_ts), anchor_mae=mb,
                            comparison_anchor=CORRECTOR_ATTRIBUTION_ANCHOR,
                            xgb_diff_anchor_mae=mb,
                            arm_mae_pre_guard=mb, arm_mae=mb,
                            mae_amplification_pre_guard=1.0,
                            mae_amplification=1.0, catastrophic=False,
                            max_abs_correction=0.0,
                            physical_violations_pre_guard=_physical_violation_count(
                                base[:, [j]], [v], getattr(c, 'PHYSICAL_LIMITS', {})),
                            physical_violations_final=_physical_violation_count(
                                base[:, [j]], [v], getattr(c, 'PHYSICAL_LIMITS', {}))))
                    rows.append(dict(
                        seed=int(seed), scenario=scen, arm=arm, target=v,
                        onset_timestamp=str(onset_ts), anchor_mae=mb,
                        comparison_anchor=CORRECTOR_ATTRIBUTION_ANCHOR,
                        xgb_diff_anchor_mae=mb,
                        arm_mae_pre_guard=mc_raw, arm_mae=mc,
                        mae_amplification_pre_guard=amp_raw,
                        mae_amplification=amp,
                        catastrophic=bool(amp > cat_thr),
                        max_abs_correction=float(np.max(np.abs(corr[:, j]))),
                        physical_violations_pre_guard=_physical_violation_count(
                            raw_pred[:, [j]], [v], getattr(c, 'PHYSICAL_LIMITS', {})),
                        physical_violations_final=_physical_violation_count(
                            pred[:, [j]], [v], getattr(c, 'PHYSICAL_LIMITS', {})),
                    ))
                _anchor_written = True
    raw = pd.DataFrame(rows)
    raw.to_csv(os.path.join(out_dir, 'study_b_safety_stress_per_seed.csv'), index=False)
    summary, verdict = _summarise_study_b_rows(raw, master_config, out_dir)
    print(f"[STUDY-B] VERDICT: {'GREEN' if verdict.get('green') else 'RED/UNPROVEN'} -- {verdict}")
    print(f"[STUDY-B] outputs: {out_dir}")
    return raw, summary, verdict


