# =============================================================================
def run_study_c_active_ablations(df_stable, target_vars, master_config, optimal_c,
                                 obs_mask=None):
    """Run four-target, post-veto Study C with matched-anchor attribution."""
    if not bool(getattr(master_config, 'RUN_STUDY_C_ACTIVE_ABLATIONS', True)):
        return None
    print('\n' + '#' * 80)
    print('### STUDY C: ACTIVE-REGIME ARCHITECTURAL ABLATIONS ###')
    print('#' * 80)
    out_dir = os.path.join(master_config.OUTPUT_DIR, 'additional_studies',
                           'study_C_active_ablations_v2')
    os.makedirs(out_dir, exist_ok=True)
    rows = []
    seeds = list(getattr(master_config, 'STUDY_C_SEEDS', [42,43,44,45,46]))
    intensities = list(getattr(master_config, 'STUDY_C_INTENSITIES', (0.10,0.15,0.20,0.25)))
    claim_targets = [v for v in getattr(master_config, 'STUDY_C_TARGETS', target_vars)
                     if v in target_vars]
    variants = list(getattr(master_config, 'STUDY_C_VARIANTS',
                            ('Full','No Attention','No CNN','Unified Encoder',
                             'Ordinary Residual Target')))
    for seed in seeds:
        for intensity in intensities:
            base_cfg = copy.deepcopy(master_config)
            base_cfg.OUTPUT_DIR = out_dir
            base_cfg._dataset_name = 'study_C_active_ablations'
            base_cfg.GATE_THRESHOLD = None
            base_cfg.STUDY_A_ENABLE_JUMP_CONTEXT = False
            base_cfg.R20_UTILITY_GATE = True
            ensure_cadence(df_stable, base_cfg, 'study_C_active_ablations')
            set_all_seeds(int(seed))
            inj = SyntheticDriftInjector(base_cfg)
            degraded, clean = inj.apply_drift(
                df_stable, 'gradual_bias', float(intensity), target_vars,
                history_episodes=int(getattr(base_cfg, 'R18_HISTORY_EPISODES', 8)),
                history_seed=int(seed) + 9001,
                history_intensity=float(dict(getattr(
                    base_cfg, 'R18_FIXED_HISTORY_INTENSITY', {}) or {})
                    .get('gradual_bias', 0.15)))
            mask = inj.last_drift_mask.copy()
            for variant in variants:
                c = copy.deepcopy(base_cfg)
                use_att, use_cnn, unified = True, True, False
                t2 = True
                if variant == 'No Attention':
                    use_att = False
                elif variant == 'No CNN':
                    use_cnn = False
                elif variant == 'Unified Encoder':
                    unified = True
                elif variant == 'Ordinary Residual Target':
                    t2 = False
                elif variant != 'Full':
                    continue
                set_all_seeds(int(seed))
                exp = PTACExperiment(
                    f'StudyC_{_safe_filename(variant)}_I{float(intensity):g}_seed{seed}',
                    c, base_lambda=optimal_c, unified_encoder=unified,
                    use_attention=use_att, use_cnn=use_cnn,
                    conformal_alpha=c.DEFAULT_CONFORMAL_ALPHA,
                    eval_truth_df=clean, obs_mask=obs_mask,
                    fault_mask=mask, train_truth_df=None,
                    corrector_target_df=(clean if t2 else None), seed=int(seed),
                    gate_threshold=None)
                exp.run(degraded, target_vars)
                arr = getattr(exp, '_r19_arrays', {})
                if not arr or 'test_index' not in arr:
                    continue
                idx = pd.DatetimeIndex(arr['test_index'])
                base = np.asarray(arr['test_base'], dtype=float)
                corr = np.asarray(arr['test_corr'], dtype=float)
                true = np.asarray(arr['test_true'], dtype=float)
                tg = list(arr['targets'])
                mm = mask.reindex(index=idx, columns=tg).fillna(False).values.astype(bool)
                om = (obs_mask.reindex(index=idx, columns=tg).fillna(False)
                      .values.astype(bool) if obs_mask is not None
                      else np.ones_like(mm, dtype=bool))
                gate = np.asarray(arr.get('gate_mask', np.ones(len(tg), bool)),
                                  dtype=bool)
                if gate.size != len(tg):
                    raise AssertionError('[STUDY-C] gate/target width mismatch')
                if (~gate).any() and not np.allclose(
                        corr[:, ~gate], 0.0, rtol=0.0, atol=1e-12):
                    raise AssertionError(
                        '[STUDY-C] a vetoed target retained a nonzero correction')
                pred = base + corr
                delta_true = true - base
                for j, v in enumerate(tg):
                    if v not in claim_targets:
                        continue
                    finite = (np.isfinite(true[:, j]) & np.isfinite(base[:, j])
                              & np.isfinite(corr[:, j]))
                    overall = om[:, j] & finite
                    d = mm[:, j] & overall
                    nominal = (~mm[:, j]) & overall
                    if not d.any():
                        continue
                    mb = float(np.mean(np.abs(true[d, j] - base[d, j])))
                    mc = float(np.mean(np.abs(true[d, j] - pred[d, j])))
                    nn_delta_mae = float(np.mean(
                        np.abs(delta_true[d, j] - corr[d, j])))
                    if not np.isclose(nn_delta_mae, mc, rtol=0.0, atol=1e-12):
                        raise AssertionError(
                            '[STUDY-C] neural-delta/final MAE identity failed')
                    rescue = 1.0 - mc / max(mb, 1e-12)
                    nom_b = (float(np.mean(np.abs(true[nominal, j]
                                                  - base[nominal, j])))
                             if nominal.any() else np.nan)
                    nom_c = (float(np.mean(np.abs(true[nominal, j]
                                                  - pred[nominal, j])))
                             if nominal.any() else np.nan)
                    all_b = float(np.mean(np.abs(true[overall, j]
                                                 - base[overall, j])))
                    all_c = float(np.mean(np.abs(true[overall, j]
                                                 - pred[overall, j])))
                    rows.append(dict(seed=int(seed), intensity=float(intensity),
                                     target=v, variant=variant,
                                     comparison_anchor=CORRECTOR_ATTRIBUTION_ANCHOR,
                                     anchor_mae=mb, corrected_mae=mc,
                                     xgb_diff_anchor_mae=mb,
                                     nn_delta_mae=nn_delta_mae,
                                     m2p_final_mae=mc,
                                     abs_gain_vs_xgb_diff=mb - mc,
                                     pct_gain_vs_xgb_diff=(
                                         100.0 * (mb - mc) / mb
                                         if mb > 1e-12 else np.nan),
                                     rescue=rescue,
                                     nominal_anchor_mae=nom_b,
                                     nominal_final_mae=nom_c,
                                     nominal_penalty_rel=(
                                         (nom_c - nom_b) / nom_b
                                         if np.isfinite(nom_b) and nom_b > 1e-12
                                         else np.nan),
                                     overall_anchor_mae=all_b,
                                     overall_final_mae=all_c,
                                     overall_abs_gain=all_b - all_c,
                                     overall_pct_gain=(
                                         100.0 * (all_b - all_c) / all_b
                                         if all_b > 1e-12 else np.nan),
                                     n_drift_observed=int(d.sum()),
                                     n_nominal_observed=int(nominal.sum()),
                                     n_overall_observed=int(overall.sum()),
                                     max_abs_correction=float(np.max(np.abs(corr[:, j]))),
                                     gate_applied=bool(gate[j]),
                                     metric_output='post_veto',
                                     safety_pass=bool(getattr(exp, '_r19_safety_mask',
                                                              np.zeros(len(tg), bool))[j])))
    raw = pd.DataFrame(rows)
    expected_rows = (len(seeds) * len(intensities) * len(variants)
                     * len(claim_targets))
    key_cols = ['seed', 'intensity', 'variant', 'target']
    if len(raw) != expected_rows or (not raw.empty and raw.duplicated(key_cols).any()):
        raise AssertionError(
            f'[STUDY-C] expected exactly {expected_rows} unique rows '
            f'({len(claim_targets)} targets), got {len(raw)}')
    raw.to_csv(os.path.join(out_dir, 'study_c_active_ablations_per_seed.csv'), index=False)
    if raw.empty:
        return raw, pd.DataFrame(), pd.DataFrame()
    group_keys = ['variant','intensity','target']
    summary = raw.groupby(group_keys).agg(
        n_seeds=('seed','nunique'), rescue_mean=('rescue','mean'),
        rescue_sd=('rescue','std'), positive_seeds=('rescue', lambda x: int(np.sum(np.asarray(x)>0))),
        anchor_mae=('anchor_mae','mean'), corrected_mae=('corrected_mae','mean'),
        nn_delta_mae=('nn_delta_mae','mean'),
        abs_gain_vs_xgb_diff=('abs_gain_vs_xgb_diff','mean'),
        pct_gain_vs_xgb_diff=('pct_gain_vs_xgb_diff','mean'),
        nominal_anchor_mae=('nominal_anchor_mae','mean'),
        nominal_final_mae=('nominal_final_mae','mean'),
        nominal_penalty_rel=('nominal_penalty_rel','mean'),
        overall_anchor_mae=('overall_anchor_mae','mean'),
        overall_final_mae=('overall_final_mae','mean'),
        overall_abs_gain=('overall_abs_gain','mean'),
        overall_pct_gain=('overall_pct_gain','mean'),
        gate_applied_rate=('gate_applied','mean'),
        safety_pass_rate=('safety_pass','mean')).reset_index()
    ci = (raw.groupby(group_keys)['rescue']
          .apply(lambda x: pd.Series(
              _student_t_mean_ci(x),
              index=['rescue_t_mean', 'rescue_ci_lo', 'rescue_ci_hi']))
          .unstack().reset_index())
    summary = summary.merge(ci, on=group_keys, how='left', validate='one_to_one')
    if not np.allclose(summary['rescue_mean'], summary['rescue_t_mean'],
                       equal_nan=True, rtol=0.0, atol=1e-12):
        raise AssertionError('[STUDY-C] mean/CI sample mismatch')
    summary.drop(columns=['rescue_t_mean'], inplace=True)
    summary['ci_method'] = 'two-sided Student-t, df=n_seeds-1'
    summary.to_csv(os.path.join(out_dir, 'study_c_active_ablations_summary.csv'), index=False)

    piv = raw.pivot_table(index=['seed','intensity','target'], columns='variant',
                          values='rescue', aggfunc='first')
    comp_rows = []
    if 'Full' in piv.columns:
        for variant in [c for c in piv.columns if c != 'Full']:
            z = (piv['Full'] - piv[variant]).dropna().rename('delta')
            zz = z.reset_index()
            for (ii, tt), g in zz.groupby(['intensity','target']):
                a = g['delta'].values.astype(float)
                n = len(a)
                mu, ci_lo, ci_hi = _student_t_mean_ci(a)
                comp_rows.append(dict(variant=variant, intensity=float(ii), target=tt,
                                      n_seeds=n, full_minus_variant_rescue=mu,
                                      ci_lo=ci_lo, ci_hi=ci_hi,
                                      ci_method='paired two-sided Student-t, df=n_seeds-1',
                                      full_better_seeds=int(np.sum(a>0))))
    comp = pd.DataFrame(comp_rows)
    comp.to_csv(os.path.join(out_dir, 'study_c_full_vs_ablation.csv'), index=False)
    print(f"[STUDY-C] outputs: {out_dir}")
    return raw, summary, comp


def generate_manuscript_assets(config, results_df, timings_df, df_stable,
                               target_vars, dataset_name=None):
    print("\n" + "#"*80 + "\n### GENERATING ASSETS FOR CONTRIBUTIONS 2 & 3 (PARETO & ATTENTION) ###\n" + "#"*80)
    # PATCH-A4: which testbed these assets belong to is now load-bearing (it
    # selects the context spec), so take it explicitly rather than inferring it
    # from whatever ensure_cadence() last stamped on the shared config object.
    _asset_ds = str(dataset_name or getattr(config, '_dataset_name', None)
                    or 'stable')
    print(f">>> assets for dataset '{_asset_ds}'")

    print(">>> Generating Pareto Frontier (Accuracy vs Complexity) for EC...")
    if results_df is not None and timings_df is not None:
        try:
            plt.figure(figsize=(10, 6))
            combined = pd.concat([results_df, timings_df], axis=1)
            y_col = next((c for c in combined.columns if 'MAE' in c and 'electric conductivity' in c and 'CI' not in c), None)
            x_col = 'Forecast Time (s)'

            if y_col and x_col in combined.columns:
                combined[y_col] = pd.to_numeric(combined[y_col], errors='coerce')
                combined[x_col] = pd.to_numeric(combined[x_col], errors='coerce')
                sns.scatterplot(data=combined, x=x_col, y=y_col, s=150, hue=combined.index, style=combined.index)
                for i in range(combined.shape[0]):
                    if not np.isnan(combined[x_col].iloc[i]) and not np.isnan(combined[y_col].iloc[i]):
                        plt.text(combined[x_col].iloc[i], combined[y_col].iloc[i], "  " + str(combined.index[i]), fontsize=8, va='center')
                plt.xscale('log')
                plt.title('Pareto Frontier: Robustness vs. Inference Latency (EC)')
                plt.xlabel('Inference Time (seconds) [Log Scale]')
                plt.ylabel('MAE: Electric Conductivity (Lower is Better)')
                plt.grid(True, which="both", ls="--", alpha=0.5)
                plt.legend(bbox_to_anchor=(1.05, 1), loc='upper left')
                plt.tight_layout()
                plt.savefig(os.path.join(config.OUTPUT_DIR, "pareto_frontier_ec.png"))
                plt.close()
                print("Pareto frontier (EC) saved.")
        except Exception as e:
            print(f"Error generating Pareto plot: {e}")

    print(">>> Generating Attention Maps...")
    try:
        # FINAL RR: prefer scores exported from the LIVE selected graph. This is
        # exact by construction and bypasses checkpoint/spec reconstruction.
        _live_selected = None
        try:
            _cand = [str(i) for i in results_df.index
                     if str(i).startswith('M2P-PTAC (C=')]
            if _cand:
                if '_val_MAE_for_selection' in results_df.columns:
                    _vv = pd.to_numeric(results_df.loc[_cand, '_val_MAE_for_selection'],
                                        errors='coerce')
                    _sel_arm = str(_vv.idxmin()) if _vv.notna().any() else _cand[0]
                else:
                    _sel_arm = _cand[0]
                _live_selected = os.path.join(
                    config.OUTPUT_DIR,
                    f'attention_scores_live_{_safe_filename(_asset_ds)}__{_safe_filename(_sel_arm)}.npz')
            if _live_selected and os.path.exists(_live_selected):
                _z = np.load(_live_selected, allow_pickle=False)
                _scores = np.asarray(_z['scores'], dtype=float)
                if _scores.ndim != 4:
                    raise ValueError(f'unexpected attention score shape {_scores.shape}')
                # Average across scored samples and heads, preserving query x key.
                map_data = _scores.mean(axis=(0, 1))
                plt.figure(figsize=(11, 8))
                sns.heatmap(map_data, cmap='viridis',
                            cbar_kws={'label': 'Mean attention probability'})
                plt.title('M2P-PTAC Temporal Attention Scores (live trained graph)',
                          fontsize=15, fontweight='bold')
                plt.xlabel('Key / attended timestep', fontsize=12)
                plt.ylabel('Query timestep', fontsize=12)
                plt.tight_layout()
                plt.savefig(os.path.join(config.OUTPUT_DIR,
                                         'attention_map_stable_ec.png'), dpi=300)
                plt.close()
                print(f"    [ATTN-LIVE] manuscript map generated directly from "
                      f"{os.path.basename(_live_selected)}; checkpoint reload skipped.")
                return
        except Exception as _le:
            print(f"    [ATTN-LIVE] selected live-score map unavailable "
                  f"({type(_le).__name__}: {_le}); falling back to exact checkpoint reconstruction.")
        tf.keras.backend.clear_session()
        df_sample = df_stable.copy()
        X_tab, _ = create_tabular_features(df_sample, target_vars,
                                           config=config)   # R16-A/C
        df_sample['hour_sin'] = np.sin(2 * np.pi * df_sample.index.hour / 24.0)
        df_sample['hour_cos'] = np.cos(2 * np.pi * df_sample.index.hour / 24.0)

        scaler = MinMaxScaler().fit(df_sample[target_vars])
        df_scaled = pd.DataFrame(scaler.transform(df_sample[target_vars]), columns=target_vars, index=df_sample.index)
        df_scaled[['hour_sin', 'hour_cos']] = df_sample[['hour_sin', 'hour_cos']]

        feats, indices = create_m2p_features(df_scaled, target_vars, ['hour_sin', 'hour_cos'], config)
        s = pd.DataFrame([r.flatten() for r in feats['short_term_input']]).values
        l = pd.DataFrame([r.flatten() for r in feats['long_term_input']]).values
        X_seq = np.concatenate([s, l], axis=1)

        _aw = int(getattr(config, '_steps_per_day', 24))
        if _aw <= 1:
            _aw = max(_roll_windows_of(config))
        context_cols = [c for c in X_tab.columns
                        if f'_roll_mean_{_aw}' in c or f'_roll_std_{_aw}' in c]
        if not context_cols:
            _aw2 = max(_roll_windows_of(config))
            context_cols = [c for c in X_tab.columns
                            if f'_roll_mean_{_aw2}' in c or f'_roll_std_{_aw2}' in c]
        # F3: create_tabular_features() ends with .dropna(), which removes the
        # rolling/lag warm-up rows; create_m2p_features() instead starts its
        # windows at LONG_WINDOW_SIZE and returns EVERY index from there on.
        # The two index sets therefore differ, and .loc[indices] raised
        # KeyError: "[Timestamp('2025-06-18 16:00:00+0000', tz='UTC'), ...] not
        # in index" -- which the broad handler turned into "Could not generate
        # attention map", so the figure was never produced in the last run.
        # Intersect on the shared index (order preserved) and subset the
        # sequence tensors to match, so the three arrays stay row-aligned.
        _idx = pd.DatetimeIndex(indices)
        _keep = _idx.isin(X_tab.index)
        if _keep.sum() < 8:
            print(f"    [F3] SKIPPING attention map: only {int(_keep.sum())} rows "
                  f"survive the tabular/sequence index intersection "
                  f"({len(_idx)} sequence rows, {len(X_tab.index)} tabular rows).")
            return
        if not _keep.all():
            print(f"    [F3] attention map: dropped {int((~_keep).sum())} of "
                  f"{len(_idx)} sequence rows absent from the dropna'd tabular "
                  f"frame (feature warm-up); {int(_keep.sum())} aligned rows kept.")
        _idx = _idx[_keep]
        X_seq = X_seq[_keep]

        # ---------------------------------------------------------- PATCH-F15
        # LATENT DIMENSION BUG. The line below used to be
        #     X_ctx = X_tab.loc[_idx, context_cols].values
        # with context_cols holding ONLY the rolling mean/std pair. The trunk
        # was trained on a much wider block: PTACExperiment.run() appends the
        # sensor-health bank and the R17 causal drift bank before fitting, and
        # this run logged
        #     [R16-A/C] context input: 111 columns (78 rolling @ w=24, 33 health)
        #     [R17] drift bank: +68 causal context columns
        # i.e. 10 rolling + 33 health + 68 drift = 111. The export therefore
        # built a 10-column context and a context_dim=10 graph.
        #
        # Verified consequence, measured on the real checkpoint: an exact
        # load_weights() raises
        #     Shape mismatch in layer #5 (named glu_linear) for weight
        #     glu_linear/kernel. Weight expects shape (360, 360). Received
        #     saved weight with shape (463, 463)
        # and PATCH-F4's by_name/skip_mismatch fallback then swallows it and
        # returns NORMALLY, leaving 19 of 23 weighted layers -- including
        # multi_head_attention, the bidirectional encoder, the GRU, both GLU
        # fusion gates and every per-channel head -- at RANDOM INITIALISATION.
        # The figure would render an untrained attention map that looks
        
        # than the crash PATCH-F4 fixed, because nothing in the output says so.
        #
        # Fix: rebuild the context from the spec the run persists (F15), in the
        # SAME column order, with the SAME train-fitted standardiser. The spec
        # is authoritative; guessing the layout is what produced the bug.
        # ------------------------------------------------------------- PATCH-A4
        # RESOLVE THE CHECKPOINT FIRST, THEN ITS PAIRED SPEC.
        #
        
        # went looking for a .h5. Both files are overwritten by every arm of
        # every testbed, so the pair was never verified: in the r3 run the
        # surviving spec held 95 columns (the stable testbed's layout, turbidity
        # included) while the log recorded writes of 111. A spec from arm A with
        # weights from arm B satisfies the width assertion below whenever the
        # widths coincide, and then the figure is drawn from a context the
        # checkpoint never saw.
        #
        # PATCH-A5 writes a manifest beside each checkpoint naming the arm and
        # its spec file. Resolution order: manifest-named spec (verified pair)
        # -> per-dataset spec -> refuse. The generic filename is no longer read:
        # it cannot be attributed to any arm.
        _ds_name = _asset_ds
        # PATCH-A5b: the REPORTED stem is written once by the reporting block
        # from the validation-selected arm and is never overwritten, so it is
        # preferred over every other name. The rest are kept as fallbacks and
        # each announces the arm it turns out to hold.
        _stems = (f"model_ptac_{_ds_name}__REPORTED",
                  "model_ptac_stable_final", f"model_ptac_{_ds_name}",
                  "model_ptac_stable", "model_ptac")
        weight_path = next(
            (p for p in (os.path.join(config.OUTPUT_DIR, s + ".h5")
                         for s in _stems) if os.path.exists(p)), None)
        if weight_path is None:
            print("    [F4] SKIPPING attention map: no .h5 checkpoint in "
                  f"{config.OUTPUT_DIR} (looked for {[s + '.h5' for s in _stems]}).")
            return
        _man_path = re.sub(r'\.h5$', '.manifest.json', weight_path)
        _spec_path, _paired = None, False
        _man = {}
        if os.path.exists(_man_path):
            try:
                with open(_man_path) as _mf:
                    _man = json.load(_mf)
                _cand = os.path.join(config.OUTPUT_DIR,
                                     str(_man.get('context_spec', '')))
                if os.path.exists(_cand):
                    _spec_path, _paired = _cand, True
                    print(f"    [A4] checkpoint {os.path.basename(weight_path)} "
                          f"-> arm '{_man.get('model_name')}' on dataset "
                          f"'{_man.get('dataset_name')}'; using its paired spec "
                          f"{os.path.basename(_cand)}.")
                else:
                    print(f"    [A4] manifest names {_man.get('context_spec')!r} "
                          f"but that file is absent; falling back to the "
                          f"per-dataset spec.")
            except Exception as _mex:
                print(f"    [A4] manifest unreadable ({type(_mex).__name__}: "
                      f"{_mex}); falling back to the per-dataset spec.")
        if _spec_path is None:
            _cand = os.path.join(config.OUTPUT_DIR,
                                 f'context_spec_{_ds_name}.json')
            if os.path.exists(_cand):
                _spec_path = _cand
                print(f"    [A4] using per-dataset spec "
                      f"{os.path.basename(_cand)} (arm not verified against "
                      f"the checkpoint).")
        if _spec_path is None:
            print(f"    [F15] SKIPPING attention map: no context spec for "
                  f"dataset '{_ds_name}' in {config.OUTPUT_DIR}, so the "
                  f"{len(context_cols)}-column context rebuilt here cannot be "
                  f"shown to match what the checkpoint was trained on. Re-run "
                  f"training to emit the spec; plotting an unverifiable "
                  f"context would risk an untrained figure.")
            return
        with open(_spec_path) as _fh:
            _spec = json.load(_fh)
        # A spec that names a DIFFERENT dataset is the collision this patch
        # exists to prevent. Refuse rather than rebuild from it.
        _spec_ds = str(_spec.get('dataset_name', '') or '')
        if _spec_ds and _spec_ds != _ds_name:
            print(f"    [A4] SKIPPING attention map: spec "
                  f"{os.path.basename(_spec_path)} was written for dataset "
                  f"'{_spec_ds}' but assets are being generated for "
                  f"'{_ds_name}'. Refusing to rebuild a context from another "
                  f"testbed's layout.")
            return
        _want = [str(c) for c in _spec['context_cols']]
        _missing = [c for c in _want if c not in X_tab.columns]
        if _missing:
            # The drift bank is built inside run() from the raw frame, not by
            # create_tabular_features, so rebuild it here the same way.
            # PATCH-A1: via the SHARED builder, with the same train fraction the
            # experiment used, so the imputation and constant-column filter match
            # what the checkpoint was trained on instead of approximating it.
            try:
                _tr_end = max(2, int(len(X_tab) * float(config.TRAIN_SPLIT)))
                _bank = attach_drift_bank_block(
                    df_sample, target_vars, config, X_tab.index, _tr_end,
                    tag=f"assets:{_ds_name}")
            except Exception as _be:
                print(f"    [A1] drift-bank rebuild for the attention map "
                      f"failed ({type(_be).__name__}: {_be}).")
                _bank = pd.DataFrame(index=X_tab.index)
            if _bank.shape[1]:
                X_tab = X_tab.copy()
                for _c in _bank.columns:
                    if _c not in X_tab.columns:
                        X_tab[_c] = _bank[_c].values
            _missing = [c for c in _want if c not in X_tab.columns]
        if _missing:
            print(f"    [F15] SKIPPING attention map: {len(_missing)} of "
                  f"{len(_want)} context columns the checkpoint was trained on "
                  f"cannot be rebuilt on this sample "
                  f"(e.g. {_missing[:3]}). Refusing to plot from a partially "
                  f"loaded model.")
            return
        X_ctx = X_tab.loc[_idx, _want].values.astype(float)
        if _spec.get('scaled') and _spec.get('scaler_mean') is not None:
            X_ctx = ((X_ctx - np.asarray(_spec['scaler_mean'], dtype=float))
                     / np.asarray(_spec['scaler_scale'], dtype=float))
        print(f"    [F15] context rebuilt from spec: {X_ctx.shape[1]} columns "
              f"(scaled={bool(_spec.get('scaled'))}), matching the "
              f"{_spec['context_dim']}-column training input.")
        assert X_ctx.shape[1] == int(_spec['context_dim']), (
            f"[F15] rebuilt context is {X_ctx.shape[1]} wide, spec says "
            f"{_spec['context_dim']}")

        # ---------------------------------------------------------- PATCH-F4
        # THE COMMENT BELOW WAS BACKWARDS AND CRASHED THE FIGURE.
        #
        #   ValueError: Layer count mismatch when loading weights from file.
        #   Model expected 15 layers, found 23 saved layers.
        #
        # The checkpoint is written by PTACExperiment (line ~5498) from a build
        # that follows Config.USE_FAULT_GATING, which is True -- so the saved
        # graph carries the detection trunk, the GLU gate and the deadband head:
        # 23 layers. This path hard-coded use_fault_gating=False and got the
        # 15-layer trunk, so load_weights() could never match. It is not that a
        # gated build "would not match an ungated checkpoint" -- it is the
        # ungated BUILD that cannot accept the gated CHECKPOINT.
        #
        # FIX: rebuild with the SAME gating flag the checkpoint was written
        # under -- follow Config (use_fault_gating=None) instead of forcing
        # False -- and load the weights into that. Verified on this graph:
        # gated build = 45 layers / 23 weighted, which is exactly the "23 saved
        # layers" the error reported; ungated = 33 / 15, the "expected 15".
        #
        # NOT via the native .keras artifact, though the run saves one. This
        # graph contains eight Lambda layers (slice_short_term, dynamic_split,
        # slice_long_term, static_split and the four per-channel deadbands), and
        # Keras 3 refuses to deserialise a Lambda wrapping a Python lambda
        # unless safe_mode=False / enable_unsafe_deserialization(). That switch
        # permits arbitrary code execution at load time, which is not a
        # reasonable price for one figure, so the weights path is used instead.
        #
        # Attention lives in the shared trunk of both graphs, so the figure this
        # produces is the figure the original comment intended. This is a
        # plotting path only -- no metric, prediction, fit or checkpoint is
        # touched, and nothing here can alter a reported number.
        # ATTENTION-FIX: rebuild with the architecture recorded beside
        # the checkpoint, not whatever mutable Config happens to contain now.
        # This fixes det_trunk/head-width mismatches after later tuning stages.
        _att_cfg = copy.deepcopy(config)
        _arch = dict(_man.get('architecture', {}) or {})
        for _k in ('BILSTM_UNITS', 'CONV_FILTERS', 'GRU_UNITS_STATIC',
                   'ATTENTION_HEADS', 'HEAD_DENSE_UNITS', 'DROPOUT_RATE',
                   'USE_FAULT_GATING', 'R17_ENABLE'):
            if _k in _arch:
                setattr(_att_cfg, _k, _arch[_k])
        if _arch:
            print(f"    [ATTN-FIX] rebuilding from checkpoint architecture: {_arch}")
        else:
            print("    [ATTN-FIX] legacy manifest has no architecture block; "
                  "falling back to current Config and requiring an exact load.")
        model = build_m2p_attention_network(
            config=_att_cfg, target_vars=target_vars,
            num_dynamic_vars=len(target_vars),
            short_window_features=len(target_vars) + 2,
            long_window_features=len(target_vars),
            context_dim=X_ctx.shape[1],
            use_attention=True, use_cnn=True,
            use_fault_gating=None
        )

        # PATCH-A4: weight_path was resolved BEFORE the spec (see above) so the
        # pair could be verified; the duplicate lookup that used to sit here is
        # gone. Resolving it twice risked the two lookups disagreeing after the
        # stem list changed.
        try:
            model.load_weights(weight_path)
            print(f"    [F4] weights loaded from "
                  f"{os.path.basename(weight_path)} into a "
                  f"{len(model.layers)}-layer build "
                  f"({sum(1 for _l in model.layers if _l.weights)} weighted).")
        except ValueError as _ve:
            if _arch:
                print(f"    [ATTN-FIX] exact load failed despite an architecture manifest: {_ve}. "
                      "Refusing skip_mismatch; attention figure is omitted rather than partially loaded.")
                return
            # Legacy fallback only: match by layer name and skip what this build does not
            # have. Verified to load a 23-weighted-layer checkpoint into a
            # 15-weighted build.
            #
            # PATCH-F15: but skip_mismatch=True is only safe if nothing on the
            # PLOTTED path was skipped. A context-width mismatch skips
            # glu_linear/glu_gate and leaves the attention trunk at random
            # init, and load_weights() still returns normally -- so the
            # skipped set is checked explicitly against the weights as they
            # stood before the load, and the figure is abandoned rather than
            # drawn from an untrained graph.
            print(f"    [F4] exact weight load failed ({_ve}); retrying by "
                  f"layer name with skip_mismatch=True.")
            _pre = {_l.name: [_w.numpy().copy() for _w in _l.weights]
                    for _l in model.layers if _l.weights}
            model.load_weights(weight_path, by_name=True, skip_mismatch=True)
            _untrained = [
                _l.name for _l in model.layers if _l.weights
                and all(np.array_equal(_a, _w.numpy())
                        for _a, _w in zip(_pre[_l.name], _l.weights))]
            if _untrained:
                print(f"    [F15] ABANDONING attention map: {len(_untrained)} "
                      f"of {sum(1 for _l in model.layers if _l.weights)} "
                      f"weighted layers kept their random initialisation after "
                      f"the by-name load ({_untrained[:6]}"
                      f"{' ...' if len(_untrained) > 6 else ''}). An attention "
                      f"map drawn from these weights would look plausible and "
                      f"mean nothing.")
                return

        att_layer = next((lyr for lyr in model.layers
                          if isinstance(lyr, layers.MultiHeadAttention)), None)
        if att_layer:
            try:
                # The trained graph called MHA(x_dynamic, x_dynamic).  Tap the
                # exact tensors fed into that trained layer, then replay only
                # the MHA call with identical weights and request its TRUE
                # attention scores.  This does not change any forecast/model.
                _ain = att_layer.input
                _ain = list(_ain) if isinstance(_ain, (list, tuple)) else [_ain]
                if len(_ain) < 2:
                    raise RuntimeError('MultiHeadAttention input tensors unavailable')
                _pre_att = Model(inputs=model.inputs, outputs=_ain)
                _vals = _pre_att.predict([X_seq, X_ctx], verbose=0)
                _vals = list(_vals) if isinstance(_vals, (list, tuple)) else [_vals]
                _q, _v = _vals[0], _vals[1]
                _k = _vals[2] if len(_vals) > 2 else None
                _nh = getattr(att_layer, 'num_heads', None)
                if _nh is None:
                    _nh = getattr(att_layer, '_num_heads', None)
                _kd = getattr(att_layer, 'key_dim', None)
                if _kd is None:
                    _kd = getattr(att_layer, '_key_dim', None)
                if _nh is None or _kd is None:
                    raise RuntimeError('cannot read trained MHA head/key dimensions')
                _vd = getattr(att_layer, 'value_dim', None)
                if _vd is None:
                    _vd = getattr(att_layer, '_value_dim', None)
                _drop = getattr(att_layer, 'dropout', None)
                if _drop is None:
                    _drop = getattr(att_layer, '_dropout', 0.0)
                _clone = layers.MultiHeadAttention(num_heads=int(_nh), key_dim=int(_kd),
                                                   value_dim=_vd,
                                                   dropout=float(_drop))
                if _k is None:
                    _out, _scores = _clone(_q, _v, return_attention_scores=True,
                                           training=False)
                else:
                    _out, _scores = _clone(_q, _v, key=_k,
                                           return_attention_scores=True,
                                           training=False)
                _clone.set_weights(att_layer.get_weights())
                if _k is None:
                    _out, _scores = _clone(_q, _v, return_attention_scores=True,
                                           training=False)
                else:
                    _out, _scores = _clone(_q, _v, key=_k,
                                           return_attention_scores=True,
                                           training=False)
                _scores = np.asarray(_scores)
                # shape: batch x heads x query_steps x key_steps
                map_data = _scores[0].mean(axis=0)
                plt.figure(figsize=(11, 8))
                sns.heatmap(map_data, cmap='viridis',
                            cbar_kws={'label': 'Mean attention probability'})
                plt.title('M2P-PTAC Temporal Attention Scores (mean over heads)',
                          fontsize=15, fontweight='bold')
                plt.xlabel('Key / attended timestep', fontsize=12)
                plt.ylabel('Query timestep', fontsize=12)
                plt.tight_layout()
                plt.savefig(os.path.join(config.OUTPUT_DIR,
                                         'attention_map_stable_ec.png'), dpi=300)
                plt.close()
                print("    [ATTN-FIX] true attention-score map saved successfully.")
            except Exception as _ae:
                # Honest fallback: output activations are NOT attention weights.
                # Save them under a different name/label rather than silently
                # misrepresenting them as probabilities.
                print(f"    [ATTN-FIX] score extraction failed ({type(_ae).__name__}: {_ae}); "
                      "saving attention-output activations as a diagnostic instead.")
                intermediate = Model(inputs=model.input, outputs=att_layer.output)
                att_output = intermediate.predict([X_seq, X_ctx], verbose=0)
                map_data = np.asarray(att_output)[0].T
                plt.figure(figsize=(14, 8))
                sns.heatmap(map_data, cmap='viridis',
                            cbar_kws={'label': 'Attention-layer output activation'})
                plt.title('Attention-layer Output Activations (diagnostic)',
                          fontsize=15, fontweight='bold')
                plt.xlabel('Look-back timestep', fontsize=12)
                plt.ylabel('Latent channel', fontsize=12)
                plt.tight_layout()
                plt.savefig(os.path.join(config.OUTPUT_DIR,
                                         'attention_activation_stable_ec.png'), dpi=300)
                plt.close()
    except Exception as e:
        # F4: previously this printed a bare message and the run continued
        # with attention_map_stable_ec.png silently absent. Print the
        # traceback so the cause is diagnosable from the log alone.
        import traceback
        print(f"    [F4] ATTENTION MAP FAILED ({type(e).__name__}): {e}")
        traceback.print_exc()


def generate_paradox_proof_plot(config, dataset_name, optimal_c):
    """Internal experiment utility."""
    print(f"\n>>> Generating robustness/specialisation figure for {dataset_name}...")
    try:
        _p_true = os.path.join(config.OUTPUT_DIR,
                               f"y_true_ec_{dataset_name}_{optimal_c}.npy")
        _p_ptac = os.path.join(config.OUTPUT_DIR,
                               f"y_pred_ptac_ec_{dataset_name}_{optimal_c}.npy")
        _p_lgbm = os.path.join(config.OUTPUT_DIR,
                               f"y_pred_lgbm_ec_{dataset_name}.npy")
        _missing = [p for p in (_p_true, _p_ptac, _p_lgbm) if not os.path.exists(p)]
        if _missing:
            print(f"    [R16-G] SKIPPING: no per-dataset prediction arrays for "
                  f"'{dataset_name}' ({', '.join(os.path.basename(m) for m in _missing)}). "
                  f"r15 would have silently drawn this figure from another "
                  f"testbed's arrays; refusing to do that.")
            return
        y_true = np.load(_p_true)
        y_ptac = np.load(_p_ptac)
        y_lgbm = np.load(_p_lgbm)
        _n = min(len(y_true), len(y_ptac), len(y_lgbm))
        if _n < 64:
            print(f"    [R16-G] SKIPPING: only {_n} aligned points.")
            return
        y_true, y_ptac, y_lgbm = y_true[:_n], y_ptac[:_n], y_lgbm[:_n]
        window = 64
        best_start = 0
        for i in range(len(y_true) - window):
            if np.std(np.diff(y_true[i:i+window], n=2)) < 0.001:
                best_start = i
                break
        plt.style.use('seaborn-v0_8-whitegrid')
        fig, ax = plt.subplots(figsize=(12, 6), dpi=300)
        t = np.arange(window)
        ax.plot(t, y_true[best_start:best_start+window], label='Ground Truth (Interpolation Artifact)', color='black', linestyle='--', alpha=0.5)
        ax.plot(t, y_lgbm[best_start:best_start+window], label='LightGBM (Numerical Specialist)', color='#ff7f0e', linewidth=2.5)
        ax.plot(t, y_ptac[best_start:best_start+window], label='M2P-PTAC (Robust Physics)', color='#1f77b4', linewidth=2.5, marker='s', markersize=3, markevery=4)
        # deviation from truth on this window -- it is not itself evidence of a
        # "trap", and labelling it as one asserted a conclusion the significance
        # tests did not support.
        ax.fill_between(t, y_true[best_start:best_start+window],
                        y_lgbm[best_start:best_start+window],
                        color='#ff7f0e', alpha=0.1,
                        label='LightGBM deviation from truth')
        ax.set_title(f'Robustness/specialisation on a low-curvature window: '
                     f'{dataset_name}', fontweight='bold')
        ax.set_ylabel('Electric Conductivity (µS/cm)')
        ax.set_xlabel(f'Step within the selected test window '
                      f'(cadence {_freq_of(config)})')
        ax.legend(loc='upper right', shadow=True)
        # chosen illustration, not a random sample. Say so on the figure.
        ax.text(0.01, 0.01, 'Window selected for low curvature; illustrative, '
                            'not a sampled comparison.',
                transform=ax.transAxes, fontsize=7, color='0.35', va='bottom')
        plt.savefig(os.path.join(config.OUTPUT_DIR,
                                 f'ROBUSTNESS_WINDOW_{dataset_name}.png'))
        plt.close()
    except Exception as e:
        print(f"Paradox Plot failed: {e}")


